  -- on Classic, its own names for the places Forever renamed (the longest first)
  classic = {
    { "Der Smaragdgrüne Traum", "Smaragdgrüner Traum" },
    { "Das Tal der Geister", "Tal der Geister" },
  },
  pages = {
    ["abyssal-council"] = {
      title = "Der Abyssische Rat",
      text = {
        { "Kultisten des Twilight-Hammers versammeln sich an Beschwörungssteinen in Silithus. Mit Siegeln, Tafeln und Texten der Macht rufen sie Templer, Herzöge und Fürsten von Feuer, Luft, Wasser und Erde herbei: die Diener des Abyssischen Rates. Jedes Ritual kann einen mächtigeren Elementar in die Wüste bringen." },
        { "Der Zirkel des Cenarius will den Kult aufgehalten und seine Texte genommen sehen. Die Steine liegen in derselben Wüste wie Ahn'Qiraj, eine Nähe, die wenig Trost spendet." },
      },
    },
    ["aerie-peak"] = {
      title = "Aerie Peak",
      text = {
        { "Aerie Peak ist die Heimat der Wildhammerzwerge, eine Stadt aus steinernen Hallen und Greifenhorsten, in einen Felsen am Westrand des Hinterlands gebaut. Sie hat den schönsten Greifenhorst der Welt, und jeder Zwerg aus Ironforge, der je auf einem Greifen geflogen ist, hat dafür einem Wildhammer zu danken." },
        { "Es ist nicht Ironforge. Hier gibt es keine großen Schmieden, wenige Mauern und noch weniger Decken. Die Wildhammer leben unter freiem Himmel, bemalen ihre Haut mit Tätowierungen und sprechen mit den Geistern des Landes. Ein Zwerg aus Ironforge fühlt sich in Aerie Peak ein wenig fehl am Platz, und das soll er auch." },
      },
    },
    ["agamaggan"] = {
      title = "Agammagan",
      text = {
        { "Im Krieg der Urtume, vor zehntausend Jahren, erhoben sich die Halbgötter der Wildnis gegen die Brennende Legion, und unter ihnen war Agammagan, ein großer Eber. Er fiel. Wo sein Blut in die Erde des Brachlands sickerte, wuchsen gewaltige Dornen, und blutrote Steine bildeten sich im Boden. Die Stacheleber leben zwischen den Dornen, nennen sich seine Kinder und tragen die Steine als Totems." },
        { "Die Schamanen der Stacheleber schöpfen noch immer aus seiner Macht, und ein Gefangener in Camp Taurajo teilt ihre Segnungen für den richtigen Preis. Die großen Dornenbauten im Süden, Razorfen, sind sein Grab, und die Stacheleber halten sie für heilig." },
      },
    },
    ["algaz"] = {
      title = "Algaz",
      text = {
        { "Die Straße aus Loch Modan nach Norden führt durch Dun Algaz, einen schmalen Pass, der durch die Berge ins Sumpfland geschlagen ist, und sie wird an beiden Enden bewacht." },
        { "Auf unserer Seite bewachen die Gebirgsjäger der Station Algaz die Straße und die Hügel ringsum. Troggs tauchen im Pass öfter auf, als es irgendwem lieb ist, und das Sumpfland dahinter ist den Zwergen kein Freund mehr, seit die Dunkeleisenzwerge kamen." },
        { "Wenn Ihr durch den Pass geht, seht Euch den Stein an. Er wird seit sehr langer Zeit von zwergischen Händen bearbeitet." },
      },
    },
    ["alonsus-faol"] = {
      title = "Alonsus Faol",
      text = {
        { "Alonsus Faol führte vor dem Ersten Krieg die Kleriker von Nordhain, und als Stormwind fiel und mit ihm die Abtei, ging der alte Mann mit den Flüchtlingen nach Norden. In Lordaeron gab er als Erzbischof der Kirche des Heiligen Lichts ein Schwert: Er gründete die Ritter der Silbernen Hand und salbte seinen Schüler Uther zum ersten der Paladine." },
        { "Sein Werk reichte weiter als bis aufs Schlachtfeld. Eine Tafel in der Kathedrale von Stormwind sagt, dass er es in Stratholme begann, nach dem Zweiten Krieg half, die Bruderschaft von Nordhain neu zu ordnen, und die Mittel für den Wiederaufbau von Stormwind selbst sammelte. Er starb, bevor die Seuche kam, an nichts Schlimmerem als dem Alter, soweit man weiß." },
        { "Hier soll er liegen. Vor der Geißel war es ein Ort der Pilgerfahrt. Heute sammelt er die Toten des Scharlachroten Klosters, und niemand kommt, um ihn zu betrauern. Er hätte Besseres verdient, und der Orden, den er gründete, ebenso." },
      },
    },
    ["altar-of-storms"] = {
      title = "Der Altar der Stürme",
      text = {
        { "Der Altar der Stürme steht im Schatten der Blackrockspitze, eine erhaltene Stätte der Hexenmeisterriten der alten Horde. Im Zweiten Krieg verwandelte die Magie, die an solchen Altären gewirkt wurde, Oger in Ogermagier und gab ihnen List und die Macht, Zauber zu wirken." },
        { "Hexenmeister der Blackrock versammeln sich noch immer hier. Mor'zul Bloodbringer, der den Altar erforscht hat, lagert in der Nähe und schickt andere Hexenmeister mit eigenen Aufträgen los." },
      },
    },
    ["alterac-mountains"] = {
      title = "Alteracgebirge",
      text = {
        { "Schnee bedeckt einen Großteil von Alterac, doch er hat wenig getan, um den Fall des Königreichs zu verbergen. Zerbrochene Burgen stehen über Städten, die das Syndikat hält, Oger bewohnen die alte Hauptstadt, und die Straßen steigen an Höhlen vorbei, die nun den Yetis gehören. Dies waren einst die Höhen eines kleinen, stolzen Reiches der Menschen, dessen König die Allianz im Zweiten Krieg verriet." },
        { client = "classic", "Am Lordameresee umschließt eine violette Kuppel den Wiederaufbau Dalarans. Die Magier haben die Zerstörung ihrer Stadt überlebt und neu begonnen, auch wenn sie bei der Arbeit kaum Zeugen zulassen." },
        { client = "forever", "Am Lordameresee ist Dalarans Wiederaufbau in ein weiteres Unglück geraten. Gestörte Kraftlinien haben die Konstrukte der Stadt gegen ihre Bewohner gewandt, und Erzmagierin Modera sucht die Hilfe von außen, die der Rat lieber nicht bräuchte." },
        { "Weiter in den Bergen kämpfen die Frostwolf und die Stormpike um das Alteractal. Das Königreich ist verschwunden, $gReisender:Reisende;. Der Streit darüber, wer in seinen Hügeln leben darf, hat es überdauert." },
      },
    },
    ["alterac-valley"] = {
      title = "Alteractal",
      text = {
        { "Im Süden des Alteracgebirges liegt ein verborgenes Tal, und zwei Völker beanspruchen es. Die Orcs des Frostwolfklans leben seit einer Generation in seinem südlichen Teil, seit der Hexenmeister Gul'dan sie dorthin verbannte. Die Zwerge des Stormpikeklans kamen später, um zu graben: nach Erzen und nach Relikten aus der fernen Vergangenheit unseres Volkes, die die Forscherliga unter dem Eis des Tals vermutet." },
        { "Die Frostwolf sahen Eindringlinge. Die Stormpike sahen Orcs, die ehrlicher Wissenschaft im Weg standen, und König Magni hat ihnen inzwischen den königlichen Befehl erteilt, das Tal für Ironforge einzunehmen. Nun kämpfen die beiden mit Heeren, Burgen, Friedhöfen und Minen quer durch das Tal, und beide Seiten rufen ihr ganzes Bündnis um Hilfe. Ich wünschte, ich könnte sagen, die Liga habe keinen Anteil daran." },
      },
    },
    ["ambermill"] = {
      title = "Ambermill",
      text = {
        { "Ambermill ist ein Dorf im Osten des Silberwalds, das den Verlassenen noch standhält, und es hält stand wegen der Magier von Dalaran. Die Kirin Tor haben Zauberer, Beschützer und Wagenladungen voller Vorräte aus Hillsbrad geschickt, sehr viel Aufmerksamkeit für ein abgelegenes Dorf." },
        { "Die Verlassenen haben herausgefunden, warum: Unter Ambermill liegt ein ruhender Knotenpunkt von Kraftlinienenergie, und Dalaran will ihn wecken. Wozu, weiß niemand im Grabmal, und die Zauberer sagen es nicht." },
      },
    },
    ["ancients"] = {
      title = "Die Urtume",
      text = {
        { "Die Urtume sind die ältesten Bäume der Wälder der Nachtelfen, weise genug geworden, um zu denken, und stark genug, um zu gehen. Im Krieg der Urtume rief Cenarius sie aus den verzauberten Wäldern herbei und führte sie gegen die Brennende Legion, ein Heer aus Baummännern, das auf die eigene Stadt der Königin marschierte. Im Dritten Krieg marschierten sie erneut." },
        { "Sie halten noch immer Wache. Urtumbeschützer stehen auf Teldrassil Wache, ein Urtum der Lehren und ein Urtum des Krieges haben ihren Platz in Darnassus, und Onu, ein weiteres Urtum der Lehren, spricht für den Wald im Hain der Uralten an der Dunkelküste." },
        { "Sie sind langsam im Reden und noch langsamer darin, ihre Meinung zu ändern. Ein Volk, das seine Hauptstadt in einen Baum gepflanzt hat, lernt wohl, Bäumen zuzuhören." },
      },
    },
    ["andorhal"] = {
      title = "Andorhal",
      text = {
        { "Andorhal versorgte den Norden Lordaerons mit Getreide. Kel'Thuzads Kult der Verdammten verseuchte seine Kornspeicher, und die Lieferungen trugen die Seuche in die Dörfer dahinter. Eine wohlhabende Stadt wurde zu einem Mittel, den Tod durch das Land zu tragen, das von ihr abhing." },
        { "Arthas tötete Kel'Thuzad hier, als er die Quelle der Seuche verfolgte. Der Tod des Nekromanten beendete sein Werk nicht. Andorhal bleibt in der Hand der Geißel, seine Ruinen beherrscht von Araj dem Beschwörer. Sowohl das Chillwind-Lager als auch das Bollwerk wollen den Lich vernichtet sehen." },
        { side = "Horde", aside = true, sign = "P. F.", "Die Seuche kam mit Andorhals Getreide nach Norden, nicht hinter einem Heer. Das ist der Teil der Geschichte, den die Leute zuerst vergessen." },
      },
    },
    ["anduin-lothar"] = {
      title = "Anduin Lothar",
      text = {
        { "Anduin Lothar war der Letzte aus dem Blut der Arathi, der Linie Thoradins, der die Menschheit zuerst vereinte, und er diente König Llane von Stormwind als sein Streiter und Waffenleutnant. Es war Lothar, der mit dem jungen Khadgar Karazhan stürmte und Medivh tötete, seinen alten Freund, als er begriff, was der Wächter getan hatte." },
        { "Er kam zu spät heim, um Stormwind zu retten, führte sein Volk über das Meer nach Lordaeron und wurde Oberbefehlshaber der Allianz. Selbst die Elfen von Quel'Thalas kamen, wie widerwillig auch immer, wegen der Schuld, die sie bei seinen Ahnen hatten." },
        { "Er starb hier. Als die Horde in der Blackrockspitze eingepfercht war, stürmte Orgrim Schicksalshammer mit seinen Leutnants heraus und traf mitten auf diesen Ebenen auf Lothars Paladine. Die beiden kämpften, bis sie erschöpft waren, und Schicksalshammer tötete ihn. Sein Leutnant Turalyon nahm Lothars blutbefleckten Schild auf und brach die Horde in der folgenden Flucht. Die Expedition, die später durch das Dunkle Portal marschierte, zog als die Söhne Lothars aus." },
      },
    },
    ["arathi-basin"] = {
      title = "Arathibecken",
      text = {
        { "Im Süden des Hochlands liegt ein fruchtbares Becken aus Höfen, Minen und Mühlen, das reichste Land, das in Arathi übrig ist, und die Allianz wie die Horde wollen, was es hervorbringt. Der Bund von Arathor, dem Andenken Stromgardes verschworen, kämpft von Westen her darum. Die Entweihten, von den Verlassenen aufgestellt, kämpfen von Osten her." },
        { "Sie kämpfen um einen Hof, eine Mine, ein Sägewerk, einen Stall und eine Schmiede, hissen die Banner der anderen und reißen sie nieder, den ganzen Tag und die ganze Nacht. Arathor hätte es verstanden: Das erste Reich der Menschen wurde auf genau solchem Land errichtet." },
      },
    },
    ["arathi-highlands"] = {
      title = "Arathihochland",
      text = {
        { "Das Arathihochland ist windgepeitschtes Land zwischen Hillsbrad und dem Sumpfland. Hier vereinte Thoradin die Stämme der Menschen zu Arathor, mit der Hauptstadt Strom. Jedes spätere Königreich der Menschen wuchs aus diesem Anfang." },
        { "Strom wurde zu Stromgarde. Seine Ruinen sind heute zwischen seinen Verteidigern, Dieben des Syndikats und Ogern aufgeteilt. Trolle der Witherbark bewohnen Siedlungen in den Hügeln, während Riesen seltsame Kreise aus aufrecht stehenden Steinen bewachen. Die Zuflucht beherbergt das Lager der Allianz, Hammerfall das der Horde. Ihre Streitkräfte kämpfen um die Höfe, Minen und Mühlen des Beckens im Süden." },
        { "Betrachtet das alte Mauerwerk, wenn Ihr Arathi durchquert, $gReisender:Reisende;. Die Königreiche der Menschen haben hier begonnen. Die Leute, die Stromgarde verteidigen, versuchen noch immer, einen Teil dieses Anfangs für sich zu behalten." },
      },
    },
    ["archesonus"] = {
      title = "Königliche Historikerin Archesonus",
      text = {
        { "Ihr habt mich also gefunden. Ich hüte die Geschichte Ironforges vom Hohen Sitz aus, wenige Schritte vom Thron König Magnis entfernt, und wer mich danach fragt, sollte besser einen freien Nachmittag mitbringen." },
        { "Die Geschichte, nach der man mich am häufigsten fragt, ist die der Dunkeleisenzwerge. Der Krieg der drei Hämmer endete damit, dass Zauberthan Thaurissan Ragnaros herbeirief, und das Erwachen des Feuerlords verwandelte ihr eigenes Land in Asche. In den Ruinen von Thaurissan, in der Brennenden Steppe, liegen noch Relikte, die mehr von dieser Geschichte bergen, als ich bisher lesen konnte. Wer mir bringt, was sie zu sagen haben, hat meinen Dank." },
        { "Dieses Register ist mein Werk, $gReisender:Reisende;, mit sehr viel Hilfe der Forscherliga, die mehr nach Hause bringt, als eine einzelne Historikerin je lesen könnte. Wenn Euch eine Seite gute Dienste geleistet hat, freut mich das. Wenn eine Euch im Stich gelassen hat, kommt und sagt es mir." },
        { side = "Horde", aside = true, sign = "P. F.", "Ich bin ihr nie begegnet. Ihr Bericht über die Welt ist dennoch der gerechteste, den ich von lebender Hand gelesen habe." },
      },
    },
    ["archmage-arugal"] = {
      title = "Erzmagier Arugal",
      text = {
        { "Als Dalarans Verteidiger der Geißel erlagen, suchte Arugal nach einer Waffe gegen die Toten. Der Magier der Kirin Tor beschwor Worgen aus einer anderen Welt. Sie bekämpften die Eindringlinge und wandten sich dann gegen die Lebenden, die sie schützen sollten." },
        { "Arugal zog sich nach Burg Shadowfang zurück und begann, die Worgen als seine Kinder zu betrachten. Das nahe Pyrewood litt unter seinem Fluch, seine Bewohner verwandelt nach Einbruch der Nacht. Was als Versuch begann, eine einzige Stadt zu retten, hat eine Burg und ein Dorf im Griff seiner Antwort zurückgelassen." },
      },
    },
    ["argent-dawn"] = {
      title = "Die Argentumdämmerung",
      text = {
        { "Die Argentumdämmerung wirbt gegen die Geißel bei der Allianz wie bei der Horde an. Ihre Ritter, Priester und Gelehrten fragen, wogegen ein Reisender zu kämpfen bereit ist, und nicht, welchem Banner er folgt. Lord Maxwell Tyrosus führt sie von der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern aus." },
        { "Offiziere im Chillwind-Lager und am Bollwerk vergeben Aufträge und nehmen die Geißelsteine an, die die Toten bei sich tragen. Gesandte arbeiten in Stormwind, Darnassus und Everlook. Die Dämmerung hat ihren Krieg zu einer Sache gemacht, der sich Leute beider Fraktionen anschließen können." },
        { "Sie teilt einen Feind mit dem Scharlachroten Kreuzzug und wenig Zuneigung für dessen Methoden. Die Dämmerung hält das Misstrauen des Kreuzzugs gegenüber jedem Fremden für eine Hilfe für den Lichkönig. Dieser Einwand hat praktischen Sinn: Der Kampf hat schon genug Feinde." },
      },
    },
    ["arthas-menethil"] = {
      title = "Arthas Menethil",
      text = {
        { "Arthas Menethil war der einzige Sohn von König Terenas von Lordaeron, ein Paladin der Silbernen Hand, von Uther selbst ausgebildet, und in glücklicheren Tagen der jungen Zauberin Jaina Proudmoore nahe. Als die Seuche kam, zog er gegen sie aus." },
        { "Er folgte ihr der Geißel voraus bis hierher und fand das Getreide bereits gegessen. Statt die Stadt sich gegen ihn erheben zu lassen, ließ er ihre Bewohner über die Klinge springen. Uther und Jaina wollten ihm nicht folgen. Der Schreckenslord Mal'Ganis, der auf ihn gewartet hatte, zog sich nach Norden zurück, und Arthas jagte ihn bis nach Nordend, verbrannte seine eigenen Schiffe, damit seine Männer nicht umkehren konnten, und nahm die Runenklinge Frostgram auf. Mit ihr tötete er Mal'Ganis und verlor seine Seele." },
        { "Er kehrte als Todesritter heim, tötete seinen Vater in dessen eigenem Thronsaal und führte die Geißel durch das Königreich, über das er hätte herrschen sollen. In Andorhal tötete er Uther. Dann ging er nach Norden zum Frostthron und wurde, wie das Buch in unserer Bibliothek sagt, selbst zum Lichkönig. Stratholme erinnert sich an ihn besser als jeder andere Ort. Seine Straßen sind noch immer voller Menschen, die er retten wollte." },
        { side = "Horde", aside = true, sign = "P. F.", "Die Chroniken Lordaerons hatten ein Kapitel, das auf ihn wartete: der Erbe, der Paladin, der künftige König. Keine von ihnen irrte sich in seinen Gaben." },
      },
    },
    ["ashenvale"] = {
      title = "Ashenvale",
      text = {
        { "Ashenvale ist der uralte Wald der Nachtelfen: gewaltige Bäume, silbernes Mondlicht, stille Seen und Ruinen, älter als jedes Königreich der Menschen. Zehntausend Jahre lang lebten die Nachtelfen hier verborgen, bewacht von ihren Schildwachen und dem Halbgott Cenarius, und ließen niemanden herein." },
        { "Dann kamen die Orcs nach Kalimdor und brauchten Holz für ihr neues Land, und seither liegt der Wald im Krieg. Im letzten Krieg schlug der Warsongklan in Ashenvale ein und tötete Cenarius unter dem Einfluss von Mannoroths Verderbnis. Die Nachtelfen haben ihnen nicht vergeben, und die Horde hat nicht aufgehört zu fällen. Nun liefern sich Schildwachen und Vorreiter der Warsong Gefechte am Ostrand des Waldes, während wahnsinnig gewordene Furbolgs, Satyrn und Naga allen gleichermaßen zusetzen." },
      },
    },
    ["astranaar"] = {
      title = "Astranaar",
      text = {
        { "Astranaar steht auf einer Insel in einem See in Ashenvale, durch Brücken mit dem Wald verbunden. Sein Mondbrunnen, sein Gasthaus und die Kaserne der Schildwachen geben den Nachtelfen einen Mittelpunkt, von dem aus sie das Land ringsum verteidigen. Es ist eine schöne Stadt mit sehr wenig Ruhe." },
        { "Ein Vater hier sucht Hilfe für das Fieber und die Albträume seiner Tochter. Gewöhnliche Heilmittel haben ihr nicht geholfen. Kräuterkundige sprechen von einer Krankheit im Wald selbst, während die Schildwachen der Verderbnis die Schuld geben, die die Dämonen des Krieges hinterlassen haben. Ein Reisender, der kommt, um Astranaar verteidigen zu helfen, stellt vielleicht fest, dass die Sorgen der Stadt weit innerhalb ihrer bewachten Zugänge beginnen." },
      },
    },
    ["atiesh"] = {
      title = "Atiesh",
      text = {
        { "Atiesh war der Stab der Wächter von Tirisfal, am Ende Medivhs, und nach seinem Tod wurde er zerbrochen und verstreut. Seine Splitter wurden aus der Nekropole Naxxramas zusammengetragen, wo Kel'Thuzad auf seinem Thron saß und hielt, was der Träger suchte. Sein Fuß ging mit dem zwergischen Forscher Brann Bronzebeard nach Ahn'Qiraj, der ohne ihn wieder herauskam." },
        { "Ein Stab, der die Macht eines Wächters getragen hatte, hatte auch die von Sargeras getragen, wie sein letzter Wächter, und das Böse war noch darin. Anachronos vom bronzenen Schwarm, bei den Höhlen der Zeit, schickt jeden, der ihm die Teile bringt, nach Stratholme, auf den geweihten Boden, auf dem die größten Ritter Lordaerons ermordet wurden, um das Ding darin herauszurufen und zu vernichten." },
        { "Sehr wenige werden ihn je halten. Der bronzene Drache sagt, wer es tut, sei immer dazu bestimmt gewesen. Der bronzene Schwarm sagt solche Dinge sehr oft." },
      },
    },
    ["auberdine"] = {
      title = "Auberdine",
      text = {
        { "Auberdine ist der Hafen der Nachtelfen an der Dunkelküste, ein Dorf aus anmutigen Häusern am Ufer, mit Schiffen nach Teldrassil und über das Meer zum Hafen von Menethil. Für die meisten Reisenden aus den Östlichen Königreichen ist es die erste Stadt der Nachtelfen, die sie je sehen." },
        { "Die Schildwachen, die es halten, haben alle Hände voll zu tun und sind froh über Hilfe. Auch die Liga hat hier einen Freund. Fragt nach Ausgrabungsleiter Remtravel, und macht Euch auf eine lange Geschichte gefasst." },
      },
    },
    ["azshara"] = {
      title = "Azshara",
      text = {
        { "Azshara trägt die Farben des Herbstes zwischen den weißen Ruinen der Hochgeborenen. Es trägt den Namen der Königin, die vor zehntausend Jahren herrschte, und liegt neben dem Meer, das so viel von ihrem Reich verschlang. Wenige Orte bieten einen schöneren Blick auf einen so großen Verlust." },
        { "Naga bewohnen die Küste und die alten Tempel. Satyrn spuken in den Wäldern, und Geister bleiben zwischen den zerbrochenen Mauern. Valormok und die Talrendisspitze sind kleine Stützpunkte in einem Land, das noch voller älterer Ansprüche ist. Azuregos wacht über die südlichen Hügel, während ein Erzmagier einen Turm hält und ein Wasserfürst eine Insel in der Bucht bewohnt." },
        { client = "classic", "In den nördlichen Hügeln steht das verschlossene Tor der Holzschlundfeste. Die Furbolgs haben diesen Teil ihres Landes für sich behalten." },
        { client = "forever", "Das steinerne Tor im Norden führt in die Schwarzschlundfeste, wo die Verderbnis einen Furbolgstamm ergriffen hat. Dies sind nicht die Holzschlundfeste, die die Tunnel im Teufelswald bewachen. Ein alter Name auf einer Karte kann ein schlechter Führer zu dem Volk hinter einem Tor sein." },
      },
    },
    ["azuregos"] = {
      title = "Azuregos",
      text = {
        { "Azuregos wacht über den Süden von Azshara, wo die Hochgeborenen genug arkane Schätze zurückließen, um einen blauen Drachen sehr lange zu beschäftigen. Sein Schwarm hütet die Magie, und diese zerstörte Küste erklärt einiges darüber, warum es solcher Hüter bedarf." },
        { "Zu seiner Aufgabe gehörte auch der blaue Splitter des Szepters der Sandstürme. Die Suche danach führt über ein magisches Buch und eine ausgeklügelte Methode, einen großen Hai namens Der weiße Riese aus der Bucht der Stürme zu locken. Ein fehlendes Stück eines uralten Szepters ist zu einer Frage von Übersetzung, Ingenieurskunst und sehr großen Zähnen geworden." },
        { "Es gibt feierliche Hüter in der Welt, $gReisender:Reisende;. Azuregos' Vorkehrungen legen nahe, dass Jahrhunderte der Verantwortung die Fähigkeit eines Drachen nicht auslöschen müssen, jemand anderem Arbeit zu machen." },
      },
    },
    ["bael-modan"] = {
      title = "Bael Modan",
      text = {
        { "General Doppelzopfs Zwerge haben Bael Modan neben ihrer Grabung im Südosten des Brachlands errichtet, mit einer Kanone und Flugmaschinen, die die Siedlung stützen. Ausgrabungsleiter Khazgorm von der Forscherliga arbeitet unter ihnen. Eine alte Stätte, ein befestigtes Lager und einer der eigenen Ausgrabungsleiter der Liga: die Anfänge einer vertrauten Expedition." },
        { "Gann Stonespire beschreibt, was dem vorausging. Dies sei die Heimat seines Stammes gewesen, sagt er, bevor die Sprengungen und Maschinen die Hügel aufrissen und sein Volk vertrieben. Die Diplomatie hat ihn im Stich gelassen. Nun will er Khazgorms Tod und die Zerstörung der Flugmaschine der Zwerge." },
        { "Innerhalb der Expedition hat Feegly unter dem Fluch eines ausgegrabenen Steins gelitten. Die Grabung hat den Grabenden ebenso Unheil gebracht wie denen, die sie vertrieben hat. Ich wäre gern stolz auf jeden Ort, an dem der Name der Liga auftaucht. Bael Modan macht das schwer." },
      },
    },
    ["balnazzar"] = {
      title = "Balnazzar",
      text = {
        { "Balnazzar war einer der Schreckenslords, die in Lordaeron zurückgelassen wurden, um die Geißel für die Brennende Legion zu beaufsichtigen. Nach der Niederlage der Legion stellten sie Arthas' Herrschaft in Frage. Arthas entkam ihrem Aufstand und ging nach Nordend. Sylvanas nahm ihnen später ihr Königreich. Auf ihren Befehl schien Varimathras seinen Bruder Balnazzar zu töten." },
        { "Man glaubte an den Tod, doch der Dämon überlebte. Er nahm die Gestalt des Obersten Kreuzzüglers Dathrohan an und herrschte über die scharlachrote Bastion in Stratholme. Wer den vermeintlichen Kreuzzügler besiegt, enthüllt, was unter der Verkleidung steckt. Es ist eine hässliche Entdeckung für einen Orden, der sich der Vernichtung genau des Bösen verschrieben hat, das ihm seine Befehle erteilt." },
      },
    },
    ["baron-rivendare"] = {
      title = "Baron Rivendare",
      text = {
        { "Baron Rivendare beherrscht die Hälfte Stratholmes, die der Geißel gehört, von ihrem Schlachthaus aus, ein Todesritter auf einem toten Pferd. Die Argentumdämmerung nennt ihn Kel'Thuzads Laufburschen. Herzog Zverenhoff in der Kapelle des hoffnungsvollen Lichts verlangt seinen Kopf." },
        { "Rivendare hält auch die Kreuzfahrerin der Argentumdämmerung Ysida Harmon gefangen. Ihr Mann bittet um ihre Rettung. Behaltet sie im Sinn, $gReisender:Reisende;, wenn das Kopfgeld des Herzogs Euch in die Stadt führt. Dort muss noch jemand lebend herauskommen." },
      },
    },
    ["barrens-oases"] = {
      title = "Die Oasen",
      text = {
        { "Die Oasen des Brachlands sind sein Leben: Becken mit frischem Wasser im trockenen Gras, an denen die Tiere und die Reisenden trinken. In letzter Zeit sind sie seltsam geworden. Tiere in ihrer Nähe verwachsen, Pflanzen wachsen zu schnell und falsch, und die Druiden von Thunder Bluff spürten eine Macht, die ins Land sickerte, und schickten einen der Ihren, um sie zu finden." },
        { "Er fand Spalten am Grund der Becken, die tief in die Erde reichen. Die Oasen werden von unten gespeist, aus den Höhlen unter dem Brachland, und was auch immer in diesen Höhlen nicht stimmt, kommt mit dem Wasser herauf." },
      },
    },
    ["black-dragonflight"] = {
      title = "Der schwarze Drachenschwarm",
      text = {
        { "Neltharion war der Erdwächter, betraut mit den tiefen Orten der Welt. Sein Verrat an den anderen Drachenschwärmen gab ihm den Namen Todesschwinge. Nach dem Zweiten Krieg trat er als Lord Prestor in die Räte der Menschenkönige, einen Drachen hinter dem Gesicht eines Adligen verborgen. Nach dem Kampf um Grim Batol entkam er den Aspekten. Wohin er sich zurückgezogen hat, bleibt unbekannt." },
        { "Seine Kinder bewohnen Orte, die wir benennen können. Onyxia hält ihre Brut in den Marschen von Dustwallow. Nefarian hält die Blackrockspitze, befehligt ihre Orcs und züchtet über ihnen chromatische Drachen. Schwarze Welpen bewohnen das Rotkammgebirge und das Ödland, während Großdrachenbrut die größeren Besitzungen des Schwarms bewacht." },
        { "Die Horte sind gewaltig genug. Lord Prestor zeigte, was ein schwarzer Drache mit einem Sitz an einem Ratstisch erreichen konnte." },
      },
    },
    ["blackfathom-deeps"] = {
      title = "Blackfathom-Tiefe",
      text = {
        { "An der Küste von Ashenvale, am Zoramstrand, gibt es vom Meer überflutete Höhlen, und in ihnen liegen die Ruinen eines Tempels der Elune, der versank, als der Brunnen der Ewigkeit zerstört wurde. Die Naga fanden ihn zuerst. Dann der Twilight-Hammer, angeführt von einem Twilight-Lord namens Kelris." },
        { "Ihre Papiere sagen, was sie dort tun. Sie sammeln die Macht der tiefen Wasser, um ein Geschöpf zu nähren, das sie Aku'mai nennen und das in den Tiefen des Tempels schläft, damit die Welt eines Tages zu dem zurückkehrt, was sie ihr größtes Zeitalter nennen: einem Zeitalter der Herrschaft der Alten Götter. Die Nachtelfen und die Horde schicken beide ihre Jungen, um sie aufzuhalten, was vielleicht das Einzige ist, worin sich die beiden in Ashenvale einig sind." },
      },
    },
    ["blackrock-clan"] = {
      title = "Der Blackrockklan",
      text = {
        { "Die Blackrock waren der größte Klan der alten Horde. Ihr Häuptling Blackhand führte sie als Kriegshäuptling im Ersten Krieg, bis Orgrim Schicksalshammer ihm den Schädel einschlug und den Titel nahm, und auch Schicksalshammer war ein Blackrock. Als die Horde fiel, ging der größte Teil des Klans mit allen anderen in die Lager, und viele von denen, die herauskamen, folgten Thrall." },
        { "Nicht alle. Blackhands Söhne, Rend und Maim, sammelten Überlebende im Blackrock. Rends Gefolgsleute halten an den alten Wegen fest: an der Eroberung, der Grausamkeit und dem Kult um den Kriegshäuptling. Rend nennt sich bis heute Kriegshäuptling und hat für Thralls Namen nur Verachtung übrig. Schlimmer noch, er hat sich mit den schwarzen Drachen eingelassen, die in der oberen Spitze hausen." },
        { "Vom Berg aus überfällt der Klan den Norden und Westen. Sie halten die Brennende Steppe, sie haben Burg Steinwacht im Rotkammgebirge eingenommen, und die Leute von Seenhain leben in Sichtweite ihrer Feuer. Was auch immer die Horde in Durotar geworden ist, dies ist, was sie war." },
      },
    },
    ["blackrock-depths"] = {
      title = "Blackrocktiefen",
      text = {
        { "Die Blackrocktiefen sind die Stadt der Dunkeleisenzwerge unter dem Berg: die Schattenschmiede, mit ihren Gefängnissen, ihrer Arena, ihren Gewölben, ihren Golemwerkstätten und ihrer Taverne, Zum grimmigen Säufer, wo sie ein dunkles Bier brauen. Ganz unten sitzt in seinem Palast der Imperator, und hinter ihm führt der Weg hinab in das eigene Reich des Feuerlords." },
        { "Die Allianz und die Horde kommen beide hierher, die Horde wegen der Golems der Dunkeleisenzwerge und ihrer Geheimnisse, die Allianz wegen eines gefangenen Marshals und wegen König Magnis Tochter. Hier gibt es sehr viel Geschichte, und das meiste davon steht in Flammen." },
      },
    },
    ["blackrock-mountain"] = {
      title = "Der Blackrock",
      text = {
        { "Der Blackrock steht zwischen der Sengenden Schlucht und der Brennenden Steppe, ein Berg aus schwarzem Stein mit Feuer in seinem Herzen. Er erhob sich, als Ragnaros kam, und die Dunkeleisenzwerge, seine Sklaven, bauten ihre Stadt in seinem Inneren. Im Zweiten Krieg war er die große Festung der Horde, und nach dem Krieg suchten die Orcs, die der Allianz entkamen, in ihm Zuflucht." },
        { "Heute liegt der Berg mit sich selbst im Krieg. Die Dunkeleisenzwerge halten die Tiefen für den Feuerlord, und die Orcs der Dunklen Horde halten mit Nefarians schwarzen Drachen die Spitze darüber. Zwischen ihnen, in der Mitte des Berges, hängen Ketten über einem See aus Lava." },
      },
    },
    ["blackrock-spire"] = {
      title = "Blackrockspitze",
      text = {
        { "Die Dunkeleisenzwerge hauten die Blackrockspitze über ihrer Stadt aus dem Fels und verloren sie dann an die Orcs. Orgrim Schicksalshammer hielt sie im Zweiten Krieg. Gegen Ende des Krieges belagerte die Allianz die Festung. Anduin Lothar fiel vor ihren Toren, bevor die Horde gebrochen wurde." },
        { "Rend Blackhand befehligt heute ihre Orcs in Nefarians Diensten. Orcs, Trolle und Oger füllen die untere Spitze, während der Drache und seine Gefolgsleute die Höhen halten. Der Aufstieg führt durch eine besetzte Festung, mit einem anderen Herrn als dem, den ihre Erbauer im Sinn hatten." },
      },
    },
    ["blackwing-lair"] = {
      title = "Pechschwingenhort",
      text = {
        { "Nefarian hält den Pechschwingenhort auf dem Gipfel der Blackrockspitze. Hier züchtet er chromatische Drachen, indem er das Blut der Drachenschwärme vermischt, auf der Suche nach einem Heer, das seine Feinde überwältigen kann. Der Hort ist zugleich seine Festung und der Ort, an dem er ihre künftigen Soldaten erschafft." },
        { "Der rote Drache Vaelastrasz ist dort unter Nefarians Kontrolle. Einst ein Freund der Sterblichen, fleht er die, die ihn erreichen, an, sein Leiden zu beenden. Es ist wenig Trost, hier einen Freund zu erreichen, $gReisender:Reisende;, wenn er Euch darum bitten muss." },
      },
    },
    ["blasted-lands"] = {
      title = "Verwüstete Lande",
      text = {
        { "Südlich der Sümpfe des Elends, hinter einer einzigen Straße und einer einzigen Burg, liegen die Verwüsteten Lande: eine rote, rissige Öde aus Staub und toten Bäumen, in der die Tiere verdreht und der Boden vergiftet ist. Hier kamen die Orcs zuerst in unsere Welt, durch das Dunkle Portal, und hier wurden sie zurückgetrieben. Das Land hat sich nie erholt." },
        { "Dämonen der Brennenden Legion wandeln noch immer hier. Die Allianz hält Wache von Nethergarde aus, die Oger halten ihre eigenen Lager, und die Horde hat ihre eigenen Geschäfte mit den Dämonen. Jeder, der hierher kommt, kommt wegen des Portals oder wegen dessen, was es zurückgelassen hat." },
      },
    },
    ["blood-elves"] = {
      title = "Die Blutelfen",
      text = {
        { "Nachdem Quel'Thalas gefallen war, führte der Letzte seiner königlichen Linie, Prinz Kael'thas Sonnenwanderer, was von den Hochelfen übrig war, im Kampf der Allianz gegen die Geißel. Sie benannten sich zu Ehren ihres gefallenen Volkes in Blutelfen um. Vom Sonnenbrunnen abgeschnitten, der sie seit Tausenden von Jahren genährt hatte, lernten sie auch, wie dringend sie seine Magie brauchten, und sie litten unter ihrem Fehlen." },
        { "Als die Allianz Schlachten verlangte, die seine geschwächten Kräfte allein nicht gewinnen konnten, nahm Kael'thas die Hilfe von Lady Vashj und ihren Naga an. Sein Befehlshaber Garithos verurteilte die Blutelfen als Verräter zum Tode. Vashj befreite sie aus den Kerkern von Dalaran und führte sie in die Scherbenwelt, den zerbrochenen Rest der Welt der Orcs. Dort befreiten sie Illidan Stormrage von seiner Wärterin, und Kael'thas schwor ihm Treue im Tausch für die Magie, die sein Volk brauchte." },
        { "Manche seiner Leute sind viel näher. Blutelfen durchsuchen die Klippen und Ruinen von Azshara nach der Magie, die die Hochgeborenen zurückließen, und zermahlen, was sie finden, zu einem glitzernden Staub. Ein Goblin, der ihr Geld nahm, und ein Kriegstrupp der Orcs, der ihnen Wachen lieh, haben beide erfahren, was ihre Anstellung wert ist. Ein anderer ist nach Düsterbruch gegangen, um seine Ruinen ihrer Macht zu berauben. Gershala Nightwhisper in Auberdine fürchtet, sie gingen den Weg der Satyrn und der Naga. Ich fürchte, er könnte recht haben." },
      },
    },
    ["bloodhoof-village"] = {
      title = "Bloodhoof",
      text = {
        { "Bloodhoof ist das Herz der Ebenen, ein Dorf aus Langhäusern und Kodogehegen an der Straße zwischen Camp Narache und Thunder Bluff. Sein Häuptling ist Baine Bloodhoof, Sohn des Oberhäuptlings Cairne, und hier legen die Jungen den zweiten der Riten ab, den Ritus der Sicht: Sie trinken das Wasser der Seher vor dem Feuer des Dorfes und folgen, wohin die Vision sie führt." },
        { "Es ist ein geschäftiger, freundlicher, praktischer Ort. Die Tauren von Bloodhoof sind ebenso Bauern und Hirten wie Jäger, und sie geben einem Fremden zu essen, bevor sie nach seinem Anliegen fragen." },
      },
    },
    ["bloodsail-buccaneers"] = {
      title = "Die Blutsegelbukaniere",
      text = {
        { "Die Blutsegelbukaniere sind die große Piratenflotte der südlichen Meere, und ihr Streit gilt Booty Bay. Der Baron und seine Schwarzmeerräuber hindern sie daran, zu plündern, wo es ihnen gefällt, und hängen sie, wenn sie sie fangen. Die Blutsegel wollen den Baron und seinen Flottenmeister tot sehen und machen jeden zum Admiral, der ihnen ihre Köpfe bringt." },
        { "Ihre Schiffe liegen vor der Küste des Schlingendorntals, die CRIMSON VEIL unter ihnen, und ihre Lager halten die Buchten der ungezähmten Küste. Ihr Flottenmeister ist Firallon, von dem die Seeleute der Schwarzmeerräuber sagen, er könne kein Beiboot über einen See segeln. Geschlagen haben sie ihn noch nicht." },
      },
    },
    ["bloodscalp-and-skullsplitter"] = {
      title = "Die Bloodscalp und die Skullsplitter",
      text = {
        { "Die Bloodscalp halten den Nordwesten des Schlingendorntals. Die Skullsplitter bewohnen den mittleren Dschungel. Beide leben zwischen den Ruinen ihrer Ahnen, der Gurubashi. Ihre Kopfjäger streifen durch den Norden, nehmen Köpfe und Trophäen, und die beiden Stämme begegnen einander mit beträchtlicher Feindseligkeit." },
        { "Nimboya verdächtigt die Bloodscalp, Yenniku festzuhalten, den jüngsten Sohn seines Häuptlings. Die Suche führt anderswohin: Zanzil der Ausgestoßene hat ihn unter seine magische Kontrolle gebracht. Merkt Euch diesen Unterschied, $gReisender:Reisende;. Der erste Feind, der in einer Ermittlung genannt wird, ist nicht immer der Verantwortliche." },
      },
    },
    ["bloodvenom-post"] = {
      title = "Blutgiftposten",
      text = {
        { "Der Blutgiftposten ist das Lager der Horde im Herzen des Teufelswalds, neben den vergifteten Fällen des Blutgiftflusses. Seine Leute kämpfen gegen den Schattenrat in Jaedenar und die verderbten Dinge des Waldes, und eine Witwe wartet dort auf Rache an dem Furbolg, der ihren Mann tötete." },
        { "Nicht jeder am Posten will den Teufelswald geheilt sehen. Eine Apothekerin der Verlassenen, Winna Hazzard, erforscht den verderbten Mondbrunnen der Jadefeuersatyrn und sucht in seinem Wasser einen Vorteil gegen die Allianz. Ich würde ihre Katze im Auge behalten." },
      },
    },
    ["blue-dragonflight"] = {
      title = "Der blaue Drachenschwarm",
      text = {
        { "Malygos, dem Zauberwirker, wurde die Sorge um die Magie gegeben, und sein Schwarm hat dafür bezahlt. Als Todesschwinge sich im Krieg der Urtume gegen die anderen Drachenschwärme wandte, litt der blaue Schwarm am schlimmsten. Sehr wenige überlebten, und Malygos ist seither nicht mehr derselbe." },
        { "Ihre Horte in diesen Landen sind wenige. Blaue Drachkin bewachen die Ufer des Mennarsees in Azshara, und die Höhlen von Mazthoril in Winterspring verbergen eine Zuflucht, in der ihre Schutzpatronin Haleh jene empfängt, die die Schuppe eines blauen Drachen besitzen und auf der richtigen Rune stehen. Die Aspekte, wird sie Euch sagen, bestehen darauf, dass ihre Schwärme sich aus den Angelegenheiten der Sterblichen heraushalten. Sie wird Euch auch sagen, dass Todesschwinges Kinder das schwierig machen." },
        { "Azuregos hält seine eigene Wache über die Ruinen im Süden von Azshara und sucht nach den arkanen Schätzen, die die Hochgeborenen zurückließen. Die Küste liegt seit zehntausend Jahren in Trümmern und gibt einem blauen Drachen noch immer Arbeit." },
      },
    },
    ["bolvar-fordragon"] = {
      title = "Hochlord Bolvar Fordragon",
      text = {
        { "Hochlord Bolvar Fordragon befehligt die Heere Stormwinds und steht dem Knabenkönig Anduin Wrynn zur Seite, solange dessen Vater Varian verschollen ist. Er ist ein Paladin der alten Schule, fromm, ehrlich und unerschütterlich, und er hält die Soldaten des Königreichs dort, wo das Königreich sie am dringendsten braucht, was selten dort ist, wo die Provinzen sie gern hätten." },
        { "Er ist ein vorsichtiger Mann, vielleicht zu vorsichtig. Als der Magistrat von Seenhain meldete, dass die Orcs der Blackrock Drachen hinter sich hätten, wollte Bolvar keine Truppen auf bloße Vermutungen hin bewegen und schickte den Boten, Lady Katrana Prestor um Rat zu fragen. Marshal Windsor, der den Beweis gefunden hatte, nannte ihn einen Narren: Der Beweis stehe zwei Fuß von ihm entfernt, sagte er, und er sehe ihn nicht. Als Windsor die Lady im Thronsaal als Onyxia entlarvte, die Tochter Todesschwinges, sagte er, selbst der Hochlord sei ihre Marionette gewesen, gehalten von einem Drachenmedaillon. Am Ende blieb Bolvar mit dem zerschmetterten Medaillon in der Hand zurück." },
        { "Er ist kein Narr. Er ist ein ehrlicher Mann, der einem Drachen aufs Wort glaubte, und ich bezweifle, dass er es noch einmal tun wird." },
      },
    },
    ["booty-bay"] = {
      title = "Booty Bay",
      text = {
        { "Booty Bay klammert sich an die Klippen einer Meereshöhle an der Südspitze des Schlingendorntals. Holzhäuser, Pfähle und Hängebrücken drängen sich um seinen Hafen. Das gewaltige offene Maul eines Hais markiert den Eingang. Baron Revilgaz führt den Hafen für das Steamwheedle-Kartell, mit dem Ziel, ihn neutral und einträglich zu halten." },
        { "Auch seine Schwarzmeerräuber sind hier zu Hause. Sie liegen im Krieg mit den Blutsegelbukanieren, die den Baron tot sehen wollen. Ein Händler findet in der Bucht einen Hafen, ein bewaffneter Reisender findet Arbeit in dem Streit dahinter. Revilgaz hat Geschäfte für beide." },
      },
    },
    ["boulderslide-ravine"] = {
      title = "Steinschlagklamm",
      text = {
        { "Im Südosten des Steinkrallengebirges gibt es eine Klamm mit einer tiefen Höhle, und die Kobolde darin haben wie besessen gegraben, auf der Suche nach einem seltenen Kristall, den sie Resonit nennen. Die Schamanen von Sonnenfels spürten etwas Falsches unter den Bergen und gingen nachsehen, und am Grund der Höhle fanden sie ein Fass voller Resonit, und darin schlafend einen der Irdenen: ein Wesen aus lebendem Stein namens Goggeroc." },
        { "Die Irdenen wurden, wenn man den Scheiben von Uldaman glauben darf, von den Titanen geschaffen, um die Welt zu formen, und sie sind die Vorväter meines eigenen Volkes. Ich hätte sehr viel darum gegeben, mit einem zu sprechen. Die Schamanen von Sonnenfels hielten ihn für eine Bedrohung des Landes, weckten ihn geschwächt und vernichteten ihn, bevor er zu Kräften kommen konnte, und die Kobolde gruben weiter." },
        { "Ich sage nicht, dass sie unrecht hatten. Ich war nicht dabei. Aber ich wüsste sehr gern, was ein Irdener schlafend in einem Fass unter dem Steinkrallengebirge tat, und wer ihn dort hineingelegt hat." },
      },
    },
    ["brackenwall-village"] = {
      title = "Brackenwall",
      text = {
        { "Brackenwall ist das Lager der Horde in Dustwallow, gehalten von Orcs und von den Ogern des Klans der Stonemaul. Die Stonemaul sind Verbündete der Horde, dank dem Tiermeister Rexxar, der ihren Oberherrn Mok'Morokk zum Anführer des Klans machte. Die Oger erzählen es Euch, und zwar häufig." },
        { "Sie kamen nach Brackenwall, weil sie mussten. Onyxias Brut fiel über ihre alte Heimat im Süden der Marsch her und brannte sie aus, und das klügste Mitglied des Klans, ein zweiköpfiger Oger, der besser spricht als die meisten Zwerge, versucht herauszufinden, warum. Die Horde wüsste auch gern, warum die Tochter Todesschwinges sich für eine kleine Schar Oger interessiert." },
      },
    },
    ["brill"] = {
      title = "Brill",
      text = {
        { "Brill war ein stilles Bauerndorf an der Straße östlich von Deathknell, und die Verlassenen haben es zu ihrem gemacht: Im Rathaus sitzt ein Magistrat, die Taverne Zur Galgenschlinge schenkt ihre seltsamen Getränke an seltsame Gäste aus, und in ihrem Keller hält die Todeswache ihre Gefangenen fest, zwergische Gebirgsjäger darunter, bis man sich ihrer annehmen kann." },
        { "Hier verrichtet auch die Königliche Apothekervereinigung einen guten Teil ihrer Arbeit. Mehr will ich dazu nicht sagen, als dass ein Zwerg in Brill kein Getränk annehmen sollte." },
      },
    },
    ["bronze-dragonflight"] = {
      title = "Der bronzene Drachenschwarm",
      text = {
        { "Nozdormu, dem Zeitlosen, wurde die Hut über die Zeit gegeben, und sein Schwarm bewacht ihre Pfade. Man sieht sie selten. Wenn doch, dann meist, weil etwas damit schiefgegangen ist, wann die Dinge geschehen." },
        { "In Andorhal geht einer von ihnen als seltsame kleine Gnomin namens Chromie umher und hat einen Raum des zerstörten Gasthauses in einen Ort verwandelt, der nicht ganz zum Rest der Stadt gehört. Sie sagt, die Geißel habe sich dort an der Zeit zu schaffen gemacht. Sie jagt die Parasiten, die sich von ihren zerrissenen Fäden nähren, und sie hat einem Reisenden geholfen, das Schicksal eines Mannes zu ändern, der in Darrowshire fiel." },
        { "In Tanaris, nahe den Höhlen der Zeit, wartet Anachronos, der vor tausend Jahren am Skarabäuswall war, als er versiegelt wurde. Der bronzene Schwarm erinnert sich an den Krieg gegen Ahn'Qiraj, weil er darin kämpfte. Fragt sie, was sie über morgen wissen, $gReisender:Reisende;, und sie werden lächeln und sagen, Eure größten Taten stünden Euch noch bevor." },
      },
    },
    ["burning-blade"] = {
      title = "Die Burning Blade",
      text = {
        { "Die Burning Blade war einst ein Klan der Orcs, berühmt für seine Klingenmeister, und einige dieser Klingenmeister rissen sich von den Dämonen los und dienen Thrall noch heute. Der Rest des Namens ist an einen Kult gegangen. Die Burning Blade von heute ist eine Bruderschaft von Hexenmeistern und Fanatikern, die die Dämonen verehren, die ihr Volk einst versklavten, und dem Schattenrat gehorchen, der die Horde in diese Welt brachte." },
        { "Sie sind die eigene Schande der Horde, versteckt in ihren eigenen Landen. Sie halten die Höhlen der Knochenhöhle in Durotar, in Sichtweite von Orgrimmar, und den Glutnebelgipfel im Brachland, wo eine Teufelswache über das wacht, was sie die Dämonensaat nennen, eine Verbindung zur Legion selbst. In Desolace haben sie die Festung Thunder Axe für sich genommen, und in den Abgründen unter Orgrimmar selbst plant ein Zweig, der sich Sengklinge nennt, im Dunkeln. Thralls Volk jagt sie, wo immer es sie findet." },
        { "Sie kamen näher daran, einen neuen Krieg zu beginnen, als irgendwer zugeben mag. Ein paar Jahre nach dem Hyjal nahm ein niederer Dämon namens Zmodlor den Kult in die Hand und hetzte Durotar und Theramore gegeneinander: angegriffene Schiffe, Überfälle, die man der anderen Seite anlastete, ein Verräter, der im Rat jedes Anführers flüsterte, Lady Jaina Proudmoores eigener Kämmerer darunter. Jaina und Thrall deckten es gemeinsam auf, und der Frieden hielt. Der Kult war nicht am Ende, wie Euch die Knochenhöhle verraten wird." },
      },
    },
    ["burning-legion"] = {
      title = "Die Brennende Legion",
      text = {
        { "Die Brennende Legion ist ein Heer aus Dämonen, von dem gefallenen Titanen Sargeras aus tausend eroberten Welten zusammengetragen, und sie ist dreimal wegen unserer gekommen. Das erste Mal vor zehntausend Jahren, durch den Brunnen der Ewigkeit der Nachtelfen. Das zweite Mal durch die Orcs, die ihre Diener verdarben und durch das Dunkle Portal schickten. Das dritte Mal war der letzte Krieg, als ihr General Archimonde am Fuß des Weltenbaums auf dem Hyjal fiel." },
        { "Ganz gegangen ist sie nie. Lord Kazzak hält die Verwüsteten Lande mit einem Heer von Dämonen rund um das ruhende Dunkle Portal. Die Hexenmeister des Schattenrats halten Dämonen in Jaedenar, im Teufelswald, wo der ganze Wald um sie herum verfault ist. Verdammniswachen und Höllenbestien wandeln durch den Demonfall-Canyon in Ashenvale, wo Grom Hellscream Mannoroth tötete, durch Mannorocs Koven in Desolace und durch die Ruinen von Azshara." },
        { "Die Legion ist geduldig. Sie hat drei Kriege verloren und ist noch immer hier, und ich glaube nicht, dass sie mit uns fertig ist." },
      },
    },
    ["burning-steppes"] = {
      title = "Brennende Steppe",
      text = {
        { "Die Brennende Steppe liegt südlich des Blackrock, eine weite Ebene aus Asche, Lava und schwarzem Fels unter einem roten Himmel. Einst war all dies das Nordende des Rotkammgebirges, bevor Thaurissan den Feuerlord weckte. Die Explosion, die folgte, nahm die Berge, die Wälder und die eigene Stadt der Dunkeleisenzwerge und hinterließ dies." },
        { "Es ist ein Land im Krieg. Die Orcs der Blackrock aus der Dunklen Horde halten die Spitze und die Pässe, der schwarze Drachenschwarm nistet auf den Höhen, und Oger halten den Schreckensfels. Die Allianz hat einen Stützpunkt in Morgans Wacht im Südosten, und es gibt einen kleinen neutralen Außenposten am Flammenkamm, auf einem Felsen über der Lava, wo jeder rasten kann." },
      },
    },
    ["caer-darrow"] = {
      title = "Caer Darrow",
      text = {
        { "Caer Darrow ist eine Burg auf einer Insel im Darrowmeresee, im Süden der Westlichen Pestländer, und sie war der Sitz des Hauses Barov, einer der großen Adelsfamilien Lordaerons. Es ist ein stiller, nebliger, schöner Ort. Seine Stadt ist voller Geister." },
        { "Die Barovs haben sie verschenkt. Um ihr Vermögen zu behalten, als die Seuche kam, schlossen sie einen Handel mit Kel'Thuzad und übergaben ihre Burg dem Kult der Verdammten, der unter ihr die Scholomance grub, die Schule der Geißel für Nekromantie. Am Ende behielten die Barovs von gar nichts viel." },
      },
    },
    ["cairne-bloodhoof"] = {
      title = "Cairne Bloodhoof",
      text = {
        { "Cairne Bloodhoof ist der Oberhäuptling der Tauren, Häuptling des Stammes der Bloodhoof und der älteste Freund, den die Horde in Kalimdor hat. Als Thralls Orcs an Land kamen, führte er sein Volk über die Ebenen, mit den Zentauren auf den Fersen, und die Orcs kämpften an ihrer Seite. Cairne vergalt es ihnen mit Freundschaft und Rat, und seither gehören die Tauren zur Horde." },
        { "Er ist heute sehr alt und sehr groß, und er spricht langsam und selten. Er erbaute Thunder Bluff, versammelte die Stämme dort und gab den Tauren zum ersten Mal, seit sie sich erinnern, eine Heimat. Sein Sohn Baine hält Bloodhoof, und einmal, so sagt man, wurde er von den Zentauren verschleppt und von einem Tiermeister der Horde zurückgebracht." },
        { "Die Orcs verehren ihn, und die Allianz traut ihm weiter als jedem anderen Anführer der Horde. Beide, so glaube ich, haben recht." },
      },
    },
    ["camp-mojache"] = {
      title = "Camp Mojache",
      text = {
        { "Camp Mojache ist das Lager der Horde im Osten von Feralas, ein Ring aus Taurenzelten und Totems auf einem Hügel zwischen den riesigen Bäumen, nahe der Straße nach Düsterbruch. Die Tauren hier beobachten die Oger der Gordunni, deren Zahl wächst, und ihre Vettern, die Grimmtotem, in den Hügeln im Süden, die keine Freunde von Thunder Bluff sind." },
        { "Die Weisen des Lagers haben ihr eigenes Interesse an den Ruinen. Sie suchen einen elfischen Meister, der mit uralten Artefakten vor dem Fall von Quel'Thalas floh, und sie glauben, er sei nach Düsterbruch gegangen." },
      },
    },
    ["camp-narache"] = {
      title = "Camp Narache",
      text = {
        { "Camp Narache liegt auf dem Red Cloud Mesa im Süden von Mulgore, ein Ring aus Fellzelten und Totems um ein Feuer, und hier beginnen junge Tauren. Häuptling Hawkwind und seine Familie halten das Lager, und sie stellen den Jungen den ersten der Riten der Erdenmutter: den Ritus der Kraft, bewiesen gegen die Stacheleber, die sich in die Schlucht darunter geschlichen haben." },
        { "Es ist zuerst ein Jagdlager. Die Tauren jagen aus Not und aus Freude, und von einem jungen Tauren erwartet man, dass er Federn und Fleisch heimbringt, bevor jemand fragt, was er sonst noch kann." },
      },
    },
    ["camp-taurajo"] = {
      title = "Camp Taurajo",
      text = {
        { "Camp Taurajo ist ein Lager der Tauren im Süden des Brachlands, Zelte und Totems um ein Feuer, der letzte freundliche Ort an der Straße nach Tausend Nadeln. Seine Leute jagen in den südlichen Ebenen und behalten die Stacheleber in den Dornen von Razorfen im Auge." },
        { "Es hat einen seltsamen Gast: einen Stacheleber namens Quetschzahn, einen Gefangenen der Tauren, der die Segnungen des Ebergottes Agammagan kennt und sie jedem lehrt, der ihm die richtigen Steine bringt. Die Tauren dulden ihn. Er ist, so sagt man mir, sehr unhöflich." },
      },
    },
    ["captain-varothen"] = {
      title = "Hauptmann Varo'then",
      text = {
        { "Hauptmann Varo'then befehligte im Krieg der Urtume die Garde von Königin Azshara: ein vernarbter Soldat, der behauptete, gegen ihre Reize gefeit zu sein, und, so erzählen die Geschichten, hoffnungslos in sie verliebt war. Stattdessen erfüllte er ihr jede Laune. Er holte die Dämonenseele für die Legion und pflegte bis zum Ende eine Fehde mit Malfurion Stormrage." },
        { "In der letzten Schlacht über dem Brunnen führte er die Hochgeborenen, die der Königin noch treu waren, und sagte Malfurion, er lebe nur, um ihr zu dienen, selbst wenn es das Ende Kalimdors bedeute. Es waren fast die letzten Worte, die er sprach. Kalimdor, so geht die Geschichte, nahm ihn beim Wort und stieß ihn ab." },
        { "Sein Geist wandelt durch die Ruinen des Shadowsong-Schreins, noch immer in der Rüstung der königlichen Garde. Was auch immer er jetzt bewacht, zehntausend Jahre haben ihn nicht davon entbunden." },
      },
    },
    ["caverns-of-time"] = {
      title = "Die Höhlen der Zeit",
      text = {
        { "Im Osten von Tanaris, zwischen den Felsen über dem Meer, führt eine Höhle hinab in die Höhlen der Zeit, den Hort des bronzenen Drachenschwarms. Ihr Herr ist Nozdormu, der Zeitlose, der Drachenaspekt, der über die Zeit wacht, und seine Drachen bewachen ihre Pfade, damit das, was war, nicht ungeschehen gemacht werden kann." },
        { "Kein Reisender kommt weit hinein. Doch am Eingang der Höhlen hat man einen bronzenen Drachen in sterblicher Gestalt warten sehen, Anachronos, und er weiß sehr viel über den Krieg gegen die Insekten von Silithus vor tausend Jahren und über den Anteil, den sein Schwarm daran hatte." },
      },
    },
    ["cenarion-circle"] = {
      title = "Der Zirkel des Cenarius",
      text = {
        { "Der Zirkel des Cenarius ist die Gemeinschaft der Druiden, benannt nach dem Halbgott Cenarius, der die ersten von ihnen lehrte. Sein Gründer war Malfurion Stormrage, der die Nachtelfen vor zehntausend Jahren gegen die Brennende Legion führte und nun vermisst wird. Seine Mitdruiden wissen nicht, was aus ihm geworden ist. Den größten Teil seiner Geschichte war der Zirkel ein Orden der Nachtelfen. Heute haben auch die Tauren ihre Druiden darin, und Erzdruide Hamuul Runetotem vertritt sie in Thunder Bluff." },
        { "Sein Sitz ist Nighthaven, in Moonglade, unter Bewahrer Remulos, dem Sohn des Cenarius, und sowohl die Allianz als auch die Horde dürfen dort in Frieden wandeln. Er unterhält Posten überall dort, wo die Natur verwundet ist: auf dem Steinkrallengipfel, in den vergifteten Wäldern des Teufelswalds und in Burg Cenarius in Silithus, von wo aus er die Insektenstöcke und die Mauern von Ahn'Qiraj beobachtet." },
        { "Die Druiden sind geduldig über das Verständnis jedes Zwerges hinaus, und sie denken in Jahreszeiten und Jahrhunderten. Wenn der Zirkel sagt, dass etwas nicht stimmt, hören die Weisen zu." },
      },
    },
    ["cenarion-hold"] = {
      title = "Burg Cenarius",
      text = {
        { "Burg Cenarius ist die Festung des Zirkels des Cenarius im Norden von Silithus, errichtet, um die Stöcke und die versiegelte Stadt im Süden zu beobachten. Die Druiden, Allianz wie Horde, halten ihre Mauern, und der Krieg gegen die Silithiden wird von hier aus geführt." },
        { "Manche in der Burg sind nicht, was sie scheinen. Unter den Druiden lebt die Brut Nozdormus, der bronzene Drachenschwarm in sterblicher Gestalt, der sich an den Krieg erinnert, der hier vor tausend Jahren geführt wurde, und auf seine Rückkehr achtet." },
      },
    },
    ["cenarius"] = {
      title = "Cenarius",
      text = {
        { "Cenarius war der Herr der Wälder, ein Halbgott mit dem Körper eines Hirsches unterhalb der Hüfte und einem verzweigten Geweih, und der erste Lehrer der Nachtelfen. Lange vor der Großen Teilung gewann er ihr neugieriges junges Volk lieb und lehrte es die Wege der lebendigen Welt. Malfurion Stormrage war sein größter Schüler, und das Druidentum ist, was sie gemeinsam schufen." },
        { "Er kämpfte im Krieg der Urtume gegen die Legion und führte die Urtume des Waldes gegen die Dämonen, überlebte die Große Teilung und half Malfurion, Illidan wegzusperren. Danach blieb er in Moonglade auf dem Hyjal. Seine Söhne, die Hüter des Hains, wachten über die Nachtelfen, während die Druiden schliefen, und seine Töchter, die Dryaden, zeigten sich kühner." },
        { "Im Dritten Krieg kam er aus dem Wald, um Grom Hellscreams Orcs aus Ashenvale zu vertreiben, und die Orcs, wahnsinnig vom Dämonenblut, töteten ihn. Seine Kinder wandeln noch durch die Wälder Kalimdors, von Raynewood bis zum Steinkrallengebirge, und Remulos hütet Moonglade in seinem Namen. Das Gedächtnis eines Hüters ist lang. Ich würde bei einem von ihnen nicht das Thema Orcs anschneiden." },
      },
    },
    ["centaurs"] = {
      title = "Die Zentauren",
      text = {
        { "Die Zentauren stammen von Zaetar ab, einem Sohn des Cenarius, und von Theradras, einer Prinzessin der elementaren Erde. Sie töteten ihren Vater. Ihre Mutter begrub ihn in Maraudon. Seine Kinder bewachen das Grab noch heute als heiligen Boden." },
        { "Zu ihren Klans gehören die Kolkar im Brachland und in Desolace, die rivalisierenden Gelkis und Magram, die Galak in Tausend Nadeln und die Maraudine am Grab. Generationenlang verfolgten sie die Tauren über die Ebenen Kalimdors, bis Cairne und seine Verbündeten, die Orcs, sie zurückdrängten." },
        { "Die Klans überfallen weiterhin. Lernt ihre Namen ebenso wie das Geräusch ihrer Hufe, $gReisender:Reisende;. Die Streitigkeiten zwischen ihnen zählen für alle, die in Reichweite ihrer Lager zu leben versuchen." },
      },
    },
    ["chillwind-camp"] = {
      title = "Chillwind-Lager",
      text = {
        { "Kommandant Ashlam Valorfist führt das Lager der Allianz in den südlichen Hügeln der Westlichen Pestländer, nahe dem Darrowmeresee. Seine Zelte haben Soldaten, Verbannte und Gelehrte angezogen, darunter Weldon Barov, den letzten lebenden Lord seines Hauses." },
        { "Von hier greift die Allianz Andorhal an und arbeitet gegen die Seuchenkessel. Das Lager hat wenig Bequemlichkeit oder Vorräte übrig. Wenn Ihr Hilfe anzubieten habt, $gReisender:Reisende;, hat Valorfist gute Verwendung dafür. Seine Zelte sind ein kleiner Anfang für die Arbeit, die vor ihm liegt." },
      },
    },
    ["church-of-the-holy-light"] = {
      title = "Die Kirche des Heiligen Lichts",
      text = {
        { "Die Kirche des Heiligen Lichts lehrt, dass Tugend, Mitgefühl und Opferbereitschaft aus einer Macht schöpfen, die heilen und schützen kann. Der Glaube kam aus Lordaeron in den Süden, und die Kathedrale des Lichts in Stormwind ist heute sein Sitz, unter Erzbischof Benedictus. Auch die Zwerge haben seine Wege von ihren menschlichen Nachbarn gelernt." },
        { "Im Zweiten Krieg gründete Erzbischof Alonsus Faol die Ritter der Silbernen Hand. Diese ersten Paladine, angeführt von Uther Lightbringer, trugen das Licht neben ihren Schwertern auf das Schlachtfeld. Seit dem Fall Lordaerons ist Stormwind zum Mittelpunkt der Kirche geworden, und ihre Priester und Paladine dienen überall in der Allianz." },
        { "Glaubensfragen können einen Gelehrten jahrelang beschäftigen. Ein verwundeter Reisender hat einen unmittelbareren Grund, für die Gelehrsamkeit eines Priesters dankbar zu sein." },
      },
    },
    ["coldridge-valley"] = {
      title = "Das Coldridgetal",
      text = {
        { "Anvilmar versammelt zwergische und gnomische Rekruten im Coldridgetal, südlich von Kharanos. Hier finden sie ihre Lehrer, ihre ersten Befehle und den Gebirgspass, der sie hinaus nach Dun Morogh führt. Ein bescheidener Anfang vielleicht, aber jeder Weg hat einen." },
        { "Die Befehle betreffen mehr als Übungen. Troggs der Felsenkiefer bedrohen das Tal, Trolle der Frostmane haben in der Nähe ein Lager aufgeschlagen, und Balir Frosthammer und Grelin Whitebeard brauchen Hilfe gegen sie. Haltet Eure Waffe bereit, $gReisender:Reisende;. Die Rekruten werden gebraucht, bevor sie das Tal überhaupt verlassen haben." },
      },
    },
    ["crystal-pylons"] = {
      title = "Die Kristallpylonen",
      text = {
        { "J.D. Collies Arbeit beginnt mit den farbigen Kristallen, die über ganz Un'Goro verstreut sind. Berichte über große Pylonen, die mit Kristallen besetzt sind, führen ihre Nachforschungen in die Wildnis, wo drei davon im Norden, Osten und Westen des Kraters stehen." },
        { "Verschiedene Kombinationen erzeugen an diesen Pylonen nützliche Wirkungen, und Collie hat ein Handbuch für weitere Versuche geschrieben. Die Expedition kann jetzt etwas mit den Kristallen anfangen, auch wenn die Absichten ihrer Erbauer ein Rätsel bleiben. Es liegt eine ehrliche Befriedigung in einer Entdeckung, die die Werkbank erreicht, bevor sie die Geschichtsbücher erreicht." },
      },
    },
    ["cthun"] = {
      title = "C'Thun",
      text = {
        { "C'Thun liegt unter dem Tempel von Ahn'Qiraj, eine der uralten Mächte, die man die Alten Götter nennt. Ein gewaltiges Auge und Massen von Tentakeln füllen seine Kammer. Die Qiraji und ihre Schwärme von Silithiden dienen ihm." },
        { "Wer sich nähert, hört Flüstern im eigenen Geist, Versprechen und Drohungen, die dem Geschöpf darunter gehören. Die Expedition fand und erschlug es. Ich kann diese Ereignisse niederschreiben, $gReisender:Reisende;, doch es bereitet mir wenig Freude, ein Ding zu verzeichnen, das seinen Betrachtern in ihren eigenen Gedanken antworten kann." },
      },
    },
    ["cult-of-the-damned"] = {
      title = "Der Kult der Verdammten",
      text = {
        { "Kel'Thuzad war ein Erzmagier Dalarans und Mitglied seines herrschenden Rates, und er suchte in den nekromantischen Künsten nach verbotenen Dingen, bis etwas antwortete: der Lichkönig. Kel'Thuzad verließ die Kirin Tor, ging unter die Armen und Verzweifelten Lordaerons und versprach ihnen eine Welt ohne Könige und ohne Hunger. Sie wurden zum Kult der Verdammten, und sie glaubten ihm." },
        { "Das Werk des Kults war die Seuche. Seine Leute verseuchten die Kornspeicher von Andorhal und die Dörfer im Norden, und die Toten erhoben sich, wo immer das Getreide gegessen wurde. Prinz Arthas tötete Kel'Thuzad in Andorhal, doch der Lichkönig brauchte ihn, und er kehrte als Lich zurück. Das Haus Barov übergab dem Kult seine Burg in Caer Darrow, und in ihren Gewölben unterhalten sie ihre Schule der Nekromantie, die Scholomance." },
        { "Sie sind lebende Männer und Frauen, was ich schlimmer finde als die Toten. Ein Ghul hat keine Wahl, wem er dient. Die Nekromanten des Kults haben gewählt." },
      },
    },
    ["daelin-proudmoore"] = {
      title = "Daelin Proudmoore",
      text = {
        { "Daelin Proudmoore, Lordadmiral von Kul Tiras, war ein Held des Zweiten Krieges: Er befehligte die Flotten der Allianz an der Seite von Anduin Lothar und Uther Lightbringer, und er vergab den Orcs nie. Er hatte auch eine Tochter, Jaina, die nach Dalaran ging, um Magie zu studieren." },
        { "Er segelte mit seiner Flotte aus Lordaeron fort, bevor Arthas es zerstörte, suchte die Meere nach Überlebenden ab und fand nach vielen Monaten Kalimdor, und seine Tochter, im Frieden mit der Horde. Das wollte er nicht hinnehmen. Er setzte seine Marinesoldaten an der Küste von Durotar an Land, errichtete diese Burg und machte sich daran, die Orcs zu vernichten, bevor sie Wurzeln schlagen konnten." },
        { "Jaina musste zwischen ihrem Vater und dem Frieden wählen, und sie wählte den Frieden. Daelin starb in den Kämpfen, bevor sie sich versöhnen konnten. Seine Flotte liegt als Wrack vor diesem Strand, und ein paar seiner Männer halten noch immer die Burg, mitten in einem Land, das nach einem Orc benannt ist." },
      },
    },
    ["dagran-thaurissan"] = {
      title = "Imperator Dagran Thaurissan",
      text = {
        { "Dagran Thaurissan herrscht über die Dunkeleisenzwerge in der Schattenschmiede, ein Nachfahre des Zauberthans, der Ragnaros herbeirief. Er trägt den Namen seines Ahnen, und ich hüte die Geschichte seines Ahnen. Ich bezweifle, dass wir uns über viel davon einig wären. Der Imperator nennt sich den mächtigsten Diener des Feuerlords. Seine Krone hat seinen Klan nicht von der Macht befreit, die sein Ahne über ihn brachte." },
        { "Er trägt Ironfoe, und seine Agenten sind bis nach Gnomeregan gelangt. Außerdem hat er König Magnis Tochter Moira zu seiner Braut gemacht. Magni schickte Streiter, um ihn zu töten und sie heimzubringen. Sie töteten den Imperator. Moiras Antwort machte den Rest ihres Auftrags um einiges weniger einfach." },
      },
    },
    ["dalaran"] = {
      title = "Dalaran",
      text = {
        { "Dalarans Türme standen jahrhundertelang am Lordameresee, Heimat der Kirin Tor und von Generationen von Schülern der Magie. Im Dritten Krieg nahm die Geißel die Stadt ein und tötete Antonidas. Archimonde zerstörte dann, was ihre Verteidiger nicht hatten retten können." },
        { client = "classic", "Die überlebenden Kirin Tor haben eine große Kuppel aus violettem Licht über den Ruinen errichtet und mit dem Wiederaufbau begonnen. Ihre Zauberer arbeiten noch immer in Hillsbrad und im Silberwald, im alten Internierungslager und in Ambermill. Erzmagier Ansirem Runeweaver empfängt Reisende vor der Kuppel. Es hat etwas Ermutigendes, wenn eine Stadt neu beginnt, selbst wenn ihre Erbauer darauf bestehen, die Vorhänge zuzuziehen." },
        { client = "forever", "Der Wiederaufbau ist von einer Krise in der Stadt eingeholt worden. Etwas hat ihre Kraftlinien gestört und ihre Konstrukte unberechenbar und zerstörerisch gemacht. Der Rat will die Sache unter sich behalten. Modera, deren Abbild am Lordameresee wartet, hat um Hilfe von außen gerufen. Die Magier haben die Zerstörung einer Stadt überlebt. Sie ist nicht bereit, ihren Stolz zur Zerstörung einer weiteren beitragen zu lassen." },
      },
    },
    ["dalsons-tears"] = {
      title = "Dalsons Tränenfeld",
      text = {
        { "Der Hof, den die Pestländer Dalsons Tränenfeld nennen, gehörte einer Familie namens Dalson, und ihre Geschichte liegt aufgeschlagen auf einem Tisch im Haus, in Frau Dalsons eigener Handschrift. Ihr Mann Harold hatte sich verwandelt. Es kostete sie alles, was sie hatte, ihn an den einzigen Ort zu schleifen, den sie fand und der sich abschließen ließ, und sie behielt den Schlüssel bei sich." },
        { "Sie wollte fort, doch sie brauchte Geld, und ihre Sachen waren im Schrank, und sie glaubte, Harold habe diesen Schlüssel bei sich. Sie wolle darüber schlafen, schrieb sie. Sie sei todmüde. Das ist der letzte Eintrag. Was aus ihr wurde, sagt das Tagebuch nicht." },
        { "Die Geißel hat seither einen ihrer Seuchenkessel auf das Feld der Familie gestellt, und die Allianz in Chillwind und die Verlassenen am Bollwerk schicken beide Reisende, um seine Gifte umzukehren. Hof um Hof sind die Pestländer voller Häuser wie diesem. Dies ist das eine, in dem jemand es aufgeschrieben hat." },
      },
    },
    ["dark-iron-dwarves"] = {
      title = "Die Dunkeleisenzwerge",
      text = {
        { "Der dritte der drei Hämmer, und derjenige, der nie vergab. Seit die Dunkeleisenzwerge ihren Krieg gegen Ironforge verloren und in ihrer Wut Ragnaros weckten, leben sie im Blackrock unter ihrem Imperator Dagran Thaurissan und dienen dem Feuerlord, den sie herbeiriefen." },
        { "Dort geblieben sind sie nicht. Ihre Sklaven graben den Kessel in der Sengenden Schlucht, ihre Gräber der Schattenschmiede plündern die Ruinen von Uldaman und halten die Festung Angor im Ödland, ihre Spione schleichen durch Dun Morogh, und ihre Plünderer machen Loch Modan zu schaffen. Im Sumpfland haben sie echten Schaden angerichtet: Sie nahmen die Festung Dun Modr ein und zerbrachen den Thandol-Übergang, die große Brücke nach Norden." },
        { "Ein Dunkeleisenzwerg kämpft mit Feuer, Schwarzpulver und einem Groll, der zwei Jahrhunderte tief reicht. Kehrt einem niemals den Rücken zu." },
      },
    },
    ["darkshire"] = {
      title = "Dunkelhain",
      text = {
        { "Dunkelhain ist die einzige Stadt, die im Dämmerwald übrig ist, ein Haufen Häuser, ein Rathaus und ein Gasthaus hinter Laternen, die Tag und Nacht brennen. Ihr Oberbürgermeister Ello Ebonlocke regiert sie mit einem Rat, und seine Verwandten befehligen die Nachtwache. Eine Historikerin, Sirra Von'Indi, führt ihre Aufzeichnungen und übersetzt alles, was Ihr bringt, irgendwann." },
        { "Es ist eine Stadt grimmiger Leute und grimmiger Witze, und mehr Geschichten, als eine Stadt dieser Größe haben sollte. Fragt die alte Wahrsagerin Madame Eva nach irgendeiner davon. Sie weiß schon, nach welcher Ihr fragen werdet." },
      },
    },
    ["darkshore"] = {
      title = "Dunkelküste",
      text = {
        { "Die Dunkelküste ist ein langer Streifen nebliger Küste am Nordrand Kalimdors, dunkler Kiefernwald auf der einen Seite und graues Meer auf der anderen, mit Teldrassil, das im Westen aus dem Wasser ragt. Die Nachtelfen leben hier seit der Zeit vor der Großen Teilung, und die Küste ist voller ihrer Ruinen: Türme und Hallen der Hochgeborenen, des alten Adels am Hof von Königin Azshara, deren Geister noch darin wandeln." },
        { "In letzter Zeit ist es eine unruhige Küste. Große Meeresgeschöpfe werden an die Strände gespült, um dort zu sterben, die Furbolgs der Schwarzfelle sind wild geworden, Naga streifen an den Ufern, und der Twilight-Hammer hat im Süden ein Lager aufgeschlagen. Die Nachtelfen von Auberdine sind besorgt und sagen es auch, was für Nachtelfen sehr viel ist." },
      },
    },
    ["darkspear-trolls"] = {
      title = "Die Dunkelspeertrolle",
      text = {
        { "Die Dunkelspeer sind Dschungeltrolle, verwandt mit den Gurubashi des Schlingendorntals. Als Thralls Flotte auf ihrer Reise nach Kalimdor ihre Inseln erreichte, kämpfte der Stamm gegen Murlocs und ihre Meerhexe. Die Orcs kämpften an ihrer Seite. Häuptling Sen'jin starb, und die überlebenden Dunkelspeer folgten Thrall über das Meer." },
        { "Vol'jin führt sie nun von Orgrimmar aus, nah beim Kriegshäuptling. Ihre Jäger, Schamanen und Hexendoktoren dienen überall in der Horde und halten an den alten Loa der Trolle fest, während sie sich unter neuen Verbündeten ein Zuhause schaffen." },
      },
    },
    ["darnassus"] = {
      title = "Darnassus",
      text = {
        { "Darnassus steht in der Krone Teldrassils, eine neue Hauptstadt, nach dem Dritten Krieg erbaut. Mondlicht, Wasserfälle und das Leuchten des Tempels des Mondes füllen eine Stadt mit wenigen Mauern und Hallen, die zwischen den Ästen gewachsen sind. Ein Zwerg aus Ironforge ist gewohnt, deutlich mehr Stein über dem Kopf zu haben." },
        { "Die Nachtelfen haben sich der Allianz angeschlossen und diese Stadt Besuchern von Völkern geöffnet, von denen sie sich lange ferngehalten haben. Tyrande Whisperwind führt die Priesterinnen vom Tempel aus, während Fandral Staghelm die Druiden in der Enklave des Cenarius leitet. Merkt Euch diese beiden Orte, $gReisender:Reisende;. Vieles von dem, was in der Stadt geschieht, beginnt am einen oder am anderen." },
      },
    },
    ["darrowshire"] = {
      title = "Darrowshire",
      text = {
        { "Darrowshire war ein Dorf im Süden des Eastweald. Als die Geißel kam, standen seine Leute und kämpften, mit dem Paladin Davil Lightfire von der Silbernen Hand und Joseph Redpath an ihrer Spitze, gegen den Ghulfürsten Horgus und den Todesritter Marduk Blackpool. Eine Weile hielten sie stand. Am Ende riss Marduk sich los, verdarb Redpaths Geist und wandte ihn gegen die Verteidiger, und das Dorf starb." },
        { "Die Schlacht geht in Darrowshire noch immer weiter, unter den Geistern. Ein kleines Mädchen, Pamela Redpath, wandert durch die Ruinen und wartet darauf, dass ihr Vater heimkommt. Mit den Relikten der Schlacht, so heißt es, lassen sich die Geister von Darrowshire erwecken, um sie noch einmal zu schlagen, und diesmal kann Joseph Redpaths Seele vielleicht gerettet werden." },
        { side = "Horde", aside = true, sign = "P. F.", "Jedes Dorf im Eastweald hatte seinen Joseph Redpath. Darrowshire ist das eine, dessen Tote die Geschichte vielleicht noch anders zu Ende bringen. Helft ihnen, wenn Ihr könnt." },
      },
    },
    ["deadwind-pass"] = {
      title = "Gebirgspass der Totenwinde",
      text = {
        { "Der Gebirgspass der Totenwinde schneidet ein graues Tal zwischen dem Dämmerwald und den Sümpfen des Elends. Tote Bäume, Krähen und zerstörte Lager säumen den Weg. Es gibt keine bewohnten Dörfer oder Höfe, und die Oger bieten wenig Grund zu verweilen." },
        { "Medivhs Turm, Karazhan, steht in seinem Herzen, über verlassenen Gebäuden. Der Pass verbindet zwei bewohnte Gegenden, ohne ihre Annehmlichkeiten zu bieten." },
      },
    },
    ["deathknell"] = {
      title = "Deathknell",
      text = {
        { "Deathknell ist eine Gruft und ein zerstörtes Dorf am westlichen Rand von Tirisfal, und hier erwachen die Verlassenen. Die Toten Lordaerons, die sich mit eigenem Verstand erheben, werden hierher gebracht, und der Hüter der Gruft begrüßt sie mit den Worten, an die sich jeder von ihnen erinnert: Ihr seid nicht länger der Sklave des Lichkönigs." },
        { "Nicht alle, die sich erheben, haben so viel Glück. Der Norden des Dorfes ist voller geistloser Toter, die noch immer dem Lichkönig gehören, und die erste Pflicht der neu erwachten Verlassenen ist es, sie zu vernichten: ihre einstigen Brüder und Schwestern, wie die Schattenpriester der Kapelle sie erinnern." },
      },
    },
    ["deathstalkers"] = {
      title = "Die Todespirscher",
      text = {
        { "Die Todespirscher sind die Augen und Messer der Verlassenen: Lord Varimathras' Elitegarde, wie einer ihrer Anwerber es ausdrückt, den Heeren der Dunklen Fürstin vorausgeschickt, um zu sehen, was auf sie wartet. Man begegnet ihnen überall dort, wo die Verlassenen ihre Grenzen vorschieben: auf Erkundung in den Höfen des nördlichen Silberwalds, in Burg Shadowfang, um Arugal zu beobachten, auf den Hügeln über Hillsbrad, wo sie Berichte aus den Pestländern für Nathanos sammeln." },
        { "Man tritt ihnen nicht einfach durch Fragen bei. Rekruten beweisen ihren Wert und ihre Verschwiegenheit in den eigenen Hinterzimmern von Undercity. Ein solcher Auftrag fand heraus, dass das Syndikat, die gefallenen Lords von Alterac, einen Freund unter den Ladenbesitzern der Stadt hatte. Mit Varimathras' Billigung, prahlt einer von ihnen, wächst ihre Zahl." },
        { "Sie sind nicht alle so grimmig wie der Name. Rane und Quinn Yorick sind Brüder, und Rane, während Quinn kaum von den Klauen eines Ghuls genesen ist, will vor allem anderen ihren Bericht abgeliefert sehen. Tot, aber noch eifrig. Die Verlassenen sind voller Überraschungen." },
      },
    },
    ["deeprun-tram"] = {
      title = "Die Tiefenbahn",
      text = {
        { "Die Tiefenbahn befördert Reisende auf fahrenden Plattformen unter der Erde zwischen Ironforge und Stormwind. Sie hat eine Reise von Tagen auf wenige Minuten verkürzt. Selbst ein Zwerg, der gern zu Fuß geht, weiß diese Leistung zu schätzen." },
        { "Der Tunnel gibt unserer Freundschaft mit Stormwind eine praktische Gestalt: zwei Hauptstädte, verbunden durch einen Weg, der ihren Reisenden die lange Straße über Land erspart. Gnomischer Erfindungsgeist hat sehr vielen Stiefelpaaren das Leben gerettet." },
        { "Achtet auf die Fenster dort, wo der Tunnel durch Wasser führt, $gReisender:Reisende;. Manche Fahrgäste sagen, sie hätten etwas Großes zurückblicken sehen. Ihr solltet Zeit für einen Blick haben, bevor die Plattform Euch weiterträgt." },
      },
    },
    ["defias-brotherhood"] = {
      title = "Die Bruderschaft der Defias",
      text = {
        { "Als die Orcs Stormwind im Ersten Krieg schleiften, war es die Steinmetzgilde unter einem Meister namens Edwin van Cleef, die es wieder errichtete. Als die Arbeit getan war, wollte das Adelshaus sie nicht bezahlen. Van Cleef führte seine Steinmetze in einem Aufruhr durch die neuen Straßen und verließ die Stadt mit dem Schwur der Rache." },
        { "Aus der Gilde wurde eine Bande. In Westfall nahmen sie den Namen Bruderschaft der Defias an, banden sich rote Tücher vor die Gesichter und machten sich daran, das Ackerland zu ruinieren, das die Stadt ernährt: Felder verbrennen, Familien vertreiben und jeden zum Verbündeten machen, der sie haben wollte. Goblin-Ingenieure arbeiten für sie in den Todesminen, und ihr Arm reicht bis nach Elwynn, ins Rotkammgebirge, in den Dämmerwald und ins eigene Gefängnis der Stadt, wo van Cleefs Leutnant Bazil Thredd die Häftlinge zum Aufstand brachte." },
        { "Die Steinmetze hatten wegen ihrer unbezahlten Arbeit einen berechtigten Groll. Doch wofür die Bruderschaft auch einmal stand, die Bauern von Westfall haben weit teurer dafür bezahlt als irgendein Lord in Stormwind." },
      },
    },
    ["demon-fall-canyon"] = {
      title = "Demonfall-Canyon",
      text = {
        { "Nachdem Grom Hellscream das Blut des Dämons getrunken und Cenarius getötet hatte, jagten Thrall und Jaina Proudmoore ihn und befreiten ihn von seinem Fluch. Dann suchte Grom den Dämon. In einer Schlucht in Ashenvale fand er Mannoroth, den Grubenlord, dessen Blut die Orcs verdammt hatte, und tötete ihn mit seiner Axt, und starb daran." },
        { "Die Orcs erinnern sich an ihn als den, der sie befreite, und benannten ihre große Halle in Orgrimmar nach ihm. Die Schlucht ist noch immer ein Ort der Dämonen: Die Diener der Brennenden Legion halten sie, und der Boden, auf dem Mannoroth fiel, ist nie wieder rein geworden." },
      },
    },
    ["desolace"] = {
      title = "Desolace",
      text = {
        { "Desolace trägt seinen Namen zu Recht: ein graues, trockenes, tot wirkendes Land westlich des Steinkrallengebirges, alles aschfarbener Fels, verdorrte Bäume und Knochen. Viel wächst hier nicht. Gestorben wird reichlich: Die Kodos kommen dafür hierher, und ihre Skelette liegen aufgetürmt auf einem großen Friedhof mitten im Land." },
        { "Es gehört, wenn es überhaupt jemandem gehört, den Zentauren, deren Klans einander über das ganze Land hinweg bekämpfen und deren heiligster Ort, Maraudon, in seinem Südwesten liegt. Die Burning Blade hält eine Festung im Norden und öffnet Dämonen die Türen, Naga spuken an der Küste, und die Allianz und die Horde halten je einen kleinen, nervösen Außenposten. Es ist kein Land, das irgendwer liebt." },
      },
    },
    ["dire-maul"] = {
      title = "Düsterbruch",
      text = {
        { "Düsterbruch war Eldre'Thalas, eine Stadt der Hochgeborenen, in den Tagen Königin Azsharas erbaut, um ihre kostbarsten arkanen Geheimnisse zu bewahren. Sie überstand die Große Teilung, und vieles davon steht noch, eine Stadt aus weißem Stein im Wald, ihre Hallen voller Bücher und Geister." },
        { "Heute ist sie in drei Teile zerbrochen. Die Oger der Gordok halten den Norden und krönen einen neuen König, wann immer der alte getötet wird. Der Satyr Alzzin der Wildformer hält den Osten und hat die Frucht der Fruchtbarkeit der Stadt zu einem üblen Ding verdorben, das man die Teufelsranke nennt. Der Westen wird noch von den Letzten der Hochgeborenen gehalten, den Shen'dralar, rund um ihre Bibliothek, die ich für sehr viel gern lesen würde." },
      },
    },
    ["dolanaar"] = {
      title = "Dolanaar",
      text = {
        { "Dolanaar liegt an der Straße von Shadowglen nach Darnassus, um einen Mondbrunnen versammelt, mit einem Gasthaus und Gebäuden zwischen den Bäumen. Druiden und Schildwachen arbeiten hier nah an den Sorgen des Waldes. Es ist ein nützlicher Halt, bevor ein Reisender zur Hauptstadt weiterzieht." },
        { "In letzter Zeit gehören zu ihren Sorgen die Furbolgs der Knarzklauen, Satyrn in den Höhlen und kranke Geschöpfe in den Wäldern. Das ruhige Aussehen des Dorfes verrät wenig über diese Arbeit. Hört Euch an, worum seine Hüter Euch bitten. Sie haben die Veränderung des Landes um sie herum beobachtet." },
      },
    },
    ["draenor"] = {
      title = "Draenor",
      text = {
        { "Bevor die Orcs durch das Portal kamen, lebten sie auf einer eigenen grünen Welt namens Draenor, in Klans, die umherzogen, jagten und stritten, wie Klans es tun. Ihre Schamanen sprachen mit den Geistern der Elemente und der Ahnen, und von allen war der alte Schamane Ner'zhul der angesehenste. Sie teilten die Welt mit den Draenei, Verbannten von anderswo, die ihre Städte in die Klippen bauten und den Orcs wenig Grund zum Krieg gaben." },
        { "Der Dämon Kil'jaeden gab ihnen einen. Er bearbeitete Ner'zhul, bis das Volk des Schamanen nach Blut hungerte, und als Ner'zhul vor dem letzten Schritt zurückschreckte, fand der Dämon in seinem Lehrling Gul'dan einen willigeren Schüler. Die Schamanen wurden zu Hexenmeistern. Arenen wurden gebaut, damit die Klans darin kämpften. Gul'dan versammelte die Häuptlinge, und sie tranken das Blut des Grubenlords Mannoroth. Von ihnen allen, sagt das Buch in unserer Bibliothek, weigerte sich nur Durotan von den Frostwolf." },
        { "Die Horde, die folgte, löschte die Draenei beinahe aus, und die Magie der Hexenmeister begann das Land selbst zu töten, bis die Prärien, durch die die Orcs seit Generationen gezogen waren, rot und unfruchtbar waren. Als sich das Dunkle Portal öffnete, gab es auf Draenor wenig, wofür es sich zu bleiben lohnte. Die Verbannten im sicheren Hafen in den Sümpfen des Elends sagen, sie kämen von dieser Welt. Ich würde mir gut überlegen, was Ihr ihnen über Orcs sagt." },
      },
    },
    ["dragonmaw-clan"] = {
      title = "Der Dragonmawklan",
      text = {
        { "Die Dragonmaw ritten im Zweiten Krieg auf roten Drachen in die Schlacht. In Grim Batol hielten sie Alexstrasza gefangen und zwangen ihre Kinder, der Horde zu dienen. Ihre Herrschaft über den Himmel beruhte auf der Gefangenschaft einer Mutter und ihrer Jungen." },
        { "Die Befreiung der Drachen brach die Stärke des Klans, doch Reste der Dragonmaw halten noch immer die Hügel des Sumpflands und überfallen seine Straßen. Sie sind Überlebende der alten Horde, nicht Gefolgsleute der neuen." },
      },
    },
    ["dragons-of-nightmare"] = {
      title = "Die Drachen des Nachtmahrs",
      text = {
        { "Yseras grüne Drachen hüten den Smaragdgrünen Traum, die unberührte Welt, durch die schlafende Druiden reisen. Vier Leutnants bewachten seine großen Baumportale: Ysondre, Lethon, Emeriss und Taerar, stationiert im Dämmerwald, im Hinterland, in Feralas und in Ashenvale." },
        { "Der Nachtmahr hat sie genommen. Sie kommen verdreht hervor und greifen an, wer sich nähert. Emeriss verbreitet Fäulnis, Taerar teilt sich in Schemen, und Lethon zieht die Geister der Gefallenen heraus. Remulos sammelt Bruchstücke der Verderbnis von den Portalen, um nachzuforschen. Ein Reisender, der einen dieser Bäume erreicht, findet vielleicht, dass genau der Hüter, der ihn hätte sicher machen sollen, zu seiner Gefahr geworden ist." },
      },
    },
    ["dreadlords"] = {
      title = "Die Schreckenslords",
      text = {
        { "Die Schreckenslords, die Nathrezim, sind die Ränkeschmiede der Brennenden Legion: vampirhaft, geduldig, besser im Verderben als im Erobern. Kil'jaeden setzte sie ein, um seine gefährlichste Schöpfung zu bewachen, den Lichkönig. Tichondrius, der gerissenste von ihnen, ergötzte sich an der Seuche. Mal'Ganis wartete in Stratholme auf Prinz Arthas. Anetheron kämpfte am Hyjal an Archimondes Seite." },
        { "Als die Macht des Lichkönigs schwand, versuchten seine Kerkermeister, Lordaeron für sich zu nehmen. Sie verloren es an Sylvanas und ihre Verlassenen, die ihre Stadt unter der zerstörten Hauptstadt bauten. Varimathras dient dort nun der Dunklen Fürstin, ob es ihm gefällt oder nicht. Balnazzar trägt in Stratholme das Gesicht des eigenen Anführers des Scharlachroten Kreuzzugs." },
        { "Ein Schreckenslord zeigt selten, was er ist. Wenn jemand in Amt und Würden darauf erpicht scheint, dass die Lebenden und die Toten einander weiter umbringen, $gReisender:Reisende;, lohnt es sich zu fragen, wem es nützt." },
      },
    },
    ["druids"] = {
      title = "Druiden",
      text = {
        { "Der erste Druide war Malfurion Stormrage, vor dem Krieg der Urtume vom Halbgott Cenarius gelehrt. Nach der Zerstörung des Brunnens folgten ihm die Nachtelfen, die dem Arkanen entsagt hatten, und tausende Jahre lang schliefen die Druiden im Smaragdgrünen Traum und erwachten nur, wenn die Welt sie brauchte." },
        { "Nun erwachen sie, und sie sind nicht nur Nachtelfen: Die Tauren haben eigene Druiden, und beide sind dem Zirkel des Cenarius in Moonglade verpflichtet. Ein Druide nimmt die Gestalten der Wildnis an, Bär, Katze und Robbe unter ihnen, heilt mit der grünen Magie des Traums und ruft Mond und Sterne auf Feinde herab." },
        { client = "forever", "Druiden der Himmelsgeborenen üben ihre Kunst heute auf beiden Seiten des Streits zwischen Allianz und Horde aus." },
        { "Malfurion selbst ist in den Traum gegangen und nicht zurückgekehrt. Bei aller Arbeit des Zirkels in der wachen Welt bleibt sein größter Lehrer außerhalb der Reichweite eines gewöhnlichen Boten." },
      },
    },
    ["druids-of-the-fang"] = {
      title = "Die Druiden des Giftzahns",
      text = {
        { "Die Druiden des Giftzahns waren Naralex' Schüler, ein Orden edler Druiden, die in die Höhlen des Wehklagens hinabstiegen, um das Brachland zu heilen. Der Albtraum, der ihren Meister ergriff, ergriff auch sie. Nun wollen sie das Land nach ihren eigenen verdrehten Träumen neu formen und haben die Gestalten und Namen von Schlangen angenommen." },
        { "Es gibt vier Anführer unter ihnen, Lord Kobrahn, Lady Anacondra, Lord Pythas und Lord Serpentis, und jeder trägt einen Edelstein des Traums. Die Druiden von Thunder Bluff sagen, ihre Gesichter verfolgten sie. Sie hätten die Edelsteine gern heimgebracht." },
      },
    },
    ["druids-of-the-talon"] = {
      title = "Die Druiden der Kralle und der Klaue",
      text = {
        { "Malfurions Druiden waren nie ein einziger Orden. Manche nahmen die Gestalt des großen Bären an und wurden zu den Druiden der Klaue. Andere nahmen die Gestalt der Sturmkrähe an und wurden zu den Druiden der Kralle. Beide hielten den Pakt mit Ysera und schliefen jahrhundertelang in den Grabhügeln, während ihre Geister im Smaragdgrünen Traum wandelten, und im Dritten Krieg weckte Malfurion sie zum Kampf." },
        { "Manche schlafen noch. Im Grabhügel von Ban'ethil auf Teldrassil liegen die Druiden der Kralle im Winterschlaf, bewacht von einem Großen Wächter. Die Furbolgs der Knarzklauen sind eingedrungen, und einer von ihnen, Ursal der Raufer, hat sich so an dem Ruf der Schläfer zu schaffen gemacht, dass sie Gefahr laufen, überhaupt nie mehr aufzuwachen. Ein Druide der Klaue, der im selben Hügel verloren ging, musste erleben, dass sein eigener Körper gegen ihn gewandt wurde." },
        { "Es ist nicht immer leicht, sie zu wecken. Kerlonian Evershade, ein Druide der Klaue, gerade erst aus dem Traum zurück, döst am Straßenrand an der Dunkelküste und bittet darum, mit seinem Horn geweckt zu werden, falls er unterwegs einnickt. Zehntausend Jahre sind eine lange Zeit, um müde gewesen zu sein." },
      },
    },
    ["dun-garok"] = {
      title = "Dun Garok",
      text = {
        { "Dun Garok ist eine zwergische Festung, in die Hügel im Südosten von Hillsbrad gebaut, sehr weit von zu Hause, und seine Besatzung unter Captain Eisenberg hält die Pässe und schützt die Leute im Vorgebirge und die Minen in der Nähe. Es ist ein sturer kleiner Außenposten Ironforges in einem Land der Toten, und ich bin stolz darauf." },
        { "Die Verlassenen hassen ihn und schicken ihre Plünderer dagegen. Die Zwerge schicken sie zurück." },
      },
    },
    ["dun-modr"] = {
      title = "Dun Modr",
      text = {
        { "Dun Modr wurde erbaut, um das Südende des Thandol-Übergangs zu bewachen, und viele Jahre lang tat es das. Heute weht dort kein Banner der Bronzebeards mehr. Die Dunkeleisenzwerge haben es eingenommen, und von seinen Mauern aus greifen sie den Übergang an und jeden, der die Straße nach Norden nimmt." },
        { "Für jeden Zwerg aus Ironforge ist es bitter, zwergische Hallen von Zwergen gegen uns gehalten zu sehen. Es erinnert uns daran, dass der Krieg der drei Hämmer nie wirklich geendet hat." },
        { "Wenn Ihr nahe vorbeikommt, zieht den Kopf ein. Ihre Schützen sind sehr gut." },
      },
    },
    ["dun-morogh"] = {
      title = "Dun Morogh",
      text = {
        { "Dun Morogh ist das verschneite Hochland um Ironforge, Heimat der Zwerge des Bronzebeardklans und ihrer gnomischen Nachbarn." },
        { "Es ist unser Land, doch wir teilen es, und nicht immer freiwillig. Die Trolle der Frostmane halten die westlichen Hügel, Troggs graben, wo es ihnen gefällt, und seit dem Fall von Gnomeregan sind die Gnome unsere Nachbarn in ihren eigenen Tälern ebenso wie in unserer Stadt." },
        { "Lernt seine Straßen gut kennen, $gReisender:Reisende;. Die meisten Zwerge, denen Ihr je begegnen werdet, haben auf ihnen ihre ersten Schritte getan." },
      },
    },
    ["durnholde-keep"] = {
      title = "Burg Durnholde",
      text = {
        { "Durnholde verwaltete nach dem Zweiten Krieg die Internierungslager der Orcs. Sein Herr, Aedelas Blackmoore, zog ein Orckind als Sklaven und Gladiator auf und wollte es ein gehorsames Heer befehligen lassen. Das Kind war Thrall. Taretha Foxton, ein Mädchen aus Blackmoores Haushalt, freundete sich mit ihm an und half ihm zu fliehen." },
        { "Thrall befreite später sein Volk. Blackmoore ist tot, und das Syndikat hält die Burg. Sein Ehrgeiz überlebte anderswo: In einem Anwesen am Lordameresee plante Aliden Perenolde, seinerseits Orcs zu versklaven. Seine Gefährtin Elysa trug Tarethas Anhänger." },
        { "Thralls Agenten kamen nach Hillsbrad, um ihn zurückzuholen, und der Kriegshäuptling hat ihn wieder. Ein Anhänger ist eine kleine Sache neben dem Fall einer Festung, $gReisender:Reisende;. Er bewahrt den Namen von jemandem, dessen Hilfe diesen Fall möglich machte." },
        { side = "Horde", aside = true, sign = "P. F.", "Ein Mädchen aus einem Haushalt Lordaerons hat für die Orcs mehr getan als die ganze Allianz Lordaerons. Ihr Name gehört in mehr Chroniken als diese." },
      },
    },
    ["durotan-and-draka"] = {
      title = "Durotan und Draka",
      text = {
        { "Durotan war Häuptling des Frostwolfklans, und der eine Häuptling, der nicht trinken wollte. Als Gul'dan die Klans versammelte, um Mannoroths Blut zu trinken, weigerte sich Durotan und warnte jeden, der zuhören wollte, dass die Hexenmeister zerstörten, was die Orcs einmal gewesen waren. Gul'dan konnte einen so beliebten Helden nicht offen töten, also verbannte er ihn und seinen ganzen Klan an den äußersten Rand der neuen Welt: in diese Berge." },
        { "Seine Gefährtin Draka ging mit ihm ins Exil, und ihr kleiner Sohn mit ihnen. Durotan ging noch einmal zurück, um seinen alten Freund Orgrim Schicksalshammer vor Gul'dan zu warnen. Gul'dans Meuchler folgten ihm nach Hause und ermordeten ihn und Draka. Ihr kleiner Sohn wurde neben ihnen von einem menschlichen Offizier gefunden, Aedelas Blackmoore, der ihn als Sklaven aufzog und Thrall nannte." },
        { "Die Frostwolf halten im Alteractal ein Grab für Durotan. Ihr Scharfseher Drek'Thar schrieb die Worte darauf: der tapferste ihrer Art, verraten von denen, die die Orcs versklavt sehen wollten. Der Vater des Kriegshäuptlings, $gReisender:Reisende;, hat nie gesehen, was aus seinem Sohn wurde. Die Frostwolf sorgen dafür, dass das Volk seines Sohnes weiß, wessen Sohn er ist." },
      },
    },
    ["durotar"] = {
      title = "Durotar",
      text = {
        { "Durotar ist ein hartes Land: rote Erde, roter Fels, Dornen und Skorpide, von der Sonne verbrannt und von trockenen Schluchten zerschnitten, mit dem Meer auf der einen Seite und den langen Ebenen des Brachlands auf der anderen. Die Orcs wählten es trotzdem. Thrall benannte es nach seinem Vater Durotan, dem Häuptling des Frostwolfklans, der ermordet wurde, bevor sein Sohn ihn kennen konnte." },
        { "Die Horde kam nach dem letzten Krieg hierher, nachdem sie aus den Lagern Lordaerons über das Meer gesetzt und am Hyjal an der Seite der Nachtelfen und Menschen gekämpft hatte. Lange ließ man sie nicht in Frieden: Admiral Daelin Proudmoore von Kul Tiras, Jaina Proudmoores Vater, schickte seine Flotte gegen die Orcs und wurde geschlagen. Seither bauen die Orcs: Orgrimmar im Norden, den Klingenhügel an der Straße, Sen'jin für ihre Verbündeten, die Trolle." },
        { "Das Land haben sie noch nicht ganz gesäubert. Zentauren fallen von Westen her ein, Stacheleber halten den Süden, und in den Höhlen der Knochenhöhle, in Sichtweite der Hauptstadt, verehrt die Burning Blade die Dämonen, die die Orcs einst versklavten. Durotar ist jung, und es weiß es." },
      },
    },
    ["duskwood"] = {
      title = "Dämmerwald",
      text = {
        { "Südlich von Elwynn rücken die Bäume zusammen, das Licht wird grau, und Ihr seid im Dämmerwald. Einst war er Teil desselben grünen Waldes. Menschen lebten und ackerten hier wie in Elwynn. Dann senkte sich eine Dunkelheit über diese Wälder, die sich nie wieder gehoben hat. Niemand in Dunkelhain kann Euch mit Gewissheit sagen, warum, auch wenn viele nach Osten blicken, zu den toten Landen des Gebirgspasses der Totenwinde und dem Turm, der dort steht." },
        { "Was die Dunkelheit brachte, ist klar genug. Die Toten erheben sich auf dem Friedhof von Rabenflucht, Worgen jagen in den Wäldern, Spinnen werden so groß wie Ponys, und Oger sind in die Hügel gezogen. Die Höfe sind verlassen, und wer geblieben ist, hat sich hinter den Laternen von Dunkelhain unter seiner eigenen Miliz versammelt, denn Stormwind hat seine Wachen abgezogen. Es ist ein Ort für mutige Reisende und für Geschichten, die man bei verriegelter Tür am Feuer erzählt." },
      },
    },
    ["dustwallow-marsh"] = {
      title = "Marschen von Dustwallow",
      text = {
        { "Die Marschen von Dustwallow sind ein weiter, nasser Sumpf an der Ostküste Kalimdors, südlich des Brachlands: Schilf, schwarze Tümpel, Krokilisken, Raptoren und sehr viel Nebel. Auf einer Insel vor ihrer Küste steht Theramore, die Stadt der Menschen von Lady Jaina Proudmoore, und im Süden des Sumpfes liegt der Drachensumpf, wo Onyxia ihren Hort hat." },
        { "Zwischen ihnen liegen die Oger von Brackenwall, die der Horde dienen, die verbrannte Ruine eines Gasthauses, über die jeder eine Theorie hat, und sehr viele schwarze Drachen. Es ist eine Marsch, in der die Allianz und die Horde vereinbart haben, als Nachbarn zu leben, und in der beide sehr genau hinsehen." },
      },
    },
    ["dwarves"] = {
      title = "Die Zwerge von Ironforge",
      text = {
        { "Die Zwerge halten Khaz Modan von Ironforge aus, seit bevor irgendwer ihre Geschichte aufschrieb, und lange wussten auch sie nicht, woher sie kamen. Die Scheiben, die die Liga aus Uldaman barg, legen eine Antwort nahe, über die die Gelehrten noch streiten: dass die ersten Zwerge Irdene waren, von den Titanen aus dem Stein geformt, die mit der Zeit zu Fleisch wurden." },
        { "Drei Klans teilten sich einst den Berg unter einem Hochkönig. Als er starb, zogen sie um seinen Thron in den Krieg. Die Bronzebeards behielten Ironforge, die Wildhammer gingen nach Norden, und die Dunkeleisenzwerge weckten im Süden den Feuerlord. Heute herrscht König Magni Bronzebeard. Sein Bruder Muradin ging mit dem Prinzen von Lordaeron nach Norden und wurde seither nicht mehr gesehen, und sein Bruder Brann ist für die Liga draußen in der Welt, was ungefähr dort ist, wo wir ihn vermuten." },
        { "Sie sind ein kräftiges, sorgfältiges, großzügiges Volk, das seinen Groll ebenso gut pflegt wie sein Mauerwerk, und ich sage das mit Zuneigung. Wenn Euch ein Zwerg sagt, eine Brücke werde halten, $gReisender:Reisende;, dann hält sie. Wenn ein Zwerg sagt, das Bier sei gut, bildet Euch Eure eigene Meinung." },
      },
    },
    ["earth-mother"] = {
      title = "Die Erdenmutter",
      text = {
        { "Die Tauren verehren die Erdenmutter als Quelle der Welt und ihres Lebens. Ihre Überlieferungen lehren Achtung vor den Gaben des Landes und Sorgfalt gegen Verschwendung. Schamanen sprechen mit seinen Geistern, Seher folgen Visionen, und die Ahnen bleiben Teil des Lebens derer, die nach ihnen kommen." },
        { "Junge Tauren legen die Riten der Erdenmutter ab, bevor die Ältesten von Thunder Bluff sie aufnehmen. Kraft wird gegen die Feinde des Stammes bewiesen. Sicht kommt durch das Wasser der Seher und das, was im Feuer erscheint. Weisheit verlangt den Segen der Ahnen an den Teufelsfelsen. Die Reise endet vor dem Oberhäuptling." },
        { "Achtet auf die Riten, wenn Ihr Eure Gastgeber verstehen wollt, $gReisender:Reisende;. Jagd, Erinnerung und das Land verbinden sich in der Art, wie ein junger Taure sich einen Platz unter ihnen verdient." },
      },
    },
    ["earthen"] = {
      title = "Die Irdenen",
      text = {
        { "Die Irdenen waren die Steinmetze der Titanen, aus lebendem Fels geschaffen, um die tiefen Orte der Welt auszuhöhlen. Als die Titanen gingen, formten und bewachten sie diese Tiefen weiter und kümmerten sich wenig um irgendetwas darüber. Die Große Teilung verletzte sie, wie sie die Erde selbst verletzte. Sie verloren viel von dem, was sie gewesen waren, und schlossen sich in den Gewölben ein, in denen sie geschaffen worden waren: Uldaman, Uldum, Ulduar, wie das Buch in unserer Bibliothek sie nennt." },
        { "Nach fast achttausend Jahren erwachten die Irdenen von Uldaman. Sie fanden ihre steinernen Häute zu Haut erweicht und ihre Macht über den Fels geschwächt. Sie waren sterblich geworden. Sie nannten sich Zwerge, gingen hinaus in die wache Welt und gründeten ein Königreich unter dem höchsten Berg des Landes, Khaz Modan, dem Berg des Khaz'goroth, um eine Schmiede, die zu seinen Ehren errichtet wurde." },
        { "Nicht alle erwachten. Irdene halten noch immer Wache in den Hallen von Uldaman, und jede Expedition, die die Liga dorthin schickt, trifft auf sie. Sie scheinen nicht zu wissen, wessen Verwandte wir sind." },
      },
    },
    ["earthen-ring"] = {
      title = "Der irdene Ring",
      text = {
        { "Der irdene Ring ist ein Kreis von Schamanen, der sich dem Studium und der Bewahrung der Elemente widmet. Sie hätten mehr über seltsame alte Götter, uralte Legenden und Überlieferungen vergessen, als die meisten Gelehrten je wissen werden, sagt ein Späher der Horde in Ashenvale, und wenn etwas von den Elementen auftaucht, das niemand erklären kann, bringt man es zu ihnen." },
        { "Sie halten sich an den Rändern der Dinge. Ein Schamane in Zoram'gar an der Küste von Ashenvale erforscht, was das Meer aus der Blackfathom-Tiefe heraufwirft, und ein anderer wartet am hoffnungsvollen Licht, wo die Toten am dichtesten drängen. Ihre Absichten hat man rein genannt, selbst wer die Gesellschaft bezweifelt, die sie pflegen. Der Ring reichte einst den Verlassenen die Hand, und manche in Thunder Bluff fragen sich nun, ob das klug war." },
        { "Eine gelehrte Gesellschaft, die den Elementen Rechenschaft schuldet statt einem König. Die Liga erkennt die Art wieder und beneidet sie ein wenig." },
      },
    },
    ["eastern-plaguelands"] = {
      title = "Östliche Pestländer",
      text = {
        { "Das Eastweald umfasste einst die östlichen Dörfer Lordaerons, seine Abteien und die Stadt Stratholme. Die Seuche verwandelte es in die Östlichen Pestländer. Seine Bäume sind tot oder sterben, riesige Pilze ragen zwischen ihnen auf, und fauliges Wasser fließt durch ein Land, das größtenteils die Geißel beherrscht." },
        { "Die Kapelle des hoffnungsvollen Lichts beherbergt im Osten die Argentumdämmerung. Der Scharlachrote Kreuzzug hält Tyrs Hand im Südosten. Tirion Fordring lebt im Exil am Thondroril, und Nathanos Blightcaller bewohnt sein altes Bauernhaus in Marris' Siedlung. Diese verstreuten Bewohner verfolgen sehr verschiedene Ziele." },
      },
    },
    ["echo-isles"] = {
      title = "Die Echoinseln",
      text = {
        { "Die Echoinseln sollten die neue Heimat der Dunkelspeertrolle werden, eine Handvoll Dschungelinseln vor der Küste von Durotar, ganz ähnlich denen, die sie verlassen hatten. Ein Hexendoktor namens Zalazane änderte das. Er wandte sich dunkler Magie zu, verhexte sein eigenes Volk und zwang es unter seinen Willen, und die treuen Dunkelspeer mussten von den Inseln aufs Festland fliehen." },
        { "Zalazane herrscht noch immer über die Inseln, und von dort schickt er seine gebannten Trolle übers Wasser, um weitere vom Stamm unter seinen Einfluss zu ziehen. Seine Opfer ruhen nicht immer, wenn sie sterben: Die Seelen mancher, sagen die Trolle, sind in ihren eigenen Schädeln gefangen, in einem Kreis der Macht auf der größten Insel." },
      },
    },
    ["edwin-vancleef"] = {
      title = "Edwin van Cleef",
      text = {
        { "Edwin van Cleef war der Meister der Steinmetzgilde, der Mann, der Stormwind wiederaufbaute, und als die Adligen sich weigerten, seine Steinmetze zu bezahlen, stellte er sich zu den Männern, die unter ihm gearbeitet hatten. Er führte sie in einem Aufruhr durch die Straßen, die sie gebaut hatten, und hinaus aus der Stadt, und in Westfall wurde die Gilde zur Bruderschaft der Defias." },
        { "Er führt sie noch immer, von seinem Schiff in der Tiefe der Todesminen aus, und er hat Stormwind nie vergeben. Bei seiner Leiche fanden diejenigen, die ihn schließlich erreichten, einen Brief an den Stadtarchitekten, versiegelt und nie abgeschickt, und er führte sehr weit, bis in die Gärten der königlichen Burg." },
        { "Ich habe versucht, gerecht über ihn zu schreiben. Ihm wurde Unrecht getan, und er tat großes Unrecht zurück, und die Bauern von Westfall zahlten für beides." },
      },
    },
    ["eitrigg"] = {
      title = "Etrigg",
      text = {
        { "Etrigg berät Thrall in Orgrimmar, ein alter Krieger mit Wissen, das die neue Horde noch braucht. Als Kriegsherr Goretooth erfuhr, dass Rend Blackhand noch lebte, schickte er Abenteurer, um Etrigg über die Blackrock zu befragen." },
        { "Rivalitäten unter den Anführern der Horde hatten Etrigg seine Söhne gekostet und ihn von ihren Kriegen fortgetrieben. Als er allein nahe Hearthglen lebte, kämpfte er gegen Tirion Fordring und rettete den Paladin dann aus einem einstürzenden Turm. Tirion verteidigte ihn später auf Kosten seines Ansehens in der Silbernen Hand." },
        { "Während Thralls Angriff auf Stratholme befreite Tirion Etrigg. Vor der Stadt bat Thrall ihn, die alten Wege der Horde wiederherzustellen, und er nahm an." },
      },
    },
    ["elune"] = {
      title = "Elune",
      text = {
        { "Elune ist die Göttin des Mondes und der älteste Glaube der Nachtelfen. In den Tagen vor der Großen Teilung glaubten sie, sie schlafe tagsüber in den Tiefen des Brunnens der Ewigkeit und erwache mit der Nacht. Ihre Priesterinnen hüteten damals ihre Tempel und hüten sie heute, im Tempel des Mondes in Darnassus." },
        { "Sie antwortet ihnen. Die Nachtelfen verdanken ihr Überleben der Großen Teilung, so sagen sie, ihrer Gnade, und eine Hohepriesterin von Elune, Tyrande Whisperwind, hat sie durch die zehntausend Jahre seither geführt. Ihre Mondbrunnen tränken ihre Städte, und ihre Priesterinnen heilen durch ihr Licht. Im Kampf, so sagt man mir, können sie es als etwas viel weniger Sanftes herabrufen." },
        { "Eine Nachtelfe wird Euch ihre Göttin selten aufdrängen. Sie hatten lange Zeit, Geduld mit dem Glauben anderer Leute zu lernen, und mit anderen Leuten." },
      },
    },
    ["elwynn-forest"] = {
      title = "Wald von Elwynn",
      text = {
        { "Elwynn ist der Wald, der Stormwind ernährt: hohe alte Bäume, offene Wiesen, Höfe und Weinberge und der träge Fluss, der hinab nach Westfall fließt. Es ist das sanfteste Land in den Reichen der Menschen, und wer an einem Sommermorgen seine Straßen entlanggeht, mag kaum glauben, was hier geschehen ist." },
        { "Im Ersten Krieg kamen die Orcs durch diese Wälder. Sie brannten die Höfe, die Abtei und die Dörfer eines nach dem anderen nieder und nahmen dann die Stadt selbst ein. Das Königreich wurde nach dem Zweiten Krieg wiederaufgebaut, und die Wälder beherbergen wieder Höfe und Siedlungen." },
        { "Der Frieden ist dünner, als er aussieht. Kobolde haben die Minen eingenommen, die Gnolle der Flusspfoten fallen von Westen her ein, und die rot maskierten Defias haben sich aus Westfall in die Wälder ausgebreitet. Fragt irgendeinen Bauern in Elwynn, ob die Soldaten des Königs kommen, wenn man sie ruft." },
      },
    },
    ["emerald-sanctuary"] = {
      title = "Das Smaragdrefugium",
      text = {
        { "Das Smaragdrefugium ist ein Hain im Süden des Teufelswalds, gehalten vom Smaragdkreis, Druiden des Zirkels des Cenarius, die geschworen haben, den Wald zu heilen. Sie kämpfen gegen die Jadefeuersatyrn und den Schattenrat und erforschen den Blutbernstein der verderbten Elementare, in der Hoffnung zu lernen, wie man den Rest rettet." },
        { "Ihre Geduld ist gewaltig. Sie reinigen die verseuchten Liedblumen und Windblüten eine nach der anderen, und sie läutern die Geister der Urtume, die die Satyrn mit Teufelsmagie gebunden haben. Es ist langsame Arbeit, und sie wissen, dass sie länger dauern kann, als irgendeiner von ihnen leben wird. Sie sind Nachtelfen. Gut möglich, dass sie recht haben." },
      },
    },
    ["eranikus"] = {
      title = "Eranikus",
      text = {
        { "Eranikus ist ein Drache aus Yseras grünem Schwarm und der Hüter des versunkenen Tempels: Seine Aufgabe war es, dafür zu sorgen, dass die Trolle ihren Gott nie wieder hervorbrachten. Nach eigener Aussage hat er versagt, und Schlimmeres ist ihm widerfahren. Während er über dem Tempel schlief, wurde er von etwas Dunklem im Traum gefangen, und es verdreht seinen Geist." },
        { "In den Tiefen des Tempels liegt sein Schemen in einem Zustand zwischen Schlaf und Tod, verstrickt in Albträume, und was von seinem freien Willen übrig ist, streckt sich nach Reisenden aus, um Hilfe zu erbitten. Ein anderer grüner Drache, Itharius, wartet in einer Höhle im Sumpf und hofft, ihn zu erlösen. Ich wünsche Itharius Glück. Der Nachtmahr, der Eranikus festhält, ist derselbe, der Yseras Leutnants an den großen Bäumen genommen hat." },
      },
    },
    ["everlook"] = {
      title = "Everlook",
      text = {
        { "Everlook ist eine Goblinstadt mitten in Winterspring, der nördlichste Anlaufhafen des Steamwheedle-Kartells, mit Mauern, einem Gasthaus, einer Bank und einer Wache aus Goblinschlägern, wo Allianz und Horde Seite an Seite handeln. Drinnen ist es wärmer, als man denkt, und weit teurer." },
        { "Jeder kommt durch Everlook. Die Argentumdämmerung hält hier einen Vertreter, die Thoriumbruderschaft einen Schmied, und alle Jäger, Forscher und Gelehrten des Nordens kehren ein, um sich die Füße zu wärmen." },
      },
    },
    ["explorers-league"] = {
      title = "Die Forscherliga",
      text = {
        { "Die Liga konnte ich kaum auslassen. Die Forscherliga ist Ironforges Gesellschaft der Historiker, Archäologen und Gräber: die Zwerge, die lieber eine Ruine lesen, als eine Halle zu bauen. Eine königliche Historikerin könnte sich keine bessere Gesellschaft wünschen." },
        { "Sie sind der ältesten Frage auf der Spur, die es gibt, nämlich woher die Zwerge kommen. Ihre Grabungen in Uldaman legen nahe, dass die Antwort bei den Titanen liegt, den Erschaffern der Welt, und wenn das stimmt, ändert es, wie jeder Zwerg von sich selbst denken sollte. König Magni nimmt es tatsächlich sehr ernst." },
        { "Ihr findet sie in der Halle der Forscher, unter Hochforscher Magellas. Bringt ihnen alles, was alt ist, $gReisender:Reisende;, und alles, was seltsam ist. Sie werden hören wollen, wo Ihr es gefunden habt, und ich ebenso." },
      },
    },
    ["fall-of-lordaeron"] = {
      title = "Der Fall Lordaerons",
      text = {
        { "Lordaeron war das erste unter den Königreichen der Menschen, und sein König Terenas Menethil hatte die Allianz durch den Zweiten Krieg geführt. Als die Seuche aus dem Norden kam und die Toten sich zu erheben begannen, war es sein Sohn, Prinz Arthas, ein Paladin der Silbernen Hand, der gegen sie auszog." },
        { "Arthas verfolgte sie zu weit. Er ließ die verseuchte Stadt Stratholme über die Klinge springen, statt ihre Bewohner sich erheben zu sehen, folgte den Herren der Seuche nach Nordend und nahm dort eine verfluchte Runenklinge auf, Frostgram. Als er heimkehrte, jubelte das Volk ihm durch die Tore zu. Er ging in den Thronsaal seines Vaters und tötete ihn, und das Königreich fiel hinter ihm an die Toten." },
        { "In diesen Ruinen ist es geschehen. Die Verlassenen gehen jeden Tag über sie hinweg, und manche von ihnen standen in der jubelnden Menge." },
        { side = "Horde", aside = true, sign = "P. F.", "Sie schreibt, dass manche der Verlassenen in der jubelnden Menge standen. Manche von uns taten es. Ich habe mehr als einmal versucht, diesen Tag niederzuschreiben, und es ist mir noch nicht gelungen." },
      },
    },
    ["falstad-wildhammer"] = {
      title = "Falstad Wildhammer",
      text = {
        { "Oberster Than Falstad Wildhammer herrscht in Aerie Peak zwischen seinen Greifenhorsten. Die Arbeit der Reiter reicht weit über das Hinterland hinaus: Als Brohann Caskbelly einen Piloten sucht, der über den Sümpfen des Elends verloren ging, schickt er Abenteurer zu Falstad, um Nachricht zu erhalten." },
        { "Die Wildhammer regieren sich selbst. Ihre Unabhängigkeit löscht ihre Geschichte mit der Allianz nicht aus, und Falstad bleibt ein nützlicher Kontakt für alle, die ihre Greifenreiter suchen. Haltet ein gemeinsames Anliegen nicht für eine Herrschaft aus Ironforge, $gReisender:Reisende;. Sein Klan hat seinen eigenen Than und seine eigene Heimat." },
      },
    },
    ["fandral-staghelm"] = {
      title = "Erzdruide Fandral Staghelm",
      text = {
        { "Fandral Staghelm ist in Malfurion Stormrages Abwesenheit der Erzdruide des Zirkels des Cenarius und derjenige, der die Druiden beim Wachsenlassen Teldrassils anführte. Er ist alt, stolz und ernst, und die Druiden folgen ihm mit etwas, das an Ehrfurcht grenzt." },
        { "Sein Volk erinnert sich an einen Kummer über alle anderen. Vor tausend Jahren, im Krieg gegen das Insektenreich von Ahn'Qiraj, ritt sein Sohn Valstann aus, um den Südwindposten zu retten, und kam nicht zurück. Tage später trat der Qiraji-General Rajaxx vor das Heer der Nachtelfen, den jungen Elfen in seinen Klauen, und riss ihn vor den Augen seines Vaters in Stücke. Als die Drachen und die Druiden die Qiraji schließlich hinter dem Skarabäuswall versiegelten, gab Anachronos Fandral das Szepter, das ihn wieder öffnen würde, und Fandral zerschlug es am Tor. 'Ich werde meinen Sohn zurückbekommen', sagte er dem Drachen, 'und wenn es Jahrtausende dauert.' Er hält die Enklave des Cenarius in Darnassus, erforscht die Sorgen des Baumes, den er pflanzte, und wird Euch sagen, er habe sie im Griff." },
      },
    },
    ["farstrider-lodge"] = {
      title = "Die Weitschreiter-Lodge",
      text = {
        { "Jäger versammeln sich in der Weitschreiter-Lodge im Südosten von Loch Modan. Marek Ironheart handelt mit Krokiliskenfleisch und -häuten, während Daryl der Jüngling jedem Herausforderungen stellt, der seine Geschicklichkeit erproben will. Hier gibt es reichlich Arbeit für einen Bogen und keinen Mangel an Gesprächen darüber, wer ihn am besten führt." },
        { "Vyrin Swiftwind schlägt eine andere Prüfung vor. Sie will Old Sooty tot sehen, als Teil eines Plans, Daryls Prahlerei bloßzustellen. In der Lodge lernt Ihr vielleicht etwas über die Jagd, $gReisender:Reisende;, aber Ihr lernt sehr viel über Jäger." },
      },
    },
    ["feathermoon-stronghold"] = {
      title = "Festung Feathermoon",
      text = {
        { "Die Festung Feathermoon steht auf der Insel Sardor vor der Küste von Feralas, mit dem Boot vom Festland aus zu erreichen. Generalin Shandris Feathermoon befehligt ihre Schildwachen von weißen Mauern über einem Hafen aus. Die Festung trägt ihren Namen." },
        { "Ihre Soldaten stellen sich den Naga der Hasskämme bei Solarsal entgegen und beobachten die Oger des Waldes. Auch Gelehrte arbeiten zwischen den alten elfischen Ruinen von Feralas." },
      },
    },
    ["felwood"] = {
      title = "Teufelswald",
      text = {
        { "Der Teufelswald war der nördliche Teil des großen Waldes von Ashenvale. Heute ist er ein vergiftetes Land, seine Bäume schwarz und verkrümmt, seine Flüsse grün, seine Furbolgs wahnsinnig und selbst seine Pflanzen verseucht. Die Dämonen haben das getan. Im letzten Krieg hielt der Schreckenslord Tichondrius hier den Schädel von Gul'dan, und seine Verderbnis breitete sich durch die Wälder aus. Als Illidan Stormrage die Macht des Schädels für sich nahm, wurde der Wald nicht geheilt." },
        { "Der Schattenrat und seine Dämonen halten Jaedenar, die Jadefeuersatyrn die alten Ruinen, und verderbte Urtume und Elementare wandeln durch die Wälder. Die Druiden des Smaragdkreises versuchen, ihn zu heilen, Pflanze um Pflanze. Die Horde hält den Blutgiftposten mittendrin, und die Nachtelfen eine Lichtung im Norden, an den Toren der Holzschlundfeste." },
      },
    },
    ["feralas"] = {
      title = "Feralas",
      text = {
        { "Feralas ist ein Land aus Regen und Riesen an der Westküste Kalimdors: ein Wald aus Bäumen, so hoch, dass ihre Kronen im Nebel verschwinden, mit uralten Ruinen zwischen ihren Wurzeln. Die Nachtelfen bauten hier lange vor der Großen Teilung, und ihre Steine sind überall, überwuchert und zerbrochen. Die Gelehrten von Feathermoon verbringen ihr Leben zwischen ihnen und können noch immer nicht sagen, was die Hälfte davon einmal war." },
        { "Heute gehört der Wald den Ogern der Gordunni, deren wachsende Zahl die Siedlungen in der Nähe beunruhigt, Gnollen, Yetis, Naga an der Küste und den Grimmtotem in den Hügeln. Die Schildwachen halten eine Inselfestung vor der Küste, die Horde ein Lager im Osten, und im Herzen des Waldes steht die zerbrochene Stadt der Hochgeborenen, die die Oger Düsterbruch nennen." },
      },
    },
    ["fire-plume-ridge"] = {
      title = "Der Feuerfedergrat",
      text = {
        { "Der Feuerfedergrat erhebt sich in der Mitte von Un'Goro, mit Lava auf seinen Hängen und Feuerelementaren zwischen den Strömen. Sturmflamme bewohnt eine Höhle nahe dem Gipfel. Der Vulkan gibt den Forschern des Kraters einen auffälligen Gegenstand zum Studium." },
        { "Ringo ging, um ihn zu erkunden, und wurde in einer Höhle an seinem Südhang gefunden, verirrt und schwer überhitzt. Die Gelehrten in Marshals Zuflucht wollen noch immer wissen, was im Herzen des Grates liegt. Ein Reisender kann ihre Neugier teilen, ohne Ringos Vorbereitungen zu teilen." },
      },
    },
    ["forest-trolls"] = {
      title = "Die Waldtrolle",
      text = {
        { "Lange bevor es Menschen in Lordaeron gab, gehörten die Wälder des Nordens den Trollen des Reiches der Amani, und sie haben niemandem vergeben, der sie ihnen nahm. Als die Hochelfen über das Meer kamen und sich in Quel'Thalas niederließen, führten die Amani über Generationen Krieg gegen sie, bis die Elfen und das erste Königreich der Menschen, Arathor, sie gemeinsam in den Trollkriegen brachen. Ihre Hauptstadt Zul'Aman steht noch tief in den östlichen Wäldern." },
        { "Die Trolle kamen im Zweiten Krieg zurück, als ihr Kriegsherr Zul'jin die Waldstämme an der Seite der Horde gegen die Elfen und die Menschen Lordaerons führte, und verloren erneut. Was übrig ist, sind Stämme, verstreut über die Hügel: die Witherbark im Arathihochland und im Hinterland, die Vilebranch in ihrer Tempelstadt Jintha'Alor, die Moosschinder in den Wäldern der Östlichen Pestländer, wo viele von ihnen nun an der Seuche verfaulen." },
        { "Sie sind groß, grünhäutig und haben Hauer, sie halten an den alten Göttern der Trolle fest, und manche an schlimmeren Bräuchen als das. Die Revantusk im Hinterland sind die Ausnahme: Sie haben sich auf die Seite der Horde gestellt, und ihre Verbündeten in der Horde verbürgen sich für sie." },
      },
    },
    ["foreword-dwarf"] = {
      title = "Ein Wort der Königlichen Historikerin",
      text = {
        { "$gReisender:Reisende;, willkommen in diesem Register Azeroths. Ich habe mit dem Land um Ironforge begonnen, wo ein Zwerg jede Straße kennen und trotzdem Fragen zu den Steinen daneben haben kann." },
        { "Die Seiten folgen unseren Klans, den Kriegen, die sie entzweiten, und den älteren Werken, die die Liga zu verstehen versucht. Sie folgen auch anderen Völkern. Unsere Geschichte hat die ihre oft genug gekreuzt, dass ein Buch, das sich auf Zwerge beschränkt, vieles unerklärt ließe." },
        { "Tragt es bei Euch und lest eine Seite, wenn ein Ort Euch Grund zum Innehalten gibt. Eine Ruine fällt leichter ins Auge als das Leben, dem sie einst Obdach gab. Beide verdienen einen Platz in den Aufzeichnungen." },
        { italic = true, "Königliche Historikerin Archesonus, der Hohe Sitz, Ironforge" },
      },
    },
    ["foreword-gnome"] = {
      title = "Ein Wort an ein Kind Gnomeregans",
      text = {
        { "$gReisender:Reisende;, diese erste Seite für einen Gnom habe ich mit einiger Sorgfalt geschrieben. Gnomeregan liegt noch immer unter Dun Morogh, und Euer Volk kann noch nicht dorthin zurück. Ein Register alter Orte sollte anerkennen, dass manche Verluste noch durchlebt werden." },
        { "Ironforge hat Eurem Volk Obdach gegeben. Ihr habt Erfindungsgeist und eine beträchtliche Menge Lärm in unsere Hallen gebracht. Wir freuen uns über die Gesellschaft, mit gelegentlichen Vorbehalten gegen den Lärm. Der Bericht über Gnomeregan steht hier, zusammen mit dem Land, das seine Verbannten nun teilen." },
        { "Lest diese Seiten, wohin Eure Arbeit Euch auch führt. Ich hoffe, der Eintrag über Eure Heimat braucht eines Tages einen glücklicheren Nachtrag. Bis dahin gehört seine Geschichte neben die Erfindungen und Aufträge, die Euch helfen könnten, sie zurückzugewinnen." },
        { italic = true, "Königliche Historikerin Archesonus, der Hohe Sitz, Ironforge" },
      },
    },
    ["foreword-human"] = {
      title = "Ein Wort an einen Sohn oder eine Tochter Stormwinds",
      text = {
        { "$gReisender:Reisende;, ich freue mich, dieses Register einem Leser aus Stormwind zu schicken. Euer Volk und meines stehen seit dem Zweiten Krieg zusammen. Unseren Berichten über die Schlachten seither fehlten selten Namen von beiden." },
        { "Stormwind wurde zerstört und wiederaufgebaut. Sein neues Mauerwerk ist eine große Leistung, und die unbezahlten Steinmetze, die es errichteten, gehören ebenfalls zu seiner Geschichte. Ihr findet diesen Bericht hier neben den Geschichten, die Euer Königreich mit mehr Grund feiert." },
        { "Benutzt das Buch auf Euren Reisen. Städte, Ruinen und Straßen können Euch erzählen, wie ein Land so wurde, wie Ihr es vorfindet, vorausgesetzt, jemand behält die Leute im Blick, die sie schufen." },
        { italic = true, "Königliche Historikerin Archesonus, der Hohe Sitz, Ironforge" },
      },
    },
    ["foreword-nightelf"] = {
      title = "Ein Wort an einen der Kaldorei",
      text = {
        { "$gReisender:Reisende;, dieses Register war für einen der Kaldorei gebunden, und ich gestehe, es ist seltsam, einem Volk, das sich an zehntausend Jahre erinnert, eine Geschichte anzubieten. Verzeiht einer Zwergin ihre Anmaßung. Wir zählen unsere Zeitalter in Stein. Ihr zählt die Euren in den Leben von Bäumen." },
        { "Die meisten dieser Jahre blieb Euer Volk in seinen Wäldern und ließ niemanden herein. Nun habt Ihr vor der Küste der Dunkelküste einen neuen Weltenbaum gepflanzt und der Allianz Eure Tore geöffnet, und die Liga ist ihrer Neugier in Eure Ruinen gefolgt, wie sie es immer tut. Wo wir falsch geraten haben, wäre ich dankbar, es zu erfahren." },
        { "Wo immer Geschichte gemacht wurde, habe ich Euch eine Seite hinterlassen. Lest sie am Feuer, und denkt daran, dass jede Ruine einst jemandes Zuhause war." },
        { italic = true, "Königliche Historikerin Archesonus, der Hohe Sitz, Ironforge" },
      },
    },
    ["foreword-orc"] = {
      title = "Ein Wort an einen von der Horde",
      text = {
        { "$gReisender:Reisende;, das Register in Euren Händen wurde in Ironforge geschrieben, von Archesonus, König Magnis Königlicher Historikerin, und Ihr fragt Euch vielleicht, warum ein Verlassener aus Undercity die Geschichte einer Zwergin an einen Orc weitergeschickt hat. Ich war ein Historiker Lordaerons, bevor die Seuche mich nahm, und ich erkenne einen gerechten Bericht, wenn ich einen lese. Der ihre ist öfter gerecht, als ich erwartet hatte." },
        { "Der Weg Eures Volkes steht darin. Das Dunkle Portal brachte es hierher. Die Niederlage brachte es in die Internierungslager Lordaerons. Thrall führte es heraus und über das Meer nach Durotar, benannt nach seinem Vater. Diese Lager standen in meinem Königreich, als ich noch lebte, und ich merke, dass ich diese Seiten langsamer lese als die anderen." },
        { "Nehmt das Buch auf Eure Reisen mit. Stärke trägt Euch weit, doch Wissen trägt weiter, und je mehr Ihr über einen Ort wisst, desto mehr werdet Ihr von ihm sehen. Wenn Euer Weg Euch je nach Undercity führt, sucht mich auf. Vielleicht habe ich eine Frage an Euch." },
        { italic = true, "Parqual Fintallas, das Apothekarium, Undercity" },
      },
    },
    ["foreword-other"] = {
      title = "Ein Wort der Königlichen Historikerin",
      text = {
        { side = "Horde", aside = true, sign = "Parqual Fintallas, das Apothekarium, Undercity", "Dieses Register wurde in Ironforge geschrieben, von Archesonus, seiner Königlichen Historikerin, und es kommt aus Undercity über meinen Schreibtisch zu Euch. Sie schreibt als Zwergin der Allianz und sagt es auch. Wo sie die Horde vergisst, lest sie mit diesem Wissen, wie ich es tat." },
        { "$gReisender:Reisende;, willkommen. Dieses Register folgt den Städten, Ruinen und Straßen Azeroths und den Leuten, deren Leben sie so hinterlassen haben, wie Ihr sie vorfindet. Ihr braucht keine besondere Abstammung, um Euch dafür zu interessieren, wo Ihr steht." },
        { "Ich schreibe vom Hohen Sitz in Ironforge, wenige Schritte vom Thron des Königs, und die Forscherliga bringt mir mehr zum Lesen heim, als ich je beenden werde. Der Bericht einer Zwergin hat die Interessen einer Zwergin, doch die Welt hat uns mehr zu erforschen gegeben als die Angelegenheiten unserer eigenen Klans." },
        { "Lest eine Seite, wenn Eure Reisen Euch an ihren Ort führen. Die Steine haben vielleicht besser überdauert als die Namen. Ich habe versucht, beide in Reichweite zu halten." },
        { italic = true, "Königliche Historikerin Archesonus, der Hohe Sitz, Ironforge" },
      },
    },
    ["foreword-skyborne"] = {
      title = "Ein Wort an einen der Himmelsgeborenen",
      text = {
        { side = "Horde", aside = true, sign = "Parqual Fintallas, das Apothekarium, Undercity", "Dieses Register wurde in Ironforge geschrieben, von Archesonus, seiner Königlichen Historikerin, und es kommt aus Undercity über meinen Schreibtisch zu Euch. Ihr Wort an Euer Volk war zu gut, um es neu zu schreiben, also steht es hier, wie sie es schrieb." },
        { "$gReisender:Reisende;, dieses Register war für einen der Himmelsgeborenen gebunden, und ich gestehe, ich musste es zweimal beginnen. Bis Euer Volk vom Himmel herabkam, wusste kein Historiker in Ironforge, dass es Euch gibt. Euer eigener Name für Euch, die Shen'dorei, das verborgene Volk, ist schöner als alles, was wir hätten schreiben können." },
        { "Wir kannten Euren Anfang, ohne zu wissen, dass er Eurer war. Eure Ahnen lebten in Eldre'Thalas, der Stadt, die die Oger heute Düsterbruch nennen, und als ihr Prinz einen Dämon binden wollte, um die Magie seines Volkes zu nähren, erhoben sie sich gegen ihn hinter einem maskierten Anführer, dem Shal'nan. Sie flohen nach Westen übers Meer, die Schiffe des Prinzen hinter sich, und Windgeister hoben ihre Insel in den Himmelswall, ganz aus der Welt hinaus. Die Forscherliga kennt diese Hallen in Feralas gut. Keiner von uns ahnte, dass ein Teil der Stadt entkommen war." },
        { "Nun sind die Geister fort, die Insel versagt, und Euer Volk ist gekommen, um Hilfe zu suchen, der Hohe Orden bei den Magiern Dalarans, die Windformer bei den Schamanen. Dieses Register kennt die Welt, in die Ihr zurückgekehrt seid, besser als die, die Ihr verlassen habt. Wo immer Geschichte gemacht wurde, habe ich Euch eine Seite hinterlassen. Lest sie am Feuer, und denkt daran, dass jede Ruine einst jemandes Zuhause war." },
        { italic = true, "Königliche Historikerin Archesonus, der Hohe Sitz, Ironforge" },
      },
    },
    ["foreword-tauren"] = {
      title = "Ein Wort an einen der Shu'halo",
      text = {
        { "$gReisender:Reisende;, Euer Volk bewahrt seine Geschichte in Liedern und im Gedächtnis des Landes. Meines bewahrte sie in Büchern, und eine Seuche kann eine Bibliothek ebenso sicher leeren wie eine Stadt. Vielleicht waren die Lieder die klügere Wahl." },
        { "Die folgenden Seiten wurden in Ironforge geschrieben, von Archesonus, seiner Königlichen Historikerin, und sie kommen aus Undercity über meinen Schreibtisch zu Euch. Sie erzählen, wie die Tauren generationenlang unter dem Druck der Zentauren über die Ebenen Kalimdors wanderten und wie Cairne Bloodhoof mit Hilfe der Orcs die Stämme in Mulgore versammelte. Thunder Bluff steht nun über dem Grasland als Heimat eines Volkes, dem eine feste Heimat lange verwehrt war." },
        { "Lest sie mit der Aufmerksamkeit, die Ihr Euren Ältesten schenkt. Wo eine Seite und ein Ältester sich widersprechen, wäre ich dankbar zu hören, in welchem Punkt und warum. Ein Historiker sammelt solche Widersprüche, wie andere Münzen sammeln." },
        { italic = true, "Parqual Fintallas, das Apothekarium, Undercity" },
      },
    },
    ["foreword-troll"] = {
      title = "Ein Wort an einen der Dunkelspeer",
      text = {
        { "$gReisender:Reisende;, dieses Register war für einen der Dunkelspeer gebunden, und ich schulde Euch zwei Geständnisse. Seine Seiten wurden in Ironforge geschrieben, von Archesonus, der dortigen Königlichen Historikerin. Ich habe sie nur aus Undercity weitergeschickt. Und die Geschichte der Trolle ist älter als alles, was einer von uns beiden im Regal stehen hat. Eure Art baute Reiche in den Dschungeln des Südens und den Wäldern des Nordens, lange bevor die Königreiche der Menschen entstanden." },
        { "Euer Stamm war klein und hart bedrängt, als Thralls Schiffe Euch auf Euren Inseln fanden, und seither habt Ihr der Horde die Treue gehalten, an den Küsten von Durotar unter Sen'jins Namen. Mein eigenes Volk kam später zur Horde, und auf einem seltsameren Weg. Wir haben viel von denen zu lernen, die zuerst zu ihr standen." },
        { "Wo immer Geschichte gemacht wurde, hat Euch die Zwergin eine Seite hinterlassen. Wo ihre Seiten hinter dem zurückbleiben, was Eure Ältesten erzählen könnten, vertraut Euren Ältesten, und dann, wenn Ihr die Zeit erübrigen könnt, erzählt mir, was sie sagten." },
        { italic = true, "Parqual Fintallas, das Apothekarium, Undercity" },
      },
    },
    ["foreword-undead"] = {
      title = "Ein Wort an einen der Verlassenen",
      text = {
        { "$gReisender:Reisende;, Ihr und ich haben beide unser Königreich überlebt. Ich war ein Historiker Lordaerons, bevor die Seuche mich nahm, und Ihr erinnert Euch vielleicht an seine Städte, wie sie waren, als seine Hauptstadt noch über der Erde stand. Dieses Register kennt sie nur aus Aufzeichnungen, denn es wurde in Ironforge geschrieben, von Archesonus, König Magnis Königlicher Historikerin. Ich habe es trotzdem weitergeschickt. Es ist ein gerechter Bericht, und gerechte Berichte über unsere Heimat sind selten." },
        { "Die Verlassenen befreiten sich vom Lichkönig und folgen nun Sylvanas unter den Ruinen der Stadt, die wir kannten. Vieles an dem Leben, das wir jetzt führen, liegt jenseits des Verständnisses einer Zwergin. Wo sie über den Scharlachroten Kreuzzug schreibt, ist sie freundlicher zu ihm, als ich es wäre." },
        { "Tragt das Register bei Euch, wenn es Euch nützt. Wo ein Ort etwas wachruft, das diese Seiten nicht erzählen können, vertraut Eurem eigenen Gedächtnis mehr als ihren Aufzeichnungen, und mehr als meinen." },
        { italic = true, "Parqual Fintallas, das Apothekarium, Undercity" },
      },
    },
    ["franclorn-forgewright"] = {
      title = "Franclorn Forgewright",
      text = {
        { "Franclorn Forgewright war der oberste Baumeister der Dunkeleisenzwerge und der Erfinder der Stonewrought-Bauweise. Er wird Euch sagen, dass Ihr mit ziemlicher Sicherheit schon auf etwas gestanden habt, das er gebaut hat, und der große Damm von Loch Modan trägt den Namen seiner Methode. Die Schattenschmiede, die Hauptstadt der Dunkeleisenzwerge unter dem Berg, war sein Werk." },
        { "Er ist tot. Sein Geist bleibt in seinem Grabmal im Blackrock, sichtbar nur für die, die selbst tot sind, und sein Nachfolger als Baumeister, Fineous Darkvire, hat seinen großen Hammer Ironfel genommen. Franclorn will ihn wieder in den Händen der Statue sehen, die die Dunkeleisenzwerge ihm am Schrein von Thaurissan errichteten. Dafür gibt er den Schlüssel zu den Tiefen dessen her, was er seine verfluchte Stadt nennt." },
        { "Gebaut hat er sie trotzdem. Ein Zwerg kann eine Stadt verleugnen und dennoch stolz auf ihr Mauerwerk sein, $gReisender:Reisende;. Ich kenne mehrere." },
      },
    },
    ["freewind-post"] = {
      title = "Freiwindposten",
      text = {
        { "Der Freiwindposten ist ein Dorf der Tauren oben auf den Nadeln in der Mitte der Schlucht, ein Haufen Hütten auf dem hohen Fels, durch Seilbrücken verbunden und über einen Aufzug zu erreichen. Windreiter kommen und gehen, und die Tauren jagen auf dem Grund der Schlucht darunter." },
        { "Er steht von zwei Seiten unter Druck. Die Zentauren der Galak fallen immer häufiger ein, und die Tauren der Grimmtotem, die den nahen Düsterwolkengipfel halten, haben sich gegen ihresgleichen gewandt. Die Tauren vom Freiwindposten sagen, sie benähmen sich schon seit einiger Zeit seltsam. Es ist hart für einen Tauren, das über andere Tauren zu sagen." },
      },
    },
    ["frostmane-trolls"] = {
      title = "Die Trolle der Frostmane",
      text = {
        { "Die Frostmane bewohnen das verschneite Land westlich von Kharanos und Lager bis hinüber zum Coldridgetal. Ihre Höhle beherbergt Kopfjäger, Seher und Schattenzauberer, und so müssen die Gebirgsjäger zwischen den Verwehungen auf mehr achten als auf Speerspitzen." },
        { "Grelin Whitebeard warnt vor neuen Angriffen, und junge Zwerge werden fast sofort gegen sie ausgeschickt, kaum dass sie von zu Hause fort sind. Der Streit wird sehr früh vertraut: ein Trolllager jenseits des letzten freundlichen Feuers, ein Bericht, der zu den Wachen zurückgebracht wird, und eine weitere Patrouille, die in denselben Schnee geschickt wird." },
      },
    },
    ["frostwolf-clan"] = {
      title = "Der Frostwolfklan",
      text = {
        { "Durotans Frostwolf verweigerten das Dämonenblut, das einen Großteil der Horde band. Als er sich den Hexenmeistern und ihrem Einfall in Azeroth widersetzte, verbannte Gul'dan seinen Klan. Sie fristeten ein hartes Leben im Alteracgebirge. Durotan wurde ermordet, doch der Klan überdauerte." },
        { "Sein Sohn Thrall fand sie nach seiner Flucht aus Durnholde. Sie lehrten ihn das Leben seines Volkes, und ihr Schamane Drek'Thar lehrte ihn, den Elementen zu folgen. Als Thrall später die Internierungslager befreite und die Horde über das Meer führte, blieben die Frostwolf in ihrem Tal." },
        { "Drek'Thar, heute blind, führt sie noch immer dort. Sie wollen ihre Heimat behalten. Die Expedition der Stormpike hat einen Anspruch Ironforges dagegen mitgebracht." },
      },
    },
    ["furbolgs"] = {
      title = "Die Furbolgs",
      text = {
        { "Die Furbolgs gehören zu den nördlichen Wäldern Kalimdors, wo ihre Dörfer und Totems seit Ewigkeiten neben dem Land der Nachtelfen stehen. Vor zehntausend Jahren kämpften sie an der Seite der Elfen gegen die Brennende Legion. Ihre Geschichte hat Platz für alte Freundschaften, wie heftig ein Fremder heute auch an einem Lager empfangen werden mag." },
        { "Stamm um Stamm hat unter der Verderbnis gelitten: die Knarzklauen auf Teldrassil, die Schwarzfelle an der Dunkelküste, die Totenwaldfelle im Teufelswald und die Winterfelle in Winterspring unter ihnen. Der Wahnsinn hat Nachbarn zu Feinden gemacht. Im Teufelswald gibt das vergiftete Land den Nachtelfen reichlich Grund, der Verseuchung der Legion die Schuld zu geben." },
        { client = "classic", "Die Holzschlundfeste hat sich diesem Schicksal widersetzt. Sie bewacht die Tunnel, die den Teufelswald, Moonglade und Winterspring verbinden, und eine weitere verschlossene Feste in Azshara. Hilfe gegen ihre verderbten Verwandten kann einem Reisenden langsam ihr Vertrauen einbringen." },
        { client = "forever", "Die Holzschlundfeste bewacht noch immer die Tunnel, die den Teufelswald, Moonglade und Winterspring verbinden, und lässt sich durch Hilfe gegen ihre verderbten Verwandten gewinnen. Die Schwarzschlundfeste in Azshara gehört einem anderen Stamm, einem, der der Verderbnis erlegen ist." },
      },
    },
    ["gadgetzan"] = {
      title = "Gadgetzan",
      text = {
        { "Gadgetzan ist eine Goblinstadt im Norden der Wüste von Tanaris, für das Steamwheedle-Kartell von Marin Noggenfogger geführt. Sie hat Mauern, Brunnen, ein Auktionshaus, ein Gasthaus, sehr viele Ingenieure und eine Wache aus angeheuerten Schlägern, die den Frieden mit großer Begeisterung wahren. Allianz und Horde handeln beide hier, und beide benehmen sich, sonst setzt es was." },
        { "Die Stadt lebt von ihrem Wasser. Ihre Ingenieure graben die Brunnen und ermitteln, wo die nächsten zu graben sind, und alle anderen bezahlen dafür. Es ist auch der Ort, um fast alles zu kaufen, vom Elixier eines Goblins, das einen vielleicht in ein Skelett verwandelt, bis zu den Eiern seltsamer Vögel, und um von fast allem zu hören, was im Süden vor sich geht." },
      },
    },
    ["gates-of-ironforge"] = {
      title = "Die Tore von Khaz Modan",
      text = {
        { "Der Nordtorpass und der Südtorpass führen Reisende zwischen Dun Morogh und Loch Modan hin und her. Gebirgsjäger halten an beiden Wegen Außenposten. Im Gebirge kann eine schmale Straße so viel Bewachung verlangen wie eine breite Grenze." },
        { "Captain Rugelfuss erklärt die Schwierigkeit von der Seite Loch Modans aus. Sein Regiment muss das Tor halten, statt die Troggs in der Nähe zu verfolgen, während die Reserve von Ironforge an der Front der Allianz gebunden ist. Er bittet Abenteurer, das Land zu verteidigen, für das seine Soldaten ihre Posten nicht verlassen können." },
      },
    },
    ["gathilzogg"] = {
      title = "Gath'Ilzogg",
      text = {
        { "Steinwacht wurde gebaut, um das Rotkammgebirge zu verteidigen. Gath'Ilzoggs Krieger der Blackrock haben daraus stattdessen die Festung gemacht, von der aus sie Seenhain überfallen und den Krieg des Berges hinab zu den Höfen und Straßen um den Immerruhsee tragen." },
        { "Magistrat Solomon hat eine Belohnung auf seinen Kopf ausgesetzt. Die Burg muss zurückerobert und ihr Befehlshaber getötet werden. Gath'Ilzoggs Tod ist nur der erste Schritt dieser Arbeit. Für Seenhain ist eine Festung am Horizont zum Maß dafür geworden, wie viel von ihrem eigenen Land die Stadt nicht mehr erreichen kann." },
      },
    },
    ["ghost-howl"] = {
      title = "Geistheuler",
      text = {
        { "Geistheuler ist ein großer Wolf aus Mulgore, dessen Fell eine schreckliche Wunde aus dem Kampf gegen die Brennende Legion trägt. Die Narbe gibt dieser besonderen Jagdtrophäe eine Geschichte, die über die Jagd über die Ebenen hinausreicht." },
        { "Skorn Whitecloud erkennt das Fell in Bloodhoof wieder. Er bietet dem Jäger eine seiner Waffen an und hofft, dass der Geist des Wolfes Frieden gefunden hat." },
      },
    },
    ["gnolls"] = {
      title = "Die Gnolle",
      text = {
        { "Die Flusspfoten überfallen Elwynn und Westfall. Die Moosfelle bewohnen das Sumpfland. Diese Rudel haben verschiedene Geschichten. Hoggers Steckbrief warnt, er sei zu gefährlich für einen einzelnen Jäger, während Rethiels Bericht sagt, die Moosfelle hätten einst friedlich neben ihren Nachbarn gelebt." },
        { "Manche Rudel dienen anderen Mächten. Die Schattenfelle im Rotkammgebirge gehorchen Morganth, und Thule Rabenklaue befehligt die untoten Moderfelle in Tirisfal und im Silberwald. Jenseits des Meeres jagen die Bleichmähnen in Mulgore, und die Waldpfoten leben in Feralas. Fragt, welchem Rudel Ihr gegenübersteht, $gReisender:Reisende;. Sein Name verrät Euch mehr über die Schwierigkeiten vor Euch als eine allgemeine Meinung über Gnolle." },
      },
    },
    ["gnomeregan"] = {
      title = "Gnomeregan",
      text = {
        { "Gnomeregan liegt unter dem westlichen Dun Morogh, die alte Hauptstadt der Gnome, in der Not des Dritten Krieges zugrunde gerichtet. Troggs drangen in ihre Hallen ein. Um sie aufzuhalten, setzten die Gnome in ihrer eigenen Stadt Strahlung frei." },
        { "Die Troggs überlebten. Viele Gnome starben, und andere wurden zu den gewalttätigen Überlebenden, die man heute Lepragnome nennt. Wer entkam, fand Zuflucht in Ironforge. Der Preis des Versuchs ist in den vergifteten Hallen noch immer deutlich zu sehen." },
        { "Sicco Thermaplugg ist noch dort. Hochtüftler Mekkatorque nennt ihn einen Verräter und bittet Abenteurer, ihn zu töten. Wenn Ihr hineingeht, $gReisender:Reisende;, denkt daran, dass dies eine Hauptstadt voller Häuser und Werkstätten war. Ihr Volk versucht noch immer zu retten, was übrig ist." },
      },
    },
    ["gnomeregan-exiles"] = {
      title = "Die Gnomeregangnome",
      text = {
        { "Ein Volk ohne Heimat, und die fröhlichsten Verbannten, denen Ihr je begegnen werdet. Die Gnome, die aus Gnomeregan entkamen, leben nun in Tüftlerstadt, im Herzen von Ironforge, und in Außenposten wie Steelgrills Depot, in Sichtweite ihrer alten Tore." },
        { "Lasst Euch von der Fröhlichkeit nicht täuschen. Jede Erfindung, die sie erproben, jeder Rekrut, den sie ausbilden, ist für einen einzigen Tag bestimmt: den Tag, an dem sie nach Gnomeregan zurückmarschieren und es sich zurückholen." },
        { "Ironforge hat ihnen Obdach angeboten, solange sie es brauchen. Die meisten Zwerge freuen sich über die Gesellschaft, wenn auch nicht über den Lärm." },
      },
    },
    ["goldshire"] = {
      title = "Goldhain",
      text = {
        { "Goldhain liegt an einer Wegkreuzung in Elwynn, mit dem Gasthaus Zur Höhle des Löwen, das für Reisende bereitsteht, und Marshal Dughan, der ihnen Arbeit geben will. Das Dorf ist älter als die Kriege. Es brannte, als die Orcs im Ersten Krieg durch Elwynn zogen." },
        { "Nach dem Zweiten Krieg kehrten die Leute Stormwinds aus dem Exil in Lordaeron zurück und bauten es wieder auf. Die Schmiede und der Markt sind wieder geschäftig, und junge Abenteurer machen hier Halt auf dem Weg, sich einen Namen zu machen. Seht Euch Dughans Kopfgeldbrett an, solange Ihr hier seid, $gReisender:Reisende;. Das Dorf hat sich erholt. Der Marshal hat noch reichlich Sorgen." },
      },
    },
    ["great-masquerade"] = {
      title = "Die große Maskerade",
      text = {
        { "Marshal Reginald Windsor sammelte Beweise gegen die Beraterin von Hochlord Bolvar Fordragon, nur um sie in den Verliesen des Blackrock zu verlieren. Nach seiner Rettung kehrte er mit neuen Beweisen zurück und mit Gefährten, die bereit waren, an seiner Seite zu stehen. Er brachte beides in die Burg Stormwind." },
        { "Dort entlarvte er Lady Katrana Prestor als Onyxia, Tochter Todesschwinges und Schwester Nefarians. Sie hatte Stormwinds Heer zu Hause gehalten, während die Orcs ihres Bruders das Rotkammgebirge bedrohten, und Bolvar ihrem Willen unterworfen. Windsor brach ihre Verkleidung vor dem Hof. Sie floh in ihren Hort in den Marschen von Dustwallow." },
        { "Windsor starb bei der Konfrontation. Schreibt seinen Namen nieder, $gReisender:Reisende;, wenn Ihr die Niederlage des Drachen verzeichnet. Sein Anteil daran begann lange bevor irgendwer ihren Hort erreichte." },
      },
    },
    ["green-dragonflight"] = {
      title = "Der grüne Drachenschwarm",
      text = {
        { "Yseras Schwarm hütet den Smaragdgrünen Traum und die vier großen Bäume, an denen der Traum die wache Welt berührt: Seradane im Hinterland, Bough Shadow in Ashenvale, Traum-Geäst in Feralas und den Zwielichtshain im Dämmerwald. Die Druiden wandeln durch den Traum dank des Paktes, den ihre Ahnen mit Ysera schlossen. Die Drachen wandeln selten durch die Welt." },
        { "Nicht allen geht es gut. Etwas hat sich in den Traum geschlichen und einige von Yseras eigenen Kindern verdreht. Die vier, die nun an den großen Bäumen spuken, haben ihre eigene Seite. Vor ihnen gab es Eranikus, der über dem versunkenen Tempel in den Sümpfen des Elends schlief und im selben Albtraum gefangen wurde." },
        { "Itharius, ein weiterer des Schwarms, wartet in einer Höhle in diesem Sumpf und sucht Sterbliche, die helfen können, Eranikus zu erlösen. Während die verderbten Hüter noch an den großen Bäumen spuken, bittet einer ihrer Verwandten Fremde, einen Drachen heimzubringen." },
      },
    },
    ["greymane-wall"] = {
      title = "Der Greymane-Wall",
      text = {
        { "Der Greymane-Wall schließt den Süden des Silberwalds vom Meer bis zur Klippe ab, mit Gilneas hinter seinem Tor. Nach dem Zweiten Krieg zerstritt sich König Genn Greymane mit den anderen Herrschern der Allianz, unter anderem über die Kosten, die besiegten Orcs in Internierungslagern zu halten. Er zog sein Königreich aus der Allianz zurück und schloss es hinter dieser Mauer ein." },
        { "Flüchtlinge aus dem Norden finden das Tor verschlossen. Kein Wort ist aus Gilneas herausgedrungen, das seine gegenwärtigen Angelegenheiten erklären würde. Die Mauer könnt Ihr deutlich genug sehen, $gReisender:Reisende;. Es ist das Land dahinter, das außerhalb dieser Aufzeichnungen bleibt." },
      },
    },
    ["grim-batol"] = {
      title = "Grim Batol",
      text = {
        { "Als die Wildhammer aus Ironforge vertrieben wurden, hauten sie Grim Batol aus den östlichen Bergen, und es war eine Festung, die es mit Ironforge selbst aufnehmen konnte. Dann zogen die Dunkeleisenzwerge unter Königin Modgud dagegen, und obwohl die Wildhammer die Schlacht gewannen und sie erschlugen, hinterließ ihr Tod eine Finsternis im Stein. Die Wildhammer wollten nicht bleiben. Sie zogen nach Norden ins Hinterland, und Grim Batol stand leer." },
        { "Es blieb nicht leer. Im Zweiten Krieg machten die Orcs des Dragonmawklans es zu ihrer Festung, und dort hielten sie Alexstrasza gefangen, die Königin der roten Drachen, und zwangen ihre Kinder, Orcs in die Schlacht zu tragen. Am Ende wurde sie befreit, und die Dragonmaw wurden zerstreut." },
        { "Die roten Drachen sind noch immer dort. Was auch immer sie in Grim Batol bewachen, sie bewachen es erbittert. Geht nicht in seine Nähe, $gReisender:Reisende;. Die roten Drachkin an seinen Zugängen sind Warnung genug." },
      },
    },
    ["grimtotem"] = {
      title = "Die Grimmtotem",
      text = {
        { "Die meisten Tauren leben nach dem Frieden der Erdenmutter. Die Grimmtotem nicht. Sie sind ein Stamm, der glaubt, die anderen Völker hätten überhaupt kein Recht auf Kalimdor, Tauren, die anderer Meinung sind, eingeschlossen, und sie kämpfen ohne Regeln und ohne Gnade darum, es zurückzunehmen." },
        { "Ihre Matriarchin Magatha, die Ältestengreisin, lebt in Thunder Bluff selbst und sitzt unter den Ältesten, was etwas über die Geduld von Cairne Bloodhoof verrät. Ihre Krieger sind weniger höflich. Sie überfallen das Steinkrallengebirge, halten den Düsterwolkengipfel in Tausend Nadeln, setzen dem Freiwindposten zu und unterhalten ein Truppenlager in Feralas. Fragt einen Tauren vom Freiwindposten, was er von den Grimmtotem hält, und tretet dann einen Schritt zurück." },
      },
    },
    ["grom-hellscream"] = {
      title = "Grom Hellscream",
      text = {
        { "Grommash Hellscream, Häuptling der Warsong, war der erste der Orchäuptlinge, der auf Draenor Mannoroths Blut trank, und er führte die anderen dazu. Die Stärke, die es ihnen gab, band die Klans an den Dämon, dessen Blut sie teilten." },
        { "Als die Horde fiel und die Klans in die Lager getrieben wurden, kämpften seine Warsong aus dem Verborgenen weiter, und Grom blieb ein unbesiegter Häuptling. Der junge Thrall lernte von ihm, was die Horde einmal gewesen war, und fand einen Verbündeten, um die zerstreuten Klans zusammenzuführen. Die beiden segelten als Freunde nach Kalimdor, mit der Hoffnung auf eine Heimat jenseits der Lager und der alten Kriege." },
        { "Grom erlebte nicht mehr, wie die neue Heimat der Horde erbaut wurde. Thrall setzte einen Stein, wo er im Demonfall-Canyon fiel. 'In vielerlei Hinsicht', steht darauf, 'begann und endete der Fluch, der auf unserem Volk lastete, mit Grom.' Sein Name bedeutete Riesenherz, schreibt der Kriegshäuptling, und er hat ihn sich hundertfach verdient." },
      },
    },
    ["gromgol-base-camp"] = {
      title = "Das Basislager von Grom'gol",
      text = {
        { "Grom'gol ist eine Palisade der Horde an der Nordküste des Schlingendorntals, angeflogen von Zeppelinen aus Orgrimmar und Undercity. Für die Dunkelspeer ist eine Reise hierher eine Rückkehr in das Land ihrer Ahnen. Zu ihren Geschäften im Dschungel gehören Verluste, die ihnen folgten, als sie gingen." },
        { "Nimboya sucht Yenniku, den jüngsten Sohn seines Häuptlings, der den Trollen von Zul'Gurub als Knabe nach altem Brauch übergeben wurde. Die Dunkelspeer verloren ihn, als sie mit Thrall fortgingen. Nimboya verdächtigt zuerst die Bloodscalp, doch die Suche enthüllt Zanzils des Ausgestoßenen magischen Griff um ihn und führt zu dem Versuch, seine Seele zu befreien." },
      },
    },
    ["gurubashi-arena"] = {
      title = "Die Arena der Gurubashi",
      text = {
        { "Mitten im Dschungel steht eine große steinerne Arena, die die Gurubashi vor langer Zeit für ihre Blutspiele erbauten. Die Trolle sind fort, das Kämpfen nicht: Die Goblins und Piraten, die sie heute betreiben, halten regelmäßig Wettkämpfe ab, und ab und zu werfen sie eine Truhe voller Schätze mitten auf den Boden und lassen den nehmen, der dann noch steht." },
        { "Sie steht allen offen, Allianz und Horde gleichermaßen, was heißt, dass sie der eine Ort im Schlingendorntal ist, an dem beide ermutigt werden, einander umzubringen." },
      },
    },
    ["gurubashi-empire"] = {
      title = "Das Reich der Gurubashi",
      text = {
        { "Die Dschungeltrolle der Gurubashi beherrschten einst ein Reich, das sich über den Süden der Östlichen Königreiche und über die Inseln des Meeres erstreckte, und das Schlingendorntal war sein Herz, mit der großen Tempelstadt Zul'Gurub in seiner Mitte. Seine Ruinen sind überall in diesem Dschungel: Stufentempel, zerbrochene Götzenbilder und gepflasterte Straßen unter den Wurzeln." },
        { "Sein Fall war das Werk seiner eigenen Priester. Die Atal'ai holten den Blutgott Hakkar den Seelenschinder in die Welt, und sein Hunger nach Opfern brachte das Reich gegen sich selbst auf. Die Stämme erhoben sich, trieben die Atal'ai ins Exil und zerfielen. Was übrig blieb, wurde zu den Stämmen, die wir kennen: die Skullsplitter und die Bloodscalp im Dschungel, die Dunkelspeer, die mit Thrall fortgingen, und andere. Die Trolle haben nicht vergessen, was sie einmal waren." },
      },
    },
    ["hakkar"] = {
      title = "Hakkar der Seelenschinder",
      text = {
        { "Hakkar der Seelenschinder ist der Blutgott der Trolle, eine geflügelte Schlange, die sich von Blut und Seelen nährt. Vor langer Zeit holten die Atal'ai ihn in die Welt. Seine Forderung nach Opfern wurde so schrecklich, dass die Stämme sich gegen seine Priester erhoben und sie ins Exil trieben." },
        { "Durch Zul'Gurub ist er zurückgekehrt. Die Zandalar warnen, dass seine Herrschaft sich über die ganze Welt ausbreiten wird, wenn man ihn nicht aufhält. Selbst sein gefallenes Herz birgt Macht: Wer ihm gegenübergetreten ist, beschreibt es als noch immer brennend. Behaltet die Warnung der Zandalar im Sinn, $gReisender:Reisende;, wenn Ihr diese Stadt betretet. Sie wissen, was seine Anbetung ihr Volk einst gekostet hat." },
      },
    },
    ["hall-of-thanes"] = {
      title = "Die Halle der Thanen",
      text = {
        { "Unter Ironforge liegen die Höhlen von Alt-Ironforge, und in ihnen ein Ort, den die Zwerge die Halle der Thanen nennen. Die Dunkeleisenzwerge haben ihren Weg dorthin gefunden. Eine Karte, die man ihren Spionen in Ironbands Truppenlager abgenommen hat, zeigt Tunnel und alte Fernstraßen, die unter der Stadt zusammenlaufen, und Erdseher Farsen, ein Besucher aus Aerie Peak, folgte ihnen hinab bis zur Halle und zu dem Dunkeleisenzwerg, der dort befiehlt, einem gewissen Durgen Dirgehammer." },
        { "Die eigenen Toten der Halle finden keine Ruhe. Afadra Dunwall, eine Hüterin der Überlieferung aus Ironforge, bittet Reisende, die Geister von Anvilmar zur Ruhe zu betten, und einer von ihnen, Faldrim Anvilmar, scheint einen alten Groll weit über das Grab hinaus bewahrt zu haben. König Magni will den Kopf des Befehlshabers. Ich hätte gern, dass die Liga sich den Ort einmal gründlich ansieht, sobald die Dunkeleisenzwerge draußen sind." },
      },
    },
    ["hammerfall"] = {
      title = "Hammerfall",
      text = {
        { "Hammerfall war nach dem Zweiten Krieg ein großes Internierungslager für Orcs. Thrall und Orgrim Schicksalshammer brachen es gemeinsam auf. Während der Kämpfe stach ein Ritter Schicksalshammer mit einer Lanze von hinten nieder, und der frühere Kriegshäuptling starb hier." },
        { "Die Horde hat das Lager als Festung wiederaufgebaut und es ihm zum Gedenken benannt. Manche der Orcs hinter seiner Palisade waren einst Gefangene auf diesem Boden." },
      },
    },
    ["hammertoes-digsite"] = {
      title = "Hammertoes Grabungsstätte",
      text = {
        { "Hammertoes Grabungsstätte ist das Lager der Forscherliga vor den Toren von Uldaman, benannt nach dem Ausgrabungsleiter, der es führte, und es hat schwere Zeiten hinter sich. Die Troggs kamen aus dem Gewölbe herauf und überrannten die Gräber. Ausgrabungsleiter Agmond, der die südlichen Stätten leitete, verstummte, und als jemand nachsehen ging, fand man sein Lager und das, was von ihm übrig war. Hammertoe selbst wurde von den Dunkeleisenzwergen des Klans Schattenschmiede verschleppt, die wissen wollen, was er über die Werke der Titanen weiß." },
        { "Ausgrabungsleiter Ryedol hält, was von der Grabung übrig ist, und er gibt nicht leicht auf. Hammertoe hoffentlich auch nicht. Die Schattenschmiede suchen in Uldaman nach den Geheimnissen der Golems der Titanen, und Hammertoe suchte zuerst nach ihnen, um sie aus den Händen der Dunkeleisenzwerge zu halten." },
      },
    },
    ["hamuul-runetotem"] = {
      title = "Erzdruide Hamuul Runetotem",
      text = {
        { "Erzdruide Hamuul Runetotem steht auf der Anhöhe der Ältesten in Thunder Bluff, unter den Lehrern und geistigen Führern der Tauren. Sein Platz dort gibt den Druiden eine Stimme in der Stadt ebenso wie ein Zuhause." },
        { "Berichte aus den Höhlen des Wehklagens führen Abenteurer von jenseits Mulgores zu ihm. Er schickt sie zu Nara Wildmane, um die Nachforschungen fortzusetzen." },
      },
    },
    ["harpies"] = {
      title = "Die Harpyien",
      text = {
        { "Harpyien nisten überall in Kalimdor, jagen und wirken Zauber, mit Flügeln und Krallen, die sie über den Boden tragen. Die Staubschwingen bewohnen Durotar, die Windfurien Mulgore, die Hexenschwingen das Brachland und die Blutfurien das Steinkrallengebirge. Ihre Schwärme haben sich unter den Siedlungen darunter Feinde gemacht." },
        { "Ruul Eagletalon schickt Jäger als Prüfung gegen die Windfurien. Die Druiden des Steinkrallengebirges wollen das verbrannte Tal von den Blutfurien zurück, um es wiederherzustellen. Ein Reisender, der unter ihren Nistplätzen hindurchzieht, hat praktischen Grund zu lernen, welcher Schwarm sie hält." },
      },
    },
    ["hearthglen"] = {
      title = "Hearthglen",
      text = {
        { "Hearthglen umgibt Burg Mardenholde im Norden der Westlichen Pestländer. Der Scharlachrote Kreuzzug hält seine Mauern, und Großinquisitor Isillien hält mit rücksichtslosen Mitteln eine grüne, überlebende Stadt inmitten des verseuchten Landes." },
        { "Die Burg war einst Tirion Fordrings Sitz. Als er verbannt wurde, weil er einen Orc verteidigte, der ihm das Leben gerettet hatte, erzählte seine Frau ihrem Sohn Taelan, er sei tot. Taelan hält nun das Zuhause seines Vaters für den Kreuzzug. Tirion lebt in einer Hütte am Thondroril, sammelt, was er von der Vergangenheit des Jungen finden kann, und sucht nach einem Weg, ihn zu erreichen." },
        { side = "Horde", aside = true, sign = "P. F.", "Lordaeron verbannte einen Paladin, weil er einen Orc verschonte. Die Orcs teilen ihre Horde heute mit den Toten Lordaerons, und ich habe noch nicht entschieden, was ich davon halten soll." },
      },
    },
    ["helcular"] = {
      title = "Helcular",
      text = {
        { "Helcular war ein Zauberer aus den Hügeln über Southshore, und er war beinahe ein Lich, als die Leute von Southshore seinen Ritualhort fanden und ihn töteten. Sie begruben ihn auf ihrem eigenen Friedhof, wohl um ihn im Auge zu behalten. Sein Lehrling nahm es schlecht auf." },
        { "Die Yetis haben den Hort jetzt, und mit ihm die Rute, durch die Helcular seine Riten wirkte. Er hatte in den Höhlen dieser Berge drei zeremonielle Feuer errichtet, die Flammen von Azel, Veraz und Uzel, und sein Lehrling will, dass die Rute geborgen, an jeder von ihnen aufgeladen und in das Grab seines Meisters mitten in der Stadt der Menschen getrieben wird." },
        { "Was dann aus dem Friedhof von Southshore heraufkommt, ist nicht der Zauberer, der er war, doch es erinnert sich, wer ihn begraben hat. Southshore hat sehr viele Feinde, $gReisender:Reisende;. Diesen hat es sich selbst gemacht." },
      },
    },
    ["high-elves"] = {
      title = "Die Hochelfen",
      text = {
        { "Die Hochelfen begannen als Nachtelfen: Hochgeborene vom Hof Azsharas, die die Große Teilung überlebten und ihre Magie nicht aufgeben konnten. Als die Druiden sie bei Todesstrafe verboten, antwortete ihr Anführer Dath'Remar mit einem Sturm von Zaubern über Ashenvale. Die Druiden wollten nicht so viele ihrer eigenen Verwandten töten. Stattdessen verbannten sie sie, und Dath'Remars Volk segelte nach Osten über den Mahlstrom, froh, seine vorsichtigen Vettern los zu sein." },
        { "Sie gingen im Norden dessen an Land, was die Menschen Lordaeron nennen sollten, und ließen sich zuerst auf den Lichtungen von Tirisfal nieder, bis nach einigen Jahren viele von ihnen wahnsinnig wurden. Gerüchte sagten, etwas Böses schlafe unter diesem Boden, und bewiesen wurde es nie. Vom Brunnen abgeschnitten, verloren sie unterwegs ihre Unsterblichkeit, wurden kleiner und blasser und kämpften um jede Meile gegen die Trolle der Amani. Schließlich gründeten sie Quel'Thalas tief in den nördlichen Wäldern, auf Land, das den Trollen heilig war, und umgaben es mit Runensteinen. Dath'Remar nahm den Namen Sonnenwanderer an, 'der am Tage wandelt', und sein Volk ist seither ein Volk der Sonne." },
        { "Quel'Thalas ist nun fort. Die Elfen, denen ein Reisender begegnet, sind, was davon übrig ist: Waldläufer, die die Quel'Lithien-Lodge am Rand der Pestländer halten, die Hochtalelfen der Quel'Danil-Hütte im Hinterland, Wanderer hier und da. Sie sind selbst im Exil stolz. Angesichts dessen, was sie verloren haben, fällt es mir schwer, es ihnen vorzuhalten." },
      },
    },
    ["high-tinker-mekkatorque"] = {
      title = "Hochtüftler Mekkatorque",
      text = {
        { "Gelbin Mekkatorque führt die Gnome von Tüftlerstadt in Ironforge aus. Die Zwerge haben seinem Volk eine Zuflucht gegeben, doch ihre eigene Hauptstadt liegt weiter unter Dun Morogh. Ein von Freunden geliehenes Zuhause kann den Verlust von Gnomeregan nicht aufwiegen." },
        { "Die Strahlung, die gegen die eindringenden Troggs freigesetzt wurde, konnte sie nicht vernichten und hat auch die Gnome verwüstet. Mekkatorque vertraute einst Sicco Thermaplugg. Nun bezichtigt er ihn des Verrats an der Stadt und bittet Abenteurer, hineinzugehen und ihn zu töten." },
      },
    },
    ["highborne"] = {
      title = "Die Hochgeborenen",
      text = {
        { "Die Hochgeborenen waren die obere Kaste der Nachtelfen, die auserwählten Diener von Königin Azshara, die den Brunnen der Ewigkeit erforschten, bis sie Magie lernten, und sie dann mehr liebten als alles andere. Es war ihre Zauberkunst, die Sargeras in die Welt lockte, und ihre Königin und ihr Hof, die seiner Legion den Weg öffneten." },
        { "Nicht alle teilten ihr Schicksal. Manche überlebten die Große Teilung unter den anderen Nachtelfen und wurden, verbannt, weil sie an ihrer Magie festhielten, zu den Hochelfen. Andere hielten in Eldre'Thalas aus, wo die Shen'dralar noch immer unter sich bleiben. Viele starben einfach und fanden keine Ruhe." },
        { "Ihre Toten sind leicht zu finden: klagend in den Ruinen der Dunkelküste, als Erscheinungen und Lichlinge durch Azshara treibend, leidend am gefrorenen Kel'Therilsee in Winterspring. Zehntausend Jahre sind eine lange Zeit, um etwas zu bereuen, $gReisender:Reisende;. Mindestens einer von ihnen, am See, scheint es wirklich zu tun." },
      },
    },
    ["highborne-ruins"] = {
      title = "Die Ruinen der Hochgeborenen",
      text = {
        { "Vor zehntausend Jahren wohnten die Hochgeborenen, die Zaubereradligen von Königin Azshara, in Türmen entlang dieser Küste, Ameth'Aran und Bashal'Aran unter ihnen, und übten ihre Magie frei aus. Der Krieg am Brunnen der Ewigkeit vernichtete sie. Tafeln in Ameth'Aran erzählen noch die Geschichte seines Falls, für jeden, der die alten Runen lesen kann und sich nicht von den Geistern verscheuchen lässt." },
        { "Die Toten sind nicht gegangen. Die Geister der Hochgeborenen spuken in beiden Ruinen, und in Ameth'Aran ist der Geist einer Frau namens Anaya Dawnrunner, deren Geliebter Cerellean Whiteclaw sie um zehntausend Jahre überlebt hat und in Auberdine noch immer von ihr träumt. In Bashal'Aran liegt ein anderer Geist, Asterion, hinter einem Siegel gefangen, das einer der Mächtigsten seiner Art gesetzt hat, und die Satyrn und Feen, die sich von der Magie der Ruinen nähren, gehen nicht in die Nähe seines Schreins." },
      },
    },
    ["hillsbrad-foothills"] = {
      title = "Vorgebirge von Hillsbrad",
      text = {
        { "Das Vorgebirge von Hillsbrad ist grünes, sanft gewelltes Land zwischen den Bergen von Alterac und dem Meer: Obstgärten, Höfe und Weiden, die alte Stadt Hillsbrad und der Hafen von Southshore. Es war ein wohlhabender Winkel Lordaerons, und irgendwie lebt es noch, was im Norden keine Kleinigkeit ist." },
        { "Es ist auch ein Schlachtfeld. Die Verlassenen halten Tarrens Mühle in den Hügeln, überfallen die Höfe der Felder von Hillsbrad, töten die Bauern und verbrennen die Ernte. Die Männer von Southshore schlagen zurück. Das Syndikat hält die alte Festung Durnholde, die Magier von Dalaran halten das Internierungslager am Lordameresee, und im Osten halten die Zwerge von Dun Garok Wache über die Pässe. Hillsbrad hat mehr Heere als Ernten." },
      },
    },
    ["hogger"] = {
      title = "Hogger",
      text = {
        { "Der Steckbrief an der Weststromgarnison beschreibt Hogger als riesigen Gnoll, der im Süden lagert, im Südwesten von Elwynn. Er gehört zu den Flusspfoten, und den Wachen von Stormwind ist es nicht gelungen, ihn zu fangen. Für seine Klaue ist eine Belohnung ausgesetzt." },
        { "Der Steckbrief rät, eine Gruppe mitzubringen. Befolgt diesen Rat, $gReisender:Reisende;. Das Eingeständnis einer Wache, dass sie Hilfe braucht, ist nützlicher als die Gewissheit eines Abenteurers, dass er keine braucht." },
      },
    },
    ["house-of-barov"] = {
      title = "Das Haus Barov",
      text = {
        { "Die Barovs waren ein Adelshaus Lordaerons, reich und stolz, die Herren von Caer Darrow. Als die Seuche kam, schlossen sie ihren Handel mit Kel'Thuzad: ihre Burg für den Kult der Verdammten, im Tausch gegen die Sicherheit ihres Vermögens. Kel'Thuzad hielt sein Wort auf seine Weise. Der Lord und seine Familie sind noch immer in der Scholomance, als Diener der Geißel." },
        { "Zwei Söhne sind übrig. Weldon Barov lebt und sitzt unter dem Schutz der Allianz im Chillwind-Lager. Alexi Barov lebt nicht und leistet den Verlassenen am Bollwerk Gesellschaft. Jeder will das Vermögen der Familie. Jeder hätte gern den Kopf seines Bruders auf einem Teller, und jeder bezahlt einen Reisenden dafür, ihn zu holen. Der Untod hat diesen Familienstreit nicht beendet." },
      },
    },
    ["humans"] = {
      title = "Die Menschen",
      text = {
        { "Das erste Königreich der Menschheit war Arathor, errichtet in Strom im Hochland, das noch heute seinen Namen trägt. Sein König Thoradin sammelte die verstreuten Stämme gegen die Trolle der Amani, und in diesem Krieg lehrten die Hochelfen von Quel'Thalas hundert Menschen, Magie zu wirken. Aus Arathor gingen mit der Zeit sieben Königreiche hervor: Stormwind, Lordaeron, Gilneas, Alterac, Stromgarde, Kul Tiras und die Stadt der Magier, Dalaran." },
        { "Die Orcs kamen durch das Dunkle Portal und brannten zuerst Stormwind nieder. Sein Volk floh nach Norden, und die Allianz, die den Zweiten Krieg gewann, wurde in Lordaeron geschmiedet. Dann nahmen die Seuche und die Geißel Lordaeron selbst, Gilneas schloss sich hinter seiner Mauer ein, und Dalaran fiel. Stormwind, in weißem Stein wiederaufgebaut, ist die größte Stadt der Menschen, die übrig ist, und ein Knabenkönig sitzt unter einem Regenten auf ihrem Thron, solange sein Vater vermisst wird." },
        { "Sie sind ein kurzlebiges Volk und ein sturköpfiges, $gReisender:Reisende;. Sie streiten mehr untereinander, als ihnen guttut, und bauen schneller wieder auf als jeder, den ich kenne. Die Liga hat gelernt, ihre Karten ernst zu nehmen und ihre Zahlungsversprechen mit etwas Vorsicht." },
      },
    },
    ["hunters"] = {
      title = "Jäger",
      text = {
        { "Jedes Volk, das nah an der Wildnis lebt, hat seine Jäger. Die Zwerge haben ihre Gebirgsjäger, treffsicher an jedem Hang, und die Nachtelfen ihre Jägerinnen und Schildwachen. Die Orcs und Trolle haben ihre Fährtenleser und Tierbändiger, und die Tauren ihre Krieger, die den Herden noch folgen wie ihre Großeltern." },
        { "Was einen Jäger auszeichnet, ist ein Gefährte. Ein Wolf, eine Katze, ein Bär, ein Raptor, eine Eule: in der Wildnis gezähmt, lernt er, an der Seite des Jägers zu kämpfen. Ihn zu füttern und zu pflegen, gehört ebenso zur Berufung wie das Schießen zu lernen. Das Tier muss davon überzeugt werden, dass sich diese neue Abmachung für es lohnt." },
        { client = "forever", "Auch Menschen lassen sich heute zu Jägern ausbilden, und die Himmelsgeborenen bringen Jäger zur Allianz wie zur Horde." },
        { "Die Liga beschäftigt Jäger als Führer, solange es sie gibt, $gReisender:Reisende;. Sie finden den Weg und das Abendessen, und sie sorgen dafür, dass keins von beiden zuerst die Gräber findet." },
      },
    },
    ["hydraxian-waterlords"] = {
      title = "Die Hydraxianer",
      text = {
        { "Auf einer Insel in der Bucht von Azshara lebt Fürst Hydraxis, ein Herr der Elementare des Wassers, und die Hydraxianer, die er führt, liegen im Krieg mit den anderen Elementen, vor allem mit dem Feuer. Ihr großer Feind ist Ragnaros, der Feuerlord, in seinem Geschmolzenen Kern." },
        { "Sie sind keine Freunde der Sterblichen, doch sie machen jene zu Verbündeten, die gegen ihre Feinde kämpfen: die Elementare von Erde und Luft in den Brunnen der Pestländer und in Silithus und die Herren des Feuers unter dem Blackrock. Denen, denen sie vertrauen, geben sie das Wasser, das die Runen im Geschmolzenen Kern löscht, und einen Weg, den Majordomus des Feuerlords herauszurufen." },
      },
    },
    ["illidan-stormrage"] = {
      title = "Illidan Stormrage",
      text = {
        { "Illidan war Malfurions Zwillingsbruder, und auch er liebte Tyrande. Sie wählte Malfurion. Im Krieg der Urtume kämpfte er mit seinem Bruder gegen die Legion, doch er gab die Magie der Hochgeborenen nie auf, und als der Brunnen der Ewigkeit zerstört wurde, trug er Phiolen mit seinem Wasser auf den Gipfel des Hyjal und goss sie in einen See und schuf so einen neuen Brunnen. Er hielt es für ein Geschenk. Malfurion nannte es ein Verbrechen und schloss ihn mit Cenarius' Hilfe in ein Hügelgefängnis ein, angekettet und bewacht, für zehntausend Jahre." },
        { "Tyrande befreite ihn, als die Legion zurückkam, in der Hoffnung, er werde helfen. In diesen Wäldern tat er etwas anderes. Der Schreckenslord Tichondrius hielt hier den Schädel von Gul'dan, ein Hexenmeisterrelikt voller Teufelsmacht, und Illidan nahm ihn und trank seine Stärke. Er kam daraus in der Gestalt eines Dämons hervor, mit einigen von Gul'dans Erinnerungen, und tötete Tichondrius. Malfurion verbannte ihn dafür." },
        { "Das Buch in unserer Bibliothek lässt ihn danach fliehen, fort von der Welt, zu den zerbrochenen Resten der Heimat der Orcs, mit den Naga und den Blutelfen im Rücken. Auch der Teufelswald hat sich von dieser Nacht nicht erholt." },
      },
    },
    ["internment-camps"] = {
      title = "Die Internierungslager",
      text = {
        { "Nach dem Zweiten Krieg hatte die Allianz ein Problem, das sie nie zuvor gehabt hatte: ein ganzes Volk als Gefangene. Die Orcs wurden in Lager getrieben, und als die Lager überquollen, baute man neue auf den Ebenen südlich dieser Berge. König Terenas besteuerte die anderen Königreiche, um sie zu bezahlen, und die Steuer zerbrach beinahe die Allianz." },
        { "Dann bemerkten die Aufseher etwas Seltsames. Die Orcs hörten auf zu fliehen. Sie hörten sogar auf, einander zu bekämpfen. Sie saßen. Manche nannten es eine Krankheit. Erzmagier Antonidas von Dalaran sah es anders: Die Orcs waren über Generationen mit dämonischer Magie gefüttert worden, und was die Aufseher sahen, war Entzug. Es gebe kein Heilmittel, schloss er, außer einem geistigen, und viele in der Allianz hielten es für unklug, überhaupt nach einem zu suchen." },
        { "Der oberste Aufseher, Aedelas Blackmoore, beherrschte die Lager von Durnholde aus und hielt sich einen eigenen Orcsklaven, aufgezogen als Waffe. Der Sklave war Thrall. Er fand sein Volk hinter diesen Mauern sitzend, und am Ende kam er zurück, um die Lager aufzubrechen. Heute werden hier keine Orcs mehr festgehalten. Die Zauberer der Kirin Tor haben das alte Lager für ihre eigenen Zwecke übernommen." },
        { side = "Horde", aside = true, sign = "P. F.", "Diese Lager standen in meinem Königreich, auf Befehl meines Königs. Sie erzählt es gerecht." },
      },
    },
    ["ironbands-excavation-site"] = {
      title = "Ironbands Ausgrabungsstätte",
      text = {
        { "Eine der Grabungen der Liga, in den Hügeln im Süden von Loch Modan, geleitet von Ausgrabungsleiter Ironband. Was er dort unten zu finden hoffte, behalte ich für mich. Was er fand, waren Troggs." },
        { "Die Splittersteintroggs kamen in großer Zahl durch die Grabungen herauf, und die Stätte ist nun mehr Schlachtfeld als Grabung. Der Ausgrabungsleiter hat nicht aufgegeben, schließlich ist er ein Zwerg und ein Mitglied der Liga, aber über Hilfe wäre er sehr froh." },
        { "Das meint die Liga, wenn sie sagt, Graben sei gefährliche Arbeit. Die Erde ist voller Dinge, die lieber begraben blieben, und mancher, die es lieber nicht wären." },
      },
    },
    ["ironforge"] = {
      title = "Ironforge",
      text = {
        { "Ironforge ist nicht auf den Berg gebaut. Es ist in ihn hineingebaut. Seine Hallen liegen im Berg von Ironforge, und in seiner Mitte brennt die Große Schmiede." },
        { "Die Stadt dreht sich um die Schmiede wie ein Rad. König Magni hält Hof auf dem Hohen Sitz, im Militärviertel werden die Verteidiger des Berges ausgebildet, die Magier bleiben im Mystikerviertel, und seit dem Fall von Gnomeregan haben die verbannten Gnome Tüftlerstadt zu ihrer eigenen gemacht: laut, klug und voller Heimweh. Unter allem verläuft die Tiefenbahn, gnomische Arbeit, die Reisende unter den Bergen hindurch nach Stormwind trägt." },
        { client = "forever", "Unter Alt-Ironforge liegt die Halle der Thanen. Eindringlinge der Dunkeleisenzwerge sind hineingebrochen, und Magni will den Kopf ihres Befehlshabers, Durgen Dirgehammer. Selbst hier können die ältesten Hallen einer Stadt zu ihrer neuesten Sorge werden." },
        { "Und dann ist da die Halle der Forscher, wo die Liga ihre Bibliothek und ihre Funde aufbewahrt: Relikte aus Uldaman, die Knochen von Tieren, die niemand lebend gesehen hat, und Karten von Orten, über die die meisten Zwerge nur je lesen werden. Was mich angeht, Ihr findet mich auf dem Hohen Sitz, wenige Schritte vom Thron des Königs entfernt. Besucht mich. Mir fehlt es immer an Leuten, die tatsächlich irgendwo gewesen sind." },
        { side = "Horde", aside = true, sign = "P. F.", "Sie meint die Einladung freundlich. Ich würde nicht raten, sie in den Farben der Horde anzunehmen." },
      },
    },
    ["jaedenar"] = {
      title = "Jaedenar",
      text = {
        { "Jaedenar war ein Ort der Nachtelfen, mit Ruinen und Grabhügeln im Westen des Teufelswalds. Heute hält ihn der Schattenrat, der alte Kult der Hexenmeister, der die Orcs einst zu einem Werkzeug der Brennenden Legion machte. Hexenmeister der Orcs und der Verlassenen, Dämonen und Satyrn füllen seine Hallen, und darunter, in der Schattenfeste, schließt Schattenlord Fel'dan seine Pakte mit der Legion." },
        { "Der Smaragdkreis will den Rat vernichtet sehen. Selbst im Inneren liegt der Kult mit sich selbst im Krieg: Seine Herren intrigieren gegeneinander, und jeder ihrer Rivalen hat Spione an den Seiten der anderen." },
      },
    },
    ["jaina-proudmoore"] = {
      title = "Lady Jaina Proudmoore",
      text = {
        { "Jaina Proudmoore war eine junge Zauberin aus Dalaran, die Tochter des Admirals von Kul Tiras und in glücklicheren Tagen eine Freundin von Prinz Arthas. Als die Seuche kam, ritt sie an seiner Seite, bis Stratholme, wo sie ihm nicht folgen wollte. Dann schickte ein Prophet sie westwärts über das Meer, und sie führte, was von Lordaerons Volk übrig war, nach Kalimdor." },
        { "Dort tat sie, was niemand in der Allianz für möglich gehalten hatte: Sie kämpfte am Hyjal an der Seite von Thrall und den Nachtelfen gegen die Brennende Legion und schloss danach Frieden mit der Horde. Als ihr Vater, Admiral Daelin Proudmoore, mit seiner Flotte kam, um den alten Krieg zu beenden, stellte sie sich der Horde nicht in den Weg, und er starb dafür. Das trägt sie seither mit sich." },
        { "Den Frieden zu halten, war nicht leicht. Ein paar Jahre nach dem Hyjal hätten Überfälle und versenkte Schiffe Theramore und Durotar beinahe wieder aufeinander gehetzt, bis Jaina, still mit Thrall zusammenarbeitend, die Burning Blade dahinter fand und ihren eigenen Kämmerer in deren Sold. Die Suche führte sie in einen geschützten Winkel von Durotar, wo sie die Letzte traf, die sie lebend zu finden erwartet hätte: Aegwynn, die Wächterin, Medivhs Mutter, die allein lebte. Jaina herrscht noch immer über Theramore und hält den Frieden mit Thrall, und ich glaube, sie ist die tapferste Person in diesem Register." },
      },
    },
    ["jinthaalor"] = {
      title = "Jintha'Alor",
      text = {
        { "Jintha'Alor ist die große Tempelstadt der Trolle der Vilebranch im Süden des Hinterlands, ein Berg aus gestuftem Stein, der sich aus dem Wald erhebt. Auf seiner Spitze pflegen die Üble Priesterin Hexx und ihre Priester die alten Riten der Amani, und einige ältere und schlimmere: Sie haben Gefangene genommen, um sie Hakkar dem Seelenschinder zu opfern, dem Blutgott der Trolle." },
        { "Die Priester der Atal'ai, die einst im Süden Hakkar dienten, reichen sogar bis hierher: Einer von ihnen, ein Priester, den sein eigenes Volk zum Exil verurteilte, lebt unter den Trollen des Hinterlands. Die Vilebranch, so verstehe ich, waren nicht traurig, ihn zu haben." },
      },
    },
    ["karazhan"] = {
      title = "Karazhan",
      text = {
        { "Karazhan war das Zuhause von Medivh, dem letzten Wächter von Tirisfal. Er erbte Aegwynns außergewöhnliche Macht und mit ihr ein Geheimnis, das sie übersehen hatte: Sargeras hatte sich vor der Geburt ihres Sohnes in ihm verborgen. Durch den Wächter, der sich der Legion entgegenstellen sollte, half ihr Herr Gul'dan, das Dunkle Portal zu öffnen." },
        { "Khadgar und Anduin Lothar töteten Medivh in diesem Turm, bevor der Erste Krieg endete. Jahre später kehrte er zurück, um Azeroth vor dem Einfall der Legion zu warnen. Selbst der Tod hatte die Geschichte des Wächters nicht beenden können." },
        { "Das Dorf darunter ist zerstört, und der Keller des Meisters liegt unter seinen verlassenen Gebäuden. Karazhan selbst bleibt verschlossen. Der Turm hat den Mann überdauert, der dort lebte, und die Gewissheit, dass er jemals ganz allein war." },
      },
    },
    ["kargath"] = {
      title = "Kargath",
      text = {
        { "Kargath ist die Festung der Horde im Nordwesten des Ödlands, eine Palisade auf einer Klippe, benannt nach Kargath Bladefist, dem einhändigen Häuptling des Klans der Shattered-Hand im Zweiten Krieg. Es ist das Lager des Expeditionskorps von Kargath, und sein Geschäft ist der Krieg gegen die Dunkeleisenzwerge des Blackrock im Westen." },
        { "Die Orcs haben Grund dazu. Die Dunkeleisenzwerge von General Zornesschmied metzelten eine ganze Abteilung des Expeditionskorps nieder, die hundertneunte, und der Kriegsherr von Kargath hat einen stehenden Befehl ausgegeben: sofort töten. In dieser einen Sache sind sich ein Zwerg aus Ironforge und ein Orc aus Kargath einig." },
      },
    },
    ["katrana-prestor"] = {
      title = "Lady Katrana Prestor",
      text = {
        { "Lady Katrana Prestor ist die engste Beraterin des Hochlords und bei Hof sehr bewundert: gelehrt, anmutig und sehr schön. Sie weiß sehr viel über sehr viele Dinge, Drachen eingeschlossen, und Bolvar Fordragon vertraut ihr vollkommen." },
        { "Nicht alle tun das. Als Magistrat Solomon von Seenhain den Thron um Soldaten gegen die Orcs der Blackrock anflehte, war es Lady Prestors Rat, der sie zu Hause hielt, und es gibt mindestens einen Marshal von Stormwind, der ihr das nie verziehen hat. Ich schreibe nur nieder, was bekannt ist. Eine Gelehrte, die mehr als das über eine Dame des Hofes schreibt, sollte sich ihrer Sache sehr sicher sein." },
      },
    },
    ["keeper-remulos"] = {
      title = "Bewahrer Remulos",
      text = {
        { "Bewahrer Remulos ist der Sohn des Cenarius, mit dem hirschgleichen Unterleib seines Vaters. Druiden kommen zu seinem Schrein in Moonglade, um Hilfe zu suchen. Der Nachtmahr, der sich im Smaragdgrünen Traum ausbreitet, hat ihnen dringenden Grund dazu gegeben." },
        { "Als Eranikus, Yseras Gefährte, hierher gerufen wurde, kam der Nachtmahr mit ihm. Remulos verteidigte Nighthaven, während seine Verbündeten darum kämpften, den Drachen zu befreien. Tyrande kam, um Eranikus zu erlösen. Ein Reisender kennt Moonglade vielleicht als einen Ort des Friedens. Sein Bewahrer musste mitten im Dorf für diesen Frieden kämpfen." },
      },
    },
    ["kelthuzad"] = {
      title = "Kel'Thuzad",
      text = {
        { "Kel'Thuzad war ein Erzmagier Dalarans und Mitglied seines herrschenden Rates, der nach verbotener Macht suchte. Antonidas fand sie zuerst, in seinen Lagerhäusern im Norden: tote Ratten, die er in Bewegung zu halten versucht hatte. Die Kirin Tor stellten ihn vor Gericht und beschlagnahmten seine Arbeit, und Kel'Thuzad, mit einer freundlichen Stimme im Kopf, die ihm die ganze Zeit geholfen hatte, verließ sie und ging nach Norden, um ihren Besitzer zu finden." },
        { "In Nordend führte ihn ein Gruftlord, Anub'arak, durch eine Zikkurat namens Naxxramas: Laboratorien, Waffenkammern und Kessel, in denen eine Flüssigkeit braute, die die Sterbenden zu Toten machte. Bei dem Anblick wurde ihm übel, und er wollte fliehen, und die Gespenster des Lichkönigs ließen ihn nicht. Am Fuß des Frostthrons kroch er, bettelte und schwor sich dessen Herrn zu. Der Lichkönig antwortete mit einer Vision von Naxxramas, das sich in die Luft erhob, eine Festung, von der aus Kel'Thuzad die Macht seines Herrn verbreiten würde." },
        { "Er kehrte zurück, um unter den Armen Lordaerons den Kult der Verdammten zu gründen, und mit ihnen verbreitete er die Seuche durch das Getreide von Andorhal. Prinz Arthas tötete ihn dort. Sein Leichnam wurde nach Quel'Thalas gebracht, zum Sonnenbrunnen, und durch dessen Macht als Lich erweckt." },
        { "Er führte die Geißel nach Dalaran, um Archimonde selbst herbeizurufen, und er stand zu Arthas, als die Schreckenslords sich gegen ihn wandten. Als Arthas nach Norden zum Frostthron ging, blieb Kel'Thuzad, um in seinem Namen über die Pestländer zu herrschen, und er herrscht noch immer über sie, von Naxxramas aus. Selbst vernichtet ist ein Lich nicht am Ende, solange seine Phylakterie besteht." },
      },
    },
    ["khans-of-desolace"] = {
      title = "Die Khane von Desolace",
      text = {
        { "Desolace ist Land der Zentauren, und ihre Klans sind zahlreich: die Kolkar im Norden, die Gelkis im Südwesten, die Magram im Südosten, die Maraudine als Wächter des heiligen Grabes. Die Gelkis und die Magram sind erbitterte Rivalen, und jeder bietet Arbeit gegen den anderen an." },
        { "Die Allianz und die Horde haben beide erkannt, dass ein geeintes Volk der Zentauren sie aus Desolace hinausfegen würde und dass der Hass der Klans aufeinander die beste Waffe ist, die sie haben. Also spielen beide dasselbe Spiel: sich mit den Gelkis oder den Magram verbünden, die Krieger des anderen Klans töten, bis man sich die Freundschaft verdient hat, und von den neuen Freunden lernen, wie man den Rest bricht. Es funktioniert. Ich finde es ein wenig traurig, dass es das tut." },
      },
    },
    ["kharanos"] = {
      title = "Kharanos",
      text = {
        { "Kharanos liegt im kalten Herzen von Dun Morogh, an der Straße zwischen den Übungsplätzen im Coldridgetal und den Toren von Ironforge. Nach zwergischem Maßstab ist es ein kleiner Ort: eine Schmiede, ein paar stämmige Häuser und das Gebäude, das ihn berühmt macht, die Brauerei Donnerbräu, wo die Familie Donnerbräu ihre Biere schon länger vervollkommnet, als irgendwer zugeben mag." },
        { "Haltet den warmen Herd nicht für Sicherheit. Trolle der Frostmane halten die Hügel im Westen, Troggs kriechen immer wieder aus den tiefen Orten herauf, und seit dem Fall von Gnomeregan teilen seine Verbannten diese Straßen mit uns. Der Ort hält seine Türen trotzdem offen: Ein Zwerg, der einen frierenden Reisenden abweist, ist überhaupt kein Zwerg." },
      },
    },
    ["kirith-the-damned"] = {
      title = "Kirith der Verdammte",
      text = {
        { "Leutnant Kirith diente dem Helden der Horde, dessen Geist nun vor Stonard wartet. Die beiden wurden in den Verwüsteten Landen von Erzmagier Allistarj gefangen genommen und dort in einer Höhle eingesperrt. Der Held hielt durch. Kiriths Wille brach. Sein Befehlshaber hörte die Experimente aus seinem eigenen Käfig, die Schreie, die durch die Hallen hallten, und danach sah und hörte er nichts mehr von ihm." },
        { "Was die Experimente aus ihm machten, wandelt nun als Kirith der Verdammte durch die Schlangenschlinge. Macht dem ein Ende, und was vom Leutnant übrig ist, spricht zu Euch und grinst sogar: Er weiß, wie Razelikh der Entweiher sich schützt, mit drei Dienern, die je ein Drittel eines Amuletts tragen, und er schickt Euch mit der Nachricht zurück zu seinem Befehlshaber." },
        { "Loramus Thalipedes, der in Azshara Dämonen jagt, nennt es unvorstellbar, dass jemand Kirith von seinem Leiden erlöst hat. Es ist eines der wenigen freundlichen Dinge, die in den Verwüsteten Landen seit langem geschehen sind." },
      },
    },
    ["kobolds"] = {
      title = "Die Kobolde",
      text = {
        { "Jeder Bergmann der Allianz hat eine Koboldgeschichte, und die meisten enden mit einer verlorenen Spitzhacke. Kobolde sind kleine Tunnelgeschöpfe mit Rattengesichtern, feige allein und gefährlich in Massen, und sie treten immer in Massen auf. Sie tragen Kerzen auf dem Kopf, um das Dunkel zu erhellen, und sie kämpfen für eine Kerze bis zum Tod, lange nachdem sie vor einem Schwert davongelaufen wären." },
        { "Sie sind überall, wo es etwas zu graben gibt. Ein Klan aus dem Rotkammgebirge hat die Minen im Wald von Elwynn und in Westfall gefüllt, die Tunnelratten haben sich über Thelsamar eingegraben, die Trockenstoppel dienen den Riesen des Arathihochlands, und die Bruchschnauzen wühlen in Tausend Nadeln nach Erz." },
        { "Es ist leicht, über sie zu lachen. Die Bauern von Elwynn, die ihr Vieh und ihre Ernten an sie verlieren, lachen nicht." },
      },
    },
    ["kodo-graveyard"] = {
      title = "Der Kodofriedhof",
      text = {
        { "Mitten in Desolace liegt der Ort, an dem die Kodos sterben: ein riesiges Feld aus Knochen und Stoßzähnen, gewaltige Brustkörbe, die sich aus dem Staub wölben, und zwischen ihnen alte Kodos, die langsam von den Ebenen hereintrotten, um sich hinzulegen. Niemand weiß, warum sie hierher kommen, und die Tauren begegnen dem Ort mit Achtung." },
        { "Nicht alle tun das. Geister von Zentauren und Kodos wandern nachts darüber, und ein Goblin hat ein Gerät erfunden, das die sterbenden Tiere mit einem Ruck wieder in den Dienst holt, und verkauft sie an die Karawanen. Ich kann mich nicht entscheiden, ob das klug oder ungeheuerlich ist. Ich vermute, die Kodos haben eine Meinung dazu." },
      },
    },
    ["kurzen-rebellion"] = {
      title = "Kurzens Rebellion",
      text = {
        { "Colonel Kurzen kam mit dem Ruf eines Soldaten ins Schlingendorntal: ein brillanter Taktiker, einst als großer und edler Mann angesehen. Im Dschungel veränderte er sich. Seine Gefolgsleute wurden zu einer Truppe, die allein ihm treu war, und plünderten und jagten mit einer Grausamkeit, die ihre einstigen Kameraden nicht hinnehmen wollten." },
        { "Lieutenant Doren führte die Abtrünnigen in ein Rebellenlager in den Hügeln. Zehnfach unterlegen bekämpfen sie Kurzen mit der Taktik, die er sie selbst gelehrt hat. Bruder Nimetz vermutet zuerst Trollmagie, doch seine Ermittlung führt zu Mai'Zoth, einem Ogermagier, und zu dem Gedankenauge, mit dem man den Geist beherrscht." },
        { "Nimetz bittet um den Tod des Magiers und um die Bergung des Artefakts. Verwendet besondere Sorgfalt auf diese zweite Aufgabe, $gReisender:Reisende;. Er fürchtet, dass es, zurückgelassen, einen weiteren Soldaten Kurzens Schicksal ausliefern würde." },
      },
    },
    ["lakeshire"] = {
      title = "Seenhain",
      text = {
        { "Seenhain ist eine Stadt aus Holzhäusern am Ufer des Immerruhsees, mit einem Gasthaus, einem Rathaus und einer Brücke über das Wasser, die die Bewohner noch immer wiederaufbauen: Bei der letzten Invasion schmolzen sie ihr Eisen ein, um Schwerter daraus zu machen, und die Gnolle stahlen die Lieferung, die es ersetzen sollte." },
        { "Ihr Magistrat Solomon ist ein vorsichtiger Mann mit sehr vielen Sorgen. Die Blackrock halten die Burg im Norden und sperren seine Leute in ihrer Stadt ein. Er hat Stormwind um Hilfe gebeten, und die Antwort kam zurück, es gebe nicht genug Soldaten, um sie auf bloße Vermutungen hin zu entbehren. Seither hat er erfahren, was die Orcs der Blackrock wirklich antreibt und wer in Stormwind ihn nicht gehört haben wollte. Seenhain, so vermute ich, wird es nicht vergessen." },
      },
    },
    ["leper-gnomes"] = {
      title = "Die Lepragnome",
      text = {
        { "Nicht jeder Gnom ist Gnomeregan entkommen. Manche überlebten die Strahlung und wurden von ihr verändert, ihre Körper zerstört und ihr Geist seltsam und gewalttätig geworden. Die Zwerge nennen sie Lepragnome, und die Verbannten sprechen überhaupt nicht gern über sie." },
        { "Sie spuken an den Zugängen zur alten Stadt und an den Depots in ihrer Umgebung, plündern, was sie können, und greifen alle an, die zu nahe kommen." },
        { "Wenn Ihr gegen sie kämpfen müsst, $gReisender:Reisende;, denkt daran, dass sie einmal jemandes Nachbarn waren." },
      },
    },
    ["lights-hope-chapel"] = {
      title = "Kapelle des hoffnungsvollen Lichts",
      text = {
        { "Das hoffnungsvolle Licht ist eine kleine Steinkapelle auf geweihtem Boden im Osten der Pestländer. Lord Maxwell Tyrosus führt dort die Argentumdämmerung. Jeder, der gegen die Geißel kämpft, kann dort willkommen sein, ob er von der Allianz oder von der Horde kommt." },
        { "Als Naxxramas über dem Land erschien, traf sich selbst der Scharlachrote Kreuzzug hier mit der Argentumdämmerung, um sich auf einen gemeinsamen Kampf zu einigen. Kel'Thuzads erbeutete Phylakterie wurde später in die Kapelle gebracht. Ein Reisender, der an ihren Mauern vorbeikommt, sieht ein bescheidenes Gebäude für einen Ort, an dem so viele Feinde Grund hatten, sich zu treffen." },
      },
    },
    ["linken"] = {
      title = "Linken",
      text = {
        { "Linken tauchte eines Tages in Marshals Zuflucht auf und hatte keine Ahnung, wie er dorthin gekommen war. Niemand sonst weiß es auch, sagt er fröhlich. Es ist ein Geheimnis für alle. Er ist ein Gnom, auch wenn die Gnome des Lagers bemerken, dass er nichts von ihrem Interesse an Apparaten zeigt, und er hatte einen Rucksack, ein Schwert und eine Beule am Kopf." },
        { "Die Erinnerungen kehren Stück für Stück zurück, während Reisende ihm helfen: ein Schwert, das in den heißen Quellen von Winterspring gehärtet werden muss, ein Totem, das mit Hilfe eines Freundes im Teufelswald entsteht. Am Ende erinnert er sich. Er kam in den Krater, um gegen Sturmflamme zu kämpfen, den Feuerelementar, der ein Artefakt namens Goldene Flamme bewacht, und dies sollte der letzte Schritt einer langen Reise sein." },
        { "Er geht ihn nicht selbst. Ihr seid jetzt der Held, sagt er zu dem, der ihm geholfen hat, und schickt ihn mit der Warnung weiter, dass es gefährlich sei, allein zu gehen. Die Flamme, verspricht er, werde in seine Heimat zurückgebracht und vor bösen Händen bewahrt. Diese Heimat habe ich auf keiner Karte gefunden. Ich habe gesucht." },
      },
    },
    ["loch-modan"] = {
      title = "Loch Modan",
      text = {
        { "Östlich der Tore liegt das sanfteste Land von Khaz Modan: grüne Hügel, Kiefernwälder und ein langer blauer See, alles gehalten von dem großen Damm an seinem Nordende." },
        { "Es ist Acker- und Jagdland, und die Zwerge, die hier leben, sind ein wenig langsamer im Zorn und sehr viel schneller dabei, Euch etwas zu trinken anzubieten, als ihre Vettern in Ironforge. Die gute Laune brauchen sie. Troggs graben in den südlichen Tälern, Oger halten den Nordosten, und in den Hügeln hat man Dunkeleisenzwerge gesehen." },
        { "Rastet in Thelsamar, seht Euch den Damm an und besucht das Tal der Könige. Dann gebt acht, wohin Ihr tretet." },
      },
    },
    ["loramus-thalipedes"] = {
      title = "Loramus Thalipedes",
      text = {
        { "Auf einer Insel vor der Küste von Azshara lebt ein Dämonenjäger namens Loramus Thalipedes allein mit seinen Teufelshunden. Wenn Ihr gegen Dämonen kämpfen wollt, sagt er, tätet Ihr gut daran, zuerst seine Geschichte anzuhören." },
        { "Reisende kommen zu ihm aus den Verwüsteten Landen, wo Razelikh der Entweiher drei Diener hält, die nicht sterben können, solange die an sie gebundenen Amulettstücke in diesem Land bleiben. Loramus weiß, wie man solche Schutzzauber bricht. Es braucht den wahren Namen des Dämonenfürsten, den ein niederer Gott an der Küste Azsharas für einen Preis eintauscht, und eine Waffe, geschmiedet, um ihn zu tragen, aus dem Kristall, den die Klippenriesen des Südens zurücklassen, und bearbeitet von einem Schmied, der mit Teufelsfeuer umgehen kann." },
        { "Er lacht über die meisten, die es versuchen. Er weist sie nicht ab, und er hält sie nicht auf. Wofür er auch immer Dämonen jagte, er scheint vor langer Zeit beschlossen zu haben, dass die Welt mehr Leute braucht, die es tun." },
      },
    },
    ["lord-kazzak"] = {
      title = "Lord Kazzak",
      text = {
        { "Lord Kazzak hält die Faulende Narbe im Süden der Verwüsteten Lande. Seit dem Dritten Krieg hat diese große Verdammniswache sie mit Teufelswachen und anderen ihrer Art besetzt. Er geht offen unter ihnen umher, ein gehörnter Diener der Brennenden Legion, der sich kaum verbergen muss." },
        { "Helden beider Fraktionen sind gegen ihn gezogen. Jeder, den er tötet, macht ihn stärker. Bedenkt das, $gReisender:Reisende;, wenn Ihr Euch ihnen anschließt: Ein gescheiterter Angriff kann die nächste Gruppe einem stärkeren Feind gegenüberstellen." },
      },
    },
    ["mages"] = {
      title = "Magier",
      text = {
        { "Die menschliche Kunst der Magie begann mit hundert Schülern. Während der Trollkriege lehrten die Hochelfen von Quel'Thalas sie, Zauber zu wirken, im Tausch für Hilfe gegen die Amani, und ihre Erben gründeten Dalaran und seinen herrschenden Rat, die Kirin Tor. Die Stadt wurde zum großen Mittelpunkt menschlicher arkaner Gelehrsamkeit." },
        { "Dalaran fiel im Dritten Krieg, und seine Schüler zerstreuten sich: mit Jaina Proudmoore nach Theramore, nach Stormwind, nach Undercity unter die Verlassenen, von denen manche in ihrem ersten Leben dort studiert hatten. Gnome und Dunkelspeertrolle haben eigene Magier. Eine Ausbildung bei den Kirin Tor ist ein Weg in die Kunst, auch wenn ihre Absolventen manchmal reden, als wäre es der einzige." },
        { client = "forever", "Man hat auch Orcs beim Handwerk der Magier gesehen, und der Hohe Orden der Himmelsgeborenen ist herabgekommen, um das arkane Wissen zu suchen, das ihr Volk verlor." },
        { "Ein Magier beschwört Feuer, Frost und reine arkane Kraft, und eine Menge frisches Wasser. Ich empfehle einen bei jeder Grabung, $gReisender:Reisende;, allein wegen des Wassers." },
      },
    },
    ["magni-bronzebeard"] = {
      title = "König Magni Bronzebeard",
      text = {
        { "König Magni Bronzebeard hält Hof auf dem Hohen Sitz von Ironforge und herrscht über die Stadt, die sein Klan seit dem Krieg der drei Hämmer hält. Er ist der älteste von drei Brüdern. Muradin ging im Dritten Krieg mit dem Prinzen von Lordaeron nach Norden, und seither hat man nichts mehr von ihm gehört. Brann ist der berühmteste Forscher der Liga, und einer der am schwersten aufzuspürenden." },
        { "Magni verfolgt die Arbeit der Liga genau. Die Funde in Uldaman legen nahe, dass die Zwerge vor langer Zeit von den Titanen geformt wurden. Ein König mit einer so langen Ahnenreihe hat Grund zu fragen, wo sie begann, und eine Historikerin, die wenige Schritte von seinem Thron entfernt steht, hat allen Grund, sein Interesse zu begrüßen." },
        { "Seine Tochter beschäftigt ihn dringender. Prinzessin Moira ist in der Stadt der Dunkeleisenzwerge unter dem Blackrock, vermählt mit Imperator Dagran Thaurissan. Ironforge nennt es eine Entführung, und Magni verspricht demjenigen, der sie heimbringt, den Lohn eines Helden. Wenn Ihr diesen Auftrag annehmt, $gReisender:Reisende;, tragt Ihr die Hoffnungen eines Vaters ebenso wie die Befehle eines Königs." },
      },
    },
    ["malfurion-stormrage"] = {
      title = "Malfurion Stormrage",
      text = {
        { "Malfurion Stormrage war ein junger Gelehrter der Nachtelfen, als die Hochgeborenen sich zu verändern begannen, und er gehörte zu den Ersten, die ahnten, warum. Als die Brennende Legion durch den Brunnen der Ewigkeit kam, ging er mit seinem Bruder Illidan und der Priesterin Tyrande, um Cenarius zu finden, der sein Lehrer wurde. Was Cenarius ihn lehrte, wurde zum Druidentum. Am Ende des Krieges der Urtume war es Malfurion, der erkannte, dass der Brunnen selbst zerstört werden musste, und die Große Teilung folgte." },
        { "Er führte die Überlebenden zum Hyjal, fand, dass Illidan dort einen neuen Brunnen geschaffen hatte, und schloss seinen eigenen Bruder in einen Hügel unter der Erde ein. Er verbot seinem Volk die Magie, schloss mit den Drachen den Pakt des Weltenbaums und ging jahrhundertelang am Stück in den Smaragdgrünen Traum schlafen, während Tyrande Wache hielt." },
        { "Tyrande weckte ihn, als die Legion zurückkehrte, und er vernichtete Archimonde am Fuß des Baumes. Nun ist er wieder im Traum verloren, und die Druiden, die in diesen Grabhügeln schlafen, sagen nicht, wann er zurückkommen wird. Sein Volk lernt, ohne ihn alt zu werden." },
      },
    },
    ["mannoroc-coven"] = {
      title = "Mannorocs Koven",
      text = {
        { "Im Süden von Desolace gibt es ein versengtes Tal, in dem Dämonen offen umhergehen: Verdammniswachen, Teufelshunde, Höllenbestien und Schlimmeres, zwischen zerbrochenen Altären und grünem Feuer. Man nennt es Mannorocs Koven, und die Dämonen sind nicht zufällig dorthin gekommen." },
        { "Man hat sie hereingelassen. Die Burning Blade hält von ihrer Festung im Norden aus ein Relikt, das man die Hand von Iruxos nennt, und damit hat sie im Tal Portale ins Reich der Dämonen geöffnet. Die Tauren von Shadowprey versuchen, sie zu schließen. Jedes geschlossene Portal ist eine Tür, die die Legion wieder öffnen muss, und die Legion ist geduldig." },
      },
    },
    ["maraudon"] = {
      title = "Maraudon",
      text = {
        { "Maraudon ist die heilige Stätte der Zentauren im Südwesten von Desolace. Ihr Vater Zaetar liegt in seinen riesigen Höhlen begraben, und ihre Mutter Theradras weilt jenseits von Kammern aus glitzerndem Kristall. Nur die Frömmsten unter den Zentauren dürfen hinein." },
        { "Das Grab ist in Unruhe. Lord Schlangenzunge verbreitet Gift durch die Höhlen und hat ein Geschöpf aus Fäulnis geschaffen. Zaetars Neffe Celebras irrt dort unter einem Fluch umher. Eine Frau vom Twilight-Hammer bittet um Schnitzereien aus den Kristallhöhlen und behauptet, sie bärgen Relikte der Alten Götter. Ich würde genau darauf achten, wessen Zwecken Eure Reise dient, $gReisender:Reisende;. Mehrere Seiten interessieren sich für das, was unter diesem heiligen Boden liegt." },
      },
    },
    ["marshal-windsor"] = {
      title = "Marshal Windsor",
      text = {
        { "Marshal Reginald Windsor befehligte Soldaten der Allianz in Morgans Wacht und sammelte Beweise, die die Orcs der Blackrock mit dem schwarzen Drachenschwarm in Verbindung brachten. Er begann zu vermuten, dass jemand in Stormwind diese Beweise verloren sehen wollte. Die Dunkeleisenzwerge nahmen ihn gefangen, nahmen seine Aufzeichnungen und machten sich daran, ihren Code zu entschlüsseln." },
        { "Windsor überlebte im Gefängnis der Schattenschmiede. Er beharrte darauf, Bolvar Fordragon sei blind für die Wahrheit, obwohl der Beweis zwei Fuß von ihm entfernt stehe. Wer den Marshal rettete, erfuhr bald, was er meinte." },
      },
    },
    ["marshals-refuge"] = {
      title = "Marshals Zuflucht",
      text = {
        { "Marshals Zuflucht ist ein Lager auf einem Felsvorsprung am nördlichen Rand des Kraters, wo die Überlebenden der Expedition von Marshal Schutz suchten. Die Expedition kam unter Williden und Hol'anyee Marshal, um den Krater zu erforschen, und sie unterschätzte die Tiere: Ihre Lager wurden überrannt, und sie flohen auf die Anhöhe." },
        { "Sie sind noch immer dort, mit einer seltsamen Schar von Gelehrten, Jägern und verirrten Forschern, die sich ihnen angeschlossen haben, und alle studieren den Krater von dem einen Ort aus, an dem nichts sie fressen wird. Einer von ihnen, ein Forscher namens Ringo, wanderte zum Vulkan davon. Wie ich höre, wurde er gefunden." },
      },
    },
    ["masters-glaive"] = {
      title = "Die Meistergleve",
      text = {
        { "Im Süden der Dunkelküste steckt eine gewaltige Klinge in der Erde, zu groß für jede Hand, die heute auf der Welt wandelt, und die Nachtelfen nennen den Ort die Meistergleve. Onu, das Urtum der Lehren, sagt, sie markiere einen Ort, an dem einer der alten Herren der Erde fiel, vor langer, langer Zeit." },
        { "Darum ist der Twilight-Hammer gekommen. Der Kult verehrt diese alten Herren, und seine Leute haben sich an der Gleve und in den Höhlen ringsum versammelt, mit Büchern voller Namen, die nicht ausgesprochen werden sollten." },
      },
    },
    ["mazthoril"] = {
      title = "Mazthoril",
      text = {
        { "Mazthoril ist eine große Eishöhle mitten in Winterspring, tief und kalt und voller blauer Drachen. Sie ist die Heimat des blauen Drachenschwarms in Kalimdor, und kobaltblaue Runen auf ihrem Boden tragen jene, die ihren Gebrauch kennen, zu Haleh, ihrer Schutzpatronin." },
        { "Die blauen Drachen sind die Hüter der Magie, und sie beobachten den schwarzen Drachenschwarm sehr genau. Sie wissen, was Nefarian in der Blackrockspitze züchtet, und dass man es nicht zulassen darf. Und da sie ihn in seinem Berg nicht leicht erreichen können, sind sie bereit, Sterblichen zu helfen, die es können." },
      },
    },
    ["mekgineer-thermaplugg"] = {
      title = "Robogenieur Thermaplugg",
      text = {
        { "Sicco Thermaplugg ist in Gnomeregan geblieben, während Hochtüftler Mekkatorque die Verbannten von Ironforge aus führt. Der Hochtüftler vertraute ihm einst. Dieses Vertrauen endete in einer Anklage wegen Verrats und der Bitte um seinen Tod." },
        { "Die Strahlung, die in der Stadt freigesetzt wurde, konnte die Troggs nicht vernichten und verwüstete ihre gnomischen Bewohner. Thermaplugg herrscht in den Ruinen, zwischen den Geschöpfen, die der Versuch vernichten sollte, und den Überlebenden, die er zurückließ." },
        { "Mekkatorque bittet Abenteurer, sein Urteil in diese Hallen zu tragen." },
      },
    },
    ["menethil-harbor"] = {
      title = "Der Hafen von Menethil",
      text = {
        { "Der Hafen von Menethil liegt an der Westküste des Sumpflands, ein Hafen der Allianz mit Schiffen nach Auberdine und Theramore. Die Straße durch Dun Algaz verbindet ihn mit dem Land im Inneren. Ein feuchtes kleines Städtchen kann ein wichtiger Ort sein, wenn so viele Reisen durch es führen." },
        { "Captain Stoutfist braucht Hilfe gegen die Orcs der Dragonmaw, die den Hafen bedrohen. Er bittet darum, ihre Katapulte zu zerstören und Häuptling Nek'rosh zu besiegen. Kümmert Euch um ihn, wenn Ihr könnt, $gReisender:Reisende;. Hier versuchen Leute, einen Hafen offen zu halten, während ein Feind sich bereit macht, ihn zu belagern." },
      },
    },
    ["mogrosh-ogres"] = {
      title = "Die Oger der Mo'grosh",
      text = {
        { "Im Nordosten von Loch Modan haben sich die Oger der Mo'grosh eine eigene Festung gebaut und fordern jeden heraus, sie ihnen zu nehmen." },
        { "Oger sind riesig, brutal und viel klüger, als Zwerge gern zugeben. Besonders ihre Schamanen und Mystiker sollte man nicht unterschätzen. Die Mo'grosh überfallen die Höfe und Straßen am See, wann es ihnen gefällt, und bisher hatte niemand die Stärke, sie endgültig aufzuhalten." },
        { "Geht nicht allein in ihre Festung, $gReisender:Reisende;. Geht überhaupt nicht hinein, wenn Ihr es vermeiden könnt." },
      },
    },
    ["moira-bronzebeard"] = {
      title = "Prinzessin Moira Bronzebeard",
      text = {
        { "Moira Bronzebeard ist Magnis einzige Tochter und die Erbin von Ironforge. Die Dunkeleisenzwerge verschleppten sie, und sie wurde Imperator Dagran Thaurissans Frau. Ihr Vater glaubte, der Imperator habe sie verzaubert, und schickte Streiter, um sie zu befreien." },
        { "Sie töteten Thaurissan. Moira nannte ihn einen großen und ehrenhaften Zwerg und sagte ihnen, sie trage sein Kind. Sie erklärte, dieses Kind werde Ironforge erben, ob Magni es billige oder nicht. Ihr mögt Magnis Befehle getragen haben, $gReisender:Reisende;, doch Moira hat eine eigene Antwort." },
        { "Ich hüte die Geschichte von Magnis Haus schon lange. Dies ist das erste Kapitel davon, das ich lieber nicht schreiben würde." },
      },
    },
    ["molten-core"] = {
      title = "Geschmolzener Kern",
      text = {
        { "Unter den Blackrocktiefen, unter allem, liegt der Geschmolzene Kern, eine Welt aus Lava in den Wurzeln des Berges, das eigene Reich des Feuerlords. Ragnaros lebt dort, seit Thaurissan ihn herbeirief, und seine Diener bewachen es: Riesen aus Feuer und Stein, die gefallenen Herren der Flamme und sein Majordomus Executus, der als Einziger ihn wecken darf." },
        { "Ein seltsames Wesen am Tor des Berges, Lothos Riftwaker, sieht überall um sich Risse in der Welt und zeigt jedem, der kühn genug ist, den Weg hinein. Die Hydraxianer, Ragnaros' uralte Feinde, helfen jedem, der hineingeht." },
      },
    },
    ["moonbrook"] = {
      title = "Moonbrook",
      text = {
        { "Moonbrook war die Marktstadt der Höfe von Westfall und die Heimat seiner Bergleute, im Ersten Krieg von den Orcs niedergebrannt und nach dem Zweiten wiederaufgebaut. Heute ist es eine Stadt der Defias: ihre Leute vertrieben, ihre Häuser voller rot maskierter Banditen, und ihre alte Schmiede und ihre Scheune verbergen den Weg hinab in die Todesminen." },
        { "Es ist ein trauriger Ort, um hindurchzugehen, und kein sicherer. Die Bruderschaft beobachtet die Straße, und wer eine gewisse Scheune am Rand der Stadt zu lange ansieht, wird wahrscheinlich herausfinden, warum." },
      },
    },
    ["moonglade"] = {
      title = "Moonglade",
      text = {
        { "Moonglade ist ein verborgenes Tal in den Bergen im Norden Kalimdors, zwischen dem Teufelswald und Winterspring, um den Elune'ara See. Es ist der heiligste Ort der Druiden, Nachtelfen und Tauren gleichermaßen, und der Zirkel des Cenarius hat sein Zuhause im Dorf Nighthaven am Ufer des Sees. Es ist ein Ort des Friedens, offen für Allianz und Horde gleichermaßen." },
        { "Druiden kommen hierher, um zu lernen, und die Gelehrten des Zirkels bewahren hier ihre Archive. Zum Mondfest kommt die ganze Welt, um die Ältesten und den Mond zu ehren." },
      },
    },
    ["morbent-fel"] = {
      title = "Morbent Fel",
      text = {
        { "Morbent Fel ist der Nekromant des Dämmerwalds, derjenige, der die Toten von Rabenflucht wandeln lässt, und ein Verbündeter der dunklen Reiter, die aus dem Gebirgspass der Totenwinde kommen. Er lebt in einem Haus oben auf dem verlassenen Gut, über dem Friedhof, hinter seinen Toten und einem Bann, der jeden Schlag gegen ihn ablenkt." },
        { "Sven Yorgen, ein Holzfäller, dessen Frau und Kinder die Reiter töteten, will ihn tot sehen, und der Weg dorthin ist lang. Das Tagebuch eines Defias verriet Sven, was auf seinem Hof geschehen war. Bischof Farthing in der Kathedrale von Stormwind wies den Weg zu einer Waffe, die den Bann brechen konnte. Das Eisen dafür kam aus den Wracks der dritten Flotte vor dem Sumpfland, wo eine Ladung Lichtschmiedeeisen unterging, und ein zwergischer Schmied in Stormwind schmiedete daraus Morbents Bann." },
        { "Das ist sehr viel Aufwand für einen einzigen Nekromanten, $gReisender:Reisende;. Sven findet das nicht, und ich stelle fest, dass ich es ihm nicht verdenken kann." },
      },
    },
    ["morgans-vigil"] = {
      title = "Morgans Wacht",
      text = {
        { "Morgans Wacht liegt in einem niedergebrannten Dorf im Südosten der Brennenden Steppe. Ein zerstörter Magierturm und Zelte bieten Soldaten der Allianz unter Marshal Maxwell Schutz. Sie stehen zwischen den Truppen der Blackrock und Seenhain jenseits der Berge." },
        { "Ihre Berichte nennen den schwarzen Drachenschwarm als die Macht, die die Orcs antreibt. Stormwind verlangte Beweise. Lady Prestor sah keinen Grund zur Beunruhigung. Ein Reisender kann hier erfahren, was die Soldaten entdeckt haben, und auch, wie wenig Hilfe ihnen diese Entdeckung bisher gebracht hat." },
      },
    },
    ["morganth"] = {
      title = "Morganth",
      text = {
        { "In den östlichen Vorbergen des Rotkammgebirges steht ein einsamer Turm, Ilgalar, und in ihm lebt ein Hexenmeister namens Morganth, der die Gnolle der Schattenfelle mit verzauberten Anhängern in seinen Dienst gezwungen hat. Das Gesetz von Seenhain zählt ihn zu den Feinden des Königreichs und jeden, der ihm hilft, zu den Verbrechern." },
        { "Ein Magier aus Elwynn, Theocritus vom Turm von Azora, hat Morganths Gnolle durch eben diese Anhänger belauscht, und was er gehört hat, macht ihm Angst: Morganth sucht nach einem alten elfischen Relikt namens Sense von Elune und hat es vielleicht gefunden. Wenn ja, sagt Theocritus, wird ganz Stormwind es zu spüren bekommen. Von demselben Relikt spricht man im Dämmerwald, im Zusammenhang mit den Worgen. Ich vermerke es, und es gefällt mir nicht." },
      },
    },
    ["morladim"] = {
      title = "Mor'Ladim",
      text = {
        { "Morgan Ladimore war ein Ritter dieses Landes, bekannt dafür, die Armen und Bedrängten zu verteidigen, jung verheiratet mit einem Mädchen namens Lys und Vater von drei Kindern. Als in Lordaeron der Krieg ausbrach, zog er nach Norden, um an der Seite von Uther Lightbringer zu kämpfen, und er sah alles, wozu dieser Krieg wurde: die aufgelöste Silberne Hand, Uthers Tod, die Seuche. Was ihn bei Verstand hielt, war der Gedanke an die Heimkehr." },
        { "Er kehrte heim in einen dunkel gewordenen Wald und ein zerstörtes Haus, und schließlich, auf dem Friedhof von Rabenflucht, an das Grab seiner Frau. Etwas in ihm zerbrach. Als die Wärter des Friedhofs ihn zurückhalten wollten, tötete er sie, und als er begriff, was er getan hatte, tötete er sich selbst. Man begrub ihn hastig, außerhalb des Friedhofs, und binnen weniger Tage war sein Grab leer. Nun wandelt er als Mor'Ladim durch den Dämmerwald und tötet jeden, dem er begegnet." },
        { "Er wusste nicht, dass eine seiner Töchter überlebt hatte. Behüterin Ladimore dient in der Nachtwache, und sie möchte, dass er weiß, dass niemand ihm die Schuld gibt." },
      },
    },
    ["morshan-rampart"] = {
      title = "Der Mor'shan-Schutzwall",
      text = {
        { "Mor'shan steht am nördlichen Rand des Brachlands, wo das Grasland in Ashenvale übergeht. Die Horde bewacht den Weg durch den Schutzwall, hin zu den Holzfällerlagern der Warsong und ihrem Streit mit den Schildwachen." },
        { "Die Mauer markiert eine Grenze, die keine Seite für entschieden hält. Die Orcs brauchen Holz, und die Nachtelfen verteidigen den Wald, der es liefert." },
      },
    },
    ["mosshide-gnolls"] = {
      title = "Die Gnolle der Moosfelle",
      text = {
        { "Die Moosfelle bewohnen das Moor im Sumpfland, das ihren Namen trägt. Rethiel der Sumpfhüter erinnert sich an Jahre, in denen sie dort friedlich lebten. Nun sieht er wachsende Zahlen, plattgetretene Pflanzen und zu viel Holz, das für ihre Feuer geschlagen wird." },
        { "Er bittet Reisende, Gnolle nahe Dun Algaz zu töten, um das Gleichgewicht des Moors wiederherzustellen. Sein Bericht macht daraus einen Streit um ein gemeinsames Zuhause, das zu eng und beschädigt geworden ist. Die Äxte und Feuer sind einem Zwerg vertraut genug. Es ist beunruhigend, sie in der Klage eines anderen darüber zu finden, was mit dem Land geschieht." },
      },
    },
    ["mulgore"] = {
      title = "Mulgore",
      text = {
        { "Nach dem roten Staub von Durotar und dem gelben Gras des Brachlands kommt Mulgore als Überraschung: sanft gewellte grüne Ebenen, klare Seen und Bäche, Herden von Kodos und Ebenenschreitern und große Tafelberge mit flachen Gipfeln, die aus dem Gras ragen. Es ist die Heimat der Tauren, und sie halten es zum ersten Mal in ihrer langen Geschichte als ihr Eigen." },
        { "Generationenlang wanderten die Tauren über die Ebenen Kalimdors, überall von den Zentauren bedrängt. Als die Orcs nach Kalimdor kamen, half Thrall Cairne Bloodhoofs Volk, die Zentauren zurückzudrängen und dieses Grasland einzunehmen, und seither haben sich die Stämme hier versammelt. Dennoch ist Mulgore nicht ohne Sorgen: Die Stacheleber der Borstennacken fallen aus den Schluchten ein, die Gnolle der Bleichmähnen jagen seine Tiere, und die Goblins der Venture Co. haben eine Mine in seine Klippen gegraben und seine Brunnen verschmutzt, gegen die ausdrückliche Weigerung der Tauren." },
      },
    },
    ["murlocs"] = {
      title = "Die Murlocs",
      text = {
        { "Murlochütten und Fischernetze säumen die Küsten auf beiden Kontinenten, von den Gewässern Elwynns bis zur Dunkelküste. Jäger und Orakel bewohnen ihre Siedlungen und greifen oft an, wer sich nähert. Ein Reisender kann mehreren Stämmen begegnen, ohne viel über die Geschichte hinter ihrer Anwesenheit zu erfahren." },
        { "Ein Stamm hatte einen entscheidenden Anteil an der Reise der neuen Horde. Murlocs im Dienst einer Meerhexe nahmen auf den Inseln der Dunkelspeer Trolle und Orcs gefangen. Thralls Gefolgsleute kämpften sich frei. Sen'jin starb, und die überlebenden Dunkelspeer segelten mit ihnen nach Kalimdor. Dieses Bündnis begann an einer Küste, die Murlocs verteidigten, lange bevor es in Durotar eine Heimat hatte." },
      },
    },
    ["myzrael"] = {
      title = "Myzrael",
      text = {
        { "Die Splitter von Myzrael bieten eine Stimme aus der Tiefe unter dem Arathihochland. Eine gefangene Prinzessin der Erde bittet einen vorbeiziehenden Reisenden, ihr bei der Flucht zu helfen, und die Kristalle verleihen der Begegnung ein Gefühl von Wärme und Geborgenheit." },
        { "Theldurin der Verirrte erzählt es anders. Er fürchtet, was sie tun wird, sobald sie wieder zu Kräften kommt, und fragt, warum die Riesen sie angekettet haben, wenn sie so leicht zu beherrschen ist. Seine Antwort ist, sie herbeizurufen und zu besiegen und ihre Fesseln dann wieder an die Splitter zu binden." },
        { "Danach steigt ein Schrei aus der Tiefe unter der Erde auf. Die Kristalle bleiben, doch ihre alte Beruhigung ist fort. Was jetzt durch sie pulsiert, fühlt sich an wie Hass auf die Welt darüber. Die Stimme, die so sanft um Hilfe bat, ist zum Beunruhigendsten an diesem stillen Hang geworden." },
      },
    },
    ["naga"] = {
      title = "Die Naga",
      text = {
        { "Die Große Teilung riss Azsharas Hochgeborene mit ihrer Hauptstadt unter das Meer. Sie überlebten, verwandelt in geschuppte Wesen mit schlangenartigem Unterleib, Flossen und in manchen Fällen vier Armen. Sie bauten ein Königreich unter dem Wasser. Die alten Geschichten verorten ihre Königin noch immer dort." },
        { "Im Dritten Krieg kehrten sie an die Oberfläche zurück, als Lady Vashj Naga in Illidans Diensten anführte. Kriegstrupps halten nun den Zoramstrand und den ertrunkenen Tempel der Blackfathom-Tiefe, die zerstörten Küsten von Azshara und der Dunkelküste und Küsten in Feralas, Desolace und Dustwallow." },
        { "Die Geschichte der Hochgeborenen endete nicht, als ihre Städte versanken, $gReisender:Reisende;. Dieselben Hochgeborenen ringen heute um Orte an den Küsten des Kontinents, ebenso verändert wie das Land, das sie einst kannten." },
      },
    },
    ["nathanos-blightcaller"] = {
      title = "Nathanos Blightcaller",
      text = {
        { "Nathanos Marris war ein Waldläuferlord Lordaerons, von allen geachtet, und der einzige Mensch, der je mit den Hochelfen von Quel'Thalas ausbilden durfte. Er starb in den Pestländern. Er wandelt noch immer dort, als Nathanos Blightcaller, der Champion der Banshee-Königin, mit seinen Seuchenhunden, an seinem eigenen alten Bauernhaus in Marris' Siedlung." },
        { "Er gibt den Jägern der Horde ihre schwerste Arbeit, gegen die Tiere der Pestländer, die Hochelfen der Quel'Lithien-Lodge und den Scharlachroten Kreuzzug, und nennt sie alle Schwachköpfe. SI:7 schickte fünf Agenten, um herauszufinden, was aus ihm geworden war. Einer kam zurück und starb. Das Wort, das er mitbrachte, war Blightcaller. Als die Allianz die Wahrheit erfuhr, verlangte Hochlord Bolvar Fordragon den Kopf des Blightcallers." },
        { side = "Horde", aside = true, sign = "P. F.", "Er nennt jeden einen Schwachkopf. Als Historiker bin ich verpflichtet festzuhalten, dass er nicht immer unrecht hat." },
      },
    },
    ["naxxramas"] = {
      title = "Naxxramas",
      text = {
        { "Naxxramas schwebt über den Pestländern, eine fliegende Zitadelle der Geißel und Kel'Thuzads Sitz. Von ihr kamen Streitkräfte für einen großen Einfall in die Städte Azeroths, was die Argentumdämmerung dazu brachte, jeden zu rufen, der bereit war, sich den Toten entgegenzustellen." },
        { "Fünf Jahre nach dem letzten Krieg regt sich der Lichkönig wieder, und Kel'Thuzad sammelt Heere für einen weiteren Angriff. Monstrositäten, Spinnen und Seuchenbringer bewohnen die Nekropole, zusammen mit vier Reitern, die einst Streiter des Lichts waren. Schaut nach oben, wenn Ihr die Pestländer durchquert, $gReisender:Reisende;. Ihr Befehlshaber hat eine Festung, die nicht darauf angewiesen ist, die Straße darunter zu halten." },
      },
    },
    ["nefarian"] = {
      title = "Nefarian",
      text = {
        { "Nefarian ist der Sohn Todesschwinges und der Bruder Onyxias. Wie seine Schwester nimmt er menschliche Gestalt an: Lord Victor Nefarius befehligt die Orcs der Blackrockspitze. Der Name verbirgt einen Drachen mit Plänen, die weit über die Festung hinausreichen." },
        { "Vom Pechschwingenhort aus kämpft er mit Ragnaros um die Herrschaft über den Berg und züchtet mit Hilfe der Dunklen Horde chromatische Drachen. Er hat sie für größere Eroberungen bestimmt. Streiter der Allianz und der Horde wurden gegen ihn geschickt, mit dem Versprechen, dass sein abgetrennter Kopf zur Schau gestellt wird. Ein Reisender, der diesen Preis sucht, muss zuerst durch das Heer, das er bereits versammelt hat." },
      },
    },
    ["nekrosh"] = {
      title = "Häuptling Nek'rosh",
      text = {
        { "Nek'rosh Skullcrusher führt, was von den Dragonmaw im Sumpfland übrig ist, und er ist der Sohn seines Vaters: Nekros Skullcrusher war der Orc, der die Drachenkönigin in Grim Batol gefangen hielt. Als die Drachen sich befreiten, nahmen sie Rache am Klan. Nek'rosh will die seine." },
        { "Er baut die Stärke der Dragonmaw in den Hügeln wieder auf, und er hat Katapulte bauen lassen, um den Hafen von Menethil zu belagern und die Straße nach Loch Modan abzuschneiden." },
        { "Wenn Ihr derjenige seid, der ihn aufhält, $gReisender:Reisende;, wäre die Liga für einen Bericht darüber dankbar, wie. Kurz, wenn Ihr es schafft. Berichte über Orchäuptlinge geraten gern lang." },
      },
    },
    ["nesingwarys-expedition"] = {
      title = "Nesingwarys Expedition",
      text = {
        { "Hemet Nesingwarys Lager liegt auf einer Lichtung im Norden des Schlingendorntals, gut ausgestattet mit Zelten, Trophäen und Gewehrständern. Der berühmte Jäger ist wegen der Panther, Tiger und Raptoren gekommen und um Die Grünen Hügel des Schlingendorntals zu schreiben. Jägern, die vorbeikommen, bietet er reichlich Gelegenheit, sich zu beweisen." },
        { "Sein Manuskript wurde vom Wind davongetragen, und seine Seiten liegen über den ganzen Dschungel verstreut. Die Kapitel erzählen von seiner Jagd, sobald jemand sie wieder in Ordnung gebracht hat. Wenn Ihr eine Seite findet, $gReisender:Reisende;, behaltet sie. Schriftsteller sind schon anstrengend genug, wenn sie wissen, wo ihr Werk ist." },
      },
    },
    ["nethergarde-keep"] = {
      title = "Burg Nethergarde",
      text = {
        { "Khadgar drängte nach dem Zweiten Krieg auf den Bau von Nethergarde, um das Dunkle Portal zu bewachen. Die Königreiche der Allianz zahlten dafür mit unterschiedlicher Begeisterung, und Dalaran stellte seine Magier. Als die Orcs das Portal wieder öffneten, belagerten sie die Burg. Die Wache war nötig gewesen." },
        { "Nethergarde ist heute auf Stormwinds Karawanen angewiesen. Seine Magier erforschen das Portal und die Öde ringsum. Ein Gelehrter bewahrt Khadgars Abhandlungen über die Konvergenz der Dimensionen. Anderswo in den Verwüsteten Landen sucht die Draenei Kum'isha nach Relikten, die einen Weg nach Hause öffnen könnten. Ein Reisender findet mehrere Gründe, einen Durchgang zu erforschen, der so viel Unheil gebracht hat." },
      },
    },
    ["night-elves"] = {
      title = "Die Nachtelfen",
      text = {
        { "Die Kaldorei sind das älteste Volk, dem die Liga begegnet ist, und sie sind zu höflich, um uns oft daran zu erinnern. Vor zehntausend Jahren schöpften ihre Hochgeborenen aus dem Brunnen der Ewigkeit, bis die Brennende Legion seinetwegen kam, und der Krieg, der folgte, zerbrach die Welt. Danach entsagten die Überlebenden dem Arkanen. Sie wandten sich den Druiden Malfurion Stormrages und den Priesterinnen der Elune zu und pflanzten auf dem Hyjal einen Weltenbaum, der sie nicht altern ließ." },
        { "Im Dritten Krieg kam die Legion zum Hyjal zurück. Um den Dämon Archimonde zu vernichten, gaben die Nachtelfen den Baum auf und mit ihm ihre Unsterblichkeit. Fandral Staghelm hat seither Teldrassil vor der Küste der Dunkelküste wachsen lassen, und Darnassus steht in seinen Ästen. Ob der neue Baum gesegnet ist wie der alte, sagen die Druiden nicht laut." },
        { "Nun altern sie, und sie lernen, was das bedeutet, $gReisender:Reisende;. Tyrande Whisperwind führt sie vom Tempel des Mondes aus, solange Malfurion im Traum verloren ist. Wenn eine Nachtelfe jedes Wort abzuwägen scheint, denkt daran, dass sie bis vor wenigen Jahren alle Zeit der Welt hatten, es zu wählen." },
      },
    },
    ["night-watch"] = {
      title = "Die Nachtwache",
      text = {
        { "Kommandantin Althea Ebonlocke führt die Nachtwache, die Miliz, die Dunkelhain aufstellte, nachdem Stormwind seine beauftragten Wachen abgezogen hatte. Die Bewohner verteidigen ihre Straße und ihre Tore gegen die Toten von Rabenflucht, die Worgen, die Oger und was sonst noch aus dem Wald kommt." },
        { "Die meisten sind keine Soldaten, und es sind zu wenige. Dennoch haben sie Dunkelhain am Leben erhalten. Behüterin Ladimore dient unter ihnen. Die Geschichte ihres Vaters steht an anderer Stelle in diesem Register." },
      },
    },
    ["nijels-point"] = {
      title = "Die Nijelspitze",
      text = {
        { "Die Nijelspitze ist das Lager der Allianz im Norden von Desolace, befestigt in den Hügeln unter dem Steinkrallengebirge. Seine Soldaten beobachten die Straßen, die Klans der Zentauren und die Dämonen von Mannorocs Koven. Besucher, die helfen wollen, finden reichlich Arbeit." },
        { "Die Hauptleute haben sich entschieden, die Rivalitäten der Zentauren auszunutzen, sich einen Klan zum Verbündeten zu machen, um zu lernen, wie man die anderen besiegt. Es ist eine praktische Antwort auf eine schwierige Lage, $gReisender:Reisende;. Die Freundschaft, die Ihr hier zu stiften helft, beginnt vielleicht mit der Bitte um den Tod der Nachbarn eines anderen." },
      },
    },
    ["noble-conspiracy"] = {
      title = "Die Verschwörung der Adligen",
      text = {
        { "Ein Brief, den man bei Edwin van Cleefs Leiche fand, führte die Ermittlungen gegen die Defias zurück nach Stormwind hinein. Er führte zu Bazil Thredd im Verlies, zu einem Besucher unter falschem Namen und schließlich zu dem Meuchler, den man Marzon die Stille Klinge nannte." },
        { "Marzon arbeitete für Lord Gregor Lescovar, der die Geheimnisse des Hofes an die Bruderschaft weitergab. Die Verbindungen des Adligen machten eine öffentliche Anklage schwierig. Die Verbündeten von SI:7 arrangierten ein Treffen in den Schlossgärten, wo Lescovar und Marzon getötet wurden." },
        { "Der Groll der Steinmetze begann damit, dass Adlige sich weigerten, für den Wiederaufbau Stormwinds zu bezahlen. Lescovar half nun dem Aufstand, den diese Weigerung mit hervorgebracht hatte. Van Cleefs Arm reichte weit tiefer in die Stadt hinein als bis zu den Leuten mit roten Masken." },
      },
    },
    ["northshire-abbey"] = {
      title = "Abtei von Nordhain",
      text = {
        { "Die Abtei von Nordhain steht in einem Tal am nördlichen Rand von Elwynn. Ihre Kleriker dienten Stormwind während des Ersten Krieges, bevor das Königreich an die Horde fiel. Nach dem Zweiten Krieg half Alonsus Faol, die Stadt wiederaufzubauen und die Bruderschaft von Nordhain neu zu ordnen." },
        { "Die Abtei unterweist die Rekruten des Königreichs heute in den Waffen ebenso wie im Glauben. Für beides gibt es ganz in der Nähe Verwendung: Kobolde besetzen die Mine, Wölfe streifen durch das Tal, und Diebe der Defias haben die Weinberge eingenommen." },
      },
    },
    ["northwatch-hold"] = {
      title = "Die Feste Northwatch",
      text = {
        { "Soldaten Theramores halten Northwatch über der Händlerküste, südlich von Ratchet. Captain Thalo'thas Brightsun beschuldigt seine Kanoniere, Schiffe seiner Flotte versenkt zu haben. Er bittet Abenteurer, die Kanonen zum Schweigen zu bringen und Captain Hellstieg zu töten." },
        { "Jaina Proudmoore hat Frieden mit Thrall geschlossen, und doch gehen die Kämpfe um die Feste weiter. Ein Reisender an dieser Küste versteht, warum man die Vereinbarung einer Herrscherin und das Verhalten eines Soldaten beide festhalten muss, wenn man diesen Frieden beschreibt." },
      },
    },
    ["ogres"] = {
      title = "Die Oger",
      text = {
        { "Die Oger kamen mit der Horde in diese Welt, aus demselben roten Land wie die Orcs, und kämpften im Zweiten Krieg als ihre schweren Fäuste. Der Hexenmeister Gul'dan verbesserte sie auf seine Weise: Er nutzte den Altar der Stürme, um Ogern die Kräfte der Ogermagier zu verleihen, und ihresgleichen beherrscht noch immer viele der Klans." },
        { "Nachdem die Horde gebrochen war, ließen sich Ogerklans in den wilden Gegenden nieder und sind dort geblieben: die Mo'grosh in Loch Modan, die Splitterfäuste im Dämmerwald, die Crushridge in Alterac, die Felsfäuste in Arathi, die Staubspeier im Ödland, die Mosh'Ogg im Schlingendorntal und die Schreckensfelsoger am Dunklen Portal. Jenseits des Meeres leben die Gordunni in Feralas und die Dünenbrecher in Tanaris. Die Gordok haben es sich in den Ruinen einer Elfenstadt in Feralas bequem gemacht und krönen jeden, der ihren König tötet." },
        { "Nicht jeder Klan hat das alte Bündnis vergessen. Die Stonemaul in den Marschen von Dustwallow kämpfen in Brackenwall an der Seite der Horde, und die Orcs sprechen gut von ihnen. Die übrigen würden Euch lieber fressen, als mit Euch zu reden." },
      },
    },
    ["onu"] = {
      title = "Onu",
      text = {
        { "Onu, ein Urtum der Lehren, steht im Hain der Uralten im Süden der Dunkelküste. Er bittet Reisende, die Meistergleve zu untersuchen, wo der Twilight-Hammer zwischen den Überresten einer gefallenen Macht sucht. Onu glaubt, dass dort lange nach ihrem Tod noch etwas von ihrer Stärke zu finden sein könnte." },
        { "Er gibt eine Phiole mit, die eine Wahrsageschale erschafft, damit er mit dem sprechen kann, der seine Untersuchung durchführt. Nehmt sie mit, $gReisender:Reisende;. Ein Urtum muss nicht zur Gleve gehen, um sich für das zu interessieren, was der Kult dort entdeckt." },
      },
    },
    ["onyxia"] = {
      title = "Onyxia",
      text = {
        { "Onyxia, Tochter Todesschwinges und Schwester Nefarians, beriet als Lady Katrana Prestor jahrelang den Regenten von Stormwind. Sie bog den Willen des Königreichs und hielt seine Truppen zu Hause, während die Orcs ihres Bruders das Rotkammgebirge bedrohten. Marshal Windsor entlarvte sie vor dem Hof. Sie floh in die Marschen von Dustwallow." },
        { "Ihr Hort ist eine andere Sache als ihr Platz bei Hof. Sie ist ein uralter, gewaltiger Drache, und Streiter beider Fraktionen suchen einen Weg hinein. Ein Reisender, der ihren menschlichen Namen kennt, weiß, warum er sich ihr entgegenstellen sollte. Ihre Höhle zu erreichen, lässt einen noch immer mit dem Drachen selbst zurück." },
      },
    },
    ["onyxias-lair"] = {
      title = "Onyxias Hort",
      text = {
        { "Onyxia hat ihren Hort im Drachensumpf, im Süden der Marschen von Dustwallow: eine große Höhle in den Klippen, mit den Eiern ihrer Brut darin und schwarzen Drachkin überall im Moor ringsum. Die Marsch zu durchqueren, ist der leichte Teil." },
        { "Der Eingang ist gesichert, und nur ein Drachenfeueramulett öffnet den Weg. Allianz und Horde werden gleichermaßen auf den langen Umweg geschickt, um eines herzustellen: durch die Blackrockspitze, für das Blut von General Drakkisath, der die Drachen der Spitze befehligt. Der Weg der Horde führt außerdem an der Drachin Aschenschwinge vorbei, die mit einer Illusion getäuscht werden muss, doch es ist das Amulett, das Euch einlässt." },
      },
    },
    ["orcs"] = {
      title = "Die Orcs",
      text = {
        { "Die Orcs kamen von Draenor, einer Welt der Klans und Schamanen, und sie kamen nicht aus freiem Willen. Der Hexenmeister Gul'dan und sein Schattenrat, im Dienst des Dämons Kil'jaeden, lehrten sie Teufelsmagie und brachten ihre Häuptlinge dazu, das Blut Mannoroths zu trinken. Die Horde, die das Dunkle Portal überschritt, wurde aus diesem Handel geboren, und sie brannte Stormwind nieder, bevor die Allianz sie im Zweiten Krieg brach." },
        { "Die besiegten Orcs wurden in Internierungslager gepfercht, teilnahmslos, während der Zorn der Dämonen aus ihnen wich. Thrall, als Sklave in Durnholde aufgewachsen, befreite sie, gab ihnen die alten Wege des Schamanen zurück und führte sie über das Meer nach Kalimdor. Am Hyjal kämpften sie an der Seite von Menschen und Nachtelfen gegen die Legion, und als Grom Hellscream Mannoroth tötete, war der Blutfluch gebrochen." },
        { "Sie nannten ihr neues Land Durotar, nach Thralls Vater, und bauten Orgrimmar in seine Felsen. Sie sind ein stolzes Volk mit einer langen Erinnerung daran, benutzt worden zu sein, $gReisender:Reisende;. Begegnet einem Orc mit Respekt und Ehrlichkeit, und verlangt nie von einem, wieder einem Herrn zu dienen." },
      },
    },
    ["orgrim-doomhammer"] = {
      title = "Orgrim Schicksalshammer",
      text = {
        { "Orgrim Schicksalshammer war Durotans Freund auf Draenor, ein Häuptling des Blackrockklans, der sah, was die Hexenmeister seinem Volk antaten, und anders als Durotan auf seinen Augenblick wartete. Er kam im Ersten Krieg. Als Gul'dans Meuchler Durotan ermordeten, tötete Schicksalshammer Blackhand, den Marionettenkriegshäuptling, den Gul'dan eingesetzt hatte, und nahm die Horde für sich. Er zerstörte Stormwind und zerschlug den Schattenrat." },
        { "Im Zweiten Krieg trieb er die Horde bis vor die Tore von Lordaerons Hauptstadt, bis Gul'dans Fahnenflucht ihn zurückzwang. Er tötete Anduin Lothar im Zweikampf in der Brennenden Steppe und verlor den Krieg trotzdem. Am Dunklen Portal gefangen genommen und nach Lordaeron gebracht, entkam er und lebte jahrelang als Einsiedler." },
        { "Thrall fand ihn dort. Der alte Kriegshäuptling, der Freund seines Vaters, folgte dem jungen und fiel bei der Befreiung eines der Lager. Thrall nahm seinen Hammer und seine schwarze Rüstung auf und wurde Kriegshäuptling. Dieser Ort trägt seinen Namen, und ebenso die Hauptstadt der Horde. Man erinnert sich an ihn als den Kriegshäuptling, der einen Krieg verlor und trotzdem dafür sorgte, dass am Ende noch eine Horde übrig war." },
      },
    },
    ["orgrimmar"] = {
      title = "Orgrimmar",
      text = {
        { "Orgrimmar ist die Hauptstadt der Horde, in einer großen Schlucht im Norden von Durotar erbaut und nach Orgrim Schicksalshammer benannt, dem Kriegshäuptling, der die Horde im Zweiten Krieg führte und im Kampf um ihre Befreiung aus den Lagern starb. Thrall trägt noch immer seinen Hammer. Die Goblins halfen beim Bau, und das merkt man: Alles ist Holz, Stacheln und Häute auf Stein, heiß wie eine Schmiede und laut wie ein Kriegslager." },
        { "In ihrem Herzen steht die Feste Grommash, benannt nach Grom Hellscream, der das Blut des Dämons Mannoroth trank und sein Volk verdammte, und der dann Mannoroth mit seiner eigenen Axt tötete und es befreite. Im Tal der Geister halten die Schamanen und die Trolle ihre Feuer, und in der Kluft der Schatten, so sagt man mir, gibt es Hexenmeister, die die Horde eher duldet, als ihnen zu vertrauen." },
        { "Es ist keine Stadt, die Zwerge willkommen heißt. Aber es ist eine echte Stadt, und die Orcs haben sie in einer Handvoll Jahren aus dem Nichts erbaut, was man von den meisten nicht sagen kann." },
      },
    },
    ["paladins"] = {
      title = "Paladine",
      text = {
        { "Die ersten Paladine waren die Ritter der Silbernen Hand, im Zweiten Krieg von Erzbischof Alonsus Faol gegründet, um das Heilige Licht auf das Schlachtfeld zu tragen. Uther Lightbringer führte sie, und sie kämpften für die Allianz durch den Krieg und den langen Frieden danach." },
        { "Der Dritte Krieg zerschlug den Orden. Prinz Arthas, selbst ein Paladin, wandte sich gegen alles, wofür er stand, und Uther fiel bei Andorhal durch ihn. Seine überlebenden Ritter zerstreuten sich nach Stormwind, Ironforge und in die Pestländer, wo manche der Argentumdämmerung dienen und andere der härteren Vorstellung des Lichts, die der Scharlachrote Kreuzzug hat. Derselbe Eid hat seine Träger in bitter verschiedene Gesellschaft geführt." },
        { client = "classic", "Heute bildet allein die Allianz Paladine aus, Menschen und Zwerge, die dem Licht in der Kathedrale des Lichts oder im Mystikerviertel von Ironforge die Treue schwören." },
        { client = "forever", "Menschen und Zwerge schwören dem Licht noch immer in Stormwind und Ironforge die Treue, während einige der Verlassenen nun ebenfalls die Berufung des Paladins ergreifen. Der Tod hat ihnen das Licht nicht verschlossen." },
      },
    },
    ["parqual-fintallas"] = {
      title = "Parqual Fintallas",
      text = {
        { "Vor der Seuche war Parqual Fintallas einer der großen Historiker Lordaerons. Heute ist er ein Verlassener, hält sich im Apothekarium von Undercity auf und forscht noch immer, auch wenn sich das, was er erforscht, mit ihm verändert hat." },
        { "Den jungen Helden der Horde stellt er eine Prüfung der Überlieferung. Bevor er seine Frage stellt, schickt er sie ins Scharlachrote Kloster nach den Anfängen der Bedrohung durch die Untoten, einem Buch, mit dem der Kreuzzug seine Paladine gegen seinesgleichen ausbildet, und er erwartet, dass sie es gelesen haben. Wissen, so meint er, zählt mehr als Stärke. Ich habe noch keinen Historiker etwas anderes behaupten hören." },
        { "Wir sind uns nie begegnet und werden es wohl auch nicht. Man sagt mir, eine Abschrift dieses Registers habe ihn trotzdem erreicht, auf Wegen, von denen ich lieber nichts wüsste. Ich hoffe, er findet es gerecht. Er wüsste besser als die meisten, wo es das nicht ist." },
        { side = "Horde", aside = true, sign = "P. F.", "Sie ist freundlicher zu mir als die Bücher des Kreuzzugs." },
      },
    },
    ["peoples-militia"] = {
      title = "Die Volksmiliz",
      text = {
        { "Als Stormwinds Soldaten nicht kamen, stellten die Leute von Westfall ihre eigenen auf. Die Volksmiliz besteht aus ein paar Soldaten, sehr vielen Bauern und einem Paladin, der sie anführt: Gryan Stoutmantle, der nicht zusehen wollte, wie Westfall der Bruderschaft überlassen wird." },
        { "Von der Späherkuppe aus bestreifen sie die Straßen, die sie können, jagen die Gnolle und die Defias und schicken ihre Späher in die Dolchhügel und die Ruinen von Moonbrook. Stoutmantle hat seine eigenen Freunde in niederen Kreisen, und durch einen von ihnen, einen Schurken in Seenhain, erfuhr er, wer die Bruderschaft anführt und wo sie sich verbirgt." },
      },
    },
    ["plague-cauldrons"] = {
      title = "Die Seuchenkessel",
      text = {
        { "Acht Seuchenkessel stehen auf den Höfen der Pestländer, vier im Westen und vier im Osten. Kessellords und die Toten der umliegenden Gehöfte bewachen sie. Ihre Dämpfe vergiften weiter ein Land, das seine Menschen schon verloren hat." },
        { "Kel'Thuzads Macht hindert die Allianz und die Verlassenen daran, sie einfach zu löschen. Stattdessen suchen Helfer in Chillwind und am Bollwerk Proben, um Gegenmittel herzustellen. In die Kessel gegeben, verändern diese Mischungen ihre Dämpfe so, dass sie die Geißel schwächen. Der Vorrat muss immer wieder erneuert werden." },
      },
    },
    ["platinum-discs"] = {
      title = "Die Platinscheiben",
      text = {
        { "Tief in Uldaman, jenseits des Steinbewahrers Archaedas, bewahren vier Platinscheiben einen Bericht, den ein steinerner Wächter spricht. Er nennt die Titanen die Schöpfer. Sie schufen die Irdenen aus dem Stein Azeroths, um seine tiefen Orte zu formen: starke Arbeiter, unermüdlich und schwer zu verletzen." },
        { "Der Wächter sagt, ihre Gestalt sei unter Belastung zerfallen. Ein Ergebnis behielt ihre Stärke, verlor aber den Verstand: die Troggs, als Fehlschlag beurteilt und unter der Erde versiegelt. Ein anderes behielt Stärke und Verstand, verlor aber den Stein. Das waren die Zwerge." },
        { "Ihr könnt verstehen, warum die Liga diese Aufzeichnung schätzt, $gReisender:Reisende;. Sie gibt uns Zwergen einen Anfang, den wir erforschen können, und macht die Geschöpfe, die die Grabungen der Liga stören, zum Teil derselben Frage wie unsere eigenen Ahnen." },
      },
    },
    ["priests"] = {
      title = "Priester",
      text = {
        { "Priester dienen dem Glauben ihres Volkes, und der Glaube der Völker ist verschieden. In Stormwind und Ironforge dienen sie dem Heiligen Licht. Die Priesterinnen der Nachtelfen dienen Elune, dem Mond, und hüten ihre Tempel seit zehntausend Jahren." },
        { "Auf der Seite der Horde haben die Dunkelspeer eigene Priester, und die Verlassenen behalten die ihren, deren Gebete sich ebenso bereitwillig dem Schatten zuneigen wie dem Licht. Ein Priester jedes dieser Völker kann eine Wunde schließen, einen Freund abschirmen, die Gefallenen erwecken oder dieselbe Macht gegen einen Feind wenden." },
        { client = "forever", "Auch die Gnome zählen nun Priester zu ihrem Volk und fügen der Gesellschaft in Tüftlerstadt eine weitere Berufung hinzu." },
        { "Sie sind die willkommenste Gesellschaft, die eine Grabung haben kann, $gReisender:Reisende;, und die am wenigsten geschätzte, bis jemand in einen Schacht fällt." },
      },
    },
    ["prince-thunderaan"] = {
      title = "Prinz Donneraan",
      text = {
        { "Donneraan der Windsucher war ein Prinz der Elementarfürsten der Luft, bis Ragnaros der Feuerlord seine Essenz verschlang. Was von ihm übrig blieb, wurde in zwei Hälften einer Fessel gebunden, die die Leutnants des Feuerlords im Geschmolzenen Kern tragen." },
        { "In Silithus weiß ein seltsames Wesen, das sich Hochlord Demitrian nennt, wie man ihn zurückbringt. Bringt ihm beide Hälften der Fesseln, das Elementium, um sie zu bearbeiten, und die Essenz des Feuerlords, und der Windsucher wird wiedergeboren. Was aus dieser Wiedergeburt hervorgeht, ist nicht dankbar, doch es lässt sich besiegen. Und daraus, so sagt man, lässt sich eine Klinge der Stürme machen." },
      },
    },
    ["pyrewood-village"] = {
      title = "Pyrewood",
      text = {
        { "Pyrewood ist ein Dorf nahe dem Greymane-Wall, und bei Tag sieht es aus wie jedes andere: Bauern, ein Rat, ein Oberbürgermeister. Bei Nacht verwandeln sich seine Bewohner in Worgen. Der Magier Arugal hat ihnen dies mit verzauberten Fesseln auferlegt, und die Verlassenen, die es erforscht haben, sagen, es sei der seltsamste Fluch, den sie je gesehen hätten." },
        { "Die Dorfbewohner wissen es, glaube ich, und leben damit auf die einzige Weise, die ihnen bleibt. Es ist der traurigste Ort im Silberwald, und im Silberwald gibt es Konkurrenz." },
      },
    },
    ["queen-azshara"] = {
      title = "Königin Azshara",
      text = {
        { "Dieses Land trägt den Namen der letzten Königin der Nachtelfen, und es ist kein Kompliment. Azshara war schön und begabt und anfangs von ihrem ganzen Volk geliebt. Sie baute ihren Palast am Ufer des Brunnens der Ewigkeit, füllte ihn mit ihren bevorzugten Dienern, den Hochgeborenen, und ließ sie erforschen, was die Macht des Brunnens vermochte." },
        { "Sie lernten Magie, und sie veränderte sie. Azshara zog sich von ihrem Volk zurück und sprach nur noch mit ihren Hochgeborenen. Dann erreichten die Wellen ihrer Zauberkunst Sargeras, und die Königin, überwältigt von ihrer eigenen Macht, willigte ein, ihm den Weg zu öffnen. Sie und ihre Hochgeborenen schufen ein Portal in den Tiefen des Brunnens, und die Brennende Legion kam hindurch." },
        { "Am Ende des Krieges der Urtume stürzte der Brunnen ein, und das Meer nahm ihren Palast, ihre Stadt und ihren Hof. Die Nachtelfen sagen, sie sei mit ihnen hinabgezogen worden. Die Naga, die an diesen Küsten spuken, waren einst ihre Hochgeborenen, und die Ruinen an dieser Küste sind, was über dem Wasser übrig blieb." },
      },
    },
    ["queldanil-lodge"] = {
      title = "Die Quel'Danil-Hütte",
      text = {
        { "Die Quel'Danil-Hütte ist die Heimat der Hochtalelfen im Hinterland, weit südlich von Quel'Thalas. Ihre Waldläufer jagen in den Hügeln, stellen sich den Waldtrollen entgegen und leisten den Wildhammer Gesellschaft. Ihr Bündnis mit den Zwergen ist Teil eines viel älteren Streits zwischen den Elfen und den Amani." },
        { "Ihre Heimat liegt jenseits der Pestländer, von der Geißel verwüstet. Hier bleibt die Hütte ein Ort der Verständigung, mit Gesandten, die Beziehungen zu anderen Völkern suchen." },
      },
    },
    ["quilboar"] = {
      title = "Die Stacheleber",
      text = {
        { "Im Krieg der Urtume kämpfte ein großer Ebergott, Agammagan, gegen die Brennende Legion und fiel. Wo sein Blut in den Boden des Brachlands sickerte, wuchsen gewaltige Dornen, und die Stacheleber kamen, um zwischen ihnen zu leben: ein Volk aus Ebermenschen, bestachelt und mit Hauern, das die Dornen für heilig hält und sich seine Kinder nennt. Den größten dieser Dornenbauten nennen sie Razorfen." },
        { "Die Stämme breiteten sich über das Brachland, Mulgore und Durotar aus: die Grimmhauer, die Borstennacken, die Stacheleber von Razorfen in ihrem Kral. Sie bekämpfen die Zentauren, die Tauren und die Orcs mit gleicher Wut, und sie bekämpften sie schon lange, bevor die Horde kam. Nun gibt es schlimmere Nachrichten. In den Hügeln von Razorfen hat der Stamm der Totenköpfe einen Handel mit der Geißel geschlossen, und ein Lich namens Amnennar der Kältebringer sitzt im Herzen von Agammagans Dornen." },
      },
    },
    ["ragefire-chasm"] = {
      title = "Ragefireabgrund",
      text = {
        { "Unter Orgrimmar liegen Höhlen aus Feuer und geschmolzenem Gestein, und die Horde hat ihre Hauptstadt darüber gebaut, ohne, wie es scheint, sehr genau hinzusehen. Zuerst kamen Troggs durch sie herauf. Dann die Sengklinge: ein Kult der Burning Blade, der sich in den Tiefen direkt unter den Füßen des Kriegshäuptlings eingerichtet hat, mit einem Dämon namens Taragaman der Hungerleider unter ihnen." },
        { "Thralls Volk hat die Jungen der Horde hinabgeschickt, um ihn zu säubern. Mir fallen wenige bessere Lektionen darüber ein, worauf eine Hauptstadt gebaut ist." },
      },
    },
    ["ragnaros"] = {
      title = "Ragnaros",
      text = {
        { "Ragnaros, der Feuerlord, ist ein Elementarfürst, den die Dunkeleisenzwerge vor Jahrhunderten herbeiriefen, in der Hoffnung, ihren Krieg zu gewinnen. Seither hält er sie in seinem Dienst. Ihr Imperator erklärt sich zu seinem Diener, während Feuerelementare durch die Schlucht und die Steppe streifen, die seine Ankunft verwüstete." },
        { "Im Geschmolzenen Kern wartet er inmitten der Lava darauf, von seinem Majordomus herbeigerufen zu werden. Nefarian macht ihm die Herrschaft über den Berg streitig, und die Hydraxianer setzen ihren uralten Widerstand gegen ihn fort. Die Dunkeleisenzwerge leben zwischen diesen Mächten, noch immer an den gebunden, den ihre Ahnen um Hilfe baten." },
      },
    },
    ["ras-frostwhisper"] = {
      title = "Ras Frostraunen",
      text = {
        { "Der Lich, der die Hallen der Scholomance beherrscht, war einst ein Mann aus Stromgarde, Ras Frostraunen mit Namen. Als die Geißel nach Stratholme kam, gab er ihr sein Leben auf dem blutgetränkten Boden der Stadt, freiwillig und mit Absicht, um einer der Unsterblichen zu werden. Heute beaufsichtigt er die Schule der Nekromantie." },
        { "Die Untoten fürchten das Leben, wie die Lebenden den Tod fürchten, sagt Magistrat Marduke, und ein denkender Untoter vernichtet oft jede Erinnerung daran, wer er war. Ras übersah etwas. Ein Andenken aus seinen sterblichen Jahren lag noch in den Ruinen von Stromgarde, und auf dem Boden eingestimmt, auf dem er starb, kann es ihn wieder sterblich machen: lange genug jedenfalls, um ihn endgültig niederzustrecken." },
        { "Es ist selten, dass man einen Lich ungeschehen macht. Noch seltener ist es, dass dies mit etwas beginnt, das er wegzuwerfen vergaß." },
      },
    },
    ["ratchet"] = {
      title = "Ratchet",
      text = {
        { "Ratchet ist ein Goblinhafen an der Küste des Brachlands, eine der neutralen Städte des Steamwheedle-Kartells, wo Schiffe nach Booty Bay kommen und gehen und niemand eine Klinge gegen irgendwen zieht, ohne es zu bereuen. Sein Herr ist Gazlowe, derselbe Goblin-Ingenieur, der Thrall half, Orgrimmar zu bauen, und er führt es wie ein Geschäft." },
        { "Seine Sorgen liegen meist auf See: Die Südmeerfreibeuter überfallen seine Schiffe von der Händlerküste aus, und die Kanoniere der Allianz in der Feste Northwatch, im Süden, haben einige davon aus Versehen versenkt, wie sie behaupten." },
      },
    },
    ["raven-hill"] = {
      title = "Rabenflucht",
      text = {
        { "Das Dorf Rabenflucht steht leer neben einem Friedhof, der sich über den ganzen Hang ausgebreitet hat. Skelette wandeln durch seine Reihen, Ghule graben zwischen den Gräbern, und die Nachtwache kann die Toten nicht in Ruhe halten. Der Friedhof ist gefährlicher geworden als die verlassenen Häuser um ihn herum." },
        { "Morbent Fel, ein Nekromant, lebt in einem Haus über dem Friedhof. Ein Holzfäller, dessen Familie er tötete, will ihn tot sehen. In der Nähe bewohnt ein alter Einsiedler eine Hütte mit Blick auf die Gräber. Früher kam er für Vorräte nach Dunkelhain, doch dort hat man ihn schon eine Weile nicht mehr gesehen." },
      },
    },
    ["ravencrest-monument"] = {
      title = "Das Ravencrest-Monument",
      text = {
        { "Die zerbrochenen Beine einer großen Statue stehen auf den südlichen Klippen von Azshara. Der Ort heißt Ravencrest-Monument. Naga besetzen die Ruinen, und der Rest des Kolosses liegt verstreut oder unter dem Meer. Selbst was übrig ist, gibt einen beachtlichen Orientierungspunkt ab." },
        { "Lord Kur'talos Ravencrest führte im Krieg der Urtume den Widerstand der Nachtelfen von der Rabenwehr aus. Sein Name erinnert an jene, die sich Azshara und der Legion widersetzten. Bewahrt auch sie in der Geschichte dieser Küsten, $gReisender:Reisende;. Der Hof der Königin war nicht das ganze Volk, dessen Welt zerstört wurde." },
      },
    },
    ["ravenholdt-manor"] = {
      title = "Ravenholdt-Anwesen",
      text = {
        { "Das Ravenholdt-Anwesen liegt verborgen in den Hügeln über Hillsbrad. Lord Jorach Ravenholdt leitet von dort die Auftragsmörderliga und bildet Diebe und Mörder aus, die das Haus selbst auswählt. Mögliche Schüler erhalten Einladungen. Eine Bewerbung wäre hier eine ungewöhnliche Art, seine Talente anzukündigen." },
        { "Die Liga stellt sich seit langem gegen das Syndikat, dessen Mitglieder sie für Stümper hält. Ihre Abzeichen zu stehlen, ist ein nützlicher Teil des Streits: Ein Mann des Syndikats, der seines verliert, muss mit Strafe von seiner eigenen Seite rechnen." },
      },
    },
    ["razelikh-the-defiler"] = {
      title = "Razelikh der Entweiher",
      text = {
        { "Razelikh der Entweiher ist ein Dämon, der von einem Hort auf dem Gipfel des höchsten Berges der Verwüsteten Lande aus herrscht, mit drei Leutnants unter sich: Grol dem Zerstörer, Lady Sevine und Erzmagier Allistarj. Sie nahmen die Krieger des gefallenen Helden der Horde und banden ihre Geister in Steine der Qual." },
        { "Der gefallene Held hat Reisende ausgeschickt, um seine Männer zu befreien, die drei Leutnants zu töten und ihre Amulette zu nehmen, und mit dem wieder ganzen Amulett zu Razelikhs Altar hinaufzusteigen und den Dämon herauszufordern. Sein Horn, sagt er, wird der Beweis sein, dass es in dieser vom Krieg zerrissenen Welt noch Helden gibt." },
      },
    },
    ["razor-hill"] = {
      title = "Klingenhügel",
      text = {
        { "Der Klingenhügel ist eine Garnisonsstadt an der Straße vom Tal der Prüfungen nach Orgrimmar: eine Kaserne, ein Gasthaus, ein Wachturm und eine Palisade aus angespitztem Holz auf einem Hügel über dem Meer. Sein Befehlshaber Gar'Thok hält ihn für den Kriegshäuptling und verbringt die meisten seiner Tage damit, alles abzuwehren, was aus den Schluchten heraufkommt oder von der Küste hereindrängt." },
        { "Gleich südlich liegt Burg Tiragarde, wo sich die Leute von Kul Tiras noch an die Küste von Durotar klammern, und das Wrack der Flotte ihres Admirals verrottet vor dem Strand. Die Grunzer des Klingenhügels behalten beides genau im Auge." },
      },
    },
    ["razorfen-downs"] = {
      title = "Die Hügel von Razorfen",
      text = {
        { "Südlich des Krals liegt ein weiterer von Agammagans Dornenbauten, die Hügel von Razorfen, und dort ist etwas Schreckliches geschehen. Die Stacheleber der Totenköpfe, die sie halten, haben einen Handel mit der Geißel geschlossen. Ein Lich, Amnennar der Kältebringer, herrscht nun über die Hügel, die Geißel hält einen Botschafter unter den Stacheleber, und die Toten wandeln zwischen den Dornen des Grabes des Ebergottes." },
        { "Wie die Diener des Lichkönigs so tief nach Kalimdor gelangten, kann mir niemand sagen. Dass sie es getan haben und dort bauen, ist Grund genug für jedes Volk im Brachland, sich Sorgen zu machen." },
      },
    },
    ["razorfen-kraul"] = {
      title = "Der Kral von Razorfen",
      text = {
        { "Charlga Razorflank herrscht über den Kral von Razorfen, ein großes Labyrinth aus Dornen und Tunneln im Süden des Brachlands. Die Krieger der Schamanin der Stacheleber halten den Eber Agathelos in seinen Tiefen. Der Bau ist eine Festung im Herzen ihres Volkes." },
        { "Henrik Lonebrows Tagebuch berichtet von seiner Gefangenschaft dort neben dem verwundeten Druiden Heralath. Heralath bat ihn, Falfindel Waywarder in Thalanaar vor Charlgas wachsender Macht zu warnen. Lonebrow erreichte den großen Aufzug, doch sein Leichnam liegt dort mit dem Tagebuch. Falfindel bittet andere, ihre Arbeit zu vollenden." },
      },
    },
    ["red-dragonflight"] = {
      title = "Der rote Drachenschwarm",
      text = {
        { "Alexstrasza nennt man die Lebensbinderin, Königin der roten Drachen und eine der ältesten Mächte der Welt. Während des Zweiten Krieges hielten die Dragonmaw sie in Grim Batol gefangen und zwangen ihre Kinder in ihren Dienst. Der Schwarm ist seither befreit." },
        { "Rote Drachkin bewachen noch immer die Zugänge zu Grim Batol. Sie behandeln Eindringlinge als Feinde, welches Anliegen diese Eindringlinge auch dorthin zu führen glauben. Haltet Abstand, $gReisender:Reisende;. Zu wissen, was ihnen hier widerfahren ist, macht einen Eindringling nicht willkommen." },
      },
    },
    ["red-rocks"] = {
      title = "Teufelsfelsen",
      text = {
        { "Östlich von Thunder Bluff, zwischen großen roten Steinen, liegt die heilige Begräbnisstätte der Tauren. Nur die Tapfersten werden an den Teufelsfelsen zur Ruhe gebettet: die Krieger, die halfen, Thunder Bluff zu gründen und zu verteidigen, und jene, die ihr Leben für ihre Stämme und Häuptlinge gaben. Die Geister der Ahnen sollen dort noch wandeln." },
        { "Die Jungen kommen für den letzten der Riten hierher, den Ritus der Weisheit, um den Segen dieser Ahnen zu empfangen. In letzter Zeit graben die Stacheleber in den Gräbern, und der alte Hüter der Überlieferung, der sie pflegt, kann sie nicht mehr abwehren. Wenn Ihr Euch jeden Tauren in Mulgore zum Freund machen wollt, gibt es keinen schnelleren Weg." },
      },
    },
    ["redridge-mountains"] = {
      title = "Rotkammgebirge",
      text = {
        { "Das Rotkammgebirge hat seinen Namen vom rostroten Stein unter seinen Kiefernwäldern. Der Immerruhsee liegt zwischen den Hügeln, mit Seenhain an seinem Westufer. Holz und Fischfang ernähren das Land, doch Heere sind oft genug durch es gezogen: Die Orcs kamen im Ersten Krieg, und die Blackrock sind zurückgekehrt." },
        { "Sie halten nun Burg Steinwacht und die Täler dahinter. Gnolle streifen durch die Schluchten, ein Hexenmeister besetzt die östlichen Hügel, und schwarze Drachenwelpen nisten in den hohen Höhlen. Seenhain hat Stormwind wiederholt um Soldaten gebeten." },
      },
    },
    ["refuge-pointe"] = {
      title = "Die Zuflucht",
      text = {
        { "Die Zuflucht ist das Lager der Allianz mitten im Arathihochland, gehalten von den Überlebenden Stromgardes und den Soldaten, die gekommen sind, um ihnen zu helfen: ein paar Zelte, ein Stall, ein Flugmeister und sehr viel Entschlossenheit. Von hier kämpfen sie gegen das Syndikat in den Ruinen ihrer Stadt und gegen die Witherbark in den Hügeln, und von hier reitet auch der Bund von Arathor hinaus zum Becken im Süden." },
        { "Die Leute von Stromgarde sind stolz, und ihr Königreich ist auf dieses Lager zusammengeschrumpft. Sie haben nicht aufgehört, es ein Königreich zu nennen." },
      },
    },
    ["regency-of-stormwind"] = {
      title = "Die Regentschaft von Stormwind",
      text = {
        { "König Varian Wrynn ist verschwunden. Er war der Sohn von König Llane, der im Ersten Krieg ermordet wurde, und wuchs unter den Flüchtlingen Stormwinds in Lordaeron auf. Sein eigenes Schicksal bleibt in der Stadt, über die er herrschte, unbekannt." },
        { "Sein junger Sohn Anduin trägt die Krone. Hochlord Bolvar Fordragon hält das Königreich für ihn, befehligt seine Streitkräfte und beschützt den Jungen. Die königliche Beraterin, Lady Katrana Prestor, steht an Bolvars Seite." },
        { "Stormwinds Heer ist dünn verteilt, und Forderungen treffen aus allen Richtungen ein." },
      },
    },
    ["remtravels-excavation"] = {
      title = "Remtravels Ausgrabung",
      text = {
        { "Als Golems Remtravels Ausgrabung im Süden der Dunkelküste überrannten, floh seine Assistentin nach Auberdine, um Hilfe zu holen. Der gefeierte Ausgrabungsleiter blieb bei der Arbeit. Hollees Bewunderung für seine Entdeckungen überdauert neben dem verzweifelten Wunsch, er möge gelegentlich bemerken, was um ihn herum geschieht." },
        { "Sein rätselhaftes Fossil hat das Interesse von Chefarchäologe Greywhisker geweckt, und eine Ähnlichkeit mit einem anderen Fund führt die Nachforschungen weiter zu Flagongut im Hafen von Menethil. Remtravel hat etwas gefunden, das es wert ist, untersucht zu werden. Ihn lange genug am Leben zu halten, damit er die Untersuchung abschließen kann, ist zu einer eigenen zweiten Expedition geworden." },
      },
    },
    ["rend-blackhand"] = {
      title = "Kriegshäuptling Rend Blackhand",
      text = {
        { "Rend ist der Sohn von Blackhand dem Zerstörer, dem ersten Kriegshäuptling der Horde. Er und sein Bruder Maim führten die Black Tooth Grin unter Orgrim Schicksalshammer, dem Mörder ihres Vaters, und suchten dabei Rache ebenso wie die Stellung, die Blackhand verloren hatte." },
        { "Rend beansprucht nun von der Blackrockspitze aus den Titel des Kriegshäuptlings, dient Nefarian und befehligt die Orcs des Drachen. Thrall weist diesen Anspruch zurück und schickt Streiter, um ihn zu töten, wobei Etriggs Wissen über die Blackrock hilft, die Antwort zu lenken. Ihr werdet hier zwei Ansprüche auf die Horde hören, doch nur einer dieser Anführer ist einem schwarzen Drachen Rechenschaft schuldig." },
      },
    },
    ["revantusk-village"] = {
      title = "Revantusk",
      text = {
        { "Die Revantusk halten ein Dorf an der Ostküste des Hinterlands. Sie sind Waldtrolle, mit der Horde verbündet, ein kleiner Stamm, bedrängt von größeren Nachbarn. Die Vilebranch nahmen ihren Ältesten, um ihn zu opfern, und die Freundschaft der Wildhammer mit den Hochelfen gibt ihnen einen weiteren Streit gleich in der Nähe." },
        { "Die Amani und die Elfen von Quel'Thalas sind Feinde, seit die Elfen sich in diesen Landen niederließen. Diese ältere Feindschaft lebt unter den Revantusk fort." },
      },
    },
    ["rexxar"] = {
      title = "Rexxar",
      text = {
        { "Der Riese, der mit einem Bären an seiner Seite die Straße durch Desolace entlanggeht, ist Rexxar, Champion der Horde. Er ist halb Orc und halb Oger, von den Mok'Nathal, und er gehört zu keiner Stadt. Misha, seine Bärin, geht, wohin er geht." },
        { "Er kam in den ersten Tagen nach Durotar, als das Land neu war und die Horde noch ihren Halt suchte, und Thrall vertraute ihm Arbeit an, die niemand sonst tun konnte. Als Admiral Daelin Proudmoore seine Flotte landen ließ, um den alten Krieg zu beenden, stand Rexxar im Zentrum der Kämpfe, die ihn beendeten, an der Seite von Thrall und Cairne und, wie es sich fügte, mit Jaina Proudmoores Einverständnis. Die Horde verdankt ihm einen guten Teil ihrer Heimat." },
        { "Er blieb nicht, um sie zu genießen. Er zieht die Wildnis den Städten vor, die er verteidigen half, und er bleibt auf den Pfaden zwischen dem Steinkrallengebirge und Feralas. Der Kriegshäuptling schickt noch immer Reisende zu ihm, wenn die Arbeit hart ist. Er wird Euch sehen, bevor Ihr ihn seht, $gReisender:Reisende;. Misha sieht Euch zuerst." },
      },
    },
    ["rockjaw-troggs"] = {
      title = "Die Troggs",
      text = {
        { "Die Aufzeichnungen der Titanen in Uldaman beschreiben Troggs als missglücktes Ergebnis der Erschaffung der Irdenen. Sie waren unter der Erde versiegelt, bis die Grabungen der Zwerge ihre Hallen öffneten. Unsere Suche nach unseren eigenen Anfängen ließ Geschöpfe frei, deren Ursprung ihnen unangenehm nahe war." },
        { "Die Felsenkiefer bewohnen die Steinbrüche und Höhlen von Dun Morogh, die Splittersteintroggs die Täler von Loch Modan und die Steingrufttroggs Uldaman selbst. Troggs drangen auch in Gnomeregan ein. Andere sind an der Dunkelküste und unter Orgrimmar aufgetaucht, auch wenn ihr Weg über das Meer ungewiss bleibt." },
        { "Gebirgsjäger bitten um Hilfe bei der Verteidigung von Straßen und Siedlungen, und die Gnome bekämpfen sie noch immer in ihrer Hauptstadt. Ein Reisender, der dieses Register bei sich trägt, wird die Gelehrten von Ironforge an der Geschichte der Troggs interessiert finden. Wer eine Mine bewacht, hat ein unmittelbareres Anliegen: sie draußen zu halten." },
      },
    },
    ["rogues"] = {
      title = "Schurken",
      text = {
        { "Jede Stadt hat ihre stillen Gewerbe, und die Schurken üben sie alle aus: das Schloss, das sich ohne Schlüssel öffnet, der Geldbeutel, der den Besitzer wechselt, ohne dass sein Eigentümer es merkt, die Klinge von hinten. Manche dienen einer Krone, wie SI:7 in Stormwind. Manche dienen niemandem außer der Münze, wie die Defias in Westfall und das Syndikat in Alterac." },
        { "Zwischen beiden stehen die Meuchler von Ravenholdt, in den Hügeln von Alterac über Hillsbrad, die ihre Aufträge und ihre Schüler mit gleicher Sorgfalt wählen sollen. Schurken jedes Volkes gehen durch ihre Tore, und wenige sprechen darüber, was sie dort gelernt haben." },
        { "Ein Schurke kämpft mit Giften, flinken Händen und Überraschung und geht, wenn sich das Blatt wendet. Die Liga hat ein paar angeheuert, um zurückzuholen, was andere ihr bereits genommen hatten, $gReisender:Reisende;. Es ist nicht die stolzeste Zeile in den Büchern der Liga, aber eine der längsten." },
      },
    },
    ["royal-apothecary-society"] = {
      title = "Die Königliche Apothekervereinigung",
      text = {
        { "Meister Faranells Königliche Apothekervereinigung dient den Verlassenen mit Alchemie, Giften und dem Versprechen einer neuen Seuche. Sylvanas hat ihren Mitgliedern aufgetragen, eine Krankheit zu finden, die die Geißel des Lichkönigs vernichten kann. Ihre Vorbereitungen reichen weit über die Laboratorien von Undercity hinaus." },
        { "In Brill und Hillsbrad sammeln Reisende Blut und andere Zutaten für Versuche an Tieren, Murlocs und Gefangenen. Apotheker Lydon blickt über das blühende Land von Hillsbrad und sehnt sich danach, seine Arbeit Tod darüber bringen zu sehen. Wer auch immer der erklärte Feind der Vereinigung sein mag, zu seinen Zielen gehören offensichtlich die Lebenden." },
        { "Die Verlassenen wissen besser als die meisten, was es heißt, wenn eine Seuche einem die Heimat nimmt. Dieses Wissen hat nicht alle ihre Apotheker davor bewahrt, dasselbe Elend gern anderen zu bereiten." },
      },
    },
    ["ruins-of-ahnqiraj"] = {
      title = "Ruinen von Ahn'Qiraj",
      text = {
        { "Als der Gong geschlagen wurde und der Skarabäuswall sich öffnete, strömten die Heere der Allianz und der Horde in die äußere Stadt von Ahn'Qiraj, die Ruinen, ein Ort aus zerbrochenen Tempeln und Sand, der von Insekten wimmelt. Der Qiraji-General Rajaxx befehligt hier, derselbe, der vor tausend Jahren Valstann Staghelm tötete, und die Ruinen werden in ihrem Herzen von dem großen steinernen Krieger Ossirian dem Narbenlosen bewacht." },
        { "Der Zirkel des Cenarius schickte eigene Streiter in die Ruinen, und für sie war die Schlacht in der Stadt das Ende eines sehr alten Krieges." },
      },
    },
    ["ruins-of-eldarath"] = {
      title = "Die Ruinen von Eldarath",
      text = {
        { "Die Ruinen der Hochgeborenen von Eldarath klammern sich an die östlichen Klippen von Azshara über der Bucht der Stürme. Ein Großteil der Stadt stürzte während der Großen Teilung ins Meer. Ihre Bewohner hatten ihr arkanes Wissen an öffentlichen Orten in Runen und Tafeln gemeißelt, und manche sind zwischen dem zerbrochenen Stein noch lesbar." },
        { "Die Naga von Kriegsherr Krellian halten die Ruinen nun vom Tempel von Zin-Malor aus. Die Nachtelfen meiden den Ort, doch die Forscherliga will Abriebe der Inschriften. Wenn Ihr an den Naga vorbeikommt, $gReisender:Reisende;, bewahren diese Tafeln vielleicht etwas, das das Meer noch nicht genommen hat." },
      },
    },
    ["ruins-of-keltheril"] = {
      title = "Die Ruinen von Kel'Theril",
      text = {
        { "Am gefrorenen Kel'Therilsee liegen die Ruinen einer Stadt der Hochgeborenen, und ihre Hochgeborenen sind noch dort, als Geister. Vor langer Zeit stahlen sie ein heiliges Relikt, den Kristall von Zin-Malor, aus seinem Tempel, um seine Macht für sich selbst abzuschöpfen. Das Ritual ging schief. Der Kristall zersprang in einer gewaltigen Explosion, und seine Stücke wurden unter das Eis des Sees getrieben." },
        { "Die Hochgeborenen wurden verflucht, an dem Ort zu bleiben, an dem sie es getan hatten, und für immer nach den Stücken zu suchen. Als schließlich jemand sie sammelte und den Kristall wieder ganz machte, sprach einer der Geister: Es tue ihm leid, und er wisse, dass nichts die Vergangenheit ändern könne, doch er habe Frieden. Der Tempel des Kristalls liegt in Ruinen, also ging er stattdessen an den Erzdruiden in Darnassus." },
      },
    },
    ["ruins-of-lordaeron"] = {
      title = "Die Ruinen von Lordaeron",
      text = {
        { "Über Undercity sind die Straßen von Lordaerons Hauptstadt weniger leer, als sie vom Tor aus aussehen. Die Geißel wandelt noch in großer Zahl durch die tieferen Ruinen, und ein unheiliger Nebel ist über die Straßen und den alten Friedhof gekrochen, hervorgerufen, so glaubt die Todeswache, von einem Nekromanten namens Rath'mael auf der Warte Lordamere. Die Verlassenen schicken, was sie an Kräften erübrigen können, und ihre Verluste sind so groß, dass ein Paladin im Königsviertel Reisende um die unversehrten Gliedmaßen bittet, die die Toten zurücklassen." },
        { "Nicht jeder, der hinaufgeht, geht für die Bansheekönigin. Edward Heartweaver ging jede Woche zum Friedhof, auf der Suche nach dem Sohn, den er verlor, als Arthas die Stadt zerstörte, bis er eines Tages nicht heimkam. Und unter den Monstrositäten, die dort oben zusammengenäht werden, ist eine, die die Apotheker den Baron nennen und unter einem älteren Namen kennen: Othmar Garithos, der Lord, der mit Sylvanas gemeinsame Sache gegen die Geißel machte und die Abmachung nicht überlebte. Captain Truman, der ihm diente, wartet noch immer in den Ruinen auf die Rückkehr seines Befehlshabers." },
        { side = "Horde", aside = true, sign = "P. F.", "Von allem auf dieser Seite ist es Edward Heartweavers wöchentlicher Gang, zu dem ich immer wieder zurückkehre." },
      },
    },
    ["ruins-of-thaurissan"] = {
      title = "Die Ruinen von Thaurissan",
      text = {
        { "Dies sind die Ruinen der Stadt Thaurissan, der Hauptstadt des Klans der Dunkeleisenzwerge, nachdem sie vor Jahrhunderten Ironforge verlassen hatten, als die Brennende Steppe grün war. Als ihre Heere bei Ironforge und Grim Batol vernichtet wurden, stiegen Zauberthan Thaurissan und sieben seiner größten Zwerge hinab, um die Mächte anzurufen, die unter der Welt schliefen, und den Krieg zu wenden." },
        { "Was antwortete, war Ragnaros, der Herr des Feuers. Der Berg barst. Die Stadt wurde zerstört, die Täler brannten, und die Dunkeleisenzwerge, die überlebten, wurden die Sklaven des Feuerlords. Die Relikte der Stadt erinnern sich noch: Wer sie berührt, sieht acht Zwerge bei einem Ritual, und dann einen allein, kniend zwischen sieben Leichen vor einer Säule aus Flammen. Ich habe diese Geschichte auf dem Hohen Sitz öfter erzählt, als ich zählen kann, und diese Relikte erklären vieles davon, was ich nur vermutet hatte. Ein Goblin in Morgans Wacht, Maxwort, wird Euch sagen, die Sieben seien Zwerge von großem Wissen gewesen, und Wissen bringe Reichtum. Goblins." },
      },
    },
    ["rustmaul-dig-site"] = {
      title = "Die Rustmaul-Grabungsstätte",
      text = {
        { "Am Rand der schimmernden Ebene schlug eine Gruppe Zwerge eine Grabung auf, Rustmaul, auf der Suche nach dem, was unter dem Salz liegt. Die Horde schickte einen Kriegstrupp, um sie zu vertreiben. Mitten im Kampf öffnete sich der Boden, und Insekten strömten aus einer Höhle in der Grabung: Silithiden, mehr, als beide Seiten je gesehen hatten, und sie hätten beinahe alle getötet." },
        { "Die Zwerge sind fort. Die Insekten nicht. Die Jäger der Horde, die überlebten, halten die Silithiden nun für eine weit größere Gefahr als jede Grabungsmannschaft, und nachdem ich die Berichte gelesen habe, tue ich das auch. Wonach die Zwerge suchten, hat mir niemand gesagt. Ich bin nicht sicher, ob sie es gefunden haben." },
      },
    },
    ["sandfury-trolls"] = {
      title = "Die Trolle der Sandfury",
      text = {
        { "Die Sandfury sind die Trolle der Wüste von Tanaris, groß, hager und hart wie der Sand, auf dem sie leben. Ihre Hauptstadt ist Zul'Farrak im Westen der Wüste, und sie verteidigen, was von ihren Landen übrig ist, gegen jeden: Allianz, Horde, Goblins, Oger, Banditen und vor allem die Insekten des Südens." },
        { "Sie sind ein altes Volk mit alten Kriegen hinter sich. Ihr Märtyrer Theka starb im Kampf gegen die Insektenkrieger, die gegen seine Stadt zogen, und die Sandfury sagen, seine Mörder seien verflucht worden, als Skarabäen an seinem Schrein weiterzuleben. Sie verehren die große Hydra Gahz'rilla in ihrem heiligen Teich, und sie erwecken ihre eigenen Toten, damit sie weiterarbeiten, wenn sie fallen." },
      },
    },
    ["sargeras-and-the-betrayal"] = {
      title = "Sargeras und der Verrat",
      text = {
        { "Sargeras war einst der Streiter der Titanen. Als Dämonen aus dem Wirbelnden Nether in die Welten zu schlüpfen begannen, die die Titanen geordnet hatten, wählte das Pantheon seinen größten Krieger, einen edlen Riesen aus geschmolzener Bronze, um sie zu jagen, und er tat es unzählige Zeitalter lang. Er besiegte die Eredar, Zauberer, die ganze Welten zu Dämonen machten, und die Nathrezim, die Völker gegeneinander aufbrachten, und er sperrte beide weg." },
        { "Ihre Verderbnis blieb bei ihm. Er versank in brütende Verzweiflung, dann in den Glauben, Ordnung selbst sei Torheit und Chaos die einzige Wahrheit, und schließlich in Hass auf die Titanen selbst, denen er die Schuld am Scheitern der Schöpfung gab. Seine bronzene Haut riss über einem Glutofen aus Zorn auf. Er brach die Gefängnisse, die er gebaut hatte, und ließ die Dämonen frei, und sie beugten sich vor ihm." },
        { "Aus den Eredar wählte er zwei Leutnants: Kil'jaeden den Betrüger, um die finstersten Völker zu finden und heranzuführen, und Archimonde den Entweiher, um das Heer zu führen. Er nannte dieses Heer die Brennende Legion. Wie viele Welten sie seither verbrannt hat, ist, wie das Buch in unserer Bibliothek sagt, noch unklar. Wir kennen eine, die sie nicht zu Ende bringen konnte." },
      },
    },
    ["satyrs"] = {
      title = "Die Satyrn",
      text = {
        { "Xavius half, den Hof von Königin Azshara der Brennenden Legion zu öffnen. Als er Sargeras enttäuschte, formte der Dämonenfürst ihn mit Hörnern, Hufen und Klauen neu. Der erste Satyr bot diese Verwandlung dann anderen Elfen an, die nach Macht hungerten, und der Fluch breitete sich unter seinen Anhängern aus." },
        { "Ihre Lager liegen noch in den alten Landen der Nachtelfen, in den Wäldern von Ashenvale, dem Teufelswald und Azshara. Rings um sie wird das Wasser verschmutzt, Bäume erkranken und Tiere verwachsen. Die Elfen, die versuchen, diese Wälder zu heilen, ringen mit einer Verderbnis, die zuerst unter ihrem eigenen Volk Fuß fasste." },
        { "Zehntausend Jahre sind eine lange Zeit, um einen Wald zu pflegen, $gReisender:Reisende;. Es ist eine bittere Zeitspanne, um seine alten Verräter noch immer am Werk darin zu finden." },
      },
    },
    ["scarlet-crusade"] = {
      title = "Der Scharlachrote Kreuzzug",
      text = {
        { "Als Prinz Arthas seinen Vater ermordete und Lordaeron an die Seuche fiel, sammelten die überlebenden Paladine der Silbernen Hand, was sie konnten, und schworen, die Toten aus dem Land zu brennen. Drei gründeten den Kreuzzug: Hochgeneral Abbendis, Hochinquisitor Isillien und Hochlord Mograine, der Aschenbringer, und in seinen ersten Tagen, so sagen die, die dabei waren, war er ein edler Orden. Sie wurden zum Scharlachroten Kreuzzug, und seither brennen sie: die Toten, und die Lebenden, die sie falsch ansehen." },
        { "Sie trauen niemandem. Jeder Fremde könnte die Seuche tragen, jeder Elf oder Zwerg ein Spion sein, und die Verlassenen sind schlicht der Feind. Vom Kloster in Tirisfal, von Hearthglen und Tyrs Hand aus führen sie einen Krieg, den zu gewinnen niemand sonst eingeladen ist. Ihr Oberster Kreuzzügler, Saidan Dathrohan, herrscht von Stratholme aus über sie, und ihr Großinquisitor Isillien von Hearthglen aus." },
        { "Der Kreuzzug bekämpft die Geißel, doch die Verderbnis in seinen eigenen Reihen gibt einen weiteren Grund, ihm zu misstrauen. Fragt im Kloster nach Hochlord Mograine und seiner Klinge, dem Aschenbringer, und achtet genau darauf, wer verstummt. Und fragt die Argentumdämmerung, was sie fand, als sie sich den Obersten Kreuzzügler selbst genau ansah." },
      },
    },
    ["scarlet-monastery"] = {
      title = "Das Scharlachrote Kloster",
      text = {
        { "Der Scharlachrote Kreuzzug hält ein Kloster auf einem Hügel im Norden von Tirisfal, über dem Meer. Seine Mauern umschließen eine Bibliothek, eine Waffenkammer, einen Friedhof und eine Kathedrale. Ritter, Priester und Inquisitoren üben dort für einen Krieg, der weit über die Geißel hinausreicht." },
        { "Auch die Verlassenen sind Feinde, ebenso jeder Reisende, den der Kreuzzug verdächtig findet. Hochinquisitor Whitemane und der Scharlachrote Kommandant Mograine halten die Kathedrale, während Streiter der Verlassenen gegen die Festung geschickt werden. Das Kloster hat die äußere Ausstattung eines Hauses des Lichts. Nähert Euch mit mehr Vorsicht, als diese Beschreibung nahelegen mag." },
        { side = "Horde", aside = true, sign = "P. F.", "Hinter diesen Mauern liegt eine Bibliothek, und in ihr ein Buch, mit dem sie ihre Paladine lehren, meinesgleichen zu vernichten. Ich schicke Helden, um es zu holen, und ich bitte sie, es zu lesen, bevor sie es zurückbringen." },
      },
    },
    ["scholomance"] = {
      title = "Scholomance",
      text = {
        { "Unter Caer Darrow liegt die Scholomance, die Schule des Kults der Verdammten, in der Nekromanten ausgebildet und die dunklen Künste der Geißel studiert werden. Ihr Schulleiter ist Dunkelmeister Gandling, und ihre Hallen sind voller Schüler, Lehrer und der Dinge, an denen sie üben. Ihre Tür ist für jeden ohne Schlüssel verriegelt." },
        { "Auch die Barovs sind dort, oder was von ihnen übrig ist: der Lord und seine Lady, erweckt von den Herren, an die sie ihr Zuhause verkauft haben. Sowohl die Allianz als auch die Verlassenen wollen in die Scholomance hinein, und beide haben festgestellt, dass der Weg hinein durch sehr viel schlechte Geschichte führt." },
      },
    },
    ["scourge"] = {
      title = "Die Geißel",
      text = {
        { "Die Geißel ist das Heer des Lichkönigs, einer Macht, die in Nordend auf einem Thron aus Eis sitzt und in den Geist der Toten spricht. Sie kam als Seuche nach Lordaeron, im Getreide getragen von einem Kult von Anbetern des Lichkönigs, und jeder, der davon aß und starb, erhob sich wieder, um ihm zu dienen. Der eigene Prinz des Königreichs, Arthas, vollendete das Werk und kehrte später nach Nordend zurück, wo er den Frostthron für sich beanspruchte." },
        { "Was er zurückließ, sind die Pestländer: ein Königreich der Toten, mit Ghulen auf den Feldern, aus Leichen zusammengenähten Monstrositäten und Seuchenkesseln, die die Erde vergiften. Stratholme gehört ihnen, unter Baron Rivendare, und die Scholomance, und die Gehöfte der halben Nordlande. Nun hängt eine schwarze Zitadelle am Himmel über den Östlichen Pestländern, Naxxramas, und ihr Herr ist der Lich Kel'Thuzad." },
        { "Die Toten ermüden nicht, und sie halten nicht an. Die Argentumdämmerung, der Scharlachrote Kreuzzug und die Verlassenen bekämpfen sie alle, trotz des Misstrauens zwischen ihnen. In der Kapelle des hoffnungsvollen Lichts haben die Dämmerung und der Kreuzzug vereinbart, gegen Naxxramas zusammenzuarbeiten." },
      },
    },
    ["scythe-of-elune"] = {
      title = "Die Sense von Elune",
      text = {
        { "Die Worgen des Dämmerwalds kamen nicht von Arugal, oder nicht nur von ihm. Die andere Hälfte der Geschichte beginnt in Ashenvale, bei einer Priesterin der Elune namens Velinde Starsong, die um einen Weg betete, ihre gefallenen Gefährtinnen an den Dämonen des Teufelswalds zu rächen, und einen erhielt: die Sense von Elune, ein verdrehter, knorriger Ast, der vielleicht älter ist als die Nachtelfen selbst." },
        { "Ihr Tagebuch sagt, dass es die Mauern der Welt schwächte, sie zu halten. Durch sie sah sie die Worgen einen eigenen Krieg führen, lernte, ohne Worte mit ihnen zu sprechen, und holte dreißig von ihnen in diese Welt, um an ihrer Seite zu kämpfen. Weitere folgten. Dann verschwanden Rudel, und ihre Zahl wuchs weiter, selbst als sie aufhörte, sie zu rufen, als bräuchte die Sense sie nicht mehr. Sie ging nach Osten über das Meer, sagt das Tagebuch, um einen Zauberer der Kirin Tor namens Arugal aufzusuchen, von dem es hieß, er habe dasselbe getan. Das ist der letzte Eintrag." },
        { "Die Sense tauchte in der Mine südlich von Dunkelhain auf, die die Einheimischen Rolands Verdammnis nennen. Ein Defias mit dem Spitznamen Jitters zog sie aus einem Haufen Geröll, und die Worgen strömten aus den Wänden. Auf der Flucht verlor er sie wieder, und wo sie jetzt liegt, sagen die Aufzeichnungen nicht. Ein Geschenk einer Göttin, irgendwo im Dunkel einer Mine im Dämmerwald, das vielleicht noch immer Türen öffnet. Mir wäre lieber, eine Priesterin fände sie als ein Schürfer." },
      },
    },
    ["searing-gorge"] = {
      title = "Sengende Schlucht",
      text = {
        { "Die Sengende Schlucht liegt nördlich des Blackrock, ein Becken aus Asche und Schlacke, von Klippen umschlossen. Wege aus Loch Modan und dem Ödland führen hinein. Einst war dies grünes Land, verbrannt, als Thaurissan Ragnaros herbeirief. Noch immer steigt Rauch aus dem auf, was der Feuerlord zurückließ." },
        { "Dunkeleisenzwerge bearbeiten die große Grube, die man den Kessel nennt, mit Sklaven und Golems. Feuerelementare ziehen über die Schlacke, und der Twilight-Hammer hält einen Altar in den nordwestlichen Hügeln. Über der Grube halten abtrünnige Dunkeleisenzwerge ein eigenes Lager. Von ihren Klippen aus könnt Ihr viel vom Land sehen, $gReisender:Reisende;, auch wenn wenig von der Aussicht einen behaglichen Anblick bietet." },
      },
    },
    ["senjin-village"] = {
      title = "Sen'jin",
      text = {
        { "Sen'jin ist die Heimat der Dunkelspeertrolle an der Küste von Durotar, eine Siedlung aus Hütten und Wachtürmen, die über die Meerenge zu den Echoinseln blickt. Sie ist nach Sen'jin benannt, dem alten Hexendoktor und Häuptling der Dunkelspeer, der Thrall willkommen hieß, als die Flotte der Orcs an seinen Inseln anlegte, und der in den folgenden Kämpfen von den Dienern einer Meerhexe getötet wurde." },
        { "Sein Sohn Vol'jin führt den Stamm heute. Die Trolle wollten auf den Echoinseln leben, doch einer ihrer eigenen Hexendoktoren wurde dort wahnsinnig, und seither drängen sich die Dunkelspeer auf diesem Küstenstreifen und blicken übers Wasser auf die Heimat, die sie verloren haben." },
      },
    },
    ["sentinel-hill"] = {
      title = "Späherkuppe",
      text = {
        { "Die Späherkuppe ist ein steinerner Wachturm auf einer Anhöhe mitten in Westfall, und sie ist der letzte Ort in der Provinz, an dem das Gesetz noch etwas bedeutet. Die Volksmiliz hält sie: eine Handvoll Soldaten und sehr viele ehemalige Bauern unter dem Paladin Gryan Stoutmantle, die lieber für ihr Land kämpfen, als ihm den Rücken zu kehren." },
        { "Viel gibt es hier nicht: den Turm, ein paar Zelte, einen Stall und ein Gasthaus, und einen guten Blick darauf, wie schlimm die Dinge geworden sind. Doch jeder Reisende, der Westfall helfen will, kommt zuerst hierher, und die Miliz hat mehr Arbeit als Hände." },
      },
    },
    ["sentinels"] = {
      title = "Die Schildwachen",
      text = {
        { "Als die Druiden im Smaragdgrünen Traum schlafen gingen, musste jemand die Wälder hüten. Tyrande Whisperwind, Hohepriesterin von Elune, sammelte ihre Schwestern zu einem Heer von Kriegerinnen und nannte sie die Schildwachen. Sie bat Malfurion, sie nicht für den Traum zu verlassen. Er ging trotzdem, und sie hielt Wache." },
        { "Sie hielten sie zehntausend Jahre lang, bestreiften Ashenvale bei Nacht, während die Druiden schliefen, mit den Söhnen des Cenarius, den Hütern des Hains, und seinen scheuen Töchtern, den Dryaden, die sie in der Not rufen konnten. Tyrande hörte nie auf zu fürchten, dass die Legion zurückkommen würde. Am Ende behielt sie recht." },
        { "Die Druiden sind nun wach, und die Schildwachen sind nicht abgezogen. Ihr findet sie an jedem Posten der Nachtelfen von Teldrassil bis Feathermoon, unter ihrer Generalin Shandris Feathermoon. Wenn eine von ihnen Euch ansieht, als hielte sie schon sehr lange Wache, $gReisender:Reisende;, dann tut sie das vielleicht wirklich." },
      },
    },
    ["shadow-council"] = {
      title = "Der Schattenrat",
      text = {
        { "Die alte Horde wurde nie ganz von ihren Kriegshäuptlingen regiert. Hinter ihnen stand der Schattenrat, ein geheimer Kreis, den der Dämon Kil'jaeden Gul'dan auf Draenor gründen half, um die Klans zu lenken und die Magie der Hexenmeister unter ihnen zu verbreiten. Es war der Rat, der Mannoroth herbeirief, damit die Häuptlinge von ihm tranken, der Rat, der Blackhand als Kriegshäuptling einsetzte, damit er tat, was man ihm sagte, und der Rat, der mit Medivh das Dunkle Portal öffnete." },
        { "Schicksalshammer brach seinen Griff, als er Blackhand tötete und die Horde für sich nahm, und Gul'dan starb, zerrissen von den Dämonen, die er am Grabmal des Sargeras entfesselte. Der Name überlebte sie beide. Hexenmeister versammeln sich noch immer unter ihm, Orcs und Verlassene darunter, und verhandeln noch immer mit der Legion." },
        { "Ihre größte Feste ist heute Jaedenar im Teufelswald, wo Schattenlord Fel'dan seine Pakte in der Schattenfeste darunter schließt. Während die Druiden sich mühen, den Wald zu reinigen, versammeln sich die Hexenmeister des Rates noch immer unter seinen Wurzeln." },
      },
    },
    ["shadowfang-keep"] = {
      title = "Burg Shadowfang",
      text = {
        { "Bevor Arugal kam, gehörte die Festung über Pyrewood Baron Silverlaine. Die Worgen des Magiers überrannten sie, und der Geist des Barons spukt noch immer in ihren Hallen. Kommandant Springvale, ein Paladin, gehört zu ihren anderen untoten Verteidigern." },
        { "Arugal zog sich mit den Worgen, die er seine Kinder nennt, hierher zurück. Die Festung heißt nun Burg Shadowfang, ein Bollwerk, das die Verlassenen an ihrer Südgrenze haben wollen. Ihre Todespirscher gingen hinein, um sie auszukundschaften, und sind nicht zurückgekehrt." },
      },
    },
    ["shadowglen"] = {
      title = "Shadowglen",
      text = {
        { "Shadowglen versammelt die jungen Rekruten der Nachtelfen um Aldrassil, einen großen Baum, in dessen Ästen ihre Lehrer wohnen. Druiden, Priesterinnen und Schildwachen pflegen diese Senke im Wald Teldrassils. Ihr Bewahrer lehrt, dass das Gleichgewicht der Natur bei kleinen Dingen beginnt." },
        { "Die Rekruten haben fast sofort Arbeit vor sich. Spinnen sind groß geworden, und die Feen und Grells sind bösartig geworden. Ein Reisender, der hier beginnt, lernt die Sorge der Hüter um den Wald kennen, indem er hilft, was darin falsch gelaufen ist." },
      },
    },
    ["shadowprey-village"] = {
      title = "Shadowprey",
      text = {
        { "Shadowprey ist das Lager der Horde an der Westküste von Desolace, ein Dorf der Trolle und Tauren aus Pfahlhütten am Meer, der letzte Halt vor der langen Straße nach Süden nach Feralas. Seine Leute jagen im toten Land und behalten die Zentauren und die Dämonen gleichermaßen im Auge." },
        { "Eine Taurin aus Shadowprey hat es auf sich genommen, die Dämonenportale der Burning Blade zu schließen, und ein Druide des Zirkels des Cenarius lagert in der Nähe und wartet auf jemanden, der stark genug ist, nach Maraudon hineinzugehen. Es ist ein kleines Dorf mit großen Problemen." },
      },
    },
    ["shadra"] = {
      title = "Shadra",
      text = {
        { "Shadra ist eine Spinnengöttin der Trolle, ein Loa des Gifts und der Netze, und die Witherbark verehren sie am Altar von Shadra'Alor im Hinterland. Sie ist kein Götzenbild. Sprecht die richtigen Worte an ihrem Altar, und sie kommt, so groß wie ein Haus." },
        { "Die Witherbark bewahren in ihren Dörfern Flaschen mit ihrem Gift auf, und die Apotheker der Verlassenen in Tarrens Mühle wollen es sehr dringend, was Euch verrät, was sie damit vorhaben. Mir wäre lieber, Shadra behielte ihr Gift." },
      },
    },
    ["shady-rest-inn"] = {
      title = "Das Gasthaus Zur süßen Ruh",
      text = {
        { "An der Straße zwischen dem Brachland und Theramore stand einst ein Gasthaus, Zur süßen Ruh, wo Reisende beider Fraktionen auf einen Trunk und ohne Fragen einkehrten. Es brannte nieder. Sein Gerippe steht noch an der Straße, und darum herum haben die Ermittler beider Seiten Dinge gefunden, die nicht zusammenpassen." },
        { "Es gibt Hufspuren im Schlamm, die fortführen. Es gibt einen schwarzen Eisenschild, der am Schornstein befestigt ist. Und es gibt ein Abzeichen in der Asche, den goldenen Anker von Theramore, mit dem Namen eines Leutnants, eines Marinesoldaten aus Kul Tiras, der mit Lady Proudmoore über das Meer kam, als vermisst gilt und sich offenbar einer Bande von Deserteuren in der Marsch angeschlossen hat. Wer das Gasthaus Zur süßen Ruh niederbrannte und warum, weiß ich nicht. Ich vermute, jemand wollte, dass die Allianz und die Horde einander die Schuld daran geben." },
      },
    },
    ["shamans"] = {
      title = "Schamanen",
      text = {
        { "Auf Draenor sprachen die Schamanen der Orcs mit den Elementen und ihren Ahnen, bis Gul'dans Hexenmeister viele von ihnen zur Teufelsmagie brachten und die Geister verstummten. Unter den Frostwolf in Alterac hielt der alte Schamane Drek'Thar die alten Wege lebendig und lehrte sie einen jungen entflohenen Sklaven namens Thrall." },
        { "Thrall brachte den Schamanismus zu seinem Volk zurück, und in Kalimdor fanden sie andere, die ihn nie verloren hatten: die Tauren, die die Erdenmutter ehren, und die Trolle, deren Hexendoktoren ihre eigenen Wege bewahrt hatten. Ein Schamane bittet Erde, Feuer, Wasser und Luft um Hilfe und trägt von jedem ein Totem, und die Elemente antworten, meistens." },
        { client = "forever", "In letzter Zeit hat man auch Zwerge den Stein und den Sturm anrufen sehen, und die Windformer der Himmelsgeborenen sind herabgekommen, um unter den Schamanen der Horde nach ihren verlorenen Windgeistern zu suchen." },
        { "Die Liga hat gelernt, vor einer Grabung einen Schamanen um Erlaubnis zu fragen, $gReisender:Reisende;. Der Boden hat Meinungen, und sie hören sie." },
      },
    },
    ["shandris-feathermoon"] = {
      title = "Shandris Feathermoon",
      text = {
        { "Generalin Shandris Feathermoon befehligt die Schildwachen von der Festung aus, die ihren Namen trägt. Ihr Dienst an Tyrandes Seite begann im Krieg der Urtume, als sie ein Kind auf der Flucht aus Ara-Hinam war, von ihrer Familie getrennt und für eine Waise gehalten. Tyrande nahm sie in ihre Obhut." },
        { "Shandris folgte ihr in die Gefahr, obwohl man ihr befohlen hatte zurückzubleiben. Einer ihrer Pfeile traf Xavius. Malfurion benutzte das Holz des steckengebliebenen Schafts, um den Satyr zu bezwingen. Das Kind hatte einen Anteil am Krieg, bevor irgendwer ihr freiwillig einen gegeben hätte." },
        { "Sie hat seit der Großen Teilung und durch die Zeitalter seither an Tyrandes Seite gestanden. Heute liegt ihr Kommando weit von Darnassus entfernt, in Feralas." },
      },
    },
    ["shendralar"] = {
      title = "Die Shen'dralar",
      text = {
        { "Die Shen'dralar sind seit der Zeit vor der Großen Teilung in Eldre'Thalas geblieben. Vom Brunnen der Ewigkeit abgeschnitten, banden sie den Dämon Immol'thar mit fünf Pylonen unter ihrer Stadt. Seit Tausenden von Jahren zapfen sie seine Macht an, um sich selbst zu erhalten." },
        { "Prinz Tortheldrin herrscht noch immer, umgeben von Hallen, in denen die Geister seines Volkes spuken. Manche Shen'dralar haben die Freiheit der Unsterblichkeit vorgezogen. Die Uralte Shen'dralar bittet um Tortheldrins Tod und um Frieden für die Geister, während die Hüter des Athenaeums Hilfe mit ihrem Wissen belohnen. Hier gibt es eine bemerkenswerte Bibliothek, doch die Geschichte, wie ihr Volk überlebte, verdient ebenso viel Aufmerksamkeit." },
      },
    },
    ["shimmering-flats"] = {
      title = "Die schimmernde Ebene",
      text = {
        { "Die schimmernde Ebene ist eine weite Salzpfanne im Osten von Tausend Nadeln, weiß genug, um einem Reisenden die Augen zu blenden. Goblins und Gnome haben die Illusionenrennbahn quer darüber gebaut. Ihre Raketenwagen drehen ihre Runden vor Zuschauern und Buchmachern, mit häufigen Unterbrechungen für Unfälle." },
        { "Die Trümmer versorgen Kravel Koalbeard mit Teilen, die er den Teams zurückverkauft. Die Brüder Brassbolt brauchen Helme für ihre Piloten. Ein Rennen bringt Sieger, Verlierer und eine nützliche Menge Schrott hervor. Die Leute, die neben der Strecke arbeiten, haben in allen dreien eine Beschäftigung gefunden." },
      },
    },
    ["shrine-of-akir"] = {
      title = "Der Schrein von Akir",
      text = {
        { "Der Schrein von Akir im Shen'darhochland ist die heilige Stätte der Al'Aketh und war der Sitz ihrer Anführerin, der Hohepriesterin Lorthuna. Um ihn einzunehmen, brauchte es den Hohen Orden, die Windformer und die Friedenswächter gemeinsam, was etwas über die Stärke des Kults verrät und noch mehr darüber, wie selten sich diese drei einig sind. Valennia Stormfist, die Hauptfrau der Friedenswächter, wurde im inneren Heiligtum schwer verwundet, und Lorthuna floh durch ein Portal zu den Türmen der Rohashi darüber." },
        { "Was auf den Türmen geschah, haben die Shen'dorei für uns nicht aufgeschrieben. Lorthuna ist von Zephras verschwunden, und der Kult hat seinen Kopf verloren. Doch die Schutzzauber, die die Insel vor Al'Akir verbargen, fielen mit ihr, und der Hohe Älteste will nicht so tun, als wüsste er, wie lange der Windlord brauchen wird, um es zu bemerken." },
      },
    },
    ["si-7"] = {
      title = "SI:7",
      text = {
        { "Von der Kaserne in der Altstadt aus leitet Mathias Shaw den Nachrichtendienst Stormwinds. SI:7 verfolgt die Geschäfte, die selten auf einem öffentlichen Aushang landen: die Defias, die Geheimnisse der Adligen und die Orte, an denen beide sich treffen." },
        { "Eine Beschreibung von Bazil Thredds Besucher führte Shaw zu einem Meuchler, der sich Marzon nannte und in den Diensten von Lord Gregor Lescovar stand. Die folgende Ermittlung endete mit beiden Männern tot in den Schlossgärten, außerhalb der bequemen Reichweite gewöhnlicher Gerechtigkeit." },
        { "Die Kaserne gibt dem Dienst ein unauffälliges Zuhause. Seine Arbeit führt in Räume, in denen sich die Feinde der Stadt sehr achtbar kleiden können." },
      },
    },
    ["sickness-of-teldrassil"] = {
      title = "Die Krankheit Teldrassils",
      text = {
        { "Teldrassil fehlen die Segnungen, die Alexstrasza und Nozdormu einst Nordrassil gaben. Die Druiden von Dolanaar sprechen offen darüber und über die Sorgen des neuen Baumes: Seltsame Tiere erheben sich aus seinem Boden, und einst freundliche Geschöpfe sind gewalttätig geworden." },
        { "Teufelsmoos ergriff Ursal den Raufer und breitete sich in seinem Stamm der Knarzklauen aus. Schwarzmoos der Stinker, ein Bäumling, ist so überwuchert, dass sein abgetrenntes Herz unter dem dunklen Bewuchs noch schlägt. Ein Satyrfürst besetzt den Teufelsfels. In Ban'ethil, wo Druiden der Kralle unter ihrem Pakt mit Ysera im Smaragdgrünen Traum schlafen, ist der Wächter verstummt." },
        { "Fandral erkennt die Probleme an und hat Heilmittel anzubieten. Andere Druiden setzen ihre Nachforschungen fort. Bringt ihnen, was Ihr findet, $gReisender:Reisende;. Ein Baum, groß genug, um einem Volk Obdach zu geben, ist auch recht groß, um von seinen Hütern untersucht zu werden." },
      },
    },
    ["silithid"] = {
      title = "Die Silithiden",
      text = {
        { "Silithiden bewohnen riesige Stöcke unter dem Süden Kalimdors. Ihre Wespen können so groß wie Hunde sein, ihre Krieger so groß wie Oger und ihre Tunnelgräber stark genug, Höhlen zum Einsturz zu bringen. Stöcke sind im Brachland, in Tausend Nadeln, in Feralas, Tanaris und Un'Goro aufgetaucht. Silithus birgt die größte Ansammlung." },
        { "Die Qiraji von Ahn'Qiraj befehligen sie. Vor tausend Jahren drängten ihre Schwärme im Krieg der Sandstürme nach Norden, bis Nachtelfen und Drachen die Stadt hinter dem Skarabäuswall versiegelten. Der Zirkel des Cenarius glaubt, dass eine ältere Macht unter Ahn'Qiraj Herren und Diener gleichermaßen lenkt." },
        { "Bewegungen um die Stöcke deuten heute auf Vorbereitungen für eine große Ausbreitung hin. Der Zirkel beobachtet genau. Für einen Reisenden, der diese Insekten erforscht, gehört zur Arbeit herauszufinden, wie weit ihre Tunnel und die Absichten ihrer Herren schon reichen." },
      },
    },
    ["silithus"] = {
      title = "Silithus",
      text = {
        { "Silithus ist eine Wüste aus gelbem Sand und großen Stöcken der Silithiden im Südwesten Kalimdors. Hinter dem Skarabäuswall liegt Ahn'Qiraj, die Stadt der Qiraji, der Herren der Insekten. Etwas noch Älteres liegt unter ihrer Herrschaft." },
        { "Der Zirkel des Cenarius wacht von seiner Burg aus, während sich Kultisten des Twilight-Hammers in Lagern in der Wüste versammeln. Streitkräfte der Allianz und der Horde wurden gemeinsam aufgestellt, um gegen den Wall zu marschieren." },
      },
    },
    ["silverpine-forest"] = {
      title = "Silberwald",
      text = {
        { "Der Silberwald ist ein Wald aus hohen grauen Kiefern an der Küste südlich von Tirisfal, der sich bis zu der großen Mauer hinabzieht, die Gilneas von der Welt abschließt. Er war ein stilles Land aus Höfen und Fischerdörfern, Teil des Reiches Lordaeron. Die Seuche kam hindurch, dann die Toten, dann Schlimmeres." },
        { "Heute ist er ein Grenzland. Die Verlassenen halten den Norden vom Grabmal aus, die Worgen, die ein wahnsinniger Magier erschuf, jagen in den Wäldern, verseuchte Gnolle graben in den toten Feldern, und die Magier von Dalaran halten ein Dorf im Osten. Jeder im Silberwald wartet auf etwas, und keiner auf etwas Gutes." },
      },
    },
    ["skyborne"] = {
      title = "Die Himmelsgeborenen",
      text = {
        { "Die Himmelsgeborenen nennen sich die Shen'dorei, das verborgene Volk, und bis sie vom Himmel herabkamen, wusste die Liga nicht, dass es sie gibt. Ihre Ahnen lebten in Eldre'Thalas, der Stadt, die die Oger heute Düsterbruch nennen, und erhoben sich gegen einen Prinzen, der einen Dämon binden wollte, um ihre Magie zu nähren. Unter dem maskierten Shal'nan flohen sie übers Meer, und Windgeister hoben ihre Insel aus der Welt hinaus in den Himmelswall." },
        { "Die Insel Zephras schwebte dort Zeitalter lang. Nun sind die Windgeister fort, die Insel versagt, und die Himmelsgeborenen sind herabgekommen, um Hilfe zu suchen. Der Hohe Orden sucht das arkane Wissen, das ihr Volk verlor, und geht zu den Magiern Dalarans. Die Windformer suchen ihre verschwundenen Geister und gehen zu den Schamanen der Horde." },
        { "Sie sind wenige, $gReisender:Reisende;, und sie wissen es. Ein Himmelsgeborener, der mit jedem Leben vorsichtig scheint, das eigene eingeschlossen, rechnet damit, wie viele von seinem Volk noch zu verlieren sind." },
      },
    },
    ["sons-of-lothar"] = {
      title = "Die Söhne Lothars",
      text = {
        { "Fünf Statuen stehen am Tor von Stormwind, und jede Tafel endet gleich: vermutlich verstorben. Es sind die Befehlshaber der Expedition der Allianz, die nach dem Zweiten Krieg durch das Dunkle Portal in die eigene Welt der Orcs marschierten, als Ner'zhul und die letzten der Klans durch es zurückkamen." },
        { "Khadgar, einst Medivhs Lehrling, führte sie, mit General Turalyon an seiner Seite. Die elfische Waldläuferin Alleria Windrunner kundschaftete für sie, Kurdran Wildhammer führte die Greifenreiter, und Danath Trollbane von Stromgarde beriet sie. Sie konnten Ner'zhul nicht davon abhalten, seine Portale zu anderen Welten zu öffnen, und als Draenor sich selbst zerriss, entschieden sie sich, das Dunkle Portal von der anderen Seite zu zerstören, damit Azeroth nicht mit hinabgerissen würde. Es gelang ihnen. Ob einer von ihnen entkam, bleibt, wie das Buch in unserer Bibliothek sagt, abzuwarten." },
        { "Lest die Tafeln selbst. Jede wurde von jemandem geschrieben, der den Helden kannte: Falstad für Kurdran, Uther für Turalyon, Thoras Trollbane für seinen Neffen, Antonidas für Khadgar, dem er alles Gute wünscht, wo immer er sei. Allerias Tafel schrieb ihre Schwester Sylvanas, Waldläufergeneralin von Quel'Thalas, bevor sie zu dem wurde, was sie heute ist." },
      },
    },
    ["southsea-freebooters"] = {
      title = "Die Südmeerfreibeuter",
      text = {
        { "Die Südmeerfreibeuter sind Piraten der warmen Meere Kalimdors, und sie machen vor allem Jagd auf die Goblins, weil die Goblins am meisten haben, was sich zu stehlen lohnt. Sie halten Lager entlang der Händlerküste des Brachlands, südlich von Ratchet, und in den Buchten von Tanaris, und ihre Schiffe lauern allem auf, was einen Hafen von Steamwheedle verlässt." },
        { "Ihr Kapitän an der Händlerküste ist Baron Küstenschipper, und Gazlowe von Ratchet hat einen Preis auf seinen Kopf ausgesetzt. Die Goblins von Gadgetzan zahlen ebenso gut für die Piraten von Tanaris. Hinter ihnen steht keine große Geschichte, kein verbannter König und keine verlorene Sache. Sie sind Diebe, die Boote besitzen, und das Meer ist weit." },
      },
    },
    ["southshore"] = {
      title = "Southshore",
      text = {
        { "Southshore ist ein Fischerort mit Hafen an der Küste von Hillsbrad, mit einem Gasthaus, einem Rathaus und einer Garnison, die gegen die Verlassenen von Tarrens Mühle kämpft. Es bleibt ein Bollwerk der Lebenden in einem Land, in dem dieser Unterschied zählt." },
        { "Kundric Zanden hütet seine Geschichte, und die Gelehrten Stormwinds schicken Forscher durch den Ort zu den zerstörten Bibliotheken von Alterac. Ich freue mich, an einem solchen Ort geführte Aufzeichnungen zu finden. Ein Reisender kann sich hier mit Vorräten versorgen, kann aber auch etwas über das Land erfahren, durch das ihn diese Vorräte tragen müssen." },
        { side = "Horde", aside = true, sign = "P. F.", "Kundric Zanden hütet die Geschichte von Southshore, und ich hüte, was von der Lordaerons übrig ist. Über das letzte Kapitel wären wir uns wohl nicht einig." },
      },
    },
    ["splintertree-post"] = {
      title = "Splintertreeposten",
      text = {
        { "Der Splintertreeposten ist das Fort der Horde am Ostrand von Ashenvale, eine Palisade aus rohem Holz, in der die Holzfäller und Reiter der Warsong ihr Lager haben. Die Schildwachen greifen es unablässig an, und die Orcs zahlen es ihnen in gleicher Münze heim." },
        { "Die Orcs sagen, sie brauchten das Holz: Durotar ist ein Land aus rotem Fels, und ein Volk muss bauen. Die Nachtelfen sagen, jeder Baum in diesem Wald sei älter als die Horde. Beide haben recht, und das macht es so schwer." },
      },
    },
    ["stalvan-mistmantle"] = {
      title = "Stalvan Mistmantle",
      text = {
        { "Stalvan Mistmantle war Lehrer in Moonbrook und Hauslehrer bei Familien auf dem Land. Er bildete sich ein, seine Schülerin Tilloa erwidere seine Zuneigung. Als sie einen Verehrer vorstellte und ihren Lehrer einen gütigen alten Onkel nannte, schlug sein eigener Bericht in Wut um. Die Morde folgten." },
        { "Briefe und Tagebücher verfolgen seinen Weg durch Westfall und Stormwind bis zum Anwesen nordöstlich von Dunkelhain, wo die Dunkelheit des Dämmerwalds ihn weiter verändert hat. Madame Evas Vorahnung beginnt die Suche, doch Stalvans eigene Worte tragen sie zu einem großen Teil weiter." },
        { "Es ist eine hässliche Geschichte, die man aus so gewöhnlichen Papieren zusammensetzen muss. Eine Lehrstelle, der Briefwechsel einer Familie, der Name einer Schülerin: die Dinge, die zu einem stillen Leben hätten gehören sollen, bleiben zwischen den Spuren derer, die er zerstörte." },
      },
    },
    ["starfall-village"] = {
      title = "Starfall",
      text = {
        { "Starfall ist eine kleine Siedlung der Nachtelfen im Schnee von Winterspring, wo Druiden und Gelehrte zwischen den Bäumen leben. Seine Leute erforschen das Land und seine Geschöpfe und die alten Ruinen am See." },
        { "Es war ein Gelehrter aus Starfall, der herausfand, was die Wildekin von Winterspring sind: keine Tiere, sondern Geschöpfe der Elune, der Mondgöttin. Der Erzdruide in Darnassus war sehr interessiert. Ich ebenso." },
      },
    },
    ["steamwheedle-cartel"] = {
      title = "Das Steamwheedle-Kartell",
      text = {
        { "Das Steamwheedle-Kartell handelt mit Allianz und Horde. Seine Goblins haben festgestellt, dass Leute, die bereit sind, einander zu bekämpfen, trotzdem Vorräte brauchen und dass beide Sorten Münzen es wert sind, genommen zu werden. Ihre Städte bieten einen Ort, an dem man die Geschäfte abwickelt." },
        { "Booty Bay, Gadgetzan, Ratchet und Everlook reichen über Dschungel, Wüste, Küste und Schnee. Schläger erzwingen den Frieden in ihnen. Revilgaz beaufsichtigt Booty Bay, während Gazlowe in Ratchet Arbeit für Besucher hat. Jeder Hafen hat Sorgen, die der Handel allein nicht regelt." },
        { "Ein Reisender kann Vorräte kaufen, Arbeit finden und der anderen Fraktion begegnen, ohne sofort zur Waffe zu greifen. Das Kartell lässt sich für vieles bezahlen, was es anbietet, doch ein neutraler Rastplatz hat seinen Wert in einer Welt, deren Straßen durch so viele Kriege führen." },
      },
    },
    ["stonard"] = {
      title = "Stonard",
      text = {
        { "Stonard ist die Festung der Horde in den Sümpfen des Elends, eine gedrungene Steinburg und ein Haufen Hütten auf einer Anhöhe über dem Morast, gehalten von Orcs, die die Verwüsteten Lande im Süden und die Straßen der Allianz im Norden im Auge behalten." },
        { "Es ist grimmig, feucht und treu, und seine Leute schicken ihre Krieger in den Tempel des Sumpfes und die Dämonenlande dahinter, ohne sich viele Illusionen darüber zu machen, wie viele zurückkommen werden. Vor seinen Mauern wartet ein Geist auf Befehle, die nie kamen." },
      },
    },
    ["stonefields-and-maclures"] = {
      title = "Die Stonefields und die Maclures",
      text = {
        { "Die Stonefields und die Maclures bewirtschaften ihre Höfe zu beiden Seiten der Tiefenschachtmine, südlich von Goldhain, und die beiden Familien liegen schon länger im Streit, als sich irgendwer zu erklären die Mühe macht. Natürlich ist Maybell Maclure in Tommy Joe Stonefield verliebt. Er wartet am Fluss westlich des Hofs seiner Familie auf ihre Briefe. Sie wartet auf eine Gelegenheit, sich davonzustehlen." },
        { "Die Großmutter der Stonefields steht auf der Seite der jungen Leute. Sie schickt eine Nachricht an ihren alten Freund William Pestle in Goldhain, der einen Unsichtbarkeitstrank brauen kann, wenn ihm jemand Kristalltang von den Murlocs am Kristallsee bringt. Damit kann Maybell ungesehen aus den Weinbergen ihrer Familie spazieren. Sie fühle sich schuldig, sie zu täuschen, sagt sie, aber nicht schuldig genug, um zu bleiben." },
        { "Der Streit geht um sie herum weiter: eine Tante der Stonefields, die den jungen Billy Maclure beschuldigt, ihre Halskette gestohlen zu haben, Mutter Stonefield, die der preisgekrönten Sau der Brackwells den Tod schwört, weil sie ihr Gemüse gefressen hat. Elwynn hat die Defias, die Kobolde und die Gnolle kommen und gehen sehen. Der Streit hat sie bisher alle überdauert." },
      },
    },
    ["stonetalon-mountains"] = {
      title = "Steinkrallengebirge",
      text = {
        { "Das Steinkrallengebirge erhebt sich zwischen Ashenvale und dem Brachland: hohe graue Gipfel, tiefe Täler und alte Wälder, die angestammte Heimat der Harpyien, mit dem heiligen Gipfel der Druiden in seinem Herzen. Die Geister dieser Berge sind zornig, sagen die Schamanen der Horde, und sie haben Grund dazu." },
        { "Die Goblins der Venture Co. sind gekommen, um zu fällen, zu brennen und zu graben, und ganze Täler sind mit ihnen verschwunden. Das verbrannte Tal im Süden wurde von ihren Maschinen bis auf den Grund niedergebrannt. Die Harpyien der Blutfurien halten die hohen Orte, die Grimmtotem überfallen Dörfer der Tauren, und mittendrin versuchen die Druiden auf dem Gipfel und die Schamanen von Sonnenfels zu heilen, was sie können." },
      },
    },
    ["stonetalon-peak"] = {
      title = "Der Steinkrallengipfel",
      text = {
        { "Der Steinkrallengipfel ist der höchste Gipfel des Gebirges und eine heilige Stätte der Druiden der Nachtelfen, die ihn mit den Waldgeistern hüten, die sie die Söhne und Töchter des Cenarius nennen. Auf ihm steht der Krallenbau, wo die Druiden Dinge der Macht hinter Schlössern eigener Erfindung aufbewahren und wo mindestens einer von ihnen, Bruder Ravenoak, in Gestalt eines Bären schläft und sie in seinen Träumen bewacht." },
        { "Die Hüter des Gipfels betrachten die Berge darunter mit Kummer: das verbrannte Tal, die gefällten Wälder, die Harpyien, die sie nicht durchlassen, um neu zu pflanzen. Sie sind geduldig, wie Druiden es sind, und sie verlieren." },
      },
    },
    ["stonewatch-keep"] = {
      title = "Burg Steinwacht",
      text = {
        { "Burg Steinwacht bewachte den nördlichen Zugang zum Rotkammgebirge. Die Blackrock kamen diesen Zugang herab und nahmen sie ein. Ihre Plünderer überfallen nun die Höfe oberhalb von Seenhain, und ihre Hinterhalte lauern an der Straße zwischen der Stadt und der Burg. Eine Befestigung nützt dem, der ihre Mauern hält." },
        { "Ein Regiment der Soldaten Stormwinds wurde zwischen den zerfallenen Türmen zerschlagen. Ein paar Überlebende sollen in den Höhlen festgehalten werden. Kriegsherr Gath'Ilzogg besetzt die Burg selbst, mit einem Preis auf seinem Kopf, den Magistrat Solomon ausgesetzt hat. Seht Euch den Boden genau an, $gReisender:Reisende;. Seenhain hat schon Männer bei dem Versuch verloren, ihn zurückzugewinnen." },
      },
    },
    ["stonewrought-dam"] = {
      title = "Der Stonewroughtdamm",
      text = {
        { "Der Stonewroughtdamm hält das Nordende des Sees. Seine Mauer und sein Wasserfall gehören zu den großen Sehenswürdigkeiten von Khaz Modan. Nehmt Euch Zeit, sie zu bewundern, $gReisender:Reisende;. Es hat sehr viel Arbeit gekostet, Euch diesen Anblick zu verschaffen." },
        { "Chefingenieur Hinderweir ist einem Anschlag der Dunkeleisenzwerge auf den Damm auf die Spur gekommen. Seine Ermittlung führt zu einem Sprengfass und zu der Mischung, die nötig ist, um es zu entschärfen. Die Zwerge bewachen dieses Werk genau, und aus gutem Grund. Menschen hängen davon ab, dass die Mauer hält, und für Hinderweir steht weit mehr auf dem Spiel als der Stolz eines Ingenieurs." },
      },
    },
    ["stormpike-guard"] = {
      title = "Die Stormpikegarde",
      text = {
        { "Die Stormpikegarde kam ins Alteractal, um zu schürfen und nach Relikten zwergischer Abstammung zu suchen, und die Forscherliga begleitete die Expedition. Sie sagen, die Frostwolf hätten ohne Anlass angegriffen. Die Frostwolf erzählen dasselbe mit vertauschten Namen." },
        { "Vanndar Stormpike befehligt die Garde, und König Magni hat ihm befohlen, das Tal für Ironforge einzunehmen. Die Frostwolf leben bereits dort und widersetzen sich dem Befehl. Ich diene dem König, der diesen Befehl gab, doch das Interesse der Liga an dem, was unter der Erde liegt, entscheidet nicht über die Ansprüche derer, die darüber leben." },
      },
    },
    ["stormrage-barrow-dens"] = {
      title = "Die Stormrage Grabhügel",
      text = {
        { "Druiden schlafen unter den Hügeln von Moonglade, während ihre Geister durch den Smaragdgrünen Traum wandeln, manchmal jahrelang. Diese Grabhügel tragen den Namen Malfurion Stormrages und erinnern an den ersten Druiden und die lange Übung seiner Anhänger." },
        { "Während des Dritten Krieges rief Tyrande schlafende Druiden zurück, um sich der Legion zu stellen. Malfurion wird nun vermisst, sein Schicksal ist den Druiden unbekannt. Da sich der Nachtmahr ausbreitet, haben die Hüter der Hügel und Remulos Grund, um jene zu fürchten, die im Traum sind. Tretet hier behutsam auf, $gReisender:Reisende;. Die Stille über den schlafenden Druiden verrät wenig über das, dem ihre Geister vielleicht gegenüberstehen." },
      },
    },
    ["stormwind-city"] = {
      title = "Stormwind",
      text = {
        { "Stormwind ist die größte Stadt der Menschen, und es ist das zweite Stormwind, das an diesem Ort steht. Das erste wurde im Ersten Krieg von der Horde geplündert und bis auf die Grundmauern niedergebrannt. König Llane wurde ermordet, und sein Volk floh mit dem Helden Anduin Lothar nach Norden, nach Lordaeron. Als der Zweite Krieg gewonnen war, kehrten sie heim und bauten es wieder auf." },
        { "Die Steinmetze der Steinmetzgilde errichteten es aus weißem Stein, schöner als zuvor: die Kathedrale des Lichts, die Kanäle und die Burg über allem. Das Adelshaus weigerte sich dann, sie zu bezahlen, und der Groll der Steinmetze ist seither zur Bruderschaft der Defias geworden, sodass man sich ausgerechnet an die schönste Stadt der Allianz am bittersten erinnert." },
        { client = "classic", "Es ist eine Stadt des Handels und der Soldaten, der Priester und der Spione, und eines Hofes, der flüstert. Der Junge auf dem Thron ist ihr König. Die Männer und Frauen um ihn herum regieren sie." },
        { client = "forever", "Es ist eine Stadt des Handels und der Soldaten, mit Schiffen in ihrem Hafen, der Priester und der Spione, und eines Hofes, der flüstert. Der Junge auf dem Thron ist ihr König. Die Männer und Frauen um ihn herum regieren sie." },
      },
    },
    ["stranglethorn-vale"] = {
      title = "Schlingendorntal",
      text = {
        { "Das Schlingendorntal ist ein Dschungel, der größte in den Östlichen Königreichen: Hitze, Regen, Ranken, Panther, Raptoren und Gorillas, vom Grün verschluckte Ruinen und eine lange Küste aus Stränden und Buchten. Es war das Herz der Gurubashi, des Trollreichs, das den Süden beherrschte, lange bevor es Königreiche der Menschen gab, und die Ruinen ihrer Tempel stehen überall." },
        { "Jeder kommt wegen irgendetwas hierher. Jäger kommen wegen Trophäen, Goblins wegen Gold und Holz, Piraten wegen Beute, und Soldaten der Allianz und der Horde, um gegen die Trolle, die Oger und einander zu kämpfen. Der Dschungel verschlingt die meisten von ihnen, früher oder später." },
      },
    },
    ["stratholme"] = {
      title = "Stratholme",
      text = {
        { "Stratholme war die zweite Stadt Lordaerons, sein Juwel im Norden. Als die Seuche in Getreidewagen dorthin kam, traf Prinz Arthas mit Uther und Jaina ein und fand die ganze Stadt krank und im Begriff, sich zu verwandeln. Er befahl, sie zu säubern. Uther weigerte sich, und Jaina verließ ihn. Arthas ließ Stratholme Haus um Haus über die Klinge springen, bevor die Toten sich erheben konnten, und der Schreckenslord Mal'Ganis erwartete ihn am Ende. Die Säuberung nennt man es heute, und es war der Anfang von Arthas' Fall." },
        { "Die Stadt hat seither schlimmeren Verrat gesehen. Ein Magier aus Stromgarde namens Ras Frostraunen gab sein Leben auf ihrem blutgetränkten Boden freiwillig der Geißel hin und erhob sich als Lich der Scholomance. Und hier wurde Hochlord Mograine, der Aschenbringer, von seinem eigenen Sohn in einen Hinterhalt gelockt und mit seiner eigenen Klinge getötet." },
        { "Die Stadt brennt noch immer. Die Geißel hält die eine Hälfte, unter Baron Rivendare, und der Scharlachrote Kreuzzug die andere, von seiner Bastion aus, unter dem Obersten Kreuzzügler. Die Toten, die nicht gesäubert wurden, wandern noch durch ihre Straßen, und manche von ihnen, die Geister, wären sehr gern frei." },
        { side = "Horde", aside = true, sign = "P. F.", "Es gibt noch immer welche, die sagen, der Prinz habe in Stratholme recht gehabt. Ich gehöre nicht zu ihnen." },
      },
    },
    ["stromgarde-keep"] = {
      title = "Burg Stromgarde",
      text = {
        { "Stromgarde steht an der Stelle von Strom, der ersten Stadt der Menschen. Seine Herrscher aus dem Hause Trollbane trugen die älteste Krone der Königreiche der Menschen. Lord Ignaeus bekämpfte die Trolle mit dem Schwert, das sie Trol'kalar nannten, den Trolltöter, und der Name der Familie erinnert an diesen Krieg." },
        { "Die heutige Stadt ist geteilt. Lord Falkensteins Syndikat hält ihre Türme, Oger bewohnen ein Viertel, und Stromgardes Verteidiger halten ein anderes. Weitere Überlebende kämpfen von der Zuflucht aus, um ihre Heimat zurückzugewinnen. Trol'kalar liegt noch immer in Trollbanes Grabmal, hinter Schutzzaubern, die die wiedervereinten Siegelzeichen öffnen können." },
      },
    },
    ["sun-rock-retreat"] = {
      title = "Sonnenfels",
      text = {
        { "Tauren und Orcs teilen sich Sonnenfels in den Klippen im Herzen des Steinkrallengebirges. Seine Schamanen sammeln Samen, um das verbrannte Land wieder wachsen zu lassen. Jäger suchen Rache für Camp Aparaje, das Dorf der Tauren, das die Grimmtotem fast zerstört haben. In der Arbeit des Lagers liegen Wiederherstellung und Vergeltung zugleich." },
        { "Ein Hexenmeister, der hier wohnt, hat ein anderes Ziel. Er dient einem Herrn in Jaedenar und bezahlt für Hilfe gegen die Druiden des Gipfels, denen er vorwirft, die Magie zu ersticken. Hört genau hin, wer welchen Auftrag anbietet, $gReisender:Reisende;. Ein gemeinsames Lager gibt seinen Bewohnern nicht dieselben Absichten." },
      },
    },
    ["swamp-of-sorrows"] = {
      title = "Sümpfe des Elends",
      text = {
        { "Die Sümpfe des Elends liegen östlich des Dämmerwalds, unter einem Himmel, der immer grau ist: Weiden und Mangroven, schwarzes Wasser, Nebel und sehr viel Schlamm. Sie verdienen ihren Namen. Krokilisken lauern in den Tümpeln, Naga spuken an der Küste, und mitten im Morast liegt ein Teich, in dem vor langer Zeit ein Trolltempel versank, mit schlafenden Drachen darüber." },
        { "Die Horde hat hier eine Stadt, Stonard, und ein paar gebrochene Seelen aus einer anderen Welt leben im Osten des Sumpfes. Es gibt nicht viele Gründe herzukommen. Die, die es gibt, sind meist sehr alt oder sehr gefährlich, und gewöhnlich beides." },
      },
    },
    ["sylvanas-windrunner"] = {
      title = "Fürstin Sylvanas Windrunner",
      text = {
        { "Sylvanas Windrunner war die Waldläufergeneralin von Silbermond, die größte Bogenschützin der Hochelfen und die Befehlshaberin ihrer Waldläufer, und sie kämpfte gegen Prinz Arthas um jeden Schritt, als er die Geißel nach Quel'Thalas führte. Als er schließlich durchbrach, tötete er sie, und zur Strafe für ihren Widerstand ließ er sie nicht ruhen: Er erhob sie als Banshee und band sie an seinen Dienst." },
        { "Als die Macht des Lichkönigs ins Wanken geriet, riss Sylvanas sich los. Sie sammelte die Untoten, die mit ihr erwacht waren, zwang einen Schreckenslord in ihren Dienst und nahm die Ruinen der Hauptstadt Lordaerons für sich ein. Die Verlassenen nennen sie die Dunkle Fürstin, und sie würden ihr überallhin folgen." },
        { "Sie stammte aus einer Familie von Waldläufern. Ihre ältere Schwester Alleria ging mit der Expedition der Allianz durch das Dunkle Portal und kam nie zurück. Es war Sylvanas, die die Worte auf ihre Tafel am Tor von Stormwind schrieb. Die jüngste, Vereesa, war ebenfalls eine Waldläuferin von Quel'Thalas." },
        { "Sie will Arthas tot sehen. Darüber hinaus behält sie ihre Gedanken für sich, und ihre Augen verraten nichts." },
        { side = "Horde", aside = true, sign = "P. F.", "Sie hat uns unseren Verstand zurückgegeben, was mehr ist, als das Licht vermochte. Was sie als Nächstes mit uns vorhat, hat sie nicht gesagt." },
      },
    },
    ["syndicate"] = {
      title = "Das Syndikat",
      text = {
        { "Alterac war das Königreich, das die Allianz im Zweiten Krieg an die Horde verkaufte, und als der Krieg gewonnen war, wurden seine Lande eingezogen und seinen Adligen ihre Titel genommen. Manche dieser Adligen haben das nie hingenommen. Sie nennen sich das Syndikat, und sie sind Diebe und Halsabschneider unter dem Banner eines Lords." },
        { "Ihr Anführer war Lord Aliden Perenolde, Sohn des Verräterkönigs, und sein Traum war es, die Orcs wieder in Ketten zu legen, wie in den Tagen der Internierungslager. Seine Leute halten die zerstörte Stadt Strahnbrad in Alterac und Burg Durnholde in Hillsbrad, wo sie die Straßen von Southshore ausrauben und gegen seinen Magistrat Ränke schmieden, und im Arathihochland hat Lord Falkenstein die Ruinen von Stromgarde selbst an sich gerissen." },
        { "Sie sind viele, und sie sind nicht sehr gut. Die Meuchler von Ravenholdt, die sie seit Jahren bekämpfen, nennen sie Stümper, und die Verlassenen setzen auf jeden Kopf einen Preis aus. Doch sehr viele Diebe können trotzdem sehr viel Schaden anrichten, und das Syndikat tut es." },
      },
    },
    ["taelan-fordring"] = {
      title = "Taelan Fordring",
      text = {
        { "Taelan Fordring wuchs in dem Glauben auf, sein Vater sei tot. Als Tirion seiner Ländereien beraubt wurde, weil er sein Wort gegenüber einem Orc hielt, blieb Taelans Mutter zurück und erzählte dem Jungen so viel. Er trat dem Scharlachroten Kreuzzug bei, stieg unter dem Obersten Kreuzzügler auf, riss das Banner der Silbernen Hand in Northdale nieder und wurde Hochlord des Kreuzzugs in Hearthglen." },
        { "Er habe nie aufgehört, von seinem Vater zu träumen, sagt er: davon, dass Tirion an seiner Seite stünde an dem Tag, an dem er zum Ritter geschlagen würde, dass sie gemeinsam gegen die Geißel kämpften, für die Ehre Lordaerons. Als Reisende ihm die Dinge bringen, die Tirion für ihn aufbewahrt hat, und die Wahrheit darüber, was aus dem Kreuzzug geworden ist, bricht er mit ihm und reitet hinaus, um seinen Vater zu finden." },
        { "Weit kommt er nicht. Großinquisitor Isillien streckt ihn vor Hearthglen nieder, in Sichtweite des Mannes, zu dem er ritt, und Tirion tötet Isillien über dem Leichnam seines Sohnes. Der Orden der Silbernen Hand, sagt Tirion danach, ist wiedergeboren. Es kostete ihn seinen Sohn, sich zu erinnern, wofür er da war." },
      },
    },
    ["talaanis-shadowsong"] = {
      title = "Talaanis Shadowsong",
      text = {
        { "Talaanis Shadowsong ist der Hohe Älteste der Insel Zephras, und sein Volk spricht gut von ihm. Ein guter Mann, sagen sie, und sehr beliebt, was die Liga bei einem Herrscher nicht für selbstverständlich zu halten gelernt hat. Er regiert von Valanaar aus mit den anderen Ältesten der Insel, Aetheen von den Böen unter ihnen." },
        { "Seine Amtsjahre waren nicht leicht. Die Pylonen versagen, die beiden Orden seines Volkes können sich kaum auf irgendetwas einigen, und der Kult der Al'Aketh griff den westlichen Wachturm an und tötete seinen eigenen Neffen, einen Friedenswächter. Als die Hohepriesterin des Kults endlich vertrieben war, nannte er es keinen Sieg. Die Schutzzauber, die Zephras vor Al'Akir verborgen hatten, waren gefallen, und er konnte nur sagen, dass es Jahre dauern könnte, vielleicht Jahrzehnte, bevor der Windlord seinen Blick auf sie richtete." },
      },
    },
    ["talonbranch-glade"] = {
      title = "Nachtlaublichtung",
      text = {
        { "Die Nachtlaublichtung ist ein kleiner Außenposten der Nachtelfen im Norden des Teufelswalds, mit einem Mondbrunnen und ein paar Häusern zwischen den verderbten Bäumen, gleich südlich der Holzschlundfeste, dem Tunnel der Furbolgs, der weiter nach Moonglade und Winterspring führt." },
        { "Sie ist eine kleine Insel aus reinem Boden in einem kranken Wald, und die Schildwachen, die sie halten, bewachen die Straße nach Norden für jeden Reisenden, der durch den Teufelswald muss." },
      },
    },
    ["tanaris"] = {
      title = "Tanaris",
      text = {
        { "Tanaris ist die große Wüste im Süden Kalimdors, ein Ozean aus Dünen und zerbrochenem Fels zwischen Tausend Nadeln und dem Meer. Wasser ist hier mehr wert als Gold, und die Goblins, die ihre einzige Stadt führen, wissen das." },
        { "Bei aller Leere ist es eine belebte Wüste. Die Trolle der Sandfury halten ihre Stadt im Westen, Banditen der Wüstenläufer streifen durch die Dünen, Piraten halten die Südküste, Oger den Süden, und in der klaffenden Schlucht regen sich die Silithiden. Und im fernen Süden, hinter versiegelten Toren, liegt eines der eigenen Werke der Titanen, für dessen Betreten die Forscherliga ihre Bärte hergeben würde." },
      },
    },
    ["tarren-mill"] = {
      title = "Tarrens Mühle",
      text = {
        { "Einst bewohnten Müller und Bauern Tarrens Mühle. Die Verlassenen halten es nun als südliches Bollwerk, mit einer Todeswache, die einer Hochexekutorin dient, die wiederum Varimathras Rechenschaft schuldet. Southshore ist nur einen kurzen Ritt entfernt." },
        { "Darthalia befiehlt Überfälle auf die Höfe von Hillsbrad und nennt ihre menschlichen Bewohner eine Plage. Sie will sie unterwerfen, während die Apotheker ihre neue Seuche vollenden. Der Krieg zwischen diesen Orten reicht weit über ihre Wachen hinaus: Die Bauern und ihre Ernten werden in seinen Befehlen beim Namen genannt." },
        { side = "Horde", aside = true, sign = "P. F.", "Man sagt uns, die neue Seuche der Apotheker sei für die Geißel bestimmt. Die letzte Seuche hat mich getötet, und das hätte ich gern schriftlich." },
      },
    },
    ["tauren"] = {
      title = "Die Tauren",
      text = {
        { "Die Tauren gehören zu den ältesten Völkern der Ebenen Kalimdors. Generationenlang wanderten ihre Stämme, folgten den Herden und den Wegen der Erdenmutter, während die Zentauren sie von einem Lager zum nächsten jagten. Cairne Bloodhoof sammelte viele der Stämme, und als Thralls Orcs an Land kamen, halfen sie den Tauren, die Zentauren zurückzudrängen und das Grasland von Mulgore zu erreichen." },
        { "Dort errichteten die Tauren Thunder Bluff auf seinen Tafelbergen und ließen sich nieder, auch wenn sie die Gewohnheiten der Straße behalten. Sie ehren die Erdenmutter, deren Augen An'she sind, die Sonne, und Mu'sha, der Mond. Ihre Schamanen sprechen mit den Geistern, und ihre Druiden wandeln mit dem Zirkel des Cenarius durch den Traum. Nicht jeder Stamm folgt Cairne. Die Grimmtotem gehen ihre eigenen Wege und pflegen ihren eigenen Groll." },
        { "Sie sind langsam im Zorn und sehr schwer aufzuhalten, wenn sie einmal zornig sind, $gReisender:Reisende;. Die Archäologen der Liga haben sie als die geduldigsten Gastgeber in Kalimdor kennengelernt, vorausgesetzt, niemand gräbt dort, wo ihre Ahnen begraben liegen." },
      },
    },
    ["teldrassil"] = {
      title = "Teldrassil",
      text = {
        { "Teldrassil ist ein Baum, und ich schreibe diesen Satz im Wissen, wie töricht er klingt. Er erhebt sich vor der Nordküste der Dunkelküste aus dem Meer, so gewaltig, dass auf seinen Ästen Wälder wachsen und Flüsse an ihnen entlangfließen, und die Nachtelfen leben in seiner Krone. Sein Name bedeutet \"Krone der Erde\"." },
        { "Die Nachtelfen hatten einst einen anderen solchen Baum, Nordrassil, auf dem Hyjal, und solange er stand, alterten sie nie. Am Ende des letzten Krieges ließen sie ihn brechen, um den Dämon Archimonde zu vernichten, und gaben mit ihm ihre Unsterblichkeit auf. Als der Krieg vorbei war, ließen die Druiden unter Fandral Staghelm Teldrassil wachsen, um seinen Platz einzunehmen." },
        { "Der alte Baum hatte den Segen der großen Drachen. Der neue hat ihn nicht, und seine eigenen Hüter geben zu, dass sein Wachstum nicht ohne Makel war. Mehr dazu an anderer Stelle. Für jetzt: Nehmt in Auberdine ein Schiff, geht durch das Tor von Rut'theran und seht ihn Euch an. Es gibt nichts Vergleichbares auf der Welt." },
      },
    },
    ["temple-of-ahnqiraj"] = {
      title = "Tempel von Ahn'Qiraj",
      text = {
        { "Die Zwillingsimperatoren Vek'lor und Vek'nilash herrschen vom Tempel von Ahn'Qiraj aus über die Qiraji. Zu ihren Dienern gehören die Schwärme der Silithiden und die großen Würmer in seinen Hallen. Die bronzenen Drachen betrachten diesen Ort mit Furcht." },
        { "Unter den Imperatoren liegt C'Thun. Der Tempel und das Reich um ihn dienen diesem Alten Gott, nicht den Herrschern, denen ein Reisender zuerst begegnet. Die Imperatoren halten ihren Hof über der Kammer ihres eigenen Herrn." },
      },
    },
    ["thandol-span"] = {
      title = "Der Thandol-Übergang",
      text = {
        { "Der Thandol-Übergang trug die Straße von Khaz Modan nach Norden ins Arathihochland und zu den Königreichen der Menschen dahinter. Seine beiden großen zwergischen Brücken dienten dieser Straße über Generationen. Ein Ingenieur bittet Euch vielleicht, das Mauerwerk zu bewundern. Wer auf den Übergang angewiesen war, hatte ebenfalls Grund, es zu bewundern." },
        { "Die Dunkeleisenzwerge haben eine Brücke so gut wie zerstört. Zwergische Soldaten halten die andere, und die Straße bleibt unter ihrer Bewachung offen. Ein schönes Stück Ingenieurskunst lässt sich leichter loben, wenn jemand anderes es am Stehen hält." },
        { "Schaut hinüber zur zerbrochenen Brücke, wenn Ihr vorbeikommt, $gReisender:Reisende;. Beide Brücken wurden gebaut, um Menschen über das Wasser zu tragen. Nur eine kann es noch." },
      },
    },
    ["the-agamands"] = {
      title = "Die Agamands",
      text = {
        { "Die Agamands waren die reichste Familie in Tirisfal, und diese Mühlen gehörten ihnen. Als die Geißel kam, befestigten sie das Haus und befahlen allen in ihren Diensten, zu bleiben und es mit ihnen zu halten. Die Knechte blieben. Sie seien treu gewesen, sagt einer von ihnen heute, und Narren." },
        { "Nichts davon hielt. Die Familie und ihre Arbeiter starben gemeinsam und erhoben sich gemeinsam, und die Agamands wandeln noch immer für den Lichkönig über die Mühlen: Gregor, der Vater, Nissa, seine Frau, und ihre Söhne. Ihre Gruft liegt am Nordende des Anwesens, mitten unter der Geißel." },
        { "Manche ihrer Arbeiter rissen sich los und sind heute Verlassene. Coleman Farthing, der in ihren Mühlen arbeitete, schickt Reisende zurück, um zu vernichten, was von der Familie übrig ist, und ihre Gruft um ihre Erbstücke zu erleichtern. Rache, sagt er, schmeckt süß. Er hofft, dass sie vor dem Ende Furcht kannten. Es sei eine törichte Hoffnung, gibt er zu. Er hält trotzdem an ihr fest." },
      },
    },
    ["the-al-aketh"] = {
      title = "Die Al'Aketh",
      text = {
        { "Die Al'Aketh sind ein Kult der Shen'dorei, erkennbar an ihren grauen Roben und geschorenen Köpfen, die Al'Akir den Windlord als rechtmäßigen Herrscher des Himmelswalls verehren. Ihre Prediger erzählen eine einfache Geschichte: Die Shen'dorei wurden stolz und hielten die Gaben der Winde für selbstverständlich, und die Geister verließen sie dafür. Auf einer Insel, die auseinanderbricht, findet sie Zuhörer." },
        { "Sie halten Falaath im Shen'darhochland und den Schrein von Akir unter ihrer Hohepriesterin Lorthuna. Sie haben die Wachtürme der Pylonen angegriffen, sind über die Druiden der Nachtklaue hergefallen, um einen eigenen Pylonen zu gewinnen, haben Spione in die Dörfer geschickt und mindestens einen Verräter in Valanaar gefunden. Ein ehemaliger Friedenswächter, Belguilos, den man den Brecher nennt, befehligt ihre Kämpfer." },
      },
    },
    ["the-ashbringer"] = {
      title = "Der Aschenbringer",
      text = {
        { "Der Aschenbringer war ein Mann, bevor er ein Schwert war. Hochlord Mograine gründete den Scharlachroten Kreuzzug mit Hochgeneral Abbendis und Hochinquisitor Isillien, als er noch ein edler Orden war, und man nannte ihn den Aschenbringer für das, was er den Heeren des Lichkönigs antat: Er ging in ganze Bataillone von Untoten hinein und kam auf der anderen Seite heraus, und hinter ihm war nichts als Asche. Seine Klinge übernahm den Namen von ihm." },
        { "Hochinquisitor Fairbanks, der dabei war, erzählt, wie es endete. Der Oberste Kreuzzügler schloss einen Handel mit Kel'Thuzad, und Mograine wurde von seinem eigenen Sohn Renault in Stratholme in einen Hinterhalt gelockt. Als die Geißel sich um sie schloss und die Klinge zu leuchten begann, hob Renault sie auf und stieß sie seinem Vater in den Rücken. 'Was hast du getan, Renault?' waren die letzten Worte des Hochlords. Der Mann und die Klinge waren eins gewesen, und der Mord verdarb beide. Mograine erhob sich als Todesritter Kel'Thuzads." },
        { "Fairbanks entkam Stratholme nach zwei Tagen unter den Toten und erzählte die Geschichte jedem im Kloster, der zuhören wollte. Dafür wurde er ermordet und in seiner Kathedrale versteckt. Doch manche hörten ihn, sagt er, und so begann die Argentumdämmerung. Renault führt das Kloster heute, als sein Scharlachroter Kommandant." },
      },
    },
    ["the-badlands"] = {
      title = "Das Ödland",
      text = {
        { "Südlich von Loch Modan bricht das Land auf zum Ödland: roter Fels, trockene Schluchten, Tafelberge und Staub, kaum ein Baum oder Bach darin. Bussarde kreisen, Kojoten schleichen umher, Oger des Klans der Staubspeier halten die Hügel, und schwarze Drachen nisten in der Lethlorklamm im Osten." },
        { "Zwerge kommen trotzdem her, denn unter dem Ödland liegt Uldaman, das Gewölbe der Titanen, und die Forscherliga gräbt seit Jahren an seiner Tür. Ebenso die Dunkeleisenzwerge, von ihrer Festung Angor aus, und ebenso die Troggs, die aus ihm heraufkamen. Auch die Horde hat hier ein Lager, in Kargath, um die Dunkeleisenzwerge zu beobachten. Es ist eine belebte Öde." },
      },
    },
    ["the-barrens"] = {
      title = "Brachland",
      text = {
        { "Das Brachland ist die große Savanne im Herzen Kalimdors: ein Meer aus gelbem Gras und Dornbäumen unter einem riesigen Himmel, mit Herden von Zhevras und Kodos, Löwen und Raptoren und ein paar kostbaren Oasen, an denen alles, was hier lebt, trinkt. Es ist heiß, trocken und gewaltig, und es gehört, soweit man das sagen kann, dem, der das nächste Wasserloch hält." },
        { "Das sind sehr viele Leute. Die Horde hält Crossroads in seinem Herzen und die Straßen ringsum. Die Goblins halten Ratchet an der Küste. Die Allianz hält Northwatch im Osten und eine zwergische Grabung im Süden. Zentauren fallen aus den Hügeln ein, Stacheleber halten die Dornenbauten im Süden, Harpyien nisten in den Rinnen, und die Burning Blade und die Venture Co. haben ihre Lager. Ein Reisender im Brachland lernt, zu trinken, wann er kann, und mit einem offenen Auge zu schlafen." },
      },
    },
    ["the-battle-of-mount-hyjal"] = {
      title = "Die Schlacht am Hyjal",
      text = {
        { "Als die Brennende Legion zurückkehrte, kam sie wegen des Weltenbaums. Archimonde, der das Heer der Legion zehntausend Jahre zuvor geführt hatte, wurde in Dalaran in die Welt zurückgerufen und folgte der Geißel über das Meer nach Kalimdor, versessen auf Nordrassil auf dem Gipfel des Hyjal." },
        { "Ein Prophet ging ihm voraus: Medivh, der letzte Wächter, von jenseits des Todes zurückgekehrt, um Wiedergutmachung zu leisten. Er drängte Menschen und Orcs, gemeinsam nach Westen zu segeln, und als keiner davon hören wollte, brachte er sie getrennt hinüber, mit Prophezeiung und List. Thralls Horde durchquerte das Brachland und fand Verbündete in Cairne Bloodhoofs Tauren. Jaina Proudmoore brachte die Überlebenden Lordaerons. In den Wäldern trafen sie auf die Nachtelfen, deren Priesterin Tyrande Whisperwind Malfurion Stormrage und seine Druiden aus ihrem langen Schlaf geweckt hatte." },
        { "Auf dem Berg kämpften drei Völker, die einander nie vertraut hatten, Seite an Seite und gaben langsam Boden preis, während Malfurion seine Falle vorbereitete. Als Archimonde den Weltenbaum erreichte, fielen die Geister des Waldes über ihn her, und die eigene Macht des Baumes wurde aufgebraucht, um ihn zu vernichten. Mit seinem Segen verloren die Nachtelfen die Unsterblichkeit, die sie zehntausend Jahre lang besessen hatten." },
        { "Der Frieden, der am Hyjal geschlossen wurde, hält in Durotar und Theramore noch immer, auch wenn nicht jeder auf beiden Seiten froh darüber ist." },
      },
    },
    ["the-broken-alliance"] = {
      title = "Die zerbrochene Allianz",
      text = {
        { "Die Allianz von Lordaeron gewann den Zweiten Krieg und überlebte den Frieden nicht. Die Horde hatte Khaz Modan, die Hälfte der Provinzen Lordaerons und die Ränder von Quel'Thalas verwüstet. Was übrig war, musste wiederaufgebaut werden, und die Orcs, die sich ergeben hatten, mussten irgendwo untergebracht werden. König Terenas wählte die Gnade und baute Lager für sie. Manche seiner Mitkönige hätten sie lieber hingerichtet gesehen, und alle wurden besteuert, um dafür zu zahlen." },
        { "Dann entkam Schicksalshammer, und jedes Königreich verdächtigte die anderen der Unfähigkeit. Ein Adliger namens Lord Prestor kam an den Hof von Terenas, bot Hilfe an, brachte die Lords gegeneinander auf und redete sich beinahe auf den leeren Thron von Alterac. Er war Todesschwinge, und als es jemand wusste, war der Schaden schon angerichtet." },
        { "Eines nach dem anderen gingen die Königreiche eigene Wege. Gilneas mauerte sich hinter dem Greymane-Wall ein. Stromgarde zog sich zurück. Die Hochelfen von Quel'Thalas, denen von Anfang an wenig an dem Krieg gelegen hatte, verließen die Allianz ganz. Nur wenige blieben Terenas treu, als die Seuche kam, und da gab es wenig, worum er sie noch bitten konnte." },
      },
    },
    ["the-bulwark"] = {
      title = "Das Bollwerk",
      text = {
        { "Das Bollwerk ist die Mauer, die die Verlassenen am östlichen Rand von Tirisfal gebaut haben, wo die Lichtungen enden und die Pestländer beginnen, und sie wird Tag und Nacht gegen die Geißel gehalten. Die Todeswache bemannt ihr Tor, und auch Offiziere der Argentumdämmerung halten dort einen Posten, was Euch verrät, wie sehr beide fürchten, was dahinter liegt." },
        { "Am Bollwerk gibt es seltsamere Dinge. Alexi Barov, der Letzte eines Adelshauses von Lordaeron, das seine Burg an den Kult der Verdammten verkaufte, leistet dort den Verlassenen Gesellschaft und hat Ansichten über das Vermögen seiner Familie, die er gern mit Euch teilt." },
      },
    },
    ["the-cauldron"] = {
      title = "Der Kessel",
      text = {
        { "Der Kessel ist die große Grube der Dunkeleisenzwerge in der Sengenden Schlucht, umgeben von Grabmaschinen und in der Hitze mit Sklavenarbeit betrieben. Manche ihrer Gefangenen wurden in solchen Wahnsinn getrieben, dass sie selbst die angreifen, die sie befreien wollen." },
        { "Die kleinere Grabung von Grimesilt liegt südöstlich davon. Unter der Hauptgrube befehligt Aufseher Maltorius die Schlackengrube, nachdem er die Thoriumbruderschaft verlassen hat, um zu seinen früheren Herren zurückzukehren. Es gibt in Grimesilt auch ein Abort mit einem Schlüssel. Die Geschäfte eines Reisenden in diesem Land können bemerkenswert verschiedene Arten von Einsperrung umfassen." },
      },
    },
    ["the-crossroads"] = {
      title = "Crossroads",
      text = {
        { "Die großen Straßen des Brachlands treffen sich in Crossroads: nach Norden nach Orgrimmar, nach Westen nach Mulgore, nach Osten nach Ratchet und nach Süden nach Tausend Nadeln. Die Horde unterhält hier eine Palisade, ein Gasthaus und einen Horst für Windreiter, mit einer Besatzung, die dem Verkehr zwischen ihnen dient." },
        { "Umtriebe der Zentauren und gestohlene Vorräte geben dieser Besatzung auch außerhalb ihrer Mauern Arbeit. Sergra Darkthorn bietet außerdem Jagdprüfungen an." },
      },
    },
    ["the-crusades-fallen"] = {
      title = "Die Gefallenen des Kreuzzugs",
      text = {
        { "Das Scharlachrote Kloster begräbt seine Helden auf seinem eigenen Friedhof, und ihre Steine sagen mehr über den Kreuzzug als seine Predigten. Lest sie, und Ihr findet, dass er nie nur ein menschlicher Orden Lordaerons war: ein Hochzauberer und ein Waldläuferhauptmann, die Bürger von Quel'Thalas waren, Meuchler aus Dalaran, ein Krieger aus Alterac, ein Lord der Roten Höhlen, ein Admiral von Kul Tiras." },
        { "Lest weiter, und Ihr findet, wie weit er ging. Orman von Stromgarde, sein erster Generalhauptmann, ging an der Mündung des Eiskronengletschers verloren. Der Großadmiral der Scharlachroten Flotte ging vor der gefrorenen Küste von Nordend verloren, und der erste Obermeuchler an Nordends Küsten. Der Kreuzzug trug seinen Krieg bis vor die Tür des Lichkönigs, und die Steine sind, was zurückkam." },
        { "Andere fielen näher an der Heimat: ein Hochabt, getötet bei der Verteidigung des Klosters selbst, ein Verteidiger, der starb, als er einen Schreckenslord erschlug, ein Elf, gefangen in einem endlosen Kampf mit einem Nekromanten. Was auch immer der Kreuzzug seither geworden ist, $gReisender:Reisende;, dies waren die Leute, die zuerst an ihn glaubten." },
        { side = "Horde", aside = true, sign = "P. F.", "Ich habe diese Steine auch gelesen. Ich kam mit einem weniger großzügigen Bericht davon." },
      },
    },
    ["the-dark-portal"] = {
      title = "Das Dunkle Portal",
      text = {
        { "Das Dunkle Portal ist ein großes Tor aus Stein zwischen unserer Welt und Draenor, der Welt der Orcs. Der Hexenmeister Gul'dan öffnete es von der anderen Seite, und der Wächter Medivh half ihm von unserer, und durch es kam vor etwa fünfundzwanzig Jahren die Horde. Der Erste Krieg, der Zweite Krieg, alles, was folgte, kam durch dieses Tor." },
        { "Nach dem Zweiten Krieg wurde es zerschlagen und von Ner'zhul wieder geöffnet, der neue Welten erobern wollte. Eine Expedition der Allianz unter Khadgar und Turalyon zog hindurch nach Draenor, um die Bedrohung zu beenden, und zerstörte das Portal von der anderen Seite, womit sie sich den Weg zurück nach Azeroth abschnitt. Sein großer steinerner Rahmen steht mitten in der Öde, sein Durchgang ruht, und die Dämonen sammeln sich darum." },
      },
    },
    ["the-deadmines"] = {
      title = "Die Todesminen",
      text = {
        { "Die Todesminen versorgten Stormwind einst mit Gold. Verlassen, als die Orcs kamen, wurden sie im Ersten Krieg zur Höhle eines Ogers. Sir Anduin Lothar drang in sie ein, um ein heiliges Buch zurückzuholen, das aus Nordhain gestohlen worden war, und geriet selbst in Gefangenschaft. Soldaten aus Stormwind holten sowohl den Ritter als auch das Buch heraus." },
        { "Die Defias haben seither tiefer gegraben. In ihren Stollen finden sich Goblin-Ingenieure, eine Gießerei und ein Schredder, und unter den alten Schächten birgt eine verborgene Bucht ein großes Kriegsschiff im Bau. Van Cleefs Pläne reichen weit über den Diebstahl von Höfen hinaus. Wenn Ihr hinabsteigt, $gReisender:Reisende;, rechnet mit deutlich mehr als einer stillgelegten Mine." },
      },
    },
    ["the-embalmer"] = {
      title = "Der Einbalsamierer",
      text = {
        { "Die Kinder von Dunkelhain kennen die Geschichte vom Einbalsamierer: einem gütigen Alchemisten, dessen Frau Eliza starb und der sie nicht gehen lassen wollte. Er benutzte dunkle Magie, um sein eigenes Herz in ihre Brust zu setzen, und es brachte sie zurück, mit einem Hunger nach Menschenfleisch, sodass er sie begraben halten musste." },
        { "Es ist keine Kindergeschichte. Der Einbalsamierer ist der alte Einsiedler Calvinius, der in einer Hütte über Rabenflucht lebt, und seine Braut wartet noch immer in ihrem Grab. Sein letztes Geschenk an Dunkelhain war Kleiner, ein aus Toten zusammengenähtes Ungeheuer, das er die Straße zur Stadt hinaufwanken ließ. Die Nachtwache erinnert sich an die Nacht, in der es kam." },
      },
    },
    ["the-emerald-dream"] = {
      title = "Der Smaragdgrüne Traum",
      text = {
        { "Der Smaragdgrüne Traum ist eine Geisterwelt außerhalb der wachen Welt, ständig im Wandel und unermesslich, von der aus Ysera die Träumerin das Wachsen jedes wilden Dings lenkt. Die Druiden wandeln in ihm wegen eines Handels, der vor langer Zeit geschlossen wurde, nach der Großen Teilung, als die Nachtelfen auf dem Hyjal einen Weltenbaum pflanzten." },
        { "Drei Drachen segneten diesen Baum. Alexstrasza setzte die Eichel in die Wasser des neuen Brunnens der Ewigkeit. Nozdormu versprach, dass die Nachtelfen, solange er stand, nie alt würden oder erkrankten. Ysera band ihn an ihren Traum. Der Preis war der Schlaf der Druiden. Malfurion und seine Anhänger willigten ein, jahrhundertelang am Stück im Winterschlaf zu verbringen, während ihre Geister über die Traumpfade wanderten, und sie hielten den Handel." },
        { "Darum sind die Grabhügel von Moonglade voller Schläfer, und darum erwacht ein Druide, der im Traum gewandelt ist, vielleicht mit dem Blick eines Reisenden, der von sehr weit her zurückkehrt. In letzter Zeit erwachen sie beunruhigt. Etwas Dunkles ist in den Traum gekommen, und Remulos, der Moonglade hütet, sagt nicht, was." },
      },
    },
    ["the-fall-of-quelthalas"] = {
      title = "Der Fall von Quel'Thalas",
      text = {
        { "Tausende von Jahren hielten die Hochelfen ihr Königreich in den Wäldern nördlich von Lordaeron, hinter einem Ring aus Runensteinen, mit dem Sonnenbrunnen in seinem Herzen. Im Dritten Krieg kam Prinz Arthas an der Spitze der Geißel dorthin." },
        { "Er kam wegen eines Leichnams. Der Geist Kel'Thuzads sagte ihm, der Nekromant könne nur in den Wassern des Sonnenbrunnens wiedererweckt werden, und so belagerte Arthas Quel'Thalas. Sylvanas Windrunner, Waldläufergeneralin von Silbermond, bekämpfte ihn mit allem, was die Elfen hatten, und verlor. Arthas erhob sie als Banshee in seinen Dienst, schlug sich zum Sonnenbrunnen durch und tauchte Kel'Thuzads Überreste hinein. Der Lich erhob sich. Die Wasser wurden verdorben." },
        { "Als die Geißel sich wieder nach Süden wandte, sagt das Buch, war in Quel'Thalas kein einziger lebender Elf mehr übrig. Ganz stimmt das nicht, $gReisender:Reisende;: Ein paar halten noch die Quel'Lithien-Lodge am äußersten Rand der Pestländer, und andere halten eine Hütte im Hinterland. Doch es kommt der Wahrheit nah genug, dass ich mit ihnen nicht darüber streiten würde." },
      },
    },
    ["the-fallen-hero"] = {
      title = "Der gefallene Held",
      text = {
        { "Vor Stonard steht der Geist eines Helden der Horde und wartet auf Befehle. Im Leben führte er seine Krieger in die Verwüsteten Lande, ohne auf sie zu warten, und fand dort, wovor die Befehle ihn gewarnt hätten: den Dämon Razelikh und seine Leutnants, die seine Männer nahmen und ihre Geister in Steine der Qual banden." },
        { "Er gibt sich selbst die Schuld an allem, und er erzählt seine Geschichte jedem, der anhält und zuhört. Er will seine Männer befreit und Razelikh vernichtet sehen, und er hilft jedem Reisenden, der es versuchen will, ob Horde oder Allianz. Es ist das Einzige, was ihm noch zu tun bleibt." },
      },
    },
    ["the-first-war"] = {
      title = "Der Erste Krieg",
      text = {
        { "Die Orcs kamen durch das Dunkle Portal, ein paar Klans auf einmal, in die Sümpfe östlich von Stormwind, und jahrelang kannte das Königreich sie nur von ihren Überfällen. König Llane glaubte nicht, dass solche Geschöpfe seine Stadt einnehmen könnten. Sein Streiter Anduin Lothar, der Letzte der Linie der Arathi, war sich weniger sicher, und noch weniger sicher war er sich ihres alten Freundes Medivh, dessen Turm in Karazhan tatsächlich sehr dunkel geworden war." },
        { "Lothar handelte nach seinen Zweifeln. Mit Medivhs jungem Lehrling Khadgar stürmte er Karazhan und tötete den Wächter, und er fand heraus, dass Medivh von Anfang an hinter dem Einfall gestanden hatte. Das Königreich rettete es nicht. Die Horde belagerte unter einem neuen Kriegshäuptling, Orgrim Schicksalshammer, die Burg Stormwind, und Llane wurde in seinen eigenen Mauern von Garona getötet, einer halborcischen Meuchlerin des Schattenrats." },
        { "Lothar kehrte in eine rauchende Ruine von einer Stadt heim und schwor mit den Männern, die ihm geblieben waren, sie zurückzuerobern. Er führte die Überlebenden von Azeroth über das Meer nach Lordaeron, um die anderen Königreiche der Menschen um Hilfe zu bitten. Das Bündnis, das sie schlossen, sollte den Zweiten Krieg führen. Stormwind wurde danach wiederaufgebaut. Seine Leute haben seither keinen Feind mehr unterschätzt." },
      },
    },
    ["the-five-aspects"] = {
      title = "Die fünf Aspekte",
      text = {
        { "Bevor sie die Welt verließen, wählten die Titanen fünf Drachenschwärme, um über sie zu wachen, und gaben jedem ihrer Anführer einen Teil ihrer eigenen Macht. Diese fünf Drachen wurden die Aspekte." },
        { "Aman'Thul gab dem bronzenen Nozdormu die Hut über die Zeit selbst: Er ist der Zeitlose. Eonar gab der roten Alexstrasza die Sorge um alles Lebendige und mit ihr die Krone ihrer Art. Alexstraszas jüngerer Schwester, der grünen Ysera, gab sie die wilden Orte, und Ysera fiel in eine Trance, aus der sie noch immer über sie wacht, im Smaragdgrünen Traum. Norgannon gab dem blauen Malygos die Sorge um die Magie. Khaz'goroth, der Former der Welt, gab dem schwarzen Neltharion die Erde und ihre tiefen Orte, und der Erdwächter war Alexstraszas größter Unterstützer." },
        { "Ihr werdet wissen, wie es mit dem Letzten endete. Neltharion schmiedete die Dämonenseele, um die anderen Schwärme zu beherrschen, und wandte sie im Krieg der Urtume gegen sie. Seither nennt die Welt ihn Todesschwinge. Malygos' Schwarm wurde beinahe ausgelöscht. Zeitalter später kettete dieselbe Scheibe die Drachenkönigin selbst in Grim Batol an." },
        { "Fünf Hüter wurden über die Welt gesetzt, $gReisender:Reisende;. Einer von ihnen wurde zu dem, wovor die anderen sie behüten." },
      },
    },
    ["the-forsaken"] = {
      title = "Die Verlassenen",
      text = {
        { "Als der Griff des Lichkönigs um seine Toten nachließ, erwachten einige von ihnen. Sie waren noch immer tot, doch ihr Verstand gehörte wieder ihnen, und sie erinnerten sich, was sie gewesen waren und was man ihnen angetan hatte. Sie nennen sich die Verlassenen, und sie folgen der, die sie befreite: Sylvanas Windrunner, der Bansheekönigin." },
        { "Sie haben die Ruine der Hauptstadt ihres Königreichs zurückerobert und eine Stadt darunter gebaut, und sie führen ihren eigenen Krieg gegen die Geißel, die sie erschuf. Sie haben sich der Horde angeschlossen, die Verbündete gegen die Allianz brauchte, und die Horde hat sie aufgenommen, was die Verlassenen dringender brauchten. Es ist keine herzliche Freundschaft." },
        { "Ich will nicht so tun, als wären die Verlassenen angenehme Gesellschaft. Die meisten von ihnen waren Männer und Frauen Lordaerons, die sich an ihr altes Leben erinnern und nicht dorthin zurückkönnen. Was sie jetzt wollen, über die Rache am Lichkönig hinaus, kann niemand außerhalb von Undercity sagen." },
        { side = "Horde", aside = true, sign = "P. F.", "Niemand außerhalb von Undercity könne sagen, was wir wollen, schreibt sie. Die meisten von uns drinnen können es auch nicht. Ich will wissen, was man uns angetan hat, und es ordentlich niederschreiben." },
      },
    },
    ["the-guardians-of-tirisfal"] = {
      title = "Die Wächter von Tirisfal",
      text = {
        { "Dalaran lernte den Preis der Magie früh. Seine jungen Magier verbrauchten Macht freigiebig, und je mehr sie verbrauchten, desto dünner wurde die Welt um ihre Stadt, bis kleine Dämonen der Brennenden Legion hindurchzuschlüpfen begannen. Die Magokraten, die die Stadt beherrschten, verbargen, was sie konnten. Als das Volk von Aufruhr zu flüstern begann, gingen sie zu den Elfen von Quel'Thalas, um Hilfe zu holen." },
        { "Die Elfen erzählten ihnen, was die Legion war und was sie der Welt schon einmal angetan hatte. Gemeinsam schlossen der Rat von Silbermond und die Magokraten einen geheimen Pakt: Ein einzelner sterblicher Streiter, ausgestattet mit der vereinten Macht elfischer und menschlicher Magie, sollte die Agenten der Legion in einem Krieg bekämpfen, von dem sonst niemand je hören sollte. Ein verborgener Rat, der sich auf den Lichtungen von Tirisfal traf, wo die Elfen sich in Lordaeron zuerst niedergelassen hatten, wählte jeden Wächter, und wenn einer alt oder müde wurde, gab er die Macht unter seiner eigenen sorgfältigen Aufsicht weiter." },
        { "Es funktionierte über Generationen. Dann wählte der Rat Aegwynn, die sich nicht beaufsichtigen lassen wollte. Sie streckte im gefrorenen Norden den Avatar von Sargeras selbst nieder und glaubte, ihn erledigt zu haben. Fast neunhundert Jahre später weigerte sie sich, den Rat ihren Nachfolger bestimmen zu lassen, gebar einen Sohn, der ihre Macht erben sollte, und nannte ihn Medivh, 'Hüter der Geheimnisse' in der Sprache der Hochelfen. Was er hütete, steht unter Karazhan." },
        { "Ein Orden, der seinen Krieg vor der ganzen Welt geheim hält, lässt sich nicht leicht berichtigen, wenn er fehlgeht, $gReisender:Reisende;. Der Rat lernte das zu spät." },
      },
    },
    ["the-high-order"] = {
      title = "Der Hohe Orden",
      text = {
        { "Der Hohe Orden sind die Shen'dorei, die am Arkanen festhalten und an ihrer Abstammung von den Gelehrten der Hochgeborenen aus Eldre'Thalas. Als die Windgeister gingen, zogen sie eine harte Lehre daraus: Ihr Volk hatte sich so vollständig auf seine elementaren Schutzherren gestützt, dass es ohne sie hilflos war. Der Hohe Orden will das Wissen zurückgewinnen, das ihre Ahnen verloren, und auf eigenen Füßen stehen, und sein Oberster Magister Elaadrin Evengale blickt auf die Kirin Tor von Dalaran, um ihnen zu zeigen, wie." },
        { "Die Windformer nennen sie leichtsinnig und überheblich. Der Hohe Orden nennt das Heuchelei. Sie haben für ihre Zuversicht bezahlt. Elaadrin schickte Belathaan Brightwish, um am Schrein von Akir Gespräche mit den Al'Aketh zu eröffnen, und Belathaan kam nie zurück. Der Kult schickte seine Zunge in einer Schachtel zurück, in Silber getaucht. Danach gab Elaadrin zu, dass die Windformer recht gehabt hatten." },
      },
    },
    ["the-hinterlands"] = {
      title = "Hinterland",
      text = {
        { "Nördlich von Arathi liegt das Hinterland: hohe grüne Hügel, tiefe Täler, Wasserfälle und alter Wald, wildes Land, über das nie ein König wirklich geherrscht hat. Die Wildhammerzwerge leben hier, in Aerie Peak, mit ihren Greifen. Ebenso die Waldtrolle des alten Reiches der Amani, deren zerfallene Tempel die Hälfte der Hügel krönen und deren lebende Stämme den Rest noch halten." },
        { "Es ist ein schönes, gefährliches Land. Eulenbestien in den Wäldern, Brühschlammer in den Sümpfen, Trolle der Witherbark und der Vilebranch in den Ruinen, und oben auf dem großen Tempel von Jintha'Alor Priester, die noch immer dem Blutgott opfern. Die Greifenreiter von Aerie Peak behalten alles aus der Luft im Auge." },
      },
    },
    ["the-lich-king"] = {
      title = "Der Lichkönig",
      text = {
        { "Der Lichkönig begann als Orc. Ner'zhul, der alte Schamane, der sein Volk als Erster zur Legion führte, floh nach dem letzten Krieg der Orcs in den Wirbelnden Nether, und Kil'jaeden wartete auf ihn. Der Dämon riss seinen Körper Stück für Stück auseinander und hielt seinen Geist am Leben, dann bot er ihm einen letzten Handel an. Ner'zhul nahm an. Sein Geist wurde in einem Block aus Eis aus den fernen Weiten des Nethers versiegelt, und der Lichkönig war geboren. Seine Todesritter und Anhänger wurden als Liche neu erschaffen, um ihm zu dienen." },
        { "Kil'jaeden schleuderte das Eis in die Welt. Es schlug auf den Gletscher von Eiskrone in Nordend und kam in Gestalt eines Throns zur Ruhe. Vom Frostthron aus griff der Lichkönig nach dem Verstand des Nordens, zuerst nach Eistrollen und Wendigos, dann nach einem Dorf der Menschen am Rand der Drachenöde, wo er die Seuche erprobte, die für Lordaeron bestimmt war. Die Schreckenslords wurden eingesetzt, um ihn zu bewachen. Kil'jaeden traute niemandem, am wenigsten einem Gefangenen." },
        { "Was daraus wurde, füllt die Hälfte der Seiten dieses Registers. Das Buch in unserer Bibliothek endet damit, dass Prinz Arthas zum Frostthron hinaufsteigt und Ner'zhuls Helm aufsetzt und die beiden eins werden. Es heißt, er baue gerüchteweise die Zitadelle von Eiskrone wieder auf und Kel'Thuzad herrsche in seinem Namen über die Pestländer. Die Liga hat keine Expedition in Nordend, $gReisender:Reisende;, und ich sehe keinen Grund, eine zu beginnen." },
      },
    },
    ["the-lost-ones"] = {
      title = "Die Verirrten",
      text = {
        { "Die Verbannten im sicheren Hafen nennen sich Draenei. Mit Hufen und Fühlern und blaugrauer Haut sind sie anders als die anderen Völker, denen ein Reisender in Azeroth gewöhnlich begegnet. Sie sagen, sie seien nach einer schrecklichen Reise aus der Welt der Orcs gekommen. Die im sicheren Hafen sind sanft geblieben und bereit zu sprechen." },
        { "Andere leben im Fallow Heiligtum und werden die Verirrten genannt. Die Verbannten sagen, die Reise habe ihre einstigen Brüder zerbrochen. Sie greifen jeden an, der sich nähert, und haben Kristalle gestohlen, die den Verbannten heilig sind. Diese Berichte vor Ort verraten uns wenig über ihr früheres Leben oder darüber, was geschah, bevor sie hierher kamen. Ich lasse diesen Teil der Seite lieber offen, als ihnen eine Vergangenheit anzudichten, die sie nicht beschrieben haben." },
      },
    },
    ["the-ordering"] = {
      title = "Die Ordnung Azeroths",
      text = {
        { "Der älteste Bericht in der Bibliothek der Liga beginnt, bevor irgendwer hier war, um einen zu führen. Die Titanen, sagt er, zogen von Welt zu Welt, um jede in Ordnung zu bringen, und kamen schließlich zu dieser. Sie fanden sie in der Hand von Elementaren, und die Elementare dienten älteren Herren: den Alten Göttern." },
        { "Das Pantheon der Titanen führte Krieg gegen sie. Vier große Herren der Elemente führten die Heere der Alten Götter, Ragnaros der Feuerlord, Therazane die Steinmutter, Al'Akir der Windlord und Neptulon der Gezeitenjäger, und einer nach dem anderen fielen sie. Die Zitadellen der Alten Götter wurden zerbrochen und die Götter selbst, fünf an der Zahl, tief unter der Erde angekettet. Ohne ihre Herren wurden die Elementare in eine eigene Ebene verbannt, um dort für immer gegeneinander zu kämpfen." },
        { "Dann machten sich die Titanen an die Arbeit. Sie schufen die Irdenen aus lebendem Stein, um die tiefen Orte auszuhöhlen, und die Meeresriesen, um das Land aus dem Meer zu heben. Als sie fertig waren, gab es einen einzigen Kontinent, Kalimdor, und in seinem Herzen einen See aus leuchtender Macht, den sie den Brunnen der Ewigkeit nannten." },
        { "Wir graben ihr Werk noch immer aus, in Uldaman und auf den Terrassen des Ödlands. Ab und zu kommt auch etwas wieder herauf, das sie begraben haben: ein Feuerlord unter dem Blackrock, ein Gott im Sand von Silithus. Die Titanen, so vermute ich, hinterließen die Welt ordentlicher, als sie sie vorfanden, aber nicht fertig." },
      },
    },
    ["the-scarab-wall"] = {
      title = "Der Skarabäuswall",
      text = {
        { "Vor tausend Jahren kamen die Qiraji und ihre Schwärme von Silithiden aus Ahn'Qiraj und fielen über Kalimdor her, und die Nachtelfen bekämpften sie im Krieg der Sandstürme. Allein konnten sie ihn nicht gewinnen. Fandral Staghelm, der sie führte, verlor seinen Sohn Valstann an die Qiraji: Der Junge wurde gefangen genommen und vor den Augen seines Vaters getötet." },
        { "Die Drachen retteten sie. Der bronzene, der rote, der blaue und der grüne Drachenschwarm kamen und trieben die Insekten in ihre Stadt zurück. Und mit ihrer Magie errichteten die Nachtelfen eine große Mauer aus Stein und eine Barriere quer durch den Süden von Silithus, den Skarabäuswall, und schlossen sie ein. Die Toten dieses Krieges liegen in der Heldenwacht, außerhalb davon." },
      },
    },
    ["the-scepter-of-the-shifting-sands"] = {
      title = "Das Szepter der Sandstürme",
      text = {
        { "Um Ahn'Qiraj zu versiegeln, schuf der bronzene Drache Anachronos ein Szepter, das Szepter der Sandstürme, und damit schloss er den Skarabäuswall und stellte einen Gong auf einem Podest davor. Nur das Szepter, gegen den Gong geschlagen, kann ihn wieder öffnen. Er gab es Fandral Staghelm." },
        { "Fandral wollte es nicht. In Gedanken an seinen Sohn zerbrach er das Szepter auf dem Boden und sagte, er wolle es nie wiedersehen. Seine Teile gingen zur Verwahrung an die Drachenschwärme. Tausend Jahre später zeigt ein kristallener Riss in der südlichen Wüste diese Erinnerung noch denen, die hineinsehen, und die bronzenen Drachen suchen jemanden, der das Szepter wieder ganz macht." },
      },
    },
    ["the-second-war"] = {
      title = "Der Zweite Krieg",
      text = {
        { "In Lordaeron fand Lothar die Könige der Menschen ausnahmsweise bereit zuzuhören. Sie willigten ein, sich als Allianz von Lordaeron zu vereinen, das erste Mal seit fast dreitausend Jahren, dass die Erben Arathors unter einem Banner standen, und ernannten Lothar zum Oberbefehlshaber. Uther Lightbringer, Admiral Daelin Proudmoore und Turalyon dienten unter ihm. Ironforge schloss sich an, und ebenso, widerwilliger, ein paar Hochelfen, die bei der Linie der Arathi in der Schuld standen." },
        { "Schicksalshammer brachte Oger aus Draenor und Trolle der Amani aus den Wäldern mit, überrannte Khaz Modan und marschierte nach Norden. Die Horde hatte die Dämonenseele gefunden und mit ihr die Drachenkönigin versklavt, sodass rote Drachen für die Orcs kämpften. Die Grenzlande von Quel'Thalas brannten, was die Zweifel der Elfen ausräumte, und die Städte Lordaerons wurden eine nach der anderen geschleift." },
        { "Die Horde stand vor den Toren von Lordaerons Hauptstadt, als Gul'dan mit der Hälfte ihrer Stärke desertierte, um das Grabmal des Sargeras aus dem Meer zu heben, und darin nur wahnsinnig gewordene Dämonen fand. Schicksalshammer musste umkehren, um ihn zu bestrafen. Die Allianz trieb ihn nach Süden zur Blackrockspitze, wo Lothar am Fuß des Berges fiel. Turalyon sammelte das Heer, brach die Horde und zerstörte hinter ihr das Dunkle Portal. Die Orcs, die überlebten, wurden in Lager getrieben." },
        { "Die Spitze, so bemerke ich, ist wieder voller Orcs." },
      },
    },
    ["the-sepulcher"] = {
      title = "Das Grabmal",
      text = {
        { "Das Grabmal ist eine Ansammlung von Grüften und Mausoleen im Silberwald, gehalten von der Todeswache und den Todespirschern der Verlassenen. Von diesem Bollwerk aus wollen sie den Wald sichern. Die Befehle der Bansheekönigin reichen weiter: Varimathras ist beauftragt, die Lande der Menschen und Zwerge im Süden zu erobern." },
        { "Vorerst halten Arugals Worgen, die Gnolle der Moderfelle und die Magier von Ambermill seine Kräfte nahe der Heimat beschäftigt. Besonders wollen die Verlassenen Arugals Werk ungeschehen machen." },
      },
    },
    ["the-seven-kingdoms"] = {
      title = "Die sieben Königreiche",
      text = {
        { "Arathor endete nicht in einem Krieg. Es trieb auseinander. Strom blieb das Herz des Reiches, während überall im Norden neue Städte entstanden. Dalaran war der Ort, an den die Magier gingen, um freier zu üben. Gilneas und Alterac drangen mit ihren Heeren in die Berge von Khaz Modan vor und trafen so auf die Zwerge von Ironforge. Kul Tiras auf seiner Insel wurde durch Fisch und Handel reich und baute eine Flotte, um beides zu tragen." },
        { "Dann wurden die Herren von Strom des trockenen Südens müde. Sie zogen nach Norden und bauten eine neue Stadt, Lordaeron, und mit der Zeit nahm der ganze Kontinent ihren Namen an. Der Letzte aus Thoradins Linie, der dafür gestritten hatte, Strom nicht aufzugeben, ging in die andere Richtung, nach Süden über die Berge, und gründete Stormwind in einem fruchtbaren Tal des Landes, das sie Azeroth nannten. Ein paar Krieger blieben, um die alten Mauern zu bewachen, und Strom wurde zu Stromgarde." },
        { "Sieben Königreiche also, jedes mit eigenen Bräuchen und eigenem Groll, und keines, das über die anderen herrschte. Es brauchte einen Einfall aus einer anderen Welt, um sie fast dreitausend Jahre später wieder unter einem Banner zu vereinen, und das Banner überlebte den Krieg, der es erhob, nicht lange. Die Liga fand die Zwerge schon immer leichter im Blick zu behalten." },
      },
    },
    ["the-shalnan"] = {
      title = "Der Shal'nan",
      text = {
        { "Die Shen'dorei erinnern sich an den Anführer, der sie aus Eldre'Thalas herausführte, nur als den Shal'nan, den Verschleierten, wegen der gesichtslosen goldenen Maske, die sein Gesicht verbarg. Als Prinz Tortheldrins Ehrgeiz sich ins Dunkle wandte, zerbrachen die Aufständischen des Shal'nan das Netz kristallener Foki, auf das der Prinz angewiesen war, und flohen. Es war der Shal'nan, der Frieden mit den Windgeistern schloss und sein Volk hinauf in den Himmelswall führte." },
        { "Er herrschte über ein Jahrhundert lang über sie, nach ihrem eigenen Bericht ein widerwilliger Anführer, und gab seine Macht dann an einen Rat der Provinzen ab, sobald die Inselzufluchten gegründet waren. Ein Kristall, hoch im großen Baum in Thendal aufbewahrt, erzählt seine Geschichte. Er sagt nicht, was aus ihm wurde, und die Shen'dorei bisher ebenso wenig." },
      },
    },
    ["the-silence-of-the-winds"] = {
      title = "Das Schweigen der Winde",
      text = {
        { "Tausende von Jahren hielten die Windgeister die Insel Zephras in der Luft und die Shen'dorei in ihrer Obhut. Vor einigen Jahrhunderten gingen sie, und nichts, was die Shen'dorei seither versucht haben, hat sie zurückgebracht oder erklärt, warum. Die Feen, die noch über der Insel spielen, sind Echos, ohne den Verstand der Geister, die einst mit ihnen sprachen." },
        { "Was die Geister zurückließen, verschleißt. Ihre Ankerpylonen halten die Insel zusammen, und ihre Magie kommt und geht nun. Kraftlinien haben begonnen, wie Narben durch die Oberfläche zu brechen, und Windsteine, die die rohe Macht der Winde bergen, werden ernsthaft gesammelt und erforscht. Jede Gruppe auf der Insel hat ihre Antwort. Die Windformer wollen die Geister finden und heimbringen, der Hohe Orden will lernen, ohne sie zu leben, und die Al'Aketh wollen stattdessen vor dem Windlord knien." },
      },
    },
    ["the-stockade"] = {
      title = "Das Verlies",
      text = {
        { "Stormwinds Gefängnis liegt unter seinen Kanälen, in den Fels unter der Stadt gehauen. Unter den Defias, die dort eingesperrt waren, war Edwin van Cleefs Leutnant Bazil Thredd. Unter seiner Führung erhoben sich die Häftlinge und übernahmen die Zellen." },
        { "Der Aufseher rief Abenteurer, um den Aufstand niederzuschlagen. Thredd war nicht der einzige gefährliche Gefangene darin: Der Orc Targorr der Schreckliche war unter den Aufrührern. Es ist ein unbehaglicher Gedanke, eine feindliche Festung unter den Straßen der eigenen Hauptstadt zu haben." },
      },
    },
    ["the-sundering"] = {
      title = "Die Große Teilung",
      text = {
        { "Vor zehntausend Jahren herrschten die Nachtelfen vom Ufer des Brunnens der Ewigkeit aus über Kalimdor, einem See aus reiner Magie im Herzen der Welt. Ihre Königin war Azshara, die schönste von allen, und ihre Hochgeborenen schöpften ohne Grenzen aus der Macht des Brunnens. Ihre Magie zog den Blick von Sargeras auf sich, dem Herrn der Brennenden Legion, und Azshara und ihre Hochgeborenen öffneten ihm den Weg, im Glauben, die Dämonen würden die Welt vollkommen machen." },
        { "Die Nachtelfen, die sich nicht beugen wollten, bekämpften die Legion im Krieg der Urtume. Lord Kur'talos Ravencrest führte sie zuerst, im Glauben, seine Königin sei eine Gefangene ihrer eigenen Berater, bis ein Meuchler, den ihr Hauptmann der Garde geschickt hatte, ihn auf dem Schlachtfeld tötete. Der Befehl fiel schließlich an einen jungen Offizier, Jarod Shadowsong, der tat, was Ravencrest verweigert hatte, und die anderen Völker rief, die Irdenen, die Tauren, die Furbolgs und die Halbgötter des Waldes, Cenarius unter ihnen. Der junge Druide Malfurion Stormrage und die Priesterin Tyrande kämpften im Herzen des Geschehens. Malfurions Bruder Illidan lief zu den Hochgeborenen über, und der Drache Neltharion wandte sich gegen die anderen Schwärme." },
        { "Am Ende erkannte Malfurion, dass der Brunnen selbst die Tür der Legion war, und der Brunnen der Ewigkeit wurde zerstört. Er riss sich selbst auseinander und nahm das Herz des Kontinents mit sich, und das Meer stürzte in das Loch, das er hinterließ. Azshara und ihre Hochgeborenen gingen mit ihrem Palast unter. Von dieser Küste aus, dem zertrümmerten Strand, blickt Ihr über den Ort, an dem die Welt zerbrach." },
      },
    },
    ["the-temple-of-atalhakkar"] = {
      title = "Der Tempel von Atal'Hakkar",
      text = {
        { "Als die Gurubashi sich gegen die Priester erhoben, die Hakkar in die Welt gebracht hatten, flohen die Atal'ai in diesen Sumpf, bauten ihrem Gott einen Tempel und versuchten weiter, ihn zurückzurufen. Die grünen Drachen Yseras fanden sie. Sie versenkten den Tempel unter dem Sumpf, und Ysera setzte einige der Ihren zu seiner Bewachung ein, damit Hakkar nie wieder durch ihn kommen sollte." },
        { "Die Atal'ai sind noch immer darin, unter dem Wasser, und ihr Prophet Jammal'an hat ihnen versprochen, dass Hakkar ihnen bei seiner Rückkehr ewiges Leben schenken werde. Sie haben es beinahe geschafft. Die Drachen, die den Tempel bewachen, sind nicht mehr, was sie waren, und die Horde in Stonard wie die Allianz wollen die Atal'ai aufgehalten sehen, bevor der Seelenschinder wieder wandelt." },
      },
    },
    ["the-third-fleet"] = {
      title = "Die dritte Flotte",
      text = {
        { "Die Wracks an der Nordküste des Sumpflands waren die dritte Flotte von Kul Tiras. Auf ihrer letzten Fahrt wurde sie vor dieser Küste von roten Drachen gestellt, von Orcs gerittenen Drachen, und verbrannt und versenkt, wo sie lag. Die Leute von Kul Tiras nennen sie die verlorene Flotte." },
        { "Ein Mann kam lebend davon: Fitzsimmons, einst Erster Maat der Wave Mistress, der im Hafen von Menethil trinkt und die Geschichte für den Preis eines Humpens erzählt. Nicht alle seine Schiffskameraden ruhen in Frieden. An Bord der INTREPID war etwas verstaut, eingeschlossen in der Geldkassette des Kapitäns, und seine Macht lässt die ertrunkenen Mannschaften über ihre verrottenden Decks gehen. Kapitän Halyndor geht noch immer mit dem Schlüssel über sein Schiff." },
        { "Was in dieser Kassette lag, war ein Auge von Paleth, eine der Kugeln, die menschliche Priester zum hellen Leuchten schufen, schwarz verflucht von dem, was es in jener Nacht sah. Die Priester von Menethil konnten es nicht reinigen. Der Erzbischof in Stormwind konnte es. Eine Flotte stirbt nicht immer auf einmal, $gReisender:Reisende;. Manchmal braucht es einen Priester und einen sturen Ersten Maat, um die Sache zu Ende zu bringen." },
      },
    },
    ["the-war-of-the-spider"] = {
      title = "Der Krieg der Spinne",
      text = {
        { "Während Thrall sein Volk aus den Lagern befreite, errichtete der Lichkönig eine Zitadelle über dem Gletscher von Eiskrone, und ein Königreich in Nordend verweigerte sich ihm. Azjol-Nerub lag unter der Erde, beherrscht von den Neruber, Spinnenfürsten, deren Tunnel unter dem halben Kontinent verliefen. Sie waren gefeit gegen seine Seuche und gegen seine Stimme in ihrem Geist, und sie schlugen gegen seine Festungen los und waren wieder fort, bevor er antworten konnte." },
        { "Er siegte durch Zermürbung. Mit den Schreckenslords und einem endlosen Vorrat an Toten fiel er in Azjol-Nerub ein und brachte ihre Tempel über den Köpfen der Spinnenfürsten zum Einsturz. Die Seuche konnte sie lebend nicht nehmen, doch seine Nekromantie konnte sie tot erwecken, und so kamen die Neruber dazu, dem Herrn zu dienen, den sie bekämpft hatten. Er bewunderte auch ihre Bauten: Die Festungen der Geißel sind in ihrem Stil gebaut." },
        { "Beides könnt Ihr in den Pestländern sehen. Die Gruftbestien, die zwischen der Geißel kriechen, sind Neruber, oder was von ihnen übrig ist, und die Zikkurate der Toten sind die Baukunst der Spinnenfürsten. Der Lichkönig behält seine Trophäen gern in der Nähe." },
      },
    },
    ["the-windshapers"] = {
      title = "Die Windformer",
      text = {
        { "Die Windformer sind die Shen'dorei, die den Windgeistern treu bleiben. Sie stammen von den Ersten ihres Volkes ab, die die Gabe der Himmelssicht von den Geistern empfingen, und sie pflegten die Instrumente und Konstrukte, die die Geister auf der Insel zurückließen. Sie haben geschworen, diese alte Schuld zurückzuzahlen: die Ebene der Elemente zu wagen, ihre verschwundenen Lehrmeister zu finden und heimzubringen. Ihre Großhimmelsseherin Ayessa Dawnsinger glaubt, der Weg liege unten, in Azeroth, und die Schamanen des irdenen Rings haben zu ihnen gestanden." },
        { "Sie sind kein verzeihendes Volk. Auf die Gewalt des Kults antwortete Ayessa mit Blut für Blut, und die Windformer sagen von sich, dass sie weder vergeben noch vergessen. Sie wollen keinen Frieden mit den Al'Aketh, und sie halten die Magie des Hohen Ordens an ihren heiligen Stätten für eine Gefahr für eine Insel, die ohnehin schon auseinanderbricht." },
      },
    },
    ["thelsamar"] = {
      title = "Thelsamar",
      text = {
        { "Thelsamar ist das Herz von Loch Modan: ein Dorf aus Steinhäusern an der Straße zwischen Ironforge und dem Sumpfland, mit einer Schmiede, einem guten Gasthaus und einem Greifenmeister für alle, die es eilig haben." },
        { "Es ist die Art von Ort, an dem jeder jeden kennt und die Neuigkeiten schneller reisen als die Greifen. Fragt im Gasthaus nach irgendetwas, das im Seenland geschieht, und Ihr hört es dreimal, jede Fassung besser als die letzte." },
        { "Die Gebirgsjäger hier sind dünn verteilt. Wenn Ihr einen starken Arm und einen freien Nachmittag habt, finden sie etwas für Euch zu tun." },
      },
    },
    ["theramore-isle"] = {
      title = "Die Insel Theramore",
      text = {
        { "Theramore ist die Stadt, die Jaina Proudmoore baute, als sie die Überlebenden Lordaerons über das Meer nach Kalimdor führte, ein Festungshafen aus weißem Stein auf einer Insel vor der Küste von Dustwallow. Es ist der stärkste Halt der Allianz auf dem Kontinent und der einzige Ort der Welt, an dem eine Herrscherin der Menschen einen dauerhaften Frieden mit der Horde geschlossen hat." },
        { "Viele seiner Soldaten kamen mit Lady Proudmoore über das Meer, Marinesoldaten aus Kul Tiras darunter, und nicht alle haben ihren Frieden mit diesem Frieden gemacht. Theramore unterhält Wachtürme in der Marsch und ein Fort im Brachland, und seine Hauptleute haben mehr Rätsel auf ihren Schreibtischen, als ihnen lieb ist." },
      },
    },
    ["thoradins-wall"] = {
      title = "Thoradinswall",
      text = {
        { "Thoradin war vor langer Zeit der Häuptling des Stammes der Arathi, der die verstreuten Stämme der Menschen im Norden eroberte oder überredete, ein einziges Volk zu werden, das Reich Arathor, und seine Hauptstadt in Strom baute. Als die Trolle des Reiches der Amani gegen die Elfen von Quel'Thalas Krieg führten, war es Thoradin, der Menschen an ihrer Seite in den Kampf führte, und die menschlichen Magier, die die Elfen in diesem Krieg ausbildeten, waren der Anfang aller menschlichen Magie." },
        { "Seine Mauer verläuft noch immer über die Hügel zwischen Arathi und Hillsbrad, heute zerbrochen und überwuchert, aber noch immer groß. Die Männer, die sie bauten, sind längst fort, und das Reich mit ihnen, doch jeder König der Menschen hat behauptet, sein Erbe zu sein." },
      },
    },
    ["thorium-brotherhood"] = {
      title = "Die Thoriumbruderschaft",
      text = {
        { "Die Thoriumbruderschaft besteht aus Dunkeleisenzwergen, die ihren Imperator verlassen haben. Ihre Schmiede arbeiten an der Thoriumspitze über dem Kessel und handeln mit denen, die bereit sind, ihnen gegen Thaurissans Truppen zu helfen. Ein Bronzebeard kann ihr Handwerk ohne große Mühe bewundern. Die politische Lage braucht etwas mehr Erklärung." },
        { "Sie wissen, wie man die Waffen und Rüstungen des Feuerlords schmiedet, vorausgesetzt, jemand bringt die Materialien aus dem Inneren des Berges. Einer von ihnen handelt sogar in der Taverne der Schattenschmiede, unter der Nase des Imperators. Wenn Ihr ihre Arbeit sucht, $gReisender:Reisende;, bringt, was sie brauchen. Ihr Streit mit ihren alten Verwandten hat ihr Können nicht geschmälert." },
      },
    },
    ["thousand-needles"] = {
      title = "Tausend Nadeln",
      text = {
        { "Südlich des Brachlands fällt der Boden über einen großen Aufzug nach Tausend Nadeln ab: eine tiefe Schlucht voller ragender Steinsäulen, Hunderte davon, die wie die Knochen der Erde aus dem Staub aufragen. Die Tauren leben oben auf ihnen, die Zentauren des Klans der Galak in der Schlucht darunter, und die Windreiter und Harpyien dazwischen." },
        { "Im Osten öffnet sich die Schlucht zur schimmernden Ebene, einem trockenen weißen Salzbett, über dem die Hitze flimmert. Die Goblins und die Gnome haben darauf eine Rennstrecke gebaut. Man sagt mir, das sei für Goblins und Gnome ganz natürlich, wenn sie eine Wüste vor sich haben." },
      },
    },
    ["thrall"] = {
      title = "Thrall",
      text = {
        { "Thrall ist der Kriegshäuptling der Horde, und sein Leben liest sich wie eine Ballade, die niemand glauben würde. Er war der Sohn Durotans, des Häuptlings der Frostwolf, als Säugling neben seinen ermordeten Eltern gefunden und als Sklave und Gladiator in Burg Durnholde von deren Herrn aufgezogen, Lord Aedelas Blackmoore, der ihn zum General eines zahmen Orcheeres machen wollte. Man gab ihm den Namen Thrall, was Sklave bedeutet, und er behielt ihn." },
        { "Er entkam mit der Hilfe eines menschlichen Mädchens, das sich mit ihm angefreundet hatte, fand den Klan seines Vaters in den Bergen von Alterac und lernte die Wege des Schamanen. Dann brach er mit Grom Hellscream und dem alten Kriegshäuptling Orgrim Schicksalshammer die Internierungslager auf und befreite sein Volk. Schicksalshammer fiel in diesem Krieg und hinterließ Thrall die Horde und seinen Hammer." },
        { "Er führte die Horde über das Meer nach Kalimdor, kämpfte an der Seite der Nachtelfen und der Menschen gegen die Brennende Legion und baute Durotar auf. Er will Frieden mit der Allianz und hat ihn mit Jaina Proudmoore von Theramore geschlossen. Ob der Rest der Allianz ihn will, ist eine andere Frage." },
        { side = "Horde", aside = true, sign = "P. F.", "Lordaeron machte ihn zum Sklaven, und er fand in seiner Horde trotzdem Platz für die Toten Lordaerons. Ich bin nicht sicher, ob ich das getan hätte." },
      },
    },
    ["thule-ravenclaw"] = {
      title = "Thule Rabenklaue",
      text = {
        { "Thule Rabenklaue war vor dem Dritten Krieg ein junger Magier mit großer Zukunft. Als der Lichkönig sich erhob, verriet er die Seinen, um der Geißel zu dienen, und die Verlassenen, von denen manche im Leben neben ihm studiert hatten, wussten nicht, dass er noch lebte, bis sie sein Werk fanden." },
        { "Er hält die Insel Fenris im Lordameresee neben dem Silberwald, und die Gnolle des Klans der Moderfelle gehören ihm: tote Dinger, erweckt und getränkt in seinen fauligen Säften, die die Gräber von Tirisfal ausheben und ihm die Leichen bringen. Was er aus ihnen macht, würden die Verlassenen lieber nicht auf die harte Tour herausfinden." },
      },
    },
    ["thunder-bluff"] = {
      title = "Thunder Bluff",
      text = {
        { "Thunder Bluff steht hoch auf den Tafelbergen Mulgores, über große Aufzüge oder mit einem Windreiter zu erreichen. Seilbrücken verbinden seine Anhöhen. Ein Zwerg aus Ironforge, der feste Böden gewohnt ist, sollte vielleicht schauen, wohin er tritt, bevor er die Aussicht betrachtet." },
        { "Cairne erbaute diese Zuflucht, nachdem die Tauren und die Orcs die Zentauren zurückgedrängt hatten. Stämme, die lange an das Wandern gewöhnt waren, versammelten sich hier. Händler und Handwerker teilen sie nun mit Jägern, den Druiden der Anhöhe der Ältesten und den Schamanen und Sehern der Anhöhe der Geister." },
        { "Cairne bleibt Oberhäuptling in ihrer Mitte. Die Grimmtotem gehören zu denen, die sich seiner Führung widersetzen. Ein Reisender sieht ein Volk, das endlich eine Stadt hat, auch wenn eine dauerhafte Heimat die Meinungsverschiedenheiten zwischen seinen Stämmen nicht beendet hat." },
      },
    },
    ["timber"] = {
      title = "Holzplanke",
      text = {
        { "Die Jäger von Kharanos nennen ihn Holzplanke: ein Wolf, größer als seine Artgenossen, mit einem lästigen Verständnis für Fallen. Sie sagen, er wähle sein Gelände und kehre auf seiner eigenen Fährte um. Jeder Jäger, der auf ihn angesetzt wurde, hat erleben müssen, dass die Beute ihn überdauerte." },
        { "Wölfe beschäftigen eine königliche Chronik selten. Dieser hier hat gute Gründe für seine Aufnahme geliefert, auch wenn ich bezweifle, dass er die Ehre zu schätzen wüsste." },
        { "Wenn Ihr ihn getötet habt, $gReisender:Reisende;, schreibt auf, was geschehen ist, solange Ihr Euch erinnert. Die Jäger werden schon bald ihren eigenen Bericht haben." },
      },
    },
    ["timbermaw"] = {
      title = "Die Holzschlundfeste",
      text = {
        { "Von allen Furbolgstämmen des Nordens hat nur die Holzschlundfeste ihren Verstand bewahrt. Die Verderbnis, die aus dem Teufelswald sickerte, machte die Totenwaldfelle und die Winterfelle zu den knurrenden Geschöpfen, denen man auf den Straßen begegnet, und die Holzschlundfeste musste zusehen, wie es ihren Verwandten geschah. Sie hielt sich in ihren Tunneln unter den Bergen zwischen dem Teufelswald, Moonglade und Winterspring und hielt sie gegen jeden." },
        { "Sie hat Grund zur Vorsicht. Die meisten Reisenden töten heute jeden Furbolg auf Sicht, ohne zu fragen, zu welchem Stamm er gehört, und so trauen die Furbolgs der Holzschlundfeste sehr wenigen. Helft ihnen gegen die verderbten Stämme, und sie werden beginnen, Euch langsam durch ihre Feste zu lassen. An der Wurzel des Wahnsinns der Winterfelle fand man einen Dämon. Ihn zu töten, gab diesem Stamm, in den Worten der Holzschlundfeste, eine Chance zu überleben." },
        { "Es macht ihnen keine Freude, gegen ihre eigenen Brüder zu kämpfen. Einer ihrer Späher bittet jene, die für ihn kämpfen, ihm die Einzelheiten zu ersparen. Verdient Euch ihr ganzes Vertrauen, und sie schicken Eurem eigenen König eine Friedensgabe. Es ist das Höflichste, was ein belagertes Volk in diesem Register irgendwem angeboten hat." },
      },
    },
    ["tiragarde-keep"] = {
      title = "Burg Tiragarde",
      text = {
        { "Burg Tiragarde ist eine Festung von Kul Tiras an der Küste von Durotar, und sie sollte überhaupt nicht hier sein. Als die Horde sich in ihrem neuen Land niedergelassen hatte, brachte Admiral Daelin Proudmoore, Herr des Inselkönigreichs Kul Tiras, seine Flotte über das Meer, um den Krieg zu beenden, den sein Volk nie vergeben hatte, entgegen dem Frieden, den seine eigene Tochter am Hyjal mit Thrall geschlossen hatte. Er wurde geschlagen und getötet, und seine Flotte liegt als Wrack vor diesem Strand." },
        { "Die Burg fiel mit ihm. Doch einige seiner Männer blieben, und unter einem Lieutenant Benedict und einem Wachkommandanten namens Zalaphil haben sie sie zurückerobert und befestigt, eine Handvoll Leute aus Kul Tiras mitten in der Heimat der Horde. Die Orcs vom Klingenhügel nennen sie Verräter. Die Leute von Kul Tiras würden über Theramore ziemlich dasselbe sagen." },
      },
    },
    ["tirion-fordring"] = {
      title = "Tirion Fordring",
      text = {
        { "Ihr findet Tirion Fordring vielleicht in einer kleinen Hütte am Thondroril. Er war einst Herr von Burg Mardenholde in Hearthglen und ein Paladin der Silbernen Hand. In seiner jetzigen Unterkunft deutet wenig auf das eine oder das andere hin." },
        { "Der Orc Etrigg rettete ihm das Leben. Tirion widersetzte sich dessen Gefangennahme und weigerte sich bei seinem Prozess in Stratholme, den Eid zu brechen, den er ihm geschworen hatte. Man nahm ihm seine Titel und Besitzungen und schickte ihn ins Exil. Seine Frau erzählte ihrem Sohn Taelan, er sei tot." },
        { "Taelan führt nun den Scharlachroten Kreuzzug in Hearthglen. Tirion bittet Reisende, einen Spielzeughammer zurückzuholen, den er dem Jungen schenkte, das Banner der Silbernen Hand, das Taelan in Northdale niederriss, und ein Gemälde, das in Stratholme versteckt ist. Das sind die Dinge, von denen er hofft, dass sie seinen Sohn erreichen. Wenn er Euch den Auftrag anvertraut, $gReisender:Reisende;, denkt daran, dass er versucht, Taelan heimzuholen." },
      },
    },
    ["tirisfal-glades"] = {
      title = "Tirisfal",
      text = {
        { "Tirisfal war das Herz des Königreichs Lordaeron: sanft gewelltes Ackerland, Obstgärten und Mühlen rund um die Hauptstadt, das reichste Land im Norden. Es ist auch auf andere Weise alter Boden. Die Lichtungen gaben dem geheimen Orden der Magier seinen Namen, den Wächtern von Tirisfal, die jahrhundertelang über die Welt wachten." },
        { "Heute ist es ein graues Land. Die Seuche nahm Lordaeron, die Toten wandelten, und die Hauptstadt fiel. Die Höfe sind leer oder Schlimmeres, die Bäume blattlos und das Licht immer trüb. Die Verlassenen beherrschen es von unter der zerstörten Stadt aus, der Scharlachrote Kreuzzug von seinem Kloster im Norden, und die Geißel wandert noch über die Felder dazwischen." },
      },
    },
    ["tower-of-althalaxx"] = {
      title = "Der Turm von Althalaxx",
      text = {
        { "Balthule Shadowstrike beobachtet den zerstörten Turm von Althalaxx nordöstlich von Auberdine. Er bleibt auf seinem Posten, statt zu riskieren, einen Hinweis zu verpassen. Die Umtriebe um ihn führen zum dunklen Strang, einem Kult von Nachtelfen, die Hexenmeistermagie ausüben. Ihr Volk hat Grund genug, sich zu erinnern, was solche Künste bringen können." },
        { "Die Ermittlung reicht nach Süden bis Ashenvale, zu einem Hexenmeister der Orcs am Fire Scar-Schrein. Delgren der Läuterer von der Argentumdämmerung nimmt dort die Jagd auf." },
      },
    },
    ["treason-of-alterac"] = {
      title = "Der Verrat von Alterac",
      text = {
        { "König Aiden Perenolde urteilte, dass die Horde den Zweiten Krieg gewinnen würde. Während die anderen Königreiche der Menschen gemeinsam kämpften, öffnete Alterac den Orcs einen Weg und versorgte sie mit den Plänen der Allianz. Als die Allianz siegte, verhängte Lordaeron das Kriegsrecht. Die Herrscher stritten dann darüber, was aus dem Königreich werden sollte." },
        { "Alteracs Hauptstadt ist zerstört und seine Bibliotheken verstreut. Stormwind schickt Gelehrte, um die Bücher zu bergen. Perenoldes Sohn Aliden hat ein anderes Erbe angetreten: Er führt das Syndikat, zu dem ehemalige Adlige Alteracs gehören, und plant, die Orcs zu versklaven, wie es sein Lehrmeister Blackmoore wollte. Hier wird auf mehrere Arten zu bergen versucht, $gReisender:Reisende;. Die der Gelehrten ist die, die ich empfehlen würde." },
        { side = "Horde", aside = true, sign = "P. F.", "Es freut mich, dass jemand Alteracs Bücher rettet. Ob je eines davon Undercity erreicht, ist eine andere Frage." },
      },
    },
    ["twilights-hammer"] = {
      title = "Der Twilight-Hammer",
      text = {
        { "Cho'galls Twilight-Hammer begann im Zweiten Krieg als Klan der Orcs, angeführt von einem zweiköpfigen Ogermagier. Er kämpfte im Glauben, die Welt solle enden. Die Niederlage der alten Horde ließ dieses Ziel in einem Kult mit Anhängern vieler Völker weiterleben." },
        { "Der Kult verehrt die Alten Götter, uralte Mächte unter der Erde. Seine Mitglieder dienen einem Schrecken in der Blackfathom-Tiefe, versammeln sich an Götzenbildern in der Sengenden Schlucht und beschwören Elementarfürsten in Silithus." },
      },
    },
    ["tyrande-whisperwind"] = {
      title = "Tyrande Whisperwind",
      text = {
        { "Tyrande Whisperwind führt die Nachtelfen als Hohepriesterin von Elune. Vor zehntausend Jahren war sie eine junge Priesterin, die an der Seite von Malfurion und Illidan Stormrage gegen die Legion kämpfte. Sie liebte Malfurion. Illidans Liebe zu ihr blieb unerwidert. Sie war es, die die anderen überzeugte, dass Malfurion recht hatte und der Brunnen zerstört werden musste, und vor dem Ende nahmen Azsharas Satyrn sie gefangen. Unterwegs nahm sie eine junge verwaiste Bogenschützin auf, Shandris Feathermoon, die heute als ihre Generalin die Schildwachen führt." },
        { "Während die Druiden im Smaragdgrünen Traum schliefen, bewachten ihre Priesterinnen und Schildwachen die Wälder durch die langen Zeitalter. Im Dritten Krieg sammelte sie die Nachtelfen, weckte Malfurion und stand am Hyjal, als Archimonde fiel." },
        { "Malfurion wird nun vermisst, und die Druiden kennen sein Schicksal nicht. Tyrande führt vom Tempel des Mondes in Darnassus aus, während Fandral Staghelm die Druiden anführt. Begegnet ihrem Willkommen mit Achtung, $gReisender:Reisende;. Die Priesterin, die Besucher begrüßt, hat ihr Volk durch Kriege geführt, die weit älter sind als unsere Königreiche." },
      },
    },
    ["tyrs-hand"] = {
      title = "Tyrs Hand",
      text = {
        { "Tyrs Hand ist eine befestigte Stadt im Südosten der Pestländer, an Tyrs Bucht, voller Kirchen und eine der ältesten heiligen Stätten Lordaerons. Sie hat schon Krieg gesehen: Im Zweiten Krieg stachelten Spione Alteracs ihre Bauern zum Aufstand an, um eine Mine der Orcs zu verbergen, und die Silberne Hand wurde geschickt, um den Frieden zu wahren. Im Dritten Krieg hielt sie gegen die Geißel stand, und sie hält noch immer, für den Scharlachroten Kreuzzug." },
        { "Kreuzzüglerlord Valdelmar herrscht über sie, Hochgeneral Abbendis befehligt ihre Soldaten, und eine Seherin, die die Kreuzzügler das Scharlachrote Orakel nennen, berät den Obersten Kreuzzügler. Jeden Tag reiten Kuriere durch die Pestländer zwischen Tyrs Hand und Stratholme. Die Verlassenen beobachten jeden einzelnen." },
      },
    },
    ["uldaman"] = {
      title = "Uldaman",
      text = {
        { "Uldaman liegt unter dem Ödland, ein Gewölbe der Titanen aus behauenen Hallen und großen steinernen Wächtern. Die Grabungen der Liga öffneten einen Weg hinein. Troggs strömten heraus und gaben den Gräbern der Liga eine unwillkommene Antwort auf eine lange gestellte Frage über diese Geschöpfe." },
        { "Troggs bewohnen nun die äußeren Hallen, und Dunkeleisenzwerge der Schattenschmiede suchen die Geheimnisse darin. Die Liga ringt mit beiden. Jenseits von Archaedas, dem letzten Wächter des Gewölbes, liegen die Scheiben von Norgannon und ihr Bericht über das Werk der Titanen. Die Liga hat guten Grund, weiterzugraben, selbst nachdem sie erfahren hat, was ihre Grabungen sonst noch freisetzen können." },
      },
    },
    ["uldum"] = {
      title = "Uldum",
      text = {
        { "Die versiegelten Tore von Uldum stehen im Tal der Behüter, weit im Süden von Tanaris. Bringt die Platinscheiben von Uldaman in ihre Nähe, und der Steinbehüter von Norgannon erwacht. Er bewacht den Eingang und verlangt die Platten von Uldum, bevor er jemanden einlässt." },
        { "Der Behüter beschreibt eine Forschungsanlage der Titanen, die sich mit dem Leben dieser Welt befasst. Wo die verlangten Platten liegen, sagt er uns nicht. Die Liga hat einen Namen, einen Zweck und ein verschlossenes Tor zu erforschen, $gReisender:Reisende;. Wir würden sehr gern einen Weg hindurch hinzufügen." },
      },
    },
    ["undercity"] = {
      title = "Undercity",
      text = {
        { "Lordaerons Hauptstadt liegt in Trümmern über der eigenen Stadt der Verlassenen. Hinter ihren zerbrochenen Mauern liegen der zerschmetterte Thronsaal und leblose Höfe. Darunter sind alte Grüfte und Katakomben zu Undercity geworden, angelegt um Ringe aus grünem Schleim. Sylvanas hält Hof in ihrem Königsviertel." },
        { "Händler, Lehrer und Wachen bewohnen die anderen Viertel, und die Königliche Apothekervereinigung arbeitet im Apothekarium. Die Verlassenen haben eine funktionierende Hauptstadt unter dem Wrack derjenigen geschaffen, die sie im Leben kannten. Ein Reisender, der nur die Ruinen oben ansieht, würde übersehen, wo die verbliebenen Geschäfte des Königreichs heute geführt werden." },
        { side = "Horde", aside = true, sign = "P. F.", "Mit dem Apothekarium hat sie recht, so weit es reicht. Ihr findet mich dort, auf der südlichen seiner beiden Brücken, wo ich Helden Fragen stelle, die glauben, Stärke genüge. Kommt und lasst Euch prüfen, $gReisender:Reisende;." },
      },
    },
    ["ungoro-crater"] = {
      title = "Un'Goro-Krater",
      text = {
        { "Un'Goro ist ein dampfender grüner Kessel, eingesunken zwischen den Wüsten von Tanaris und Silithus. Teufelssaurier schreiten durch seinen Dschungel, Stegodons und große Affen bewohnen das Becken, und Pterrordaxe kreisen darüber. Die Tauren, die hierher reisen, sprechen von Geschöpfen, edler als ihre Gegenstücke draußen, und von der Verbindung des Kraters zur Erdenmutter." },
        { "Teergruben, heiße Quellen und der Feuerfedergrat teilen den Wald, mit einem Stock der Silithiden im Süden. In Marshals Zuflucht studiert die Expedition ein Land, das ein anderes Zeitalter bewahrt zu haben scheint. J.D. Collies Versuche mit den farbigen Kristallen haben begonnen, ihre Verwendungen zu enthüllen. Ihr Ursprung bleibt eine größere Frage." },
        { client = "forever", "Die Shapers' Terrace hat dieser Frage einen Ort gegeben, an dem sie beginnen kann." },
      },
    },
    ["uthers-tomb"] = {
      title = "Uthers Grabmal",
      text = {
        { "Uther Lightbringer war der erste der Paladine, gesalbt von Erzbischof Faol, der Befehlshaber der Ritter der Silbernen Hand, Prinz Arthas' Lehrer und der größte Streiter, den das Licht unter den Menschen hatte. Er weigerte sich, an der Säuberung Stratholmes teilzunehmen, und Arthas entließ ihn dafür. Als Arthas mit seinem verfluchten Schwert aus Nordend zurückkam, stellte Uther sich ihm entgegen, als Hüter der Urne mit König Terenas' Asche, und sagte seinem alten Schüler, er hoffe, in der Hölle warte ein besonderer Platz auf ihn. Arthas tötete ihn." },
        { "Sein Grabmal steht auf Sorrow Hill über dem Darrowmeresee, eine Halle aus weißem Stein mit seiner Statue darin, mitten im toten Land. Dort ist es still wie nirgends sonst in den Pestländern, und wer noch an das Licht glaubt, kommt, um ihm die Ehre zu erweisen." },
        { side = "Horde", aside = true, sign = "P. F.", "Terenas war mein König, und Uther starb, als er seine Asche hütete. Ich würde dieses Grabmal gern sehen." },
      },
    },
    ["vaelastrasz"] = {
      title = "Vaelastrasz",
      text = {
        { "Vaelastrasz ist ein roter Drache aus dem Schwarm der Drachenkönigin, und vor tausend Jahren wurde ihm ein Splitter des Zepters anvertraut, das Ahn'Qiraj versiegelte. In der Blackrockspitze erscheint er Sterblichen als Vaelan, in einer Gestalt, wie er sagt, deren Anblick sie ertragen können, und er hilft den Kühnen, das Siegel des Aufstiegs zu schmieden, das ihnen die obere Zitadelle öffnet." },
        { "Das Schmieden verlangt Edelsteine von drei Generälen der Spitze und den Atem eines schwarzen Drachen, dessen Wille gebrochen wurde. Der rote Schwarm hatte nie etwas dagegen, sich das Feuer seines Feindes zu borgen." },
        { "Am Ende fing Nefarian ihn. Im Pechschwingenhort wartet er, verdreht von der Verderbnis des schwarzen Drachen, und fleht die an, die ihn erreichen, den Splitter des Zepters zurückzunehmen, bevor er zerstört wird. 'Zu spät, Freunde!', sagt er und wendet sich gegen sie. Wer ihn niederstreckt, erfährt danach, dass seine Seele Frieden gefunden hat. Ich hoffe es." },
      },
    },
    ["valanaar"] = {
      title = "Valanaar",
      text = {
        { "Valanaar ist die Hauptstadt der Insel Zephras, an ihrem südöstlichen Rand, und der Sitz ihres Hohen Ältesten. An seinen Docks legen die Himmelsschiffe an: kleine fliegende Schiffe, die einst zwischen den Inseln der Shen'dorei verkehrten und nun zum ersten Mal hinab nach Azeroth fahren, nach Dalaran für den Hohen Orden und nach Mulgore für die Windformer." },
        { "Wenn Ihr durchkommt, schaut im Gasthaus vorbei. Oben bewahren die Shen'dorei einen Kristall, der den Aufstand ihrer Ahnen in Eldre'Thalas aus ihrer eigenen Sicht erzählt. Ich kenne nichts Älteres, das für sie spricht, und ich gäbe sehr viel darum, ihn zu hören." },
      },
    },
    ["valley-of-kings"] = {
      title = "Das Tal der Könige",
      text = {
        { "Im Südwesten von Loch Modan halten zwei große Könige aus Stein Wache: Madoran Bronzebeard und Khardros Wildhammer, die ihre Klans im Krieg der drei Hämmer anführten." },
        { "Ihre Söhne errichteten diese Statuen nach ihrem Tod, um sie zu ehren und jeden, der diese Straße heraufkam, zu warnen, dass die Königreiche der Zwerge nicht zu erobern seien. Die Dunkeleisenzwerge waren damals im Süden, wie sie es heute sind. Die Botschaft hat sich nicht geändert." },
        { "Haltet an und schaut hinauf, $gReisender:Reisende;. Bronzebeard und Wildhammer stehen hier Seite an Seite, wie sie es seither kaum irgendwo sonst getan haben." },
      },
    },
    ["valley-of-trials"] = {
      title = "Das Tal der Prüfungen",
      text = {
        { "Im Tal der Prüfungen werden die Jungen der Horde geprüft: Orcs und Trolle gleichermaßen, hinausgeschickt zwischen die Eber und Skorpide der Schlucht, um zu zeigen, was in ihnen steckt. Es ist ein enger, sonnenverbrannter Ort südlich des Klingenhügels, und seine Prüfungen sollen hart sein." },
        { "Nicht alle seine Gefahren sind Tiere. In den Höhlen des Tals hat die Burning Blade ihre Kultisten und ihre Wichtel versteckt, nah genug an den eigenen Jungen der Horde, um beleidigend zu sein, und die erste Lektion, die viele Orcs lernen, ist, dass der älteste Feind ihres Volkes manchmal das Gesicht eines Orcs trägt." },
      },
    },
    ["varimathras"] = {
      title = "Varimathras",
      text = {
        { "Als Arthas nach Nordend aufbrach, herrschten Varimathras und seine Brüder, die Schreckenslords, über die Ruinen Lordaerons. Sylvanas, gerade erst frei von der Kontrolle des Lichkönigs, besiegte ihn und ließ ihm die Wahl zwischen Dienst und Tod. Er wählte den Dienst und half ihr dann, sich gegen seine Brüder zu wenden." },
        { "Heute steht er an der Seite der Bansheekönigin in Undercity. Es ist eine eindrucksvolle Partnerschaft, auch wenn ihr Anfang wenig Beruhigendes über die Treue beider Seiten verrät. Varimathras fand einen Weg, einen Wechsel des Herrn zu überleben. Sylvanas hat ihn dort behalten, wo sie ihn sehen kann." },
        { side = "Horde", aside = true, sign = "P. F.", "Wir gehen im Königsviertel an ihm vorbei und sagen nichts. Ich bin mir weniger sicher als die Dunkle Fürstin, dass ihn in der Nähe zu halten dasselbe ist, wie ihn treu zu halten." },
      },
    },
    ["venture-company"] = {
      title = "Die Venture Co.",
      text = {
        { "Wenn sich etwas ausgraben, fällen oder aus dem Boden pumpen lässt, ist die Venture Co. schon mit einem Schredder da. Sie ist ein Unternehmen der Goblins, eine Handelsgesellschaft ohne Treue zu irgendwem außer ihrem Vorstand, und ihr Geschäft ist es, zu nehmen, was anderen gehört, und es zu verkaufen, bevor sie es merken." },
        { "In Kalimdor sind sie überall. Sie roden die Wälder des Steinkrallengebirges kahl, sie haben gegen die ausdrückliche Weigerung der Tauren in den Klippen von Mulgore geschürft und dabei gleich die Brunnen verschmutzt, und im Brachland haben sie das Schlickermoor zu einem schwarzen Ölteich gepumpt. Jenseits des Meeres schlagen sie Holz im Dschungel des Schlingendorntals und graben in seinen Hügeln." },
        { "Ihresgleichen hält wenig von ihnen. Die Goblins des Steamwheedle-Kartells, die die neutralen Häfen halten, zahlen gutes Geld an jeden, der der Gesellschaft das Leben schwer macht, und ebenso, so stelle ich mir vor, jeder Taure in Mulgore." },
      },
    },
    ["voljin"] = {
      title = "Vol'jin",
      text = {
        { "Vol'jin führt die Dunkelspeer und ist ein Schattenjäger, einer ihrer Priesterkrieger, die mit den Loa wandeln. Sein Vater Sen'jin starb in den Kämpfen auf den Inseln, wo Thralls Flotte zuerst auf den Stamm traf. Vol'jin hat das Versprechen seines Vaters an die Horde gehalten." },
        { "Er bleibt in Thralls Nähe in Orgrimmar, während sein Volk Sen'jin hält und darauf blickt, die Echoinseln zurückzugewinnen. Ein Reisender, der den Anführer der Dunkelspeer sucht, findet ihn also in der Hauptstadt, die verlorene Heimat des Stammes noch immer unter seinen Sorgen." },
      },
    },
    ["wailing-caverns"] = {
      title = "Die Höhlen des Wehklagens",
      text = {
        { "Dampf klingt in den Höhlen unter dem Brachland wie Trauer, wo Flüsse durch ein Labyrinth aus Fels ziehen. Naralex sah in ihren Wassern ein Mittel, das trockene Land darüber zu heilen. Indem er sie mit dem Smaragdgrünen Traum verband, hoffte er, das Brachland grün zu machen." },
        { "Er stieg mit seinen Schülern hinab und schlief. Der Traum wurde zum Albtraum. Naralex ist nicht erwacht, die Geschöpfe der Höhlen haben sich verändert, und die meisten seiner Anhänger sind mit ihm gefallen. Ein Schüler sucht noch Hilfe, um zu seinem Meister zu gelangen und ein Ritual des Erwachens durchzuführen." },
      },
    },
    ["war-of-the-three-hammers"] = {
      title = "Der Krieg der drei Hämmer",
      text = {
        { "Vor etwa zweieinhalb Jahrhunderten gehörte Ironforge drei Klans zugleich. Die Bronzebeards, die Wildhammer und die Dunkeleisenzwerge lebten unter einem einzigen Hochkönig, Modimus Anvilmar, und als er starb, konnten sie sich nicht einigen, wer ihm folgen sollte." },
        { "Der Streit wurde zu einem Krieg unter dem Berg. Die Bronzebeards hielten die Stadt. Die Wildhammer unter Than Khardros wurden vertrieben und errichteten ihre eigene Festung in Grim Batol, und die Dunkeleisenzwerge unter Zauberthan Thaurissan zogen sich in die Berge des Südens zurück." },
        { "Die Dunkeleisenzwerge waren nicht am Ende. Sie marschierten zugleich gegen Ironforge und Grim Batol und verloren beide Schlachten. In seiner Wut griff Thaurissan nach einer Macht, die weit älter war als jeder Klan, und weckte Ragnaros, den Herrn des Feuers. Der Süden brannte: Die Sengende Schlucht und die Brennende Steppe sind, was übrig blieb, und die Dunkeleisenzwerge dienen dem Feuerlord seither im Blackrock." },
        { "Auch die Wildhammer blieben nicht in Grim Batol. Der Tod von Königin Modgud, die vor seinen Toren erschlagen wurde, hinterließ eine Finsternis im Stein, und sie fanden ein neues Zuhause in Aerie Peak im Hinterland. Ironforge erinnert sich noch, welcher Klan geblieben ist." },
      },
    },
    ["warlocks"] = {
      title = "Hexenmeister",
      text = {
        { "Gul'dan brachte die Magie der Hexenmeister in die Horde der Orcs. Er und sein Schattenrat lernten sie von Kil'jaeden, und damit machten sie ihr Volk zu Waffen der Brennenden Legion. Die Hexenmeister der Horde erweckten die Toten, riefen Dämonen und verbrannten ganze Länder, und ihre Kunst überlebte ihre Herren." },
        { "Ihre Schüler finden sich heute auf beiden Seiten. Die Burning Blade dient der Legion noch immer in Durotar. Die Hexenmeister Stormwinds halten sich im Keller des Geschlachteten Lamms. Auch Gnome und Verlassene studieren sie. Ein Hexenmeister bindet Dämonen in seinen Dienst, spricht Flüche aus und bezahlt die Macht mit seinem eigenen Leben, wenn nichts anderes hilft." },
        { client = "forever", "Auch die Dunkelspeer zählen nun Hexenmeister zu ihren Zauberwirkern." },
        { "Die meisten Städte dulden Hexenmeister, ohne ihnen zu trauen, $gReisender:Reisende;, und die Hexenmeister scheinen es so vorzuziehen." },
      },
    },
    ["warriors"] = {
      title = "Krieger",
      text = {
        { "Es gibt keinen einzelnen Orden der Krieger, $gReisender:Reisende;, nur ein Handwerk, so alt wie der erste Streit. Lordaerons Fußsoldaten und Stormwinds Ritter, die Grunzer der Orcs, die eben diese Mauern brachen, die Taurenkrieger der Ebenen und die Jäger der Dunkelspeer von den Inseln lernten dieselben Lektionen auf verschiedenen Wegen." },
        { "Dennoch hat das Handwerk seine Schulen. Ein Krieger lernt, auf drei Arten zu stehen. Die Kampfhaltung dient dazu, zuerst und hart zuzuschlagen. Die Verteidigungshaltung hält eine Linie hinter einem Schild. Die Raserei eines Berserkers verausgabt die Kraft des Körpers freigiebig und fordert sie später zurück. Der größte Teil der Arbeit besteht darin, zu lernen, was der Augenblick verlangt." },
        { "Jede Hauptstadt unterhält eine Halle, in der Krieger die Jungen ausbilden. Die Liga heuert sehr viele von ihnen als Begleiter an, und ich habe noch keinen getroffen, der keine Meinung dazu gehabt hätte, wo die Gräber graben sollten." },
      },
    },
    ["warsong-gulch"] = {
      title = "Warsongschlucht",
      text = {
        { "In der Warsongschlucht, am Südrand von Ashenvale, haben die Nachtelfen ihre Stellung gegen weiteres Holzfällen der Warsong bezogen. Die Schildwachen der Silverwing halten das eine Ende des Tals und die Warsongvorhut das andere. Ihre Kämpfer laufen zwischen den Lagern hin und her, um das Banner des Feindes zu erbeuten." },
        { "Die Horde betrachtet dies als Verteidigung eines Holzfällerbetriebs. Die Allianz betrachtet den Betrieb als Einfall. Beide schicken Kämpfer von weit jenseits Ashenvales." },
      },
    },
    ["warsong-lumber-camp"] = {
      title = "Das Holzfällerlager der Warsong",
      text = {
        { "Als die Orcs in Kalimdor landeten, schickte Thrall Grom Hellscream und seinen Warsongklan nach Ashenvale, um Holz zu holen. Die Hüter des Waldes wollten sie dort nicht haben, und der Halbgott Cenarius, der Herr des Waldes selbst, erhob sich gegen sie." },
        { "Grom konnte ihn nicht besiegen. Also tat er, was die Orcs geschworen hatten, nie wieder zu tun: Er trank das Blut des Dämons Mannoroth, und mit dessen Stärke töteten die Warsong Cenarius in seinem eigenen Wald. Der Fluch des Dämons lag wieder auf ihnen. Die Holzfällerlager der Warsong sind noch immer hier, und sie fällen noch immer, und die Nachtelfen haben ein langes Gedächtnis." },
      },
    },
    ["wendigos"] = {
      title = "Die Wendigos",
      text = {
        { "Der altgediente Bau bietet Schutz vor dem Schnee von Dun Morogh, vorausgesetzt, Ihr könnt seine Wendigos überreden, ihn zu teilen. Ein Bote, der vor ihnen floh, ließ eine Munitionslieferung zurück. Die Geschöpfe hatten das stärkere Argument." },
        { "Pilot Stonegear will ihre Mähnen für einen Teppich in seiner Belagerungsmaschine, der Trollpflug. Selbst Maschinen brauchen in diesem Land ein wenig Behaglichkeit, $gReisender:Reisende;. Die Munition zu bergen und die Maschine auszustatten, verlangt beides, einem Wendigo deutlich näher zu kommen, als dem Boten lieb war." },
      },
    },
    ["western-plaguelands"] = {
      title = "Westliche Pestländer",
      text = {
        { "Die Westlichen Pestländer waren einst reiches Ackerland Lordaerons. Verseuchtes Getreide trug den Untod durch seine Dörfer. Graue Felder, verfaulende Scheunen und verdorrte Bäume umgeben heute die Toten, die noch durch sie wandeln. Grünes Gift hängt über einem Land, das einst das Königreich ernährte." },
        { "Das Chillwind-Lager beherbergt im Süden die Allianz und die Argentumdämmerung, die Verlassenen halten das Bollwerk im Westen, und der Scharlachrote Kreuzzug hält Hearthglen im Norden. Zwischen diesen Stützpunkten liegen Andorhal, die Seuchenkessel und die Scholomance am See. Den Weg eines Reisenden durch dieses Land bemisst man danach, wo die Lebenden noch Boden halten können." },
      },
    },
    ["westfall"] = {
      title = "Westfall",
      text = {
        { "Westfall war die Kornkammer Stormwinds: weite goldene Felder, Windmühlen und Gehöfte, die sich bis zum Meer hinabziehen. Die Orcs brannten es in den Kriegen nieder, und die Bauern kehrten zurück und säten von Neuem. Was die Orcs nicht vollenden konnten, haben die Defias vollendet." },
        { "Die Bruderschaft hat sich Westfall zu eigen gemacht. Sie vertrieb die Bauernfamilien Hof um Hof von ihrem Land, nahm Moonbrook als ihre Stadt und die alten Minen darunter als ihre Festung, und das Heer des Königs kam nie. \"Stormwind hat uns im Stich gelassen\", werden Euch die Männer auf der Späherkuppe sagen, und es fällt schwer, ihnen zu widersprechen. Nun sind die Felder trocken, die Gnolle der Flusspfoten überfallen die Höfe, und Erntegolems pirschen durch die Furchen. Murlocs halten die Küste, und selbst im Leuchtturm spukt es." },
        { "Ein paar sture Bauern sind geblieben. Fragt Bauer Saldean, warum, und er wird Euch sagen, dass es sein Land ist." },
      },
    },
    ["wetlands"] = {
      title = "Das Sumpfland",
      text = {
        { "Nördlich der Berge wird der Boden weich und die Luft grau, und Ihr seid im Sumpfland: Marsch, Schilf und Regen, vom Pass von Dun Algaz bis zum Meer beim Hafen von Menethil." },
        { "Einst war dies Land der Zwerge, durch den Thandol-Übergang mit den Königreichen der Menschen verbunden. Heute ist es ein Kreuzweg der Kriege anderer Leute. Die Orcs der Dragonmaw halten die Hügel, die Dunkeleisenzwerge haben unsere Festung Dun Modr eingenommen, Gnolle und Murlocs füllen die Marschen, und im Osten brütet Grim Batol über allem." },
        { "Bleibt auf der Straße, haltet Euer Pulver trocken und verweilt nicht nach Einbruch der Dunkelheit." },
      },
    },
    ["whelgars-excavation-site"] = {
      title = "Whelgars Ausgrabungsstätte",
      text = {
        { "Noch eine Grabung der Liga, diese in den Marschen des Sumpflands, unter Ausgrabungsleiter Whelgar. Die Marsch behält, was sie verschluckt, und die Liga hatte große Hoffnungen in das gesetzt, was unter ihr lag." },
        { "Dann kamen die Raptoren. Sie zogen in die Grabung ein und betrachteten die Gräber als Freiwild, und die Leute der Liga wurden auf einen Grat über der Stätte vertrieben, wo manche von ihnen noch immer darauf warten, dass die Tiere abziehen." },
        { "Wenn Ihr vorbeikommt, seht nach ihnen. Sie werden sehr froh sein, jemanden mit einer Waffe zu sehen." },
      },
    },
    ["whitemane-and-mograine"] = {
      title = "Whitemane und Mograine",
      text = {
        { "Hochinquisitor Sally Whitemane und der Scharlachrote Kommandant Renault Mograine halten die Kathedrale des Scharlachroten Klosters. Er befehligt ihre Ritter. Sie lenkt ihren Glauben. Ihre Herrschaft über das Licht kann ihn wiedererwecken, wenn er fällt, was einen Sieg über den Kommandanten weniger endgültig macht, als ein Reisender hoffen mag." },
        { "Renault ist der Sohn von Hochlord Alexandros Mograine, dem Aschenbringer, einem großen Streiter der Silbernen Hand gegen die Geißel. Sein Vater ist tot. Fairbanks, ein weiterer Hochinquisitor, versteckt in der Kathedrale, behauptet zu wissen, wie er starb, und sagt, dass Renault dabei war. Dem Kreuzzug wäre sein Schweigen lieber. Wer die Klinge des Hochlords bringt, hört vielleicht den Bericht, den sie nicht erzählt haben wollen. Die Seite des Aschenbringers in diesem Register erzählt, was er sagt." },
        { side = "Horde", aside = true, sign = "P. F.", "Whitemane erweckt ihren Kommandanten von den Toten, und der Kreuzzug verbrennt den Rest von uns für weniger." },
      },
    },
    ["wildhammer-clan"] = {
      title = "Der Wildhammerklan",
      text = {
        { "Die Wildhammer waren einer der drei Hämmer des alten Königreichs Khaz Modan, und nach dem Krieg, der die drei entzweite, nahmen sie Grim Batol als Heimat. Als die Königin der Dunkeleisenzwerge Modgud dort starb, hinterließ ihr Tod eine Finsternis im Stein, und so verließen die Wildhammer es und zogen nach Norden ins Hinterland, wo sie seither unter freiem Himmel leben, Greifen reiten und die alten Wege der Geister pflegen." },
        { "Sie sind stolz, wild, sehr unabhängig, und sie finden, wir aus Ironforge hätten zu lange unter der Erde verbracht. Im Zweiten Krieg kämpften ihre Greifenreiter für die Allianz und waren der Schrecken der Drachen der Horde. Heute behalten sie ihre Gedanken für sich, und ihre eigenen Freunde: die Hochelfen von Quel'Danil unter ihnen, was die Trolle des Hinterlands ihnen übelnehmen." },
      },
    },
    ["wildkin"] = {
      title = "Die Wildekin",
      text = {
        { "Die großen Eulenbären des Nordens heißen Wildekin oder Moonkin, und die Nachtelfen behandeln sie mit einer Ehrfurcht, die Reisende nicht immer teilen. Es heißt, Elune selbst habe sie erschaffen, und manche sagen, sie seien ihre Lieblinge gewesen. Ein Gelehrter der Nachtelfen, der ihre Federn erforscht, findet darin eine Magie, die die Geschöpfe weniger ausüben als in sich tragen, als Teil ihres Wesens." },
        { "Sie sind großer Sanftheit und großer Wildheit fähig, besonders wenn etwas bedroht ist, das ihnen wichtig ist, und in Winterspring sollen sie Geheimnisse der Nachtelfen hüten. Manche dort sind wahnsinnig geworden, sagen die Berichte, weil sie zu lange in der Nähe dessen waren, was sie beschützen." },
        { "In letzter Zeit sind die sanften weniger geworden. Die Moonkin der Dunkelküste werden von einem großen roten Kristall in den östlichen Hügeln angezogen, und die Schildwachen von Auberdine halten sie nicht mehr für harmlos. Ich würde jedem Eulenbären weit ausweichen, $gReisender:Reisende;, und einem wahnsinnigen noch weiter." },
      },
    },
    ["windshear-crag"] = {
      title = "Die Scherwindklippe",
      text = {
        { "Die Scherwindklippe ist das große Holzfäller- und Bergbaulager der Venture Co. im Norden des Steinkrallengebirges, ein Tal aus Baumstümpfen, Sägen, Wasserrädern und Schreddern, den menschenförmigen Maschinen, die Bäume schneller fällen als jede Mannschaft. Über allem, nahe dem großen Rad, lebt sein Aufseher, Gerenzo Wrenchwhistle, ein Goblin, der inzwischen mehr Metall als Fleisch ist." },
        { "Das verbrannte Tal im Süden ist, was die Gesellschaft zurücklässt: ein ganzer Wald, niedergebrannt. Die Druiden wollen ihn neu pflanzen, die Schamanen wollen die Maschinen aufhalten, und selbst einige der eigenen Ingenieure der Gesellschaft haben angewidert gekündigt." },
      },
    },
    ["wintersaber-trainers"] = {
      title = "Die Wintersäblerausbilder",
      text = {
        { "Hoch oben auf dem Frostsäblerfelsen im Norden von Winterspring zieht eine Handvoll Nachtelfen die weißen Säbler des Nordens auf. Ihr Anführer, Rivern Frostwind, bleibt für sich. Die meisten bemerken seine Anwesenheit nicht, sagt er, was ihm recht ist." },
        { "Die Katzen sind nicht leicht zu verdienen. Rivern beginnt mit jedem, der eine will, indem er ihn nach Fleisch schickt, von den Chimären und den Splitterzahnbären, um die jungen Säbler in der Ausbildung zu füttern, und dann um Hilfe gegen die Furbolgs der Winterfelle, die dem Felsen zusetzen. Es ist eine lange Lehrzeit, und wenige beenden sie." },
        { "Wer es tut, reitet auf einem Frostsäbler aus Winterspring hinaus, was, wie man mir sagt, jeden Botengang wert ist. Die Katzen ihrerseits scheinen zu glauben, die Abmachung sei ihre Idee gewesen." },
      },
    },
    ["winterspring"] = {
      title = "Winterspring",
      text = {
        { "Winterspring ist das hohe, verschneite Tal nördlich des Teufelswalds und östlich von Moonglade, ein Land aus tiefem Schnee, gefrorenen Seen und heißen Quellen, die in der Kälte dampfen. Frostsäbler jagen hier, und Eulen, Yetis, Riesen und die Wildekin. Die Nachtelfen ziehen ihre Frostsäbler am Frostsäblerfelsen auf, und die Druiden halten ein Dorf in Starfall." },
        { "Die Furbolgs des Stammes der Winterfelle trinken ein verderbtes Feuerwasser, das aus dem Teufelswald heraufgebracht wird, und werden davon wahnsinnig. Die blauen Drachen haben ihren Hort in den Höhlen von Mazthoril, und die Goblins von Everlook verkaufen an der Wegkreuzung alles an jeden." },
      },
    },
    ["worgen"] = {
      title = "Die Worgen",
      text = {
        { "Arugal beschwor Worgen aus einer anderen Welt, als Dalarans Verteidiger der Geißel erlagen. Die Wolfsmenschen griffen die Toten an und wandten sich dann gegen die Lebenden. Der Magier zog sich nach Burg Shadowfang zurück, nannte sie seine Kinder und verfluchte Pyrewood, dessen Bewohner bei Tag Menschen und bei Nacht Worgen sind." },
        { "Der Dämmerwald bietet eine andere Spur. Die Nachtwache meldet ihr plötzliches Auftauchen in einer Mine südlich von Dunkelhain. Berichte deuten auf die Sense von Elune hin, ein altes elfisches Relikt, das jemand in den Wald trug, der seine Macht nicht verstand." },
        { "Die Geschöpfe sind stark, klug und können trotz ihrer aufrechten Gestalt auf allen vieren laufen. Haltet die beiden Spuren auseinander, $gReisender:Reisende;. Zu wissen, wer sie in den einen Wald brachte, hat ihr Auftauchen im anderen nicht erklärt." },
      },
    },
    ["zaetar-and-theradras"] = {
      title = "Zaetar und Theradras",
      text = {
        { "Zaetar war der Sohn des Cenarius, ein Wesen des Waldes. Theradras war eine Prinzessin der elementaren Erde. Aus ihrer Verbindung gingen die Zentauren hervor, die ihren eigenen Vater töteten. Theradras bettete ihn in den Höhlen von Maraudon zur Ruhe, wo seine Kinder ihn noch immer verehren und sein Grab bewachen." },
        { "Ein Druide des Zirkels des Cenarius wartet nahe Shadowprey und sucht jemanden, der Theradras gegenübertreten und Zaetars Überreste bergen kann. Der heilige Boden der Zentauren ist auch die Ruhestätte eines Mitglieds der Familie des Cenarius." },
      },
    },
    ["zandalar-tribe"] = {
      title = "Der Stamm der Zandalar",
      text = {
        { "Die Zandalar bezeichnen sich als den ältesten Stamm der Trolle, von dem die anderen abstammen. Ihre Priester und Gelehrten bewahren die Erinnerung an ihr Volk und ihre Götter. Selten mischen sie sich in die Angelegenheiten anderer Völker ein, doch Hakkars Rückkehr hat sie auf die Insel Yojamba vor der Küste des Schlingendorntals gebracht." },
        { "Ihr Anführer Molthor arbeitet mit jedem zusammen, der bereit ist, sich dem Seelenschinder entgegenzustellen. Diese Einladung schließt Leute ein, die die Trolle gewöhnlich wenig Grund hätten willkommen zu heißen." },
      },
    },
    ["zephras-isle"] = {
      title = "Die Insel Zephras",
      text = {
        { "Die Insel Zephras ist eine Insel, die fliegt. Sie schwebt im Himmelswall, der Ebene der Luft, wohin die Windgeister die Shen'dorei vor langer Zeit trugen, und sie ist die Heimat der Himmelsgeborenen, die seit kurzem zu uns herabgekommen sind. Ihre Leute leben in Valanaar am südöstlichen Rand, in den Dörfern des Shen'darhochlands und in Thendal und auf den Höfen des Böenbeerentieflands." },
        { "Die Geister, die die Insel banden, verließen sie vor einigen Jahrhunderten. Ihre großen Ankerpylonen halten Zephras noch oben, doch ihre Magie wird unstet, und Ban'aethal begann eines Nachts in den Himmel zu fallen und musste vor dem Morgen geräumt werden. Seit einiger Zeit hat kein Himmelsschiff mehr zu den anderen Inseln übergesetzt, Anvilas und Siroccas, und es gibt Shen'dorei, die fürchten, sie seien alles, was von ihrem Volk übrig ist." },
        { "Ich habe nie dort gestanden, $gReisender:Reisende;, und ich beneide Euch ein wenig. Haltet Euch bitte von den Rändern fern." },
      },
    },
    ["zulfarrak"] = {
      title = "Zul'Farrak",
      text = {
        { "Zul'Farrak ist die Stadt der Trolle der Sandfury, eine ummauerte Stadt aus Sandstein im Westen von Tanaris, mit Pyramiden, Schreinen und einem heiligen Teich, aus dem die Hydra Gahz'rilla aus der Tiefe gerufen wird. Häuptling Ukorz Sandscalp herrscht über sie, und der Schrein des Märtyrers Theka steht innerhalb ihrer Mauern." },
        { "Viele kommen hierher wegen dessen, was die Trolle bewachen. Die Schrifttafeln der Prophezeiung von Mosh'aru sprechen von einem Weg, die Essenz des Gottes Hakkar einzuschließen. Es gibt auch eine legendäre Klinge und das eigene Härtemittel der Trolle, das Schmiede schätzen. Und es gibt Schätze, die Goblins und Narren in gleicher Zahl anlocken. Die meisten von ihnen kommen nie wieder heraus." },
      },
    },
    ["zulgurub"] = {
      title = "Zul'Gurub",
      text = {
        { "Zul'Gurub war die Tempelstadt im Herzen des Reichs der Gurubashi. Nach Jahrhunderten der Stille ist es wieder Hakkars Stadt. Hohepriester, die ausgesandt wurden, um sich ihm entgegenzustellen, sind seiner Macht verfallen, und die Zandalar müssen nun jenseits ihres eigenen Volkes Hilfe suchen." },
        { "Die gefangenen Priester nehmen die Gestalten der alten Tiergötter an: Fledermaus, Panther, Tiger, Schlange und Spinne. Opfer nähren den Altar des Seelenschinders. Die Zandalar warnen, dass seine wachsende Macht ganz Azeroth bedroht. Wenn Ihr hineingeht, denkt daran, warum sie Euch gebeten haben zu gehen: Selbst jene, die ihn aufhalten sollten, wurden zu Werkzeugen seiner Herrschaft." },
      },
    },
  },
})
